# ----------------------------------------------------------------------
# Outbound-network safety lock.
# Set to True via --offline (or by future code paths) to HARD-DISABLE
# every outbound network call this tool can make:
#   * socket.gethostbyaddr (PTR lookups in _public_ip_context)
#   * urllib.request.urlopen (RDAP queries in _public_ip_context)
#   * tshark name resolution (we also pass -n explicitly)
# Use this when analyzing pcaps from an untrusted source so the tool
# cannot generate DNS/HTTPS traffic that might be attributed to recon
# of the captured environment.  This flag overrides the discovery
# questionnaire's "air_gapped" answer — if either is true, no calls.
# ----------------------------------------------------------------------
