_MANUF_DB: Optional[Dict[str, str]] = None


def _wireshark_manuf_db() -> Dict[str, str]:
    """Load tshark's built-in manufacturer table once (local data, no network).

    Keys are lower-case hex prefixes of 6, 7 or 9 digits (/24, /28, /36 blocks).
    """
    global _MANUF_DB
    if _MANUF_DB is not None:
        return _MANUF_DB
    table: Dict[str, str] = {}
    try:
        result = subprocess.run(["tshark", "-G", "manuf"], capture_output=True, text=True,
                                encoding="utf-8", errors="replace", timeout=60)
        for line in result.stdout.splitlines():
            parts = [part.strip() for part in line.split("\t")]
            if len(parts) < 2 or not parts[0]:
                continue
            prefix, _, bits_text = parts[0].partition("/")
            digits = int(bits_text) // 4 if bits_text.isdigit() else 6
            hex_prefix = prefix.replace(":", "").replace("-", "").lower()
            if len(hex_prefix) < digits or hex_prefix[:6] == "000000":
                continue
            table[hex_prefix[:digits]] = parts[2] if len(parts) > 2 and parts[2] else parts[1]
    except (OSError, subprocess.SubprocessError):
        table = {}
    _MANUF_DB = table
    return table


def lookup_oui_vendor(mac: str) -> str:
    """Return the IEEE-registered vendor for a MAC address, or ''."""
    if not mac or len(mac) < 8:
        return ""
    hex_mac = mac.replace(":", "").replace("-", "").lower()
    manuf = _wireshark_manuf_db()
    for digits in (9, 7, 6):
        name = manuf.get(hex_mac[:digits])
        if name:
            return name
    return OUI_VENDOR_MAP.get(mac[:8].lower(), "")


def passive_os_from_syn(ttl: int, window: int) -> str:
    """Classify OS family from TCP SYN TTL + window size.

    Crude but useful: SYN packets expose an initial TTL (rounded up to
    the nearest 32 or 64 boundary in practice) and an initial receive
    window that are fairly OS-specific.  Returns '' if nothing matches.
    """
    if ttl <= 0:
        return ""
    # Round TTL up to common starting values: 64, 128, 255.
    if ttl <= 64:
        initial = 64
        family = "Linux/Unix/BSD"
    elif ttl <= 128:
        initial = 128
        family = "Windows"
    elif ttl <= 255:
        initial = 255
        family = "Network device / IoT"
    else:
        return ""
    # Narrow by window size where possible.
    if initial == 64:
        if window == 5840:
            return "Linux 2.4/2.6"
        if window in (5792, 14600, 29200, 64240):
            return "Linux (modern)"
        if window == 65535:
            return "BSD / macOS"
        return family
    if initial == 128:
        if window in (8192,):
            return "Windows 7/Server 2008"
        if window in (64240, 65535):
            return "Windows 10+/Server 2016+"
        return family
    return family
