def advisories_for_finding(category: str, title: str, tags: Optional[Sequence[str]] = None) -> List[str]:
    """Look up advisory/standard references for a finding."""
    haystack = f"{category} {title}".lower()
    tag_set = {t.lower() for t in (tags or [])}
    refs: List[str] = []
    for keys, entries in ADVISORY_MAP:
        for key in keys:
            if key in haystack or key in tag_set:
                for ref in entries:
                    if ref not in refs:
                        refs.append(ref)
                break
    return refs


def mitre_for_finding(category: str, title: str, tags: Optional[Sequence[str]] = None) -> List[str]:
    """Look up MITRE ATT&CK for ICS IDs for a finding.

    Matches any substring in MITRE_ICS_MAP against "<category> <title>".
    Returns a deduplicated list of technique IDs (e.g. ['T0831','T0855']).
    """
    haystack = f"{category} {title}".lower()
    tag_set = {t.lower() for t in (tags or [])}
    ids: List[str] = []
    for keys, technique_ids in MITRE_ICS_MAP:
        for key in keys:
            if key in haystack or key in tag_set:
                for tid in technique_ids:
                    if tid not in ids:
                        ids.append(tid)
                break
    return ids


def utc_now_iso() -> str:
    """Return the current UTC timestamp in ISO-8601 format."""
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()


def path_exists(path_text: str) -> bool:
    """Return True if a filesystem path exists."""
    return Path(path_text).expanduser().exists()


def human_size(size_bytes: int) -> str:
    """Format a byte count as a human-readable string."""
    if size_bytes < 1024:
        return f"{size_bytes} B"
    units = ["KB", "MB", "GB", "TB"]
    value = float(size_bytes)
    for unit in units:
        value /= 1024.0
        if value < 1024.0:
            return f"{value:.1f} {unit}"
    return f"{value:.1f} PB"


def safe_slug(value: str) -> str:
    """Make a string filename-safe."""
    cleaned = re.sub(r"[^A-Za-z0-9._-]+", "_", value.strip())
    return cleaned.strip("_") or "session"


def _versioned_path(folder: Path, base_name: str, ext: str) -> Path:
    """Return the first non-existent path of the form <folder>/<base_name>[_vN].<ext>.

    If <base_name>.<ext> does not exist, return it directly.  Otherwise
    increment a _v2, _v3 … suffix until a free slot is found.  This avoids
    silently overwriting artifacts from earlier runs in the same output folder.
    """
    candidate = folder / f"{base_name}.{ext}"
    if not candidate.exists():
        return candidate
    version = 2
    while True:
        candidate = folder / f"{base_name}_v{version}.{ext}"
        if not candidate.exists():
            return candidate
        version += 1


def _versioned_paths(folder: Path, base_names: Sequence[str], ext: str) -> List[Path]:
    """Like _versioned_path, with one shared _vN suffix that is free for every
    name, so files written together (the two Purdue diagrams) stay paired."""
    version = 1
    while True:
        suffix = "" if version == 1 else f"_v{version}"
        candidates = [folder / f"{name}{suffix}.{ext}" for name in base_names]
        if not any(candidate.exists() for candidate in candidates):
            return candidates
        version += 1


def is_capture_file(path: Path) -> bool:
    """True for capture files tshark reads natively (incl. gzip-compressed)."""
    return path.is_file() and path.name.lower().endswith(CAPTURE_SUFFIXES)


def split_capture_name(name: str) -> Tuple[str, str]:
    """Split 'site.pcap.gz' into ('site', 'pcap.gz') using the longest capture suffix."""
    lowered = name.lower()
    for suffix in sorted(CAPTURE_SUFFIXES, key=len, reverse=True):
        if lowered.endswith(suffix):
            return name[: -len(suffix)], name[-len(suffix) + 1:]
    stem, _, ext = name.rpartition(".")
    return stem or name, ext


def service_port_for(sport: int, dport: int) -> int:
    """Pick the server-side port of a flow whose handshake was not observed."""
    if not sport or not dport:
        return dport or sport
    if sport == dport:
        return dport
    dport_known = dport in _SERVICE_PORT_HINTS
    sport_known = sport in _SERVICE_PORT_HINTS
    if dport_known != sport_known:
        return dport if dport_known else sport
    return min(sport, dport)


def colorize(text: str, severity: Optional[str] = None, bold: bool = False) -> str:
    """Apply ANSI colors when stdout is a terminal."""
    if not sys.stdout.isatty():
        return text
    color = ""
    if severity == SEVERITY_CRITICAL:
        color = ANSI_RED
    elif severity == SEVERITY_HIGH:
        color = ANSI_ORANGE
    elif severity == SEVERITY_MEDIUM:
        color = ANSI_YELLOW
    elif severity == SEVERITY_CORRELATION:
        color = ANSI_BLUE
    elif severity == SEVERITY_INTRUSION:
        color = ANSI_BRIGHT_RED
    elif severity == SEVERITY_INFO:
        color = ANSI_CYAN
    elif severity == "SUCCESS":
        color = ANSI_GREEN
    elif severity == "MUTED":
        color = ANSI_GREY
    prefix = ""
    if bold:
        prefix += ANSI_BOLD
    prefix += color
    return f"{prefix}{text}{ANSI_RESET}" if prefix else text


def print_header(title: str) -> None:
    """Print a section header."""
    print(colorize(f"\n=== {title} ===", bold=True))


def prompt_input(message: str, default: Optional[str] = None) -> str:
    """Prompt the user for input and return the stripped result."""
    suffix = f" [{default}]" if default else ""
    answer = input(f"[?] {message}{suffix}: ").strip()
    return answer or (default or "")


def prompt_yes_no(message: str, default: bool = True) -> bool:
    """Prompt for a yes/no answer."""
    default_text = "Y/n" if default else "y/N"
    answer = input(f"[?] {message} [{default_text}]: ").strip().lower()
    if not answer:
        return default
    return answer.startswith("y")


def file_sha256(path: Path) -> str:
    """Compute SHA-256 for a file."""
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def is_public_ip(ip_text: str) -> bool:
    """Return True only for routable public IPv4 addresses.

    Excludes RFC 1918, loopback, link-local, CGNAT, unspecified, multicast,
    and reserved ranges so those never trigger public-IP findings.
    """
    if not ip_text or ":" in ip_text:
        return False
    parts = ip_text.split(".")
    if len(parts) != 4:
        return False
    try:
        a, b = int(parts[0]), int(parts[1])
        c = int(parts[2])
    except ValueError:
        return False
    if a == 10:                         return False  # RFC 1918 10/8
    if a == 172 and 16 <= b <= 31:      return False  # RFC 1918 172.16/12
    if a == 192 and b == 168:           return False  # RFC 1918 192.168/16
    if a == 127:                        return False  # Loopback 127/8
    if a == 169 and b == 254:           return False  # Link-local 169.254/16
    if a == 100 and 64 <= b <= 127:     return False  # CGNAT 100.64/10
    if a == 0:                          return False  # Unspecified 0/8
    if a == 192 and b == 0 and c == 2:  return False  # TEST-NET-1 192.0.2/24
    if a == 198 and b == 51 and c == 100: return False  # TEST-NET-2 198.51.100/24
    if a == 203 and b == 0 and c == 113:  return False  # TEST-NET-3 203.0.113/24
    if a >= 224:                        return False  # Multicast + reserved
    return True


def _shannon_entropy(s: str) -> float:
    """Shannon entropy in bits of the characters in *s*."""
    if not s:
        return 0.0
    freq = Counter(s.lower())
    n = len(s)
    return -sum((c / n) * math.log2(c / n) for c in freq.values())


def _dns_label_entropy(qname: str) -> Tuple[float, str]:
    """Return (entropy, label) for the most entropic non-TLD label in *qname*.

    Skips the rightmost label (the TLD) so that 'com', 'net', etc. don't
    dilute entropy scores for short domain names.
    """
    labels = qname.rstrip(".").split(".")
    candidates = labels[:-1] if len(labels) > 1 else labels
    best = max(candidates, key=lambda lb: (len(lb), _shannon_entropy(lb)))
    return _shannon_entropy(best), best


def subnet_from_ip(ip_text: str) -> str:
    """Return the /24 (IPv4) or /64 (IPv6) network containing an address."""
    if not ip_text:
        return "unknown"
    if ":" in ip_text:
        try:
            return str(ipaddress.ip_network(f"{ip_text.split('%')[0]}/64", strict=False))
        except ValueError:
            return "unknown"
    parts = ip_text.split(".")
    if len(parts) != 4:
        return "unknown"
    return ".".join(parts[:3]) + ".0/24"


def is_group_mac(mac_text: str) -> bool:
    """True for broadcast and multicast MAC addresses (the I/G bit is set)."""
    try:
        return bool(int(mac_text.split(":")[0], 16) & 1)
    except ValueError:
        return False


def is_group_address(ip_text: str, mac_text: str = "") -> bool:
    """True for broadcast / multicast destinations, which are not hosts.

    A subnet-directed broadcast (e.g. 10.1.2.255) is only recognizable by
    its Ethernet destination, so the frame's MAC is checked as well.
    """
    if mac_text and is_group_mac(mac_text):
        return True
    if not ip_text:
        return False
    if ip_text == "255.255.255.255":
        return True
    try:
        return ipaddress.ip_address(ip_text.split("%")[0]).is_multicast
    except ValueError:
        return False


def is_unspecified_address(ip_text: str) -> bool:
    """True for 0.0.0.0 / :: (hosts that do not have an address yet)."""
    try:
        return ipaddress.ip_address(ip_text.split("%")[0]).is_unspecified
    except ValueError:
        return False


def is_link_local_ipv6(ip_text: str) -> bool:
    try:
        addr = ipaddress.ip_address(ip_text.split("%")[0])
    except ValueError:
        return False
    return addr.version == 6 and addr.is_link_local


def format_epoch(value: Any) -> str:
    """Render an epoch timestamp as 'YYYY-MM-DD HH:MM:SS UTC' ('' when invalid)."""
    try:
        return datetime.fromtimestamp(float(value), timezone.utc).strftime("%Y-%m-%d %H:%M:%S UTC")
    except (TypeError, ValueError, OverflowError, OSError):
        return ""


def human_duration(seconds: float) -> str:
    """Render a duration for report text: seconds, minutes, hours, days, or years."""
    seconds = max(0.0, float(seconds))
    if seconds < 1:
        return "under a second"
    if seconds < 90:
        return f"{seconds:.0f} seconds"
    minutes = seconds / 60
    if minutes < 90:
        return f"{minutes:.0f} minutes"
    hours = minutes / 60
    if hours < 48:
        return f"{hours:.1f} hours"
    days = hours / 24
    if days < 730:
        return f"{days:.0f} days"
    return f"{days / 365.25:.1f} years"


def format_share(part: int, total: int) -> str:
    """Percentage of part in total for report text: "0%", "37%", "99.6%", "100%"."""
    if total <= 0:
        return "n/a"
    share = 100.0 * part / total
    if 99.0 < share < 100.0:
        return f"{share:.1f}%"
    return f"{share:.0f}%"


RISK_BANDS = ["MINIMAL", "LOW", "MODERATE", "HIGH", "SEVERE"]


def risk_band(score: int) -> str:
    """Map numeric risk score to a named band."""
    if score >= 120:
        return "SEVERE"
    if score >= 75:
        return "HIGH"
    if score >= 35:
        return "MODERATE"
    if score >= 10:
        return "LOW"
    return "MINIMAL"


def risk_banner(band: str) -> str:
    """Render a compact ASCII banner for the final risk band."""
    text = f" {band} RISK "
    edge = "=" * len(text)
    return f"{edge}\n{text}\n{edge}"


def pretty_json(data: Dict[str, Any]) -> str:
    """Serialize JSON in a stable, readable way."""
    return json.dumps(data, indent=2, sort_keys=True)


@dataclass
class ProcessedPcap:
    """Track a pcap already processed into a session."""

    path: str
    filename: str
    sha256: str
    size_bytes: int
    processed_at: str
    packet_count: int = 0
    start_time: Optional[str] = None
    end_time: Optional[str] = None
    truncated: bool = False


@dataclass
class DeviceRecord:
    """Unified device registry entry."""

    ip: str
    macs: List[str] = field(default_factory=list)
    hostnames: List[str] = field(default_factory=list)
    protocols: List[str] = field(default_factory=list)
    ports: List[int] = field(default_factory=list)          # service ports this device answered on
    client_ports: List[int] = field(default_factory=list)   # service ports this device connected to
    source_pcaps: List[str] = field(default_factory=list)
    subnets: List[str] = field(default_factory=list)
    vlans: List[str] = field(default_factory=list)
    outgoing_count: int = 0
    incoming_count: int = 0
    inferred_role: str = "Unknown"
    inferred_zone: str = "Unknown"
    notes: List[str] = field(default_factory=list)
    evidence: List[str] = field(default_factory=list)
    vendors: List[str] = field(default_factory=list)
    os_fingerprint: str = ""
    user_agents: List[str] = field(default_factory=list)
    server_banners: List[str] = field(default_factory=list)
    ipv6_addresses: List[str] = field(default_factory=list)  # link-local addresses of this same host (by MAC)


@dataclass
class ConnectionSummary:
    """Summary of a relationship between two devices."""

    source_ip: str
    destination_ip: str
    protocol: str
    destination_port: int
    packet_count: int = 0
    first_seen: Optional[str] = None
    last_seen: Optional[str] = None
    source_pcaps: List[str] = field(default_factory=list)
    notes: List[str] = field(default_factory=list)
    # Packets that carried this flow's protocol label; None for flows saved before v2.8.3.
    labelled_packets: Optional[int] = None


@dataclass
class Finding:
    """Single finding in the findings registry."""

    finding_id: str
    severity: str
    category: str
    title: str
    description: str
    evidence: List[str]
    source_ips: List[str]
    destination_ips: List[str]
    protocol: str
    source_pcaps: List[str]
    next_steps: str
    created_at: str
    first_seen: Optional[str] = None
    last_seen: Optional[str] = None
    tags: List[str] = field(default_factory=list)
    score_weight: int = 0
    dedupe_key: str = ""
    mitre_ids: List[str] = field(default_factory=list)
    advisory_refs: List[str] = field(default_factory=list)
    occurrences: int = 1


@dataclass
class SessionState:
    """Persistent session state saved to JSON."""

    name: str
    site: str
    assessor: str
    folder: str
    created_at: str
    updated_at: str
    session_file: str
    environment_answers: Dict[str, str] = field(default_factory=dict)
    processed_pcaps: Dict[str, ProcessedPcap] = field(default_factory=dict)
    devices: Dict[str, DeviceRecord] = field(default_factory=dict)
    connections: Dict[str, ConnectionSummary] = field(default_factory=dict)
    findings: List[Finding] = field(default_factory=list)
    packet_fingerprints: List[str] = field(default_factory=list)
    duplicate_packets: Dict[str, List[str]] = field(default_factory=dict)
    analysis_metadata: Dict[str, Any] = field(default_factory=dict)


def dataclass_from_dict(cls: Any, payload: Dict[str, Any]) -> Any:
    """Instantiate a dataclass from a plain dictionary.

    Ignores unknown keys so sessions saved with older versions load cleanly,
    and missing keys fall back to each field's declared default.
    """
    known = {f.name for f in cls.__dataclass_fields__.values()}  # type: ignore[attr-defined]
    return cls(**{k: v for k, v in payload.items() if k in known})


def session_to_dict(session: SessionState) -> Dict[str, Any]:
    """Serialize a session to JSON-ready dictionaries."""
    return {
        "name": session.name,
        "site": session.site,
        "assessor": session.assessor,
        "folder": session.folder,
        "created_at": session.created_at,
        "updated_at": session.updated_at,
        "session_file": session.session_file,
        "environment_answers": session.environment_answers,
        "processed_pcaps": {key: asdict(value) for key, value in session.processed_pcaps.items()},
        "devices": {key: asdict(value) for key, value in session.devices.items()},
        "connections": {key: asdict(value) for key, value in session.connections.items()},
        "findings": [asdict(finding) for finding in session.findings],
        "packet_fingerprints": session.packet_fingerprints,
        "duplicate_packets": session.duplicate_packets,
        "analysis_metadata": session.analysis_metadata,
    }


def session_from_dict(payload: Dict[str, Any]) -> SessionState:
    """Hydrate a session from a JSON dictionary."""
    session = SessionState(
        name=payload["name"],
        site=payload["site"],
        assessor=payload["assessor"],
        folder=payload["folder"],
        created_at=payload["created_at"],
        updated_at=payload["updated_at"],
        session_file=payload["session_file"],
        environment_answers=payload.get("environment_answers", {}),
        analysis_metadata=payload.get("analysis_metadata", {}),
    )
    session.processed_pcaps = {
        key: dataclass_from_dict(ProcessedPcap, value)
        for key, value in payload.get("processed_pcaps", {}).items()
    }
    session.devices = {
        key: dataclass_from_dict(DeviceRecord, value)
        for key, value in payload.get("devices", {}).items()
    }
    session.connections = {
        key: dataclass_from_dict(ConnectionSummary, value)
        for key, value in payload.get("connections", {}).items()
    }
    session.findings = [dataclass_from_dict(Finding, item) for item in payload.get("findings", [])]
    session.packet_fingerprints = payload.get("packet_fingerprints", [])
    session.duplicate_packets = payload.get("duplicate_packets", {})
    return session


def load_config() -> Dict[str, Any]:
    """Load the persisted config file."""
    if not CONFIG_PATH.exists():
        return {
            "last_pcap_folder": "",
            "last_assessor_name": "",
            "last_site_name": "",
            "write_burst_count": DEFAULT_WRITE_BURST_COUNT,
            "write_burst_seconds": DEFAULT_WRITE_BURST_SECONDS,
            "polling_anomaly_multiplier": DEFAULT_POLLING_ANOMALY_MULTIPLIER,
        }
    try:
        return json.loads(CONFIG_PATH.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError):
        return {
            "last_pcap_folder": "",
            "last_assessor_name": "",
            "last_site_name": "",
            "write_burst_count": DEFAULT_WRITE_BURST_COUNT,
            "write_burst_seconds": DEFAULT_WRITE_BURST_SECONDS,
            "polling_anomaly_multiplier": DEFAULT_POLLING_ANOMALY_MULTIPLIER,
        }


def save_config(config: Dict[str, Any]) -> None:
    """Persist the config file."""
    try:
        CONFIG_PATH.write_text(pretty_json(config), encoding="utf-8")
    except OSError as exc:
        print(colorize(f"[!] Could not save preferences to {CONFIG_PATH}: {exc}", SEVERITY_MEDIUM))


# Direct runtime dependencies only — everything else the tool uses is stdlib.
_FIELD_REQUIREMENTS = "python-docx>=1.1.0\n"
# Earlier generated requirements files; replaced on upgrade unless hand-edited.
_LEGACY_FIELD_REQUIREMENTS = ("python-docx>=1.1.0\nscapy>=2.5.0\n",)


def _workspace_readme_text() -> str:
    return (
        f"{TOOL_NAME} v{VERSION} — offline OT/ICS packet-capture analysis\n"
        f"{__copyright__}\n"
        "\n"
        "This workspace was set up automatically on first run:\n"
        "\n"
        "  pcaps/    drop your capture files here (.pcap / .pcapng / .cap, also .gz)\n"
        "            (captures left next to otscope.py are moved here automatically)\n"
        "  output/   reports, session files, and diagrams are written here\n"
        "\n"
        "Quick start\n"
        "  1. Install Python dependencies:\n"
        "       pip install -r requirements.txt\n"
        "  2. Install tshark (part of the Wireshark suite):\n"
        "       Windows:        winget install WiresharkFoundation.Wireshark\n"
        "       Debian/Ubuntu:  sudo apt install tshark\n"
        "       macOS:          brew install wireshark\n"
        "  3. Put capture files in pcaps/ and run:\n"
        "       python otscope.py                 (interactive)\n"
        "       python otscope.py --scan pcaps    (non-interactive quick scan)\n"
        "       python otscope.py --offline       (hard-lock all outbound network calls)\n"
        "\n"
        "Nothing leaves this machine: analysis is fully offline and reports are\n"
        "written to the output/ folder next to this file.\n"
    )


def _bootstrap_workspace() -> None:
    """Self-provision the workspace next to the script on first run.

    Lets a bare otscope.py dropped into an empty folder create everything
    it needs: pcaps/ and output/ folders, a minimal requirements.txt, and
    a README_FIRST.txt quick-start.  Capture files dropped loose next to
    the script are adopted into pcaps/ so the "one folder" workflow just
    works.  Every step is best-effort — a read-only location (e.g. a
    locked USB drive) must never stop the tool.  Generated files are only
    replaced when they are an unmodified copy written by an older version.
    """
    try:
        _PCAPS_ROOT.mkdir(parents=True, exist_ok=True)
        _OUTPUT_ROOT.mkdir(parents=True, exist_ok=True)
    except OSError:
        pass
    readme_text = _workspace_readme_text()
    for name, content in (
        ("requirements.txt", _FIELD_REQUIREMENTS),
        ("README_FIRST.txt", readme_text),
    ):
        target = _SCRIPT_DIR / name
        try:
            if not target.exists():
                target.write_text(content, encoding="utf-8")
                continue
            existing = target.read_text(encoding="utf-8", errors="replace")
            if name == "requirements.txt":
                stale = existing in _LEGACY_FIELD_REQUIREMENTS
            else:
                first_line = existing.split("\n", 1)[0]
                stale = first_line.startswith(f"{TOOL_NAME} v") and first_line != readme_text.split("\n", 1)[0]
            if stale:
                target.write_text(content, encoding="utf-8")
        except OSError:
            pass
    if _PCAPS_ROOT.is_dir():
        try:
            loose = sorted(item for item in _SCRIPT_DIR.iterdir() if is_capture_file(item))
        except OSError:
            loose = []
        for item in loose:
            base, ext = split_capture_name(item.name)
            dest = _versioned_path(_PCAPS_ROOT, base, ext)
            try:
                shutil.move(str(item), str(dest))
                print(f"[i] Moved capture into workspace: {item.name} -> pcaps{os.sep}{dest.name}")
            except OSError:
                pass


def ensure_runtime_dependencies() -> None:
    """Check for required runtime tools and packages."""
    missing = []
    if shutil.which("tshark") is None:
        missing.append("tshark")
    try:
        import docx  # noqa: F401
    except ImportError:
        missing.append("python-docx")
    if missing:
        print_header("Missing Dependencies")
        print("[!] The following dependencies are required before analysis can run:")
        for name in missing:
            print(f"    - {name}")
        print("\nInstall guidance:")
        print(f'    pip install -r "{_SCRIPT_DIR / "requirements.txt"}"')
        print("")
        print("    Debian/Ubuntu alternative:")
        print("    sudo apt install tshark python3-docx")
        print("")
        print("    tshark (part of the Wireshark suite) if missing:")
        print("      Windows:        winget install WiresharkFoundation.Wireshark")
        print("      Debian/Ubuntu:  sudo apt install tshark")
        print("      macOS:          brew install wireshark")
        raise SystemExit(1)


def next_steps_for(severity: str, category: str) -> str:
    """Generate concise remediation-oriented next-step language."""
    if "absence" in category.lower():
        return (
            "Verify capture point visibility with site staff. Consider recapturing from a different network tap point. "
            "This may indicate a segmentation issue or a system that was offline during capture."
        )
    if "cleartext" in category.lower() or "legacy" in category.lower():
        return (
            "Replace the legacy service with a secure alternative where possible, such as HTTPS, SSH, SNMPv3, or TLS. "
            "If the service must remain, restrict source IPs, disable unused accounts, and document the compensating controls."
        )
    if severity == SEVERITY_CRITICAL:
        return (
            "Treat this as a high-priority remediation item. Confirm whether the behavior is expected, identify the initiating host, "
            "and remove or block the risky function if it is not operationally required."
        )
    if severity == SEVERITY_INTRUSION:
        return (
            "Review the source host, timing, and target devices to determine whether this activity matches approved maintenance or testing. "
            "If not, block the path, preserve the capture, and investigate the initiating system before returning it to service."
        )
    return (
        "Confirm that the observed protocol, source, destination, and timing match intended design. "
        "If the activity is unnecessary, remove the exposure at the device, service, or firewall layer."
    )


# Each finding is placed in one narrative family, checked in order, from its
# title and tags only.  Category names are deliberately not matched: a broad
# category such as "Network Hygiene and Segmentation" would otherwise pull
# every finding in it toward the same text.
_NARRATIVE_RULES: List[Tuple[str, Tuple[str, ...], Tuple[str, ...]]] = [
    # (family, title substrings, tags)
    ("mitm", ("adversary-in-the-middle", "arp ", "arp-", "multiple mac", "gratuitous arp", "claims multiple ips"),
     ("mitm", "arp_spoof", "mac_conflict")),
    ("sis", ("tristation", "triconex", "safety instrumented"), ("sis", "tristation")),
    ("replay", ("duplicate or unsolicited", "replay"), ("replay",)),
    ("restart", ("cold restart", "warm restart", "plc stop", "disable spontaneous", "stop/start"), ("restart", "suppression")),
    ("value_anomaly", ("register value anomaly",), ("value_anomaly",)),
    ("dos", ("denial-of-service",), ("dos",)),
    ("file_transfer", ("project file", "firmware", "ladder", "engineering file"), ("firmware_transfer",)),
    ("write", ("write", "operate", "control asdu", "control operation", "flow deployment", "set operation",
               "forward open", "logic transfer", "download"),
     ("write", "write_volume", "unexpected_writer", "multi_writer", "logic_download")),
    ("polling", ("polling burst", "polling pattern", "polling anomaly"), ("timing_anomaly", "polling_pattern")),
    ("recon", ("scan", "sweep", "walk", "enumeration", "reconnaissance", "identify all", "read szl", "list identity",
               "read device id", "who-is", "browse", "interrogation"),
     ("recon", "discovery")),
    ("c2", ("beacon", "user-agent", "ja3", "tls fingerprint", "dns query name", "txt response", "nxdomain"),
     ("beacon", "c2", "dga", "dns_tunneling", "offensive_tool")),
    ("credentials", ("credential", "community string", "authentication failure", "without credentials"),
     ("credential_exposure", "anonymous_mqtt")),
    ("engineering", ("umas", "engineering traffic", "program upload"), ("engineering", "program_upload")),
    ("cleartext", ("without tls", "cleartext", "telnet", "ftp", "tftp", "http", "snmpv1", "smb", "rdp", "vnc",
                   "tls", "ssl", "securitypolicy", "without authentication", "signed but not encrypted",
                   "without secure authentication", "legacy", "web-server banner"),
     ("cleartext", "legacy", "weak_crypto", "noauth")),
    ("boundary", ("public ip", "dual-zone", "vlan", "ot-to-it", "dns resolvers"), ("boundary", "public", "vlan")),
    ("it_noise", ("mdns", "llmnr", "netbios", "ssdp", "ws-discovery"), ("it-on-ot",)),
    ("dhcp", ("dhcp",), ("dhcp-rogue",)),
    ("tcp_anomaly", ("reset storm", "unanswered syn"), ("tcp_anomaly",)),
    ("ipv6", ("ipv6",), ("ipv6",)),
    ("icmp", ("icmp",), ("icmp",)),
    ("time", ("ntp",), ("time-sync",)),
    ("capture", ("capture",), ("capture-integrity",)),
    ("av", (), ("av_media",)),
    ("wireless", ("zigbee", "z-wave", "coap"), ("wireless",)),
    ("dns", ("dns",), ("dns",)),
]


def narrative_family(finding: "Finding") -> str:
    """Return the narrative family used for a finding's explanatory text."""
    if finding.category == "Absence of Expected Traffic":
        return "absence"
    if finding.category == "Unknown and Unclassified Traffic":
        return "unknown"
    title = finding.title.lower()
    tags = {tag.lower() for tag in finding.tags}
    for family, title_keys, tag_keys in _NARRATIVE_RULES:
        if tags.intersection(tag_keys) or any(key in title for key in title_keys):
            return family
    return "default"


_WHY_THIS_MATTERS: Dict[str, str] = {
    "mitm": "This finding matters because a host that can rewrite ARP mappings sits invisibly between OT devices and can read, alter, or drop any command or process value that passes through it.",
    "sis": "This finding matters because a safety instrumented system is the last automated layer that keeps the process from harming people or equipment, and its engineering protocol can read and change the safety logic.",
    "replay": "This finding matters because injected or replayed responses let an attacker show operators false process values while the real process changes.",
    "restart": "This finding matters because stopping, restarting, or silencing a controller has immediate operational impact and can hide follow-on manipulation.",
    "value_anomaly": "This finding matters because sudden jumps in reported values can mean the values were spoofed rather than measured.",
    "dos": "This finding matters because a controller flooded with requests or connections stops answering its HMIs, which blinds operators and can halt the process.",
    "file_transfer": "This finding matters because controller programs and firmware moving over the network can be copied for offline attack planning or swapped for modified versions.",
    "write": "This finding matters because this traffic can change controller state, process values, or device configuration rather than just observe data.",
    "polling": "This finding matters because abnormal polling patterns can starve a controller of resources, or reveal a script or second client acting on the process.",
    "recon": "This finding matters because discovery and enumeration activity is often a precursor to targeted manipulation or exploitation.",
    "c2": "This finding matters because the traffic is consistent with a compromised host keeping contact with an attacker outside the network.",
    "credentials": "This finding matters because exposed or guessed credentials give an attacker legitimate-looking access that monitoring rarely questions.",
    "engineering": "This finding matters because engineering protocols can upload, download, and modify controller programs; whoever can speak them can change the process logic.",
    "cleartext": "This finding matters because the protocol or session protection is weak enough that credentials, commands, or process data may be exposed or modified by anyone with network visibility.",
    "boundary": "This finding matters because traffic that crosses zones weakens OT segmentation and increases the chance that IT-side compromise or internet exposure can directly reach control systems.",
    "it_noise": "This finding matters because name-resolution and discovery broadcasts can be answered by any host on the segment, which lets an attacker collect credentials or redirect connections.",
    "dhcp": "This finding matters because a rogue DHCP server can hand every new client a malicious gateway or DNS server.",
    "tcp_anomaly": "This finding matters because connections that are repeatedly refused, aborted, or unanswered point to scanning, a misconfigured client, or a failing service.",
    "ipv6": "This finding matters because unmanaged IPv6 is a parallel network path that IPv4-only firewalls and monitoring do not see.",
    "icmp": "This finding matters because ICMP reachability lets any host on the segment map which controllers are alive.",
    "time": "This finding matters because unsynchronized clocks undermine forensic timelines, alarm correlation, and certificate validation.",
    "capture": "This finding matters because gaps or short windows in the capture limit what the analysis can see.",
    "av": "This finding matters because audio/video systems on a control network are usually unmanaged, rarely patched endpoints whose continuous high-bandwidth streams share switching capacity with control traffic — and camera/DVR platforms are a frequent initial foothold for attackers.",
    "wireless": "This finding matters because wireless control networks can be observed or injected into by anyone within radio range.",
    "dns": "This finding matters because OT devices that resolve names can be redirected by whoever controls name resolution.",
    "absence": "This finding matters because missing expected traffic can mean the capture point had limited visibility, a device was offline, or segmentation is preventing expected communications.",
    "unknown": "This finding matters because traffic that cannot be identified cannot be assessed, and undocumented services are a common hiding place for unauthorized access.",
}

# Remediation per narrative family: (plan action, contain now, fix, verify).
# The action is the one-line entry in the Remediation Plan; the three steps
# are the numbered "What to Do" list in each finding.
_REMEDIATION_STEPS: Dict[str, Tuple[str, str, str, str]] = {
    "mitm": (
        "Isolate the impostor device and turn on ARP protection",
        "Find the switch port the impostor MAC is connected to (switch MAC address table) and isolate it, then clear the ARP caches of the affected hosts.",
        "Enable Dynamic ARP Inspection or port security on the OT switch ports, and add static ARP entries for critical controller/HMI pairs.",
        "Check controller logic, setpoints, and recent writes against a known-good backup, then recapture and confirm each affected IP is claimed by only one MAC.",
    ),
    "sis": (
        "Confirm who is talking to the safety controller",
        "Confirm the host is the approved SIS engineering workstation and that a change was planned; if not, disconnect it from the safety network and inform operations and the process safety owner.",
        "Keep the controller's key switch in RUN except during approved changes, keep the safety network separate from control and IT networks, and allow TriStation (UDP 1502) only from the SIS engineering workstation.",
        "Compare the safety controller's program and configuration with the last approved backup, and recapture to confirm only the approved workstation talks to it.",
    ),
    "replay": (
        "Find the host injecting the extra responses",
        "Compare the Ethernet source MAC and TTL of the extra responses with the genuine server's to find the sender, and isolate it unless it is a known protocol gateway.",
        "Close the injection path: look for ARP spoofing on the segment and enable Dynamic ARP Inspection or port security on the OT switch ports.",
        "Compare the values the HMI displayed with the controller's own readings, then recapture and confirm each request gets exactly one response.",
    ),
    "restart": (
        "Confirm who stopped, restarted, or silenced the controller",
        "Ask operations whether the command came from an approved engineering host during a documented maintenance window; if not, block that host's access to the controller.",
        "Allow restart, stop, and reporting-control commands only from the designated engineering workstation (firewall or switch ACL), and turn on the controller's own access protection where it has one.",
        "Check the controller's mode, configuration, and event log for changes around the event, and confirm unsolicited reporting is enabled again if it was turned off.",
    ),
    "value_anomaly": (
        "Check the reported values against the real process",
        "Compare the reported values with the controller's own display and the field instruments to decide whether the process or the network data is wrong.",
        "If the network values were spoofed, find and isolate the injecting host (check the segment for ARP spoofing); if the process really changed, hand over to operations.",
        "Recapture during normal operation and confirm the register values track the process again.",
    ),
    "dos": (
        "Stop the flood and protect the controller",
        "Identify the flooding host and block it at its switch port or the firewall.",
        "Limit which hosts can reach the controller's service ports, and rate-limit new connections to it where the network equipment supports it.",
        "Ask operations whether HMIs lost communication during the window, then recapture and confirm the controller answers its HMIs normally.",
    ),
    "file_transfer": (
        "Control program and firmware transfers",
        "Confirm the transfer was an approved change; if not, isolate the source host and compare the controller's program or firmware with a known-good backup.",
        "Allow program and firmware transfers only from authenticated engineering workstations, and disable unneeded FTP, TFTP, SMB, or web download functions on PLC-facing systems.",
        "Recapture and confirm transfers come only from the approved engineering workstation.",
    ),
    "write": (
        "Restrict who can write to the controllers",
        "Ask operations whether each writing host is an approved HMI or engineering workstation, and block any that is not at its switch port or the firewall.",
        "Allow write functions only from the approved HMI and engineering hosts (firewall or switch ACL), and disable unused write services where the vendor allows it.",
        "Check the affected setpoints and outputs against their expected values, then recapture and confirm writes come only from the approved hosts.",
    ),
    "polling": (
        "Bring the polling client back to its approved scan rate",
        "Identify the client creating the pattern and ask operations whether it is an approved HMI, historian, or engineering tool.",
        "Correct its scan list and polling rate to the approved configuration, and rate-limit or block clients that are not on the approved list.",
        "Recapture and confirm the polling rate and register list match the approved configuration.",
    ),
    "recon": (
        "Find and stop the scanning host",
        "Identify the scanning host and confirm whether it is an approved management station; if not, block its access to OT ports.",
        "Allow device discovery only from approved management stations, and disable discovery services the devices do not need.",
        "Tell operations that device enumeration occurred, then recapture and confirm the scanning has stopped.",
    ),
    "c2": (
        "Investigate the host for compromise",
        "Block the external destination at the OT boundary, and isolate the source host if operations can run without it.",
        "Find the process creating the traffic, examine the host for compromise, and rebuild it from a known-good image if it is compromised.",
        "Recapture and confirm the host no longer contacts the destination before returning it to service.",
    ),
    "credentials": (
        "Change the exposed credentials",
        "Change the exposed or guessed credentials now, starting with administrative accounts.",
        "Remove default and shared passwords, give each person a unique role-based account, and turn off management interfaces that send credentials in cleartext.",
        "Confirm the old credentials no longer work and that logins now use an encrypted protocol.",
    ),
    "engineering": (
        "Limit engineering access to the designated workstation",
        "Confirm the engineering session was approved; if not, block the source host's access to the controller and compare the controller program with a known-good backup.",
        "Allow engineering protocols only from the designated engineering workstation, password-protect controller projects, and use the controller's memory-protect setting or run-mode key where available.",
        "Recapture and confirm engineering traffic comes only from the designated workstation during approved sessions.",
    ),
    "cleartext": (
        "Secure or restrict the unencrypted service",
        "Limit access to the service to the hosts that need it or a dedicated management subnet, and change any credentials seen in the capture.",
        "Enable the strongest authentication and encryption the device supports (for example HTTPS, SSH, SNMPv3, or TLS) and disable the insecure legacy access methods.",
        "Recapture and confirm the service now uses encryption or is no longer reachable from other hosts.",
    ),
    "boundary": (
        "Close the unapproved path between zones",
        "Confirm whether the cross-zone traffic is documented and required; if not, block it at the zone firewall.",
        "Put a firewall or industrial DMZ between the zones, permit only explicitly required ports, and force remote administration through an approved jump host.",
        "Recapture and confirm only the documented flows cross the boundary.",
    ),
    "it_noise": (
        "Turn off broadcast name resolution on OT hosts",
        "Identify the hosts sending these broadcasts (usually Windows HMIs or engineering workstations).",
        "Disable LLMNR, NetBIOS over TCP/IP, mDNS, SSDP, and WS-Discovery on those hosts with Group Policy, or filter them at the OT switch.",
        "Recapture and confirm the broadcasts have stopped.",
    ),
    "dhcp": (
        "Remove the unauthorized DHCP server",
        "Find the switch port of the unauthorized DHCP server and disconnect it.",
        "Enable DHCP snooping on the OT switches so only the approved server's port can hand out addresses.",
        "Check that clients which took an address from it have the correct gateway and DNS settings, and recapture to confirm only the approved server answers.",
    ),
    "tcp_anomaly": (
        "Find out why the connections fail",
        "Identify the client and the service involved, and block the client if it is an unapproved scanner.",
        "Fix the client or service configuration so control sessions stop failing.",
        "Recapture and confirm the resets or unanswered connection attempts have stopped.",
    ),
    "ipv6": (
        "Disable or manage IPv6 on OT hosts",
        "Identify the hosts sending IPv6 and confirm whether the site uses IPv6 at all.",
        "If IPv6 is not used, disable it on the OT hosts or block it at the switch; if it is used, add it to the firewall rules and monitoring.",
        "Recapture and confirm IPv6 traffic is gone or matches the documented design.",
    ),
    "icmp": (
        "Limit ICMP to approved monitoring hosts",
        "Identify the hosts sending ICMP to the controllers and confirm whether they are approved monitoring systems.",
        "Allow ICMP only from approved monitoring hosts, at the OT boundary and in switch ACLs.",
        "Recapture and confirm the controllers answer only the systems that need to reach them.",
    ),
    "time": (
        "Synchronize OT clocks to an internal time source",
        "Check the clock and time-source settings on the affected devices.",
        "Point OT devices to a local internal time source and block direct queries to public time servers from the control network.",
        "Confirm device clocks agree with the reference within the site's tolerance, and recapture to confirm time queries go only to the internal source.",
    ),
    "capture": (
        "Retake the capture",
        "Treat findings for the affected capture as incomplete coverage.",
        "Retake the capture with a longer window or from a better vantage point.",
        "Confirm the capture appliance or SPAN port reported no dropped packets during the new capture.",
    ),
    "av": (
        "Separate audio/video systems from control traffic",
        "Ask the site which camera, DVR/NVR, intercom, or VoIP systems these are and who manages them.",
        "Move them onto a dedicated VLAN separated from control traffic, enable IGMP snooping where multicast video is used, and bring camera and DVR firmware under patch management.",
        "Recapture and confirm the audio/video traffic no longer shares the control network.",
    ),
    "wireless": (
        "Secure the wireless control network",
        "Confirm every wireless controller and node is in the asset inventory, and remove unknown devices.",
        "Enable the protocol's link-layer security and restrict device enrollment.",
        "Recapture and confirm only enrolled devices communicate, using encrypted frames.",
    ),
    "dns": (
        "Restrict name resolution from OT devices",
        "Identify which OT devices resolve names and which servers they query.",
        "Point OT devices only to approved internal DNS servers, or remove DNS access from controllers that should work by IP address only.",
        "Recapture and confirm DNS queries go only to the approved internal servers.",
    ),
    "absence": (
        "Confirm what the capture could see",
        "Ask site staff whether the expected devices were online during the capture.",
        "Retake the capture from a better vantage point, and compare the expected protocol flows with the firewall rules and switch layout.",
        "Confirm the expected traffic appears in the new capture.",
    ),
    "unknown": (
        "Identify the unknown service",
        "Ask the device owner which application uses the port.",
        "Document the service in the communication matrix if it is needed, and block it if it is not.",
        "Recapture and confirm only documented services remain.",
    ),
}

