# the analyst can paste into Wireshark, plus 1-3 numbered steps for what
# to look at.  Evidence lines in this report carry "@<epoch>" tags so
# analysts can additionally use `frame.time_epoch == <value>` to jump
# directly to the corresponding frame.
# ----------------------------------------------------------------------
