_WIRESHARK_FALLBACK: Tuple[str, List[str]] = ("", [
    "Open the listed source pcap(s) in Wireshark.",
    "Each evidence line in this report ends with `@<epoch>` — paste that into the display filter as `frame.time_epoch == <value>` to jump to the exact frame.",
    "Right-click the highlighted frame → 'Follow → TCP/UDP Stream' to see the full conversation and confirm intent.",
    "Use 'Statistics → Conversations' to enumerate every flow involving the source and destination IPs.",
])


def wireshark_guide_for(finding: "Finding") -> Optional[Tuple[str, List[str]]]:
    """Return the specific (display_filter, steps) guide for a finding, or None."""
    haystack = " ".join([
        finding.title.lower(),
        " ".join(finding.tags).lower(),
        finding.protocol.lower(),
        finding.category.lower(),
    ])
    for keys, dfilter, steps in _WIRESHARK_GUIDE:
        if any(k in haystack for k in keys):
            return dfilter, steps
    return None


def wireshark_steps_for_finding(finding: "Finding") -> Tuple[str, List[str]]:
    """Return (display_filter, steps[]) for investigating this finding in
    Wireshark, falling back to generic guidance when no entry matches.
    """
    return wireshark_guide_for(finding) or _WIRESHARK_FALLBACK


def related_findings_for_finding(session: "SessionState", finding: "Finding", limit: int = 3) -> List[str]:
    """Return a short list of findings related by IP, protocol, or tags."""
    related: List[str] = []
    finding_ips = set(finding.source_ips + finding.destination_ips)
    finding_tags = set(finding.tags)
    for candidate in session.findings:
        if candidate.finding_id == finding.finding_id:
            continue
        candidate_ips = set(candidate.source_ips + candidate.destination_ips)
        shared_ips = finding_ips.intersection(candidate_ips)
        shared_tags = finding_tags.intersection(candidate.tags)
        same_protocol = finding.protocol and finding.protocol == candidate.protocol
        if shared_ips or shared_tags or same_protocol:
            related.append(candidate.title)
        if len(related) >= limit:
            break
    return related


def lead_sentences(text: str, count: int = 2) -> str:
    """Return the first `count` sentences of a description."""
    sentences = re.split(r"(?<=[.!?])\s+(?=[A-Z])", text.strip())
    return " ".join(sentences[:count])


def sentences_after(text: str, count: int = 1) -> str:
    """Return a description without its first `count` sentences."""
    sentences = re.split(r"(?<=[.!?])\s+(?=[A-Z])", text.strip())
    return " ".join(sentences[count:])


def correlation_summary_lines(session: "SessionState") -> List[str]:
    """Build a compact summary of related/high-order findings.

    The first lines are reserved for plain-English attack-chain narratives
    derived from co-occurring intrusion-class findings, so a SOC operator
    opening the report sees the story before the raw correlation list.
    """
    lines: List[str] = []

    # ---- Attack-chain narratives (top of summary) ----
    # MITM chain: emit a single human-readable sentence when the
    # combined-signal MITM finding fired.
    mitm_findings = [f for f in session.findings if "mitm" in f.tags]
    for f in sorted(mitm_findings, key=lambda item: SEVERITY_ORDER.get(item.severity, 0), reverse=True)[:3]:
        prefix = "⚠ ACTIVE ATTACK" if f.severity == SEVERITY_INTRUSION else "⚠ ATTACK POSITION"
        lines.append(f"{prefix}: {lead_sentences(f.description, 2)}")

    correlated = [
        finding for finding in session.findings
        if finding.severity in {SEVERITY_CORRELATION, SEVERITY_INTRUSION} or "boundary" in finding.tags
    ]
    # Skip MITM findings here — they were already narrated above.
    for finding in correlated:
        if "mitm" in finding.tags:
            continue
        if len(lines) >= 10:
            break
        endpoints = ", ".join(finding.source_ips[:2] + finding.destination_ips[:2]) or finding.protocol
        lines.append(f"{finding.title}: {endpoints}")
    source_counter: Counter[str] = Counter()
    for finding in session.findings:
        for ip_text in finding.source_ips:
            source_counter[ip_text] += 1
    for ip_text, count in source_counter.most_common(5):
        if len(lines) >= 12:
            break
        if count >= 3:
            lines.append(f"{ip_text} appears in {count} findings and may be a key pivot or misconfigured node.")
    return lines[:12]


def aggregated_report_issues(session: "SessionState", categories: Optional[Sequence[str]] = None) -> List[Dict[str, Any]]:
    """Aggregate findings into report-friendly issue sections."""
    category_filter = set(categories or [])
    grouped: Dict[Tuple[str, str], Dict[str, Any]] = {}
    for finding in session.findings:
        if category_filter and finding.category not in category_filter:
            continue
        key = (finding.category, finding.title)
        if key not in grouped:
            grouped[key] = {
                "category": finding.category,
                "title": finding.title,
                "severity": finding.severity,
                "description": finding.description,
                "evidence": [],
                "source_ips": set(),
                "destination_ips": set(),
                "source_pcaps": set(),
                "protocols": set(),
                "findings": [],
            }
        issue = grouped[key]
        if SEVERITY_ORDER.get(finding.severity, 0) > SEVERITY_ORDER.get(issue["severity"], 0):
            issue["severity"] = finding.severity
        issue["source_ips"].update(finding.source_ips)
        issue["destination_ips"].update(finding.destination_ips)
        issue["source_pcaps"].update(finding.source_pcaps)
        if finding.protocol:
            issue["protocols"].add(finding.protocol)
        issue["findings"].append(finding)
        for line in finding.evidence:
            if line and line not in issue["evidence"]:
                issue["evidence"].append(line)
    issues = list(grouped.values())
    issues.sort(key=lambda item: (SEVERITY_ORDER.get(item["severity"], 0), item["category"], item["title"]), reverse=True)
    return issues


def report_issue_ids(report_issues: Sequence[Dict[str, Any]]) -> Dict[Tuple[str, str], str]:
    """Number report issues per category prefix (e.g. NET-001), in report order."""
    issue_ids: Dict[Tuple[str, str], str] = {}
    id_counters: Dict[str, int] = defaultdict(int)
    for issue in report_issues:
        prefix = _finding_id_prefix(issue["category"])
        id_counters[prefix] += 1
        issue_ids[(issue["category"], issue["title"])] = f"{prefix}-{id_counters[prefix]:03d}"
    return issue_ids


# Remediation priority by severity: (priority, label, severities).
_PLAN_PRIORITIES: List[Tuple[int, str, Tuple[str, ...]]] = [
    (1, "Act now", (SEVERITY_INTRUSION, SEVERITY_CRITICAL)),
    (2, "This week", (SEVERITY_CORRELATION, SEVERITY_HIGH)),
    (3, "Next maintenance window", (SEVERITY_MEDIUM,)),
    (4, "Backlog", (SEVERITY_LOW, SEVERITY_INFO)),
]


def plan_priority(severity: str) -> Tuple[int, str]:
    """Map a severity to its remediation priority number and label."""
    for priority, label, severities in _PLAN_PRIORITIES:
        if severity in severities:
            return priority, label
    return _PLAN_PRIORITIES[-1][0], _PLAN_PRIORITIES[-1][1]


def _ip_sort_key(text: str) -> Tuple[int, int, str]:
    try:
        address = ipaddress.ip_address(text.split("%")[0])
        return address.version, int(address), text
    except ValueError:
        return 9, 0, text


def build_remediation_plan(report_issues: Sequence[Dict[str, Any]],
                           issue_ids: Dict[Tuple[str, str], str]) -> List[Dict[str, Any]]:
    """Combine report issues that share the same fix into prioritized plan rows.

    A row takes the most urgent priority among the findings it covers.  Rows
    are ordered by priority, then by the most severe finding they cover, then
    by how many findings they cover.  Device lists are capped at 50
    (`device_count` keeps the full number).
    """
    rows: Dict[Tuple[Any, ...], Dict[str, Any]] = {}
    for issue in report_issues:
        steps = remediation_for_finding(issue["findings"][0])
        priority, label = plan_priority(issue["severity"])
        key = (steps["action"], steps["contain"], steps["fix"], steps["verify"])
        row = rows.get(key)
        if row is None:
            row = rows[key] = {
                "priority": priority,
                "priority_label": label,
                "action": steps["action"],
                "steps": {"contain": steps["contain"], "fix": steps["fix"], "verify": steps["verify"]},
                "ot_safety_note": steps["safety"],
                "owner": steps["owner"],
                "top_severity": issue["severity"],
                "devices": set(),
                "findings": [],
            }
        if priority < row["priority"]:
            row["priority"], row["priority_label"] = priority, label
        if SEVERITY_ORDER.get(issue["severity"], 0) > SEVERITY_ORDER.get(row["top_severity"], 0):
            row["top_severity"] = issue["severity"]
        row["devices"].update(issue["source_ips"])
        row["devices"].update(issue["destination_ips"])
        row["findings"].append({"id": issue_ids.get((issue["category"], issue["title"]), ""),
                                "title": issue["title"], "severity": issue["severity"]})
    plan = sorted(rows.values(), key=lambda row: (row["priority"], -SEVERITY_ORDER.get(row["top_severity"], 0),
                                                  -len(row["findings"]), row["action"]))
    for row in plan:
        devices = sorted(row["devices"], key=_ip_sort_key)
        row["device_count"] = len(devices)
        row["devices"] = devices[:50]
    return plan


def occurrence_label(finding: "Finding") -> str:
    """Name what one finding involves: "source → destination", one host, or the capture file."""
    def _ips(ips: Sequence[str]) -> str:
        return ", ".join(ips[:3]) + (f" (+{len(ips) - 3} more)" if len(ips) > 3 else "")
    source, destination = _ips(finding.source_ips), _ips(finding.destination_ips)
    if source and destination:
        return f"{source} → {destination}"
    return source or destination or ", ".join(finding.source_pcaps[:2]) or finding.protocol or finding.title


class TSharkError(RuntimeError):
    """Raised when a tshark subprocess call fails."""


# Captures that ended mid-packet (or hit a corrupt record).  tshark still
# yields every complete packet before the damage, so these are analyzed
# normally and only flagged — truncation is routine for field captures.
_PARTIAL_READ_MARKERS = ("cut short in the middle of a packet", "appears to be damaged or corrupt")
_PARTIAL_CAPTURES: Dict[str, str] = {}


def run_tshark(display_filter: str, fields: Sequence[str], pcap_file: Path) -> List[Dict[str, str]]:
    """Run tshark and return structured rows for one pcap file."""
    rows = list(iter_tshark_rows(display_filter, fields, pcap_file))
    return rows


_TSHARK_FIELD_NAMES: Optional[set] = None


def _tshark_field_names() -> set:
    """Field and protocol names this tshark build knows (empty set if unknown).

    tshark rejects an entire command when any -e field is missing from the
    build, so fields are filtered against this list first and missing ones
    simply read as empty.
    """
    global _TSHARK_FIELD_NAMES
    if _TSHARK_FIELD_NAMES is None:
        names: set = set()
        try:
            result = subprocess.run(["tshark", "-G", "fields"], capture_output=True, text=True,
                                    encoding="utf-8", errors="replace", timeout=120)
            for line in result.stdout.splitlines():
                parts = line.split("\t")
                if len(parts) >= 3 and parts[0] in ("F", "P"):
                    names.add(parts[2])
        except (OSError, subprocess.SubprocessError):
            names = set()
        _TSHARK_FIELD_NAMES = names
    return _TSHARK_FIELD_NAMES


def iter_tshark_rows(display_filter: str, fields: Sequence[str], pcap_file: Path) -> Iterable[Dict[str, str]]:
    """Stream tshark field output as dictionaries (every requested key present)."""
    known_fields = _tshark_field_names()
    requested = [name for name in fields if not known_fields or name in known_fields or name.startswith("_ws.")]
    command = [
        "tshark",
        # -n disables ALL name resolution (MAC/network/transport). Without
        # this, tshark may issue PTR queries from your machine for every
        # IP address parsed out of the capture — which would be visible
        # to whoever owns the IP block being looked up. See OFFLINE_MODE
        # docstring at top of file for the full network-safety contract.
        "-n",
        "-r",
        str(pcap_file),
        "-T",
        "fields",
        "-E",
        "separator=\t",
        "-E",
        "quote=n",
        "-E",
        "occurrence=f",
    ]
    if display_filter:
        command.extend(["-Y", display_filter])
    for field_name in requested:
        command.extend(["-e", field_name])
    missing = [name for name in fields if name not in requested]
    # Redirect stderr to a spooled temp file (in-memory up to 1 MB,
    # disk-backed beyond) instead of subprocess.PIPE.  This avoids the
    # pipe-fills-and-tshark-blocks deadlock that occurs on noisy captures
    # where tshark prints many dissector warnings: a 64 KB pipe fills,
    # tshark blocks on write, and we never read it because we're still
    # consuming stdout.  A temp file never blocks the writer.
    stderr_tmp = tempfile.SpooledTemporaryFile(max_size=1024 * 1024, mode="w+b")
    process = subprocess.Popen(
        command,
        stdout=subprocess.PIPE,
        stderr=stderr_tmp,
        text=True,
        encoding="utf-8",
        errors="replace",
    )
    assert process.stdout is not None
    completed_normally = False
    try:
        for line in process.stdout:
            line = line.rstrip("\n")
            values = line.split("\t")
            if len(values) < len(requested):
                values.extend([""] * (len(requested) - len(values)))
            elif len(values) > len(requested):
                values = values[: len(requested)]
            row = {requested[index]: values[index].strip() for index in range(len(requested))}
            for name in missing:
                row[name] = ""
            yield row
        completed_normally = True
    finally:
        # Always tear down the subprocess — even if the caller broke out
        # of the loop early or threw an exception.  Without this, tshark
        # keeps running until Python's GC eventually closes our pipe
        # fds, which can leave zombie tshark processes consuming CPU
        # for many seconds after the caller "moved on".
        try:
            process.stdout.close()
        except Exception:
            pass
        if process.poll() is None:
            try:
                process.wait(timeout=5)
            except subprocess.TimeoutExpired:
                process.terminate()
                try:
                    process.wait(timeout=2)
                except subprocess.TimeoutExpired:
                    process.kill()
                    try:
                        process.wait(timeout=2)
                    except subprocess.TimeoutExpired:
                        pass
        # Surface stderr only on a clean-iteration failure; if the caller
        # abandoned the generator we don't raise (they're already on a
        # different path).
        try:
            stderr_tmp.seek(0)
            stderr_text = stderr_tmp.read().decode("utf-8", errors="replace").strip()
        except Exception:
            stderr_text = ""
        finally:
            try:
                stderr_tmp.close()
            except Exception:
                pass
        if completed_normally and process.returncode not in (0, None):
            if any(marker in stderr_text for marker in _PARTIAL_READ_MARKERS):
                if str(pcap_file) not in _PARTIAL_CAPTURES:
                    _PARTIAL_CAPTURES[str(pcap_file)] = stderr_text.splitlines()[-1] if stderr_text else ""
                    print(colorize(
                        f"[!] {pcap_file.name}: capture ends with a truncated or damaged record — "
                        "every complete packet before it is analyzed.", SEVERITY_MEDIUM))
            else:
                raise TSharkError(stderr_text or f"tshark failed for {pcap_file}")


BASE_PACKET_FIELDS = [
    "frame.time_epoch",
    "frame.len",
    "frame.protocols",
    "ip.src",
    "ip.dst",
    "ipv6.src",
    "ipv6.dst",
    "eth.src",
    "eth.dst",
    "vlan.id",
    "tcp.srcport",
    "tcp.dstport",
    "udp.srcport",
    "udp.dstport",
    # ARP detail fields — used by check_network_hygiene ARP spoof detection.
    # Empty on non-ARP frames, so cost is a single extra comma in the output.
    "arp.opcode",
    "arp.src.hw_mac",
    "arp.src.proto_ipv4",
    "arp.dst.hw_mac",
    "arp.dst.proto_ipv4",
    # Passive OS fingerprint helpers — empty on non-TCP-SYN frames; cheap to include.
    "tcp.flags",
    "tcp.window_size_value",
    "ip.ttl",
    "_ws.col.Protocol",
    "_ws.col.Info",
    # JA3 fingerprint — empty on non-TLS frames; used by JA3 known-bad check.
    "tls.handshake.ja3",
    # Modbus register value tracking — empty on non-Modbus frames; cheap to include.
    "modbus.reference_num",
    "modbus.regval_uint16",
    # IoT wireless protocol fields — empty on non-matching frames; cheap to include.
    "zbee_nwk.security",   # Zigbee: 0 = unencrypted, 1 = security header present
    "coap.code",           # CoAP: method code (e.g. "0.03" PUT, "0.02" POST)
    # Audio/Video streaming — RTP payload type (empty on non-RTP frames).
    # 0-23 audio, 24-34 video (33 = MPEG-TS mux), >=96 dynamic (H.264/Opus/...).
    "rtp.p_type",
    # Structured protocol fields.  Detectors read these instead of parsing the
    # Info column, which never carries credentials, cipher suites, community
    # strings, or transaction IDs.  All are empty on unrelated frames.
    "ip.id",
    "mbtcp.trans_id",
    "mbtcp.unit_id",
    "modbus.func_code",
    "modbus.exception_code",
    "dnp3.dst",
    "dnp3.al.func",
    "bacapp.type",
    "iec60870_asdu.typeid",
    "iec60870_asdu.causetx",
    "s7comm.header.rosctr",
    "tcp.seq",
    "tcp.len",
    "mqtt.msgtype",
    "mqtt.clientid",
    "mqtt.conflag.uname",
    "mqtt.topic",
    "mqtt.retain",
    "snmp.version",
    "snmp.community",
    "snmp.data",
    "tls.handshake.type",
    "tls.handshake.version",
    "tls.handshake.ciphersuite",
    "tls.handshake.extensions.supported_version",
    "tls.alert_message.desc",
    "opcua.MessageSecurityMode",
    "opcua.security.spu",
    "rtsp.method",
    "rtsp.status",
    "http.response.code",
    "http.authorization",
]

# Superset used only for checks that need payload content (legacy, artifact extraction).
# Requesting payload bytes is expensive; do not add to BASE_PACKET_FIELDS.
PAYLOAD_PACKET_FIELDS = BASE_PACKET_FIELDS + [
    "tcp.payload",
    "udp.payload",
    "data.data",
    "http.user_agent",
    "http.server",
    "http.request.method",
    "http.host",
    "mqtt.username",
    "mqtt.passwd",
]


def _tcp_flag_bits(row: Dict[str, str]) -> int:
    """Return the TCP flags of a row as an int (0 for non-TCP rows)."""
    try:
        return int(row.get("tcp.flags") or "0", 16)
    except ValueError:
        return 0


def _int_field(row: Dict[str, str], name: str, default: int = -1) -> int:
    """Parse a numeric tshark field (decimal or 0x-hex); `default` when absent.

    Fields that occur more than once in a frame arrive comma-separated; the
    first occurrence is used.
    """
    text = (row.get(name) or "").split(",")[0].strip()
    if not text:
        return default
    try:
        return int(text, 0)
    except ValueError:
        return default


_CIPHER_NAMES: Optional[Dict[int, str]] = None


def tls_cipher_name(code: int) -> str:
    """Return the IANA name of a TLS cipher suite from tshark's value table (offline)."""
    global _CIPHER_NAMES
    if _CIPHER_NAMES is None:
        names: Dict[int, str] = {}
        try:
            result = subprocess.run(["tshark", "-G", "values"], capture_output=True, text=True,
                                    encoding="utf-8", errors="replace", timeout=120)
            for line in result.stdout.splitlines():
                parts = line.split("\t")
                if len(parts) >= 4 and parts[0] == "V" and parts[1] == "tls.handshake.ciphersuite":
                    try:
                        names[int(parts[2], 0)] = parts[3]
                    except ValueError:
                        continue
        except (OSError, subprocess.SubprocessError):
            names = {}
        _CIPHER_NAMES = names
    return _CIPHER_NAMES.get(code, f"0x{code:04x}")


def weak_cipher_label(name: str) -> str:
    """Classify a cipher-suite name as weak; '' when it is acceptable."""
    upper = name.upper()
    for marker, label in (("_NULL_", "NULL"), ("_ANON_", "anonymous"), ("EXPORT", "EXPORT"), ("RC4", "RC4"),
                          ("3DES", "3DES"), ("DES_CBC", "DES"), ("_MD5", "MD5")):
        if marker in upper or upper.endswith(marker.rstrip("_")):
            return label
    return ""


_TLS_VERSION_NAMES = {0x0002: "SSLv2", 0x0300: "SSLv3", 0x0301: "TLS 1.0", 0x0302: "TLS 1.1",
                      0x0303: "TLS 1.2", 0x0304: "TLS 1.3"}


def row_source_ip(row: Dict[str, str]) -> str:
    """Return the best source IP for a tshark row."""
    return row.get("ip.src") or row.get("ipv6.src") or ""


def row_destination_ip(row: Dict[str, str]) -> str:
    """Return the best destination IP for a tshark row."""
    return row.get("ip.dst") or row.get("ipv6.dst") or ""


def row_destination_port(row: Dict[str, str]) -> int:
    """Return the destination port if present."""
    port_text = row.get("tcp.dstport") or row.get("udp.dstport") or "0"
    try:
        return int(port_text)
    except ValueError:
        return 0


def row_source_port(row: Dict[str, str]) -> int:
    """Return the source port if present."""
    port_text = row.get("tcp.srcport") or row.get("udp.srcport") or "0"
    try:
        return int(port_text)
    except ValueError:
        return 0


def payload_bytes_from_row(row: Dict[str, str]) -> bytes:
    """Return the best-effort decoded payload bytes for a tshark row."""
    hex_text = row.get("tcp.payload") or row.get("udp.payload") or row.get("data.data") or ""
    hex_text = re.sub(r"[^0-9A-Fa-f]", "", hex_text)
    if len(hex_text) < 2:
        return b""
    if len(hex_text) % 2 == 1:
        hex_text = hex_text[:-1]
    try:
        return bytes.fromhex(hex_text)
    except ValueError:
        return b""


def printable_strings_from_bytes(payload: bytes, minimum_length: int = 4) -> List[str]:
    """Extract printable ASCII strings from raw bytes."""
    if not payload:
        return []
    text = "".join(chr(byte) if 32 <= byte <= 126 else " " for byte in payload)
    return [item.strip() for item in re.findall(rf"[ -~]{{{minimum_length},}}", text) if item.strip()]


def condensed_string_samples(payload: bytes, minimum_length: int = 3, limit: int = 4) -> List[str]:
    """Extract a few concise printable strings suitable for reports."""
    samples: List[str] = []
    for item in printable_strings_from_bytes(payload, minimum_length=minimum_length):
        cleaned = re.sub(r"\s+", " ", item).strip()
        if len(cleaned) < minimum_length:
            continue
        if cleaned.lower() in {"telnet", "http", "ftp", "tcp", "udp"}:
            continue
        if len(cleaned) > 120:
            cleaned = cleaned[:117] + "..."
        if cleaned not in samples:
            samples.append(cleaned)
        if len(samples) >= limit:
            break
    return samples


def protocol_family_from_row(row: Dict[str, str]) -> str:
    """Best-effort protocol family inference from a tshark row."""
    protocol_text = (row.get("_ws.col.Protocol") or "").strip()
    info_text = (row.get("_ws.col.Info") or "").strip().lower()
    frame_protocols = (row.get("frame.protocols") or "").lower()
    if "modbus" in protocol_text.lower() or "modbus" in frame_protocols:
        return "Modbus TCP"
    if "bacnet" in protocol_text.lower() or "bacnet" in frame_protocols:
        return "BACnet/IP"
    if "dnp3" in protocol_text.lower() or "dnp3" in frame_protocols:
        return "DNP3"
    if "mqtt" in protocol_text.lower() or "mqtt" in frame_protocols:
        return "MQTT"
    if "opcua" in protocol_text.lower() or "opcua" in frame_protocols or "opc ua" in info_text:
        return "OPC-UA"
    if "cip" in protocol_text.lower() or "enip" in frame_protocols or "ethernet/ip" in info_text:
        return "EtherNet/IP"
    if "s7comm" in protocol_text.lower() or "profinet" in protocol_text.lower() or "s7" in frame_protocols:
        return "Siemens S7 / PROFINET"
    if "goose" in protocol_text.lower() or "goose" in frame_protocols:
        return "IEC 61850 GOOSE"
    if "mms" in protocol_text.lower() or "mms" in frame_protocols:
        return "IEC 61850 MMS"
    if "rtsp" in protocol_text.lower():
        return "RTSP"
    if "sip" in protocol_text.lower():
        return "SIP (VoIP)"
    if "rtcp" in protocol_text.lower():
        return "RTP Media"
    if "rtmp" in protocol_text.lower():
        return "RTMP"
    if "rtp" in protocol_text.lower():
        return "RTP Media"
    if "mp2t" in protocol_text.lower() or "mp2t" in frame_protocols:
        return "MPEG-TS"
    if "gvcp" in protocol_text.lower() or "gvsp" in protocol_text.lower():
        return "GigE Vision"
    if "http" in protocol_text.lower():
        return "HTTP"
    if "tls" in protocol_text.lower() or "ssl" in protocol_text.lower():
        return "TLS"
    if "dns" in protocol_text.lower():
        return "DNS"
    if "arp" in protocol_text.lower():
        return "ARP"
    if "icmp" in protocol_text.lower():
        return "ICMP"
    if frame_protocols.endswith(("udp", "udp:data")) and "1502" in (row.get("udp.srcport"), row.get("udp.dstport")):
        return "Triconex TriStation"
    if protocol_text:
        return protocol_text
    return "Unknown"


def select_pcaps_from_folder(folder: Path, exclude_filenames: Optional[Sequence[str]] = None) -> List[Path]:
    """List pcap files recursively and prompt the user to select some."""
    exclude = set(exclude_filenames or [])
    pcaps = sorted(
        [path for path in folder.rglob("*") if is_capture_file(path) and path.name not in exclude],
        key=lambda item: (str(item.parent), item.name.lower()),
    )
    if not pcaps:
        if exclude and any(is_capture_file(path) for path in folder.rglob("*")):
            print(f"[!] No new capture files in {folder} — every capture there is already in this session.")
        else:
            print(f"[!] No capture files were found in {folder}.")
        return []
    current_parent: Optional[Path] = None
    for index, path in enumerate(pcaps, start=1):
        if path.parent != current_parent:
            rel_parent = path.parent.relative_to(folder)
            print(f"\n  [{rel_parent or '.'}]")
            current_parent = path.parent
        print(f"    {index}. {path.name} ({human_size(path.stat().st_size)})")
    selection = prompt_input("Select files (all, 1 2 3, or 1-4)", "all")
    selection = selection.strip().lower()
    if selection == "all":
        return pcaps
    chosen: List[Path] = []
    for token in selection.replace(",", " ").split():
        if "-" in token:
            start_text, end_text = token.split("-", 1)
            try:
                start = int(start_text)
                end = int(end_text)
            except ValueError:
                continue
            for index in range(start, end + 1):
                if 1 <= index <= len(pcaps):
                    chosen.append(pcaps[index - 1])
        else:
            try:
                index = int(token)
            except ValueError:
                continue
            if 1 <= index <= len(pcaps):
                chosen.append(pcaps[index - 1])
    deduped: List[Path] = []
    seen = set()
    for path in chosen:
        if path not in seen:
            seen.add(path)
            deduped.append(path)
    return deduped


def collect_pcaps_from_path(path: Path) -> List[Path]:
    """Return all capture files under *path* without prompting.

    Accepts either a single capture file or a directory (searched recursively).
    """
    if path.is_file():
        if not is_capture_file(path):
            raise SystemExit(f"Not a capture file ({', '.join(CAPTURE_SUFFIXES)}): {path}")
        return [path]
    if not path.is_dir():
        raise SystemExit(f"Path not found: {path}")
    pcaps = sorted(
        [p for p in path.rglob("*") if is_capture_file(p)],
        key=lambda p: (str(p.parent), p.name.lower()),
    )
    if not pcaps:
        raise SystemExit(f"No pcap files found in: {path}")
    return pcaps


def discovery_questions() -> List[Tuple[str, str]]:
    """Return the environment discovery question set."""
    return [
        ("environment_type", "Environment type (e.g., manufacturing, power, water, physical security, building automation)"),
        ("expected_protocols",
         "Expected OT protocols — enter any that apply, comma-separated\n"
         "    OT:  modbus  bacnet  dnp3  iec61850  iec104  mqtt  opcua  enip  s7\n"
         "         omron   srtp    umas  melsec    historian  ignition  nodered  physical  tristation\n"
         "    IoT: zigbee  coap  zwave\n"
         "    A/V: voip  video  camera  cctv"),
        ("known_hmis", "Known HMI or engineering workstation IPs/hostnames (optional)"),
        ("air_gapped", "Is this environment air-gapped or isolated from the internet? (yes/no)"),
        ("baseline_file", "Baseline file to compare against (optional path, e.g. site_baseline.otpa_baseline)"),
        ("save_as_baseline", "After analysis, save this session's device/flow set AS a new baseline? (yes/no)"),
    ]


def ask_environment_questions(existing: Optional[Dict[str, str]] = None) -> Dict[str, str]:
    """Ask the structured environment discovery questions."""
    answers = dict(existing or {})
    print("[?] Environment discovery answers are optional. Press Enter to skip a question, or type S once to skip the rest.")
    skip_remaining = False
    for key, question in discovery_questions():
        if skip_remaining:
            answers.setdefault(key, "")
            continue
        current = answers.get(key, "")
        answer = prompt_input(question, current or None)
        if answer.strip().upper() == "S":
            skip_remaining = True
            answers[key] = current or ""
        else:
            answers[key] = answer
    return answers




