def _finding_id_prefix(category: str) -> str:
    """Return the short report ID prefix for a finding category."""
    return _CATEGORY_PREFIX_MAP.get(category, "FIND")


def detection_confidence_for_finding(finding: "Finding") -> str:
    """Estimate how confident the tool is that the detection is accurate."""
    family = narrative_family(finding)
    title = finding.title.lower()
    if family in ("absence", "unknown"):
        return "Low"
    if family in ("mitm", "write", "restart", "credentials", "engineering", "file_transfer", "cleartext", "ipv6", "icmp",
                  "it_noise", "dhcp", "av"):
        return "High"
    if family in ("polling", "value_anomaly") or any(t in title for t in ("register scanning", "public ip", "sweep", "walk")):
        return "High"
    if family in ("replay", "c2", "tcp_anomaly") or "possible" in title:
        return "Medium"
    return "Medium"


def maliciousness_confidence_for_finding(finding: "Finding") -> str:
    """Estimate how likely the detected behavior is malicious vs. operationally normal."""
    family = narrative_family(finding)
    if finding.severity == SEVERITY_INTRUSION:
        return "High"
    if family == "mitm":
        return "High" if finding.severity == SEVERITY_CRITICAL else "Low / Medium — requires site validation"
    if family in ("replay", "c2", "dos"):
        return "Medium"
    if family in ("polling", "recon"):
        return "Low — may be authorized maintenance"
    if family in ("cleartext", "credentials", "ipv6", "icmp", "it_noise", "boundary", "time", "capture", "av"):
        return "Low — a weakness or exposure rather than an attack"
    if family in ("absence", "unknown"):
        return "Unknown"
    if finding.severity == SEVERITY_CRITICAL:
        return "Medium"
    if finding.severity == SEVERITY_HIGH:
        return "Low / Medium — requires site validation"
    return "Unknown"


def ot_significance_for_finding(finding: "Finding") -> str:
    """Return an OT-focused explanation of why this finding matters to an IT auditor."""
    family = narrative_family(finding)
    if family in _OT_SIGNIFICANCE:
        return _OT_SIGNIFICANCE[family]
    return (
        "In OT environments, traffic anomalies that would be low-risk in IT can have direct "
        "consequences for physical processes, equipment, and safety.  This finding warrants "
        "validation with site personnel to determine whether it is authorized activity or a "
        "gap requiring remediation."
    )


def auditor_guidance_for_finding(finding: "Finding") -> List[str]:
    """Return 3–5 auditor action bullets for validating a finding."""
    family = narrative_family(finding)
    if family in _AUDITOR_GUIDANCE:
        return _AUDITOR_GUIDANCE[family]
    return [
        "Confirm with site personnel whether the observed behavior is expected and authorized.",
        "Cross-reference the source and destination IPs against the site's approved communication matrix.",
        "Request maintenance logs and change records covering the capture period.",
        "If the activity cannot be explained by normal operations, escalate for further investigation.",
    ]


def benign_explanation_for_finding(finding: "Finding") -> str:
    """One sentence describing what site context would make this finding benign."""
    family = narrative_family(finding)
    if family in _BENIGN_EXPLANATION:
        return _BENIGN_EXPLANATION[family]
    return "This finding would be benign if confirmed by site personnel as representing authorized, expected communications during normal or approved maintenance operations."


def build_network_interpretation_summary(session: "SessionState") -> List[str]:
    """Return a list of plain-English paragraphs interpreting observed network behavior."""
    paragraphs: List[str] = []
    devices = session.devices

    ot_initiators: List["DeviceRecord"] = []
    ot_responders: List["DeviceRecord"] = []
    it_noise_on_ot = any("it-on-ot" in finding.tags for finding in session.findings)

    for dev in devices.values():
        role = (dev.inferred_role or "").lower()
        if any(r in role for r in ("hmi", "engineering", "scada", "historian", "workstation")):
            ot_initiators.append(dev)
        elif any(r in role for r in ("plc", "rtu", "controller", "field device", "server")):
            ot_responders.append(dev)

    ot_initiators.sort(key=lambda d: d.outgoing_count + d.incoming_count, reverse=True)
    ot_responders.sort(key=lambda d: d.outgoing_count + d.incoming_count, reverse=True)

    if ot_initiators:
        init_text = ", ".join(
            f"{d.ip} ({d.inferred_role})" for d in ot_initiators[:3]
        )
        paragraphs.append(
            f"Likely OT communication initiators (HMI / SCADA / engineering workstations): "
            f"{init_text}.  These hosts generated the majority of outbound OT protocol traffic "
            f"and appear to represent the control or management tier.  Validate their roles "
            f"with site staff before treating them as confirmed sources."
        )

    if ot_responders:
        resp_text = ", ".join(
            f"{d.ip} ({d.inferred_role})" for d in ot_responders[:3]
        )
        paragraphs.append(
            f"Likely OT servers / controllers (PLCs, RTUs, field devices): "
            f"{resp_text}.  These hosts predominantly responded to requests on OT protocol "
            f"ports and appear to represent the field or control layer.  Validate physical "
            f"device identification with site staff."
        )

    if it_noise_on_ot:
        paragraphs.append(
            "IT-style discovery protocols (mDNS, LLMNR, NetBIOS, SSDP, WS-Discovery) were observed "
            "on subnets that hold OT devices.  Windows-based HMIs and engineering workstations emit "
            "these by default, but they can also indicate insufficient segmentation between IT and "
            "OT zones or unauthorized IT devices on OT subnets."
        )

    ephemeral_count = sum(
        1 for c in session.connections.values()
        if c.destination_port and int(c.destination_port) > 49151
    )
    if ephemeral_count > 10:
        paragraphs.append(
            f"{ephemeral_count:,} flows reach services on dynamic-range ports (above 49151).  "
            "Flow direction is taken from the TCP handshake or the well-known service port, so "
            "these are real listeners on high ports — typically Windows RPC/DCOM endpoints (for "
            "example OPC DA), RTP media, or vendor protocols.  Fixed-port firewall rules cannot "
            "describe them; review with the site which of them are expected."
        )

    observed = [(dev.ip, note) for dev in devices.values() for note in dev.evidence]
    if observed:
        paragraphs.append(
            "Host observations from the analysis: "
            + "; ".join(f"{ip_text} — {note}" for ip_text, note in observed[:8])
            + "."
        )

    folded = [(address, dev.ip) for dev in devices.values() for address in dev.ipv6_addresses]
    if folded:
        paragraphs.append(
            "IPv6 link-local addresses matched to their IPv4 hosts by MAC address: "
            + ", ".join(f"{address} → {ip_text}" for address, ip_text in folded[:10])
            + ".  They are listed under the IPv4 host in the device inventory."
        )

    groups = session.analysis_metadata.get("group_addresses") or {}
    if groups:
        ranked = sorted(groups.items(), key=lambda item: -item[1].get("packets", 0))
        parts = []
        for address, info in ranked[:10]:
            protocols = ", ".join(info.get("protocols", [])[:3])
            senders = ", ".join(info.get("senders", [])[:3])
            detail = "; ".join(part for part in (protocols, f"from {senders}" if senders else "") if part)
            parts.append(f"{address} ({detail})" if detail else address)
        paragraphs.append(
            f"Broadcast and multicast destinations ({len(groups)}), which are not hosts and are kept out of the "
            "device inventory: " + ", ".join(parts) + ("…" if len(groups) > 10 else "") + "."
        )

    paragraphs.append(
        "Network zone assignments and device roles above are inferred from traffic patterns "
        "alone.  Validate all device identifications against the site's network documentation, "
        "asset register, and physical inspection before using this summary in a formal finding.  "
        "Confirm whether all observed communication paths appear in the site's approved "
        "communication matrix."
    )

    if not paragraphs:
        paragraphs.append(
            "Insufficient traffic was observed to draw meaningful conclusions about OT network "
            "roles and communication patterns.  Consider retaking the capture from a point with "
            "visibility to OT protocol traffic."
        )

    return paragraphs


class OTPcapAnalyzer:
    """Main application controller for the OT PCAP Analyzer."""

    def __init__(self, config: Dict[str, Any]) -> None:
        self.config = config
        self.session: Optional[SessionState] = None
        self.packet_fingerprint_set: set[str] = set()
        self.finding_index: Dict[str, Finding] = {}
        self.public_ip_cache: Dict[str, Dict[str, str]] = {}
        # TCP connections whose SYN was seen: endpoint pair -> server endpoint.
        self._tcp_servers: Dict[Tuple[Tuple[str, int], Tuple[str, int]], Tuple[str, int]] = {}
        self._host_address_cache: Dict[str, bool] = {}
        # (detector, new findings, reason it was skipped) for the current protocol pass.
        self._detector_results: List[Tuple[str, int, str]] = []
        # Files written during this run, with what each is for (end-of-run summary).
        self.artifacts_written: List[Tuple[Path, str]] = []

    def _note_artifact(self, path: Path, description: str, label: str, detail: str = "") -> None:
        """Remember a written file for the end-of-run summary and announce it."""
        self.artifacts_written = [item for item in self.artifacts_written if item[0] != path]
        self.artifacts_written.append((path, description))
        print(colorize(f"[✓] {label}: {path.name}{detail}", "SUCCESS"))

    def _detector_done(self, name: str, before: int) -> None:
        """Record one protocol detector's result; print it only with --verbose."""
        assert self.session is not None
        if any(entry[0] == name for entry in self._detector_results):
            return
        added = len(self.session.findings) - before
        self._detector_results.append((name, added, ""))
        if VERBOSE:
            print(colorize(f"[✓] {name} complete. New findings added: {added}", "SUCCESS"))

    def _detector_skipped(self, name: str, reason: str) -> None:
        self._detector_results.append((name, 0, reason))
        if VERBOSE:
            print(colorize(f"[i] {name} skipped — {reason}.", "INFO"))

    def _detector_summary(self) -> str:
        ran = [entry for entry in self._detector_results if not entry[2]]
        hits = sorted((entry for entry in ran if entry[1]), key=lambda entry: -entry[1])
        found = ("findings from " + ", ".join(f"{name} ({count})" for name, count, _ in hits)) if hits else "no findings"
        return f"{len(ran)} detectors ran — {found}."

    def _print_coverage(self) -> None:
        """Say how much of the traffic was identified, and list what was not."""
        coverage = self.traffic_coverage()
        total, identified = coverage["total_packets"], coverage["identified_packets"]
        if not total:
            return
        line = f"Traffic identified: {identified:,} of {total:,} packets ({format_share(identified, total)})."
        unidentified = coverage["unidentified"]
        if not unidentified:
            self._log_ts(f"[i] {line}")
            return
        if total - identified < total / 100:
            self._log_ts(f"[i] {line} {len(unidentified)} small flow{'s' if len(unidentified) != 1 else ''} "
                         "not identified — listed in the report.")
            return
        self._log_ts(colorize(f"[!] {line} Not identified by OTscope or tshark:", SEVERITY_MEDIUM))
        for connection in unidentified[:5]:
            print(f"        {self._flow_text(connection)}")
        if len(unidentified) > 5:
            print(f"        (+{len(unidentified) - 5} more flows)")
        if identified < total / 2:
            print(colorize("    Most of the traffic could not be identified, so a low risk score here does not "
                           "mean the capture is benign.", SEVERITY_MEDIUM))

    TCP_ORIENTATION_CAP = 500_000
    EVIDENCE_CAP = 50
    MERGED_IP_CAP = 1000

    def _orient(self, row: Dict[str, str]) -> Tuple[str, str, int, str, bool]:
        """Return (client_ip, server_ip, service_port, transport, to_server) for a row.

        The server side comes from the TCP handshake when it was captured,
        otherwise from well-known service ports.  `to_server` is True when
        this packet travels from the client toward the service.
        """
        src, dst = row_source_ip(row), row_destination_ip(row)
        sport, dport = row_source_port(row), row_destination_port(row)
        if row.get("tcp.srcport"):
            transport = "TCP"
        elif row.get("udp.srcport"):
            transport = "UDP"
        else:
            return src, dst, 0, "", True
        pair = ((src, sport), (dst, dport)) if (src, sport) <= (dst, dport) else ((dst, dport), (src, sport))
        server = self._tcp_servers.get(pair) if transport == "TCP" else None
        if server is None and transport == "TCP":
            syn_ack = _tcp_flag_bits(row) & 0x12
            if syn_ack == 0x02:
                server = (dst, dport)
            elif syn_ack == 0x12:
                server = (src, sport)
            if server is not None and len(self._tcp_servers) < self.TCP_ORIENTATION_CAP:
                self._tcp_servers[pair] = server
        if server is None:
            service = service_port_for(sport, dport)
            server = (dst, dport) if service == dport else (src, sport)
        if server == (dst, dport):
            return src, dst, dport, transport, True
        return dst, src, sport, transport, False

    def set_session(self, session: SessionState) -> None:
        """Attach a session and refresh runtime indexes."""
        self.session = session
        self.packet_fingerprint_set = set(session.packet_fingerprints)
        self.finding_index = {}
        for finding in session.findings:
            if finding.dedupe_key:
                self.finding_index[finding.dedupe_key] = finding

    def _stamp_provenance(self) -> None:
        """Stamp tool / author / version into analysis_metadata.

        Internal bookkeeping field used by the JSON report writer to
        cross-reference tool provenance.  Persists across session
        reload/resume because analysis_metadata is part of the session
        schema serialized by session_to_dict / session_from_dict.
        """
        if self.session is None:
            return
        self.session.analysis_metadata["_provenance"] = {
            "tool": TOOL_NAME,
            "version": VERSION,
            "author": __author__,
            "copyright": __copyright__,
            "stamped_at": utc_now_iso(),
        }

    def save_session(self) -> None:
        """Write the current session state to disk."""
        if self.session is None:
            return
        self.session.updated_at = utc_now_iso()
        self.session.packet_fingerprints = sorted(self.packet_fingerprint_set)
        self._stamp_provenance()
        session_path = Path(self.session.session_file)
        session_path.write_text(pretty_json(session_to_dict(self.session)), encoding="utf-8")
        self._note_artifact(session_path, "Session — resume it or add captures later", "Session saved")

    def _checkpoint_save_silent(self) -> None:
        """Atomic quiet save used between files in long analysis runs.

        Writes to a .tmp sibling then renames into place so an interrupted
        write cannot leave a half-written session file.
        """
        if self.session is None:
            return
        self.session.updated_at = utc_now_iso()
        self.session.packet_fingerprints = sorted(self.packet_fingerprint_set)
        self._stamp_provenance()
        session_path = Path(self.session.session_file)
        tmp_path = session_path.with_suffix(session_path.suffix + ".tmp")
        tmp_path.write_text(pretty_json(session_to_dict(self.session)), encoding="utf-8")
        tmp_path.replace(session_path)

    def load_session(self, path: Path) -> SessionState:
        """Load a session JSON file from disk."""
        payload = json.loads(path.read_text(encoding="utf-8"))
        session = session_from_dict(payload)
        self.set_session(session)
        return session

    def create_session(self, folder: Path, session_name: str, site: str, assessor: str, env_answers: Dict[str, str]) -> SessionState:
        """Create a new analysis session."""
        session_file = folder / f"{safe_slug(session_name)}.otpa_session"
        session = SessionState(
            name=session_name,
            site=site,
            assessor=assessor,
            folder=str(folder),
            created_at=utc_now_iso(),
            updated_at=utc_now_iso(),
            session_file=str(session_file),
            environment_answers=env_answers,
        )
        self.set_session(session)
        return session

    def add_note(self, note_text: str, device_ip: Optional[str] = None) -> None:
        """Add a free-text assessor note as an INFO finding."""
        if self.session is None or not note_text.strip():
            return
        if device_ip and device_ip in self.session.devices:
            self.session.devices[device_ip].notes.append(note_text.strip())
        finding = Finding(
            finding_id=str(uuid.uuid4()),
            severity=SEVERITY_INFO,
            category="Assessor Notes",
            title="Assessor note",
            description=note_text.strip(),
            evidence=[note_text.strip()],
            source_ips=[device_ip] if device_ip else [],
            destination_ips=[],
            protocol="Manual Note",
            source_pcaps=[],
            next_steps="Retain this note with the assessment record.",
            created_at=utc_now_iso(),
            score_weight=0,
            dedupe_key=f"note::{device_ip or 'session'}::{hashlib.sha1(note_text.encode('utf-8')).hexdigest()}",
        )
        self._merge_finding(finding)

    def _merge_finding(self, finding: Finding) -> None:
        """Deduplicate or append a finding."""
        if self.session is None:
            return
        finding.score_weight = SCORE_WEIGHTS.get(finding.severity, 0)
        if finding.dedupe_key and finding.dedupe_key in self.finding_index:
            existing = self.finding_index[finding.dedupe_key]
            existing.occurrences += finding.occurrences
            # Bounded merges: per-packet detectors can hit the same key
            # millions of times, so evidence and host lists stop growing at
            # a cap instead of being re-sorted without limit.
            existing.evidence = self._bounded_extend(existing.evidence, finding.evidence, self.EVIDENCE_CAP)
            existing.source_ips = self._bounded_union(existing.source_ips, finding.source_ips, self.MERGED_IP_CAP)
            existing.destination_ips = self._bounded_union(existing.destination_ips, finding.destination_ips,
                                                           self.MERGED_IP_CAP)
            existing.source_pcaps = sorted(set(existing.source_pcaps + finding.source_pcaps))
            existing.tags = sorted(set(existing.tags + finding.tags))
            existing.mitre_ids = sorted(set(existing.mitre_ids + finding.mitre_ids))
            existing.advisory_refs = sorted(set(existing.advisory_refs + finding.advisory_refs))
            existing.last_seen = finding.last_seen or existing.last_seen
            if SEVERITY_ORDER[finding.severity] > SEVERITY_ORDER[existing.severity]:
                existing.severity = finding.severity
                existing.score_weight = SCORE_WEIGHTS.get(existing.severity, 0)
            return
        self.session.findings.append(finding)
        if finding.dedupe_key:
            self.finding_index[finding.dedupe_key] = finding

    @staticmethod
    def _bounded_extend(existing: List[str], new: Sequence[str], cap: int) -> List[str]:
        """Order-preserving union of two lists that stops growing at `cap`."""
        if len(existing) >= cap:
            return existing
        merged = list(existing)
        seen = set(merged)
        for item in new:
            if len(merged) >= cap:
                break
            if item not in seen:
                seen.add(item)
                merged.append(item)
        return merged

    @staticmethod
    def _bounded_union(existing: List[str], new: Sequence[str], cap: int) -> List[str]:
        """Sorted union of two lists that stops adding items once `cap` is reached."""
        if len(existing) >= cap:
            return existing
        merged = set(existing)
        for item in new:
            if len(merged) >= cap:
                break
            merged.add(item)
        return sorted(merged)

    def add_finding(
        self,
        severity: str,
        category: str,
        title: str,
        description: str,
        evidence: Sequence[str],
        source_ips: Sequence[str],
        destination_ips: Sequence[str],
        protocol: str,
        source_pcaps: Sequence[str],
        dedupe_key: str,
        tags: Optional[Sequence[str]] = None,
        first_seen: Optional[str] = None,
        last_seen: Optional[str] = None,
        mitre_ids: Optional[Sequence[str]] = None,
    ) -> None:
        """Create and merge a finding object."""
        finding = Finding(
            finding_id=str(uuid.uuid4()),
            severity=severity,
            category=category,
            title=title,
            description=description,
            evidence=list(dict.fromkeys(item for item in evidence if item)),
            source_ips=list(sorted(set(item for item in source_ips if item))),
            destination_ips=list(sorted(set(item for item in destination_ips if item))),
            protocol=protocol,
            source_pcaps=list(sorted(set(item for item in source_pcaps if item))),
            next_steps=next_steps_for(severity, category),
            created_at=utc_now_iso(),
            first_seen=first_seen,
            last_seen=last_seen,
            tags=list(sorted(set(tags or []))),
            dedupe_key=dedupe_key,
            mitre_ids=list(sorted(set(mitre_ids or []) | set(mitre_for_finding(category, title, tags)))),
            advisory_refs=advisories_for_finding(category, title, tags),
        )
        finding.next_steps = recommended_fix_for_finding(finding)
        self._merge_finding(finding)

    # ------------------------------------------------------------------
    # PROGRESS / TIMING HELPERS
    # ------------------------------------------------------------------
    # `_log_ts(msg)` prepends a wall-clock `[HH:MM:SS]` to any progress
    # line so a long run is self-documenting in the terminal scrollback.
    # `_proc_rate_bps` is set by `run_capture_inventory` after it knows
    # bytes-processed-per-second on this machine — subsequent steps use
    # it to print up-front ETAs so the user can predict remaining time.
    # ------------------------------------------------------------------

    def _now_hms(self) -> str:
        return datetime.now().strftime("%H:%M:%S")

    def _log_ts(self, msg: str) -> None:
        print(f"[{self._now_hms()}] {msg}", flush=True)

    @staticmethod
    def _format_duration(seconds: float) -> str:
        if seconds < 1:
            return "<1s"
        if seconds < 60:
            return f"~{seconds:.0f}s"
        if seconds < 3600:
            mins = seconds / 60
            return f"~{mins:.1f}m"
        return f"~{seconds/3600:.1f}h"

    def _estimate_step(self, key: str, pcaps: Sequence[Path]) -> Optional[float]:
        """Return an estimated wall-clock duration in seconds for an
        analysis step, or None if we don't have a calibrated rate yet.

        The rate is set after the inventory pass finishes (it gives us
        a real bytes/sec figure for THIS machine on THIS dataset).  Per-
        step factors below approximate how heavy each subsequent pass
        is relative to a full single-pass tshark read.
        """
        rate = getattr(self, "_proc_rate_bps", 0.0) or 0.0
        if rate <= 0:
            return None
        try:
            total_bytes = sum(p.stat().st_size for p in pcaps if p.exists())
        except OSError:
            return None
        # Factors empirically reflect each filter's selectivity vs the
        # unfiltered inventory read: narrower filters skip rows quickly
        # but tshark still has to scan the whole pcap, so the floor is
        # ~30-40% of the inventory time.
        factors = {
            "streaming":          1.10,   # one combined pass + per-protocol bookkeeping
            "legacy":             0.40,   # PAYLOAD fields make this slightly heavier
            "artifact_extraction":0.45,
            "intrusion":          0.35,
            "unknown":            0.45,
        }
        if key in factors:
            return max(1.0, (total_bytes / rate) * factors[key])
        if key == "network_hygiene":
            # Hygiene cost has two components:
            #   1. Pure-Python iteration over devices and connections
            #      (~1µs per device, ~3µs per connection in our profile).
            #   2. Public-IP RDAP/PTR lookups (~2.5s per uncached IP)
            #      unless air-gapped/offline.
            # On normal-sized captures the iteration is sub-second and the
            # RDAP cost dominates.  On flood-scale captures (1M+ devices)
            # the iteration dominates and the user must see a real ETA.
            if self.session is None:
                return 0.5
            n_dev = len(self.session.devices)
            n_conn = len(self.session.connections)
            iter_cost = (n_dev * 1e-6) + (n_conn * 3e-6)
            base = 0.5 + iter_cost
            if self._is_air_gapped():
                return base
            uncached_public = 0
            for c in self.session.connections.values():
                src_dev = self.session.devices.get(c.source_ip)
                if not (src_dev and self._likely_ot_device(src_dev)):
                    continue
                if not is_public_ip(c.destination_ip):
                    continue
                if c.destination_ip not in self.public_ip_cache:
                    uncached_public += 1
            return base + uncached_public * 2.5
        return None

    def _device(self, ip_text: str) -> DeviceRecord:
        """Fetch or create a device record by IP."""
        assert self.session is not None
        if ip_text not in self.session.devices:
            self.session.devices[ip_text] = DeviceRecord(ip=ip_text)
        return self.session.devices[ip_text]

    def _remember_unique(self, items: List[Any], value: Any) -> None:
        """Append a value to a list if it is not already present."""
        if value not in items:
            items.append(value)

    _GENERIC_PROTOCOL_LABELS = {"", "TCP", "UDP", "Unknown", "DATA"}

    def _connection_key(self, client_ip: str, server_ip: str, transport: str, service_port: int) -> str:
        """Build a stable key for a connection summary."""
        return f"{client_ip}|{server_ip}|{transport}|{service_port}"

    def _register_connection(self, client_ip: str, server_ip: str, label: str, transport: str, service_port: int,
                             pcap_name: str, timestamp: Optional[str], symmetric: bool = False) -> None:
        """Count a packet against its client -> server:service_port flow.

        Both directions of a conversation land on one record, labeled with
        the most specific protocol seen (e.g. 'DNP3' rather than 'TCP').
        `symmetric` flows (same port both ways, or port-less like ICMP) keep
        the orientation of whichever direction was seen first.
        """
        assert self.session is not None
        transport_key = transport or label or "IP"
        key = self._connection_key(client_ip, server_ip, transport_key, service_port)
        if key not in self.session.connections:
            reverse = self._connection_key(server_ip, client_ip, transport_key, service_port)
            if symmetric and reverse in self.session.connections:
                key = reverse
            else:
                self.session.connections[key] = ConnectionSummary(
                    source_ip=client_ip,
                    destination_ip=server_ip,
                    protocol=label or transport_key,
                    destination_port=service_port,
                    packet_count=0,
                    first_seen=timestamp,
                    last_seen=timestamp,
                    source_pcaps=[pcap_name],
                    labelled_packets=0,
                )
        connection = self.session.connections[key]
        if connection.protocol in self._GENERIC_PROTOCOL_LABELS and label not in self._GENERIC_PROTOCOL_LABELS:
            connection.protocol = label
        if connection.labelled_packets is not None and label not in self._GENERIC_PROTOCOL_LABELS:
            connection.labelled_packets += 1
        connection.packet_count += 1
        if timestamp and (connection.first_seen is None or timestamp < connection.first_seen):
            connection.first_seen = timestamp
        if timestamp and (connection.last_seen is None or timestamp > connection.last_seen):
            connection.last_seen = timestamp
        self._remember_unique(connection.source_pcaps, pcap_name)

    def _packet_fingerprint(self, row: Dict[str, str]) -> str:
        """Build the cross-file deduplication fingerprint for a packet.

        Millisecond timestamp plus addressing (MACs, IPs, ports, IP ID) and
        frame length: the same frame captured into two overlapping pcaps
        matches, while distinct frames sent in the same millisecond — ARP
        bursts, cyclic PROFINET/GOOSE — stay distinct.
        """
        try:
            timestamp_ms = int(float(row.get("frame.time_epoch") or "0") * 1000)
        except ValueError:
            timestamp_ms = 0
        fingerprint_base = "|".join([
            row_source_ip(row), row_destination_ip(row),
            row.get("eth.src") or "", row.get("eth.dst") or "",
            str(row_source_port(row)), str(row_destination_port(row)),
            row.get("ip.id") or "", protocol_family_from_row(row),
            str(timestamp_ms), row.get("frame.len") or "0",
        ])
        return hashlib.sha1(fingerprint_base.encode("utf-8")).hexdigest()

    def _is_host_address(self, ip_text: str, mac_text: str = "") -> bool:
        """True when an address belongs to a host (not broadcast, multicast, or unset)."""
        if not ip_text or (mac_text and is_group_mac(mac_text)):
            return False
        cached = self._host_address_cache.get(ip_text)
        if cached is None:
            if len(self._host_address_cache) > 200_000:
                self._host_address_cache.clear()
            cached = not (is_group_address(ip_text) or is_unspecified_address(ip_text))
            self._host_address_cache[ip_text] = cached
        return cached

    def _note_group_destination(self, ip_text: str, sender_ip: str, protocol: str) -> None:
        """Count traffic to a broadcast / multicast address (kept out of the device list)."""
        assert self.session is not None
        groups = self.session.analysis_metadata.setdefault("group_addresses", {})
        entry = groups.get(ip_text)
        if entry is None:
            if len(groups) >= 500:
                return
            entry = groups[ip_text] = {"packets": 0, "senders": [], "protocols": []}
        entry["packets"] += 1
        if sender_ip and sender_ip not in entry["senders"] and len(entry["senders"]) < 10:
            entry["senders"].append(sender_ip)
        if protocol and protocol not in entry["protocols"] and len(entry["protocols"]) < 10:
            entry["protocols"].append(protocol)

    def _register_arp_sender(self, row: Dict[str, str], pcap_name: str) -> None:
        """Record the sender of a self-consistent ARP frame as a host.

        Hosts that only ever ARP (quiet devices, or an attacker poisoning
        caches from its own address) would otherwise never appear in the
        inventory.  Frames whose ARP sender MAC differs from the Ethernet
        source are someone speaking for another host and are skipped.
        """
        arp_ip = row.get("arp.src.proto_ipv4") or ""
        arp_mac = (row.get("arp.src.hw_mac") or "").lower()
        if not arp_ip or not arp_mac or arp_mac != (row.get("eth.src") or "").lower():
            return
        if not self._is_host_address(arp_ip, arp_mac):
            return
        device = self._device(arp_ip)
        device.outgoing_count += 1
        self._remember_unique(device.source_pcaps, pcap_name)
        self._remember_unique(device.subnets, subnet_from_ip(arp_ip))
        self._remember_unique(device.macs, arp_mac)
        vendor = lookup_oui_vendor(arp_mac)
        if vendor:
            self._remember_unique(device.vendors, vendor)
        self._remember_unique(device.protocols, "ARP")

    def _register_packet_row(self, row: Dict[str, str], pcap_name: str) -> bool:
        """Merge packet-derived information into the unified session."""
        assert self.session is not None
        source_ip = row_source_ip(row)
        destination_ip = row_destination_ip(row)
        timestamp = row.get("frame.time_epoch") or None
        protocol = protocol_family_from_row(row)
        destination_port = row_destination_port(row)
        source_port = row_source_port(row)
        client_ip, server_ip, service_port, transport, to_server = self._orient(row)
        fingerprint = self._packet_fingerprint(row)
        if fingerprint in self.packet_fingerprint_set:
            self.session.duplicate_packets.setdefault(fingerprint, [])
            if pcap_name not in self.session.duplicate_packets[fingerprint]:
                self.session.duplicate_packets[fingerprint].append(pcap_name)
            return False
        self.packet_fingerprint_set.add(fingerprint)
        if row.get("arp.opcode"):
            self._register_arp_sender(row, pcap_name)
        host_ips = {ip for ip, mac in ((source_ip, ""), (destination_ip, row.get("eth.dst", "")))
                    if self._is_host_address(ip, mac)}
        vlan_id = row.get("vlan.id", "").strip()
        # Passive OS fingerprint: only look at TCP SYN (flags 0x02) from the source.
        os_guess = ""
        tcp_flags = row.get("tcp.flags", "").strip().lower()
        if tcp_flags in ("0x00000002", "0x0002", "0x02", "2"):
            try:
                ttl = int(row.get("ip.ttl", "0") or 0)
                window = int(row.get("tcp.window_size_value", "0") or 0)
                os_guess = passive_os_from_syn(ttl, window)
            except (TypeError, ValueError):
                os_guess = ""
        for ip_text, mac_text, direction in (
            (source_ip, row.get("eth.src", ""), "out"),
            (destination_ip, row.get("eth.dst", ""), "in"),
        ):
            if not ip_text:
                continue
            if ip_text not in host_ips:
                if direction == "in" and not is_unspecified_address(ip_text):
                    self._note_group_destination(ip_text, source_ip, protocol)
                continue
            device = self._device(ip_text)
            self._remember_unique(device.source_pcaps, pcap_name)
            self._remember_unique(device.subnets, subnet_from_ip(ip_text))
            if mac_text:
                self._remember_unique(device.macs, mac_text)
                vendor = lookup_oui_vendor(mac_text)
                if vendor:
                    self._remember_unique(device.vendors, vendor)
            if vlan_id:
                self._remember_unique(device.vlans, vlan_id)
            if protocol:
                self._remember_unique(device.protocols, protocol)
            if direction == "out":
                device.outgoing_count += 1
                if os_guess and not device.os_fingerprint:
                    device.os_fingerprint = os_guess
            else:
                device.incoming_count += 1
        # Service ports: a device "serves" a port only once it answers on it
        # (a refused or unanswered probe proves nothing); same-port protocols
        # such as BACnet or NTP are peers, so both ends get the port.
        symmetric = not service_port or source_port == destination_port
        if service_port and source_ip and destination_ip:
            if source_port == destination_port:
                for ip_text in (source_ip, destination_ip):
                    if ip_text in host_ips:
                        self._remember_unique(self._device(ip_text).ports, service_port)
                        self._remember_unique(self._device(ip_text).client_ports, service_port)
            elif to_server:
                if client_ip in host_ips:
                    self._remember_unique(self._device(client_ip).client_ports, service_port)
            elif not _tcp_flag_bits(row) & 0x04 and server_ip in host_ips:
                self._remember_unique(self._device(server_ip).ports, service_port)
        if source_ip and destination_ip:
            self._register_connection(client_ip, server_ip, protocol, transport, service_port, pcap_name,
                                      timestamp, symmetric=symmetric)
        return True

    # ------------------------------------------------------------------
    # BASELINE / DIFF MODE
    # ------------------------------------------------------------------
    # A baseline is a tiny JSON snapshot of "what normal looks like" for
    # this environment: the set of observed devices, the set of observed
    # (src, dst, dst_port, proto) flow tuples, per-device protocol sets,
    # and per-device destination-port sets.  Operators run the tool
    # against a trusted capture once (save baseline), then subsequent
    # runs compare_to_baseline() emits findings for anything NEW — new
    # device, new flow pair, new protocol per device, new destination
    # port per device.  This is the single highest-signal detection
    # mechanism for OT environments because deviation from normal is
    # almost always interesting.
    # ------------------------------------------------------------------

    BASELINE_VERSION = 1

    def save_baseline(self, path: Path) -> None:
        """Persist a concise 'known-good' snapshot to `path`.

        Small on purpose: a baseline is meant to be committed to a
        version-control system by the asset owner and hand-reviewed.
        """
        assert self.session is not None
        device_profiles: Dict[str, Dict[str, List[Any]]] = {}
        for ip, dev in self.session.devices.items():
            device_profiles[ip] = {
                "protocols": sorted(set(dev.protocols)),
                "ports":     sorted(set(dev.ports)),
                "macs":      sorted(set(dev.macs)),
                "vlans":     sorted(set(dev.vlans)),
                "role":      dev.inferred_role,
            }
        flow_keys = sorted({
            f"{c.source_ip}|{c.destination_ip}|{c.destination_port}|{c.protocol}"
            for c in self.session.connections.values()
        })
        payload = {
            "baseline_version": self.BASELINE_VERSION,
            "tool_version": VERSION,
            "created_at": utc_now_iso(),
            "site": self.session.site,
            "source_session": self.session.name,
            "device_profiles": device_profiles,
            "flows": flow_keys,
        }
        path.write_text(pretty_json(payload), encoding="utf-8")
        self._note_artifact(path, "Baseline — compare future captures against it", "Baseline saved",
                            f" ({len(device_profiles):,} devices, {len(flow_keys):,} flows)")

    def _load_baseline(self, path: Path) -> Dict[str, Any]:
        """Load a baseline JSON from disk and validate its shape."""
        payload = json.loads(path.read_text(encoding="utf-8"))
        if not isinstance(payload, dict) or "device_profiles" not in payload or "flows" not in payload:
            raise ValueError(f"{path} is not a valid baseline file.")
        return payload

    def compare_to_baseline(self, path: Path) -> int:
        """Compare the current session to a saved baseline and emit diff findings.

        Emits these categories:
          * "New device since baseline"          (MEDIUM — can be CRITICAL on
                                                  air-gapped nets; we escalate)
          * "New flow since baseline"            (HIGH)
          * "New protocol on existing device"    (HIGH)
          * "New destination port on existing device"  (MEDIUM)
        """
        assert self.session is not None
        try:
            baseline = self._load_baseline(path)
        except (OSError, ValueError, json.JSONDecodeError) as exc:
            print(colorize(f"[!] Failed to load baseline {path}: {exc}", SEVERITY_HIGH))
            return 0
        baseline_devices = baseline.get("device_profiles", {}) or {}
        baseline_flows: set[str] = set(baseline.get("flows", []) or [])
        air_gapped = self._is_air_gapped()
        new_device_sev = SEVERITY_CRITICAL if air_gapped else SEVERITY_HIGH
        print_header(f"Baseline Diff (vs {path.name})")

        # 1) NEW DEVICES
        new_devices = [ip for ip in self.session.devices.keys() if ip not in baseline_devices]
        for ip in new_devices:
            dev = self.session.devices[ip]
            self.add_finding(
                new_device_sev,
                "Baseline Deviation",
                "New device since baseline",
                f"{ip} was not present in the reference baseline '{path.name}'. "
                "A previously-unknown device appeared on the network segment "
                "covered by these captures. On a mature OT network this is "
                "almost always worth investigating — it is a rogue device, "
                "a misconfigured deployment, or lateral-movement pivot.",
                [
                    f"Protocols observed: {', '.join(sorted(dev.protocols)) or '(none)'}",
                    f"Ports observed: {', '.join(str(p) for p in sorted(dev.ports)) or '(none)'}",
                    f"MACs: {', '.join(sorted(dev.macs)) or '(none)'}",
                    f"First seen in: {', '.join(sorted(dev.source_pcaps)[:5])}",
                ],
                [ip],
                [],
                "Multi-Protocol",
                sorted(dev.source_pcaps),
                f"baseline::new-device::{ip}",
                tags=["baseline_diff", "new_device", "intrusion" if air_gapped else "boundary"],
            )

        # 2) NEW FLOWS
        current_flow_keys = {
            f"{c.source_ip}|{c.destination_ip}|{c.destination_port}|{c.protocol}": c
            for c in self.session.connections.values()
        }
        new_flows = [(k, current_flow_keys[k]) for k in current_flow_keys.keys() - baseline_flows]
        # Cluster per source IP to avoid one finding per flow when a scanner
        # creates hundreds of new flows.
        by_src: Dict[str, List[ConnectionSummary]] = defaultdict(list)
        for _, conn in new_flows:
            by_src[conn.source_ip].append(conn)
        for src_ip, conns in by_src.items():
            if not conns:
                continue
            samples = sorted(
                [f"{c.source_ip} -> {c.destination_ip} {c.protocol}/{c.destination_port} ({c.packet_count} pkts)"
                 for c in conns]
            )[:10]
            severity = SEVERITY_HIGH if len(conns) < 50 else SEVERITY_CRITICAL
            self.add_finding(
                severity,
                "Baseline Deviation",
                "New flow since baseline",
                f"{src_ip} initiated {len(conns)} flow(s) that were not present in the reference "
                f"baseline '{path.name}'. New talker pairs on an OT segment should be manually "
                "validated — they may be legitimate maintenance, new deployments, or early-stage attack activity.",
                samples + [f"Total new flows from this source: {len(conns)}"],
                [src_ip],
                sorted({c.destination_ip for c in conns})[:10],
                "Multi-Protocol",
                sorted({p for c in conns for p in c.source_pcaps}),
                f"baseline::new-flows::{src_ip}",
                tags=["baseline_diff", "new_flow"],
            )

        # 3) NEW PROTOCOLS / 4) NEW PORTS on existing devices
        for ip, dev in self.session.devices.items():
            baseline_profile = baseline_devices.get(ip)
            if not baseline_profile:
                continue  # handled by "new device" above
            baseline_protocols = set(baseline_profile.get("protocols", []))
            baseline_ports = set(int(p) for p in baseline_profile.get("ports", []))
            new_protos = sorted(set(dev.protocols) - baseline_protocols)
            new_ports  = sorted(set(dev.ports) - baseline_ports)
            if new_protos:
                self.add_finding(
                    SEVERITY_HIGH, "Baseline Deviation",
                    "New protocol on existing device",
                    f"{ip} is using protocol(s) not seen in the reference baseline. "
                    "A device suddenly speaking a new protocol is a strong indicator "
                    "of reconnaissance, mis-configuration, or compromise.",
                    [
                        f"New protocols: {', '.join(new_protos)}",
                        f"Baseline protocols: {', '.join(sorted(baseline_protocols)) or '(none)'}",
                    ],
                    [ip], [], "Multi-Protocol",
                    sorted(dev.source_pcaps),
                    f"baseline::new-proto::{ip}",
                    tags=["baseline_diff", "new_protocol"],
                )
            if new_ports:
                self.add_finding(
                    SEVERITY_MEDIUM, "Baseline Deviation",
                    "New destination port on existing device",
                    f"{ip} communicated on TCP/UDP port(s) not seen in the reference baseline.",
                    [
                        f"New ports: {', '.join(str(p) for p in new_ports)}",
                        f"Baseline ports: {', '.join(str(p) for p in sorted(baseline_ports)) or '(none)'}",
                    ],
                    [ip], [], "Multi-Protocol",
                    sorted(dev.source_pcaps),
                    f"baseline::new-port::{ip}",
                    tags=["baseline_diff", "new_port"],
                )

        print(colorize(
            f"[✓] Baseline diff: {len(new_devices)} new device(s), "
            f"{len(new_flows)} new flow(s) across {len(by_src)} source(s).",
            "SUCCESS",
        ))
        return 0

    def _prune_low_confidence_devices(self, min_packets: int = 2) -> Dict[str, int]:
        """Remove device records that are not real endpoints, then consolidate.

        Broadcast / multicast / unspecified addresses are never devices (new
        sessions do not create them; older sessions may carry them) and are
        summarized under ``analysis_metadata["group_addresses"]`` instead.
        Destination-only IPs seen fewer than ``min_packets`` times are
        dropped.  IPv6 link-local addresses are then folded into the IPv4
        host that uses the same MAC, and the "ARP" protocol label is kept
        only for hosts seen in nothing but ARP.
        """
        assert self.session is not None
        stats = {"kept": 0, "dropped_multicast": 0, "dropped_sparse": 0,
                 "dropped_dest_only": 0, "folded_ipv6": 0}
        to_delete: List[str] = []
        for ip, dev in self.session.devices.items():
            total_pkts = dev.incoming_count + dev.outgoing_count
            group_macs_only = bool(dev.macs) and all(is_group_mac(mac) for mac in dev.macs)
            if is_unspecified_address(ip) or ip in {"", "::"}:
                to_delete.append(ip); stats["dropped_sparse"] += 1; continue
            if is_group_address(ip) or group_macs_only:
                groups = self.session.analysis_metadata.setdefault("group_addresses", {})
                entry = groups.setdefault(ip, {"packets": 0, "senders": [], "protocols": []})
                entry["packets"] = max(entry["packets"], total_pkts)
                for protocol in dev.protocols[:10]:
                    if protocol not in entry["protocols"]:
                        entry["protocols"].append(protocol)
                to_delete.append(ip); stats["dropped_multicast"] += 1; continue
            if dev.outgoing_count == 0 and total_pkts < min_packets:
                to_delete.append(ip); stats["dropped_dest_only"] += 1; continue
            if total_pkts < min_packets and len(dev.source_pcaps) < 1:
                to_delete.append(ip); stats["dropped_sparse"] += 1; continue
            stats["kept"] += 1
        for ip in to_delete:
            del self.session.devices[ip]
        stats["folded_ipv6"] = self._fold_link_local_ipv6()
        for dev in self.session.devices.values():
            if "ARP" in dev.protocols and len(dev.protocols) > 1:
                dev.protocols.remove("ARP")
        return stats

    def _fold_link_local_ipv6(self) -> int:
        """Merge IPv6 link-local device records into the IPv4 host with the same MAC."""
        assert self.session is not None
        ipv4_by_mac: Dict[str, List[str]] = defaultdict(list)
        for ip, dev in self.session.devices.items():
            if ":" not in ip:
                for mac in dev.macs:
                    ipv4_by_mac[mac.lower()].append(ip)
        folded = 0
        for ip in [ip for ip in self.session.devices if is_link_local_ipv6(ip)]:
            dev = self.session.devices[ip]
            macs = [mac.lower() for mac in dev.macs if not is_group_mac(mac)]
            if len(macs) != 1 or len(ipv4_by_mac.get(macs[0], [])) != 1:
                continue
            host = self.session.devices[ipv4_by_mac[macs[0]][0]]
            self._remember_unique(host.ipv6_addresses, ip)
            self.session.analysis_metadata.setdefault("ipv6_links", {})[ip] = {"host": host.ip, "mac": macs[0]}
            for attr in ("protocols", "ports", "client_ports", "source_pcaps", "vendors", "vlans"):
                target = getattr(host, attr)
                for value in getattr(dev, attr):
                    self._remember_unique(target, value)
            host.outgoing_count += dev.outgoing_count
            host.incoming_count += dev.incoming_count
            del self.session.devices[ip]
            folded += 1
        return folded

    def _all_processed_packet_count(self) -> int:
        """Return the total raw packet count across processed pcaps."""
        assert self.session is not None
        return sum(item.packet_count for item in self.session.processed_pcaps.values())

    def _filtered_rows(
        self,
        pcaps: Sequence[Path],
        display_filter: str,
        fields: Optional[Sequence[str]] = None,
    ) -> List[Tuple[Path, Dict[str, str]]]:
        """Collect filtered tshark rows for a list of pcap files.

        Pass ``fields`` to request a superset of BASE_PACKET_FIELDS (e.g.
        PAYLOAD_PACKET_FIELDS) for checks that need payload content.
        """
        effective_fields = list(fields) if fields is not None else BASE_PACKET_FIELDS
        rows: List[Tuple[Path, Dict[str, str]]] = []
        for pcap in pcaps:
            try:
                for row in iter_tshark_rows(display_filter, effective_fields, pcap):
                    rows.append((pcap, row))
            except TSharkError as exc:
                print(colorize(f"[!] tshark error on {pcap.name}: {exc}", SEVERITY_HIGH))
        return rows

    def _is_air_gapped(self) -> bool:
        """Return True if outbound network calls should be suppressed.

        Honors both the discovery questionnaire's air-gapped answer and
        the global --offline lock.  Either flag being true means we make
        no PTR / RDAP / hostname resolution calls.
        """
        if OFFLINE_MODE:
            return True
        if self.session is None:
            return False
        return self.session.environment_answers.get("air_gapped", "").strip().lower().startswith("y")

    def _public_ip_context(self, ip_text: str) -> Dict[str, str]:
        """Best-effort public IP enrichment using PTR and RDAP.

        Skipped entirely for air-gapped environments to avoid hangs.
        """
        if not ip_text or not is_public_ip(ip_text):
            return {}
        if self._is_air_gapped():
            return {}
        if ip_text in self.public_ip_cache:
            return self.public_ip_cache[ip_text]
        context: Dict[str, str] = {}
        try:
            host, aliases, _ = socket.gethostbyaddr(ip_text)
            if host:
                context["ptr"] = host
            if aliases:
                context["aliases"] = ", ".join(aliases[:3])
        except Exception:
            pass
        try:
            request = urllib.request.Request(
                f"https://rdap.org/ip/{ip_text}",
                headers={"User-Agent": f"{TOOL_NAME}/{VERSION}"},
            )
            with urllib.request.urlopen(request, timeout=4) as response:
                payload = json.loads(response.read().decode("utf-8", errors="replace"))
            if isinstance(payload, dict):
                if payload.get("name"):
                    context["network_name"] = str(payload["name"])
                if payload.get("country"):
                    context["country"] = str(payload["country"])
                if payload.get("port43"):
                    context["whois_server"] = str(payload["port43"])
        except Exception:
            pass
        self.public_ip_cache[ip_text] = context
        return context

    def _expected_protocol(self, names: Sequence[str]) -> bool:
        """Return True if the discovery answers say a protocol is expected."""
        assert self.session is not None
        expected = self.session.environment_answers.get("expected_protocols", "").lower()
        return any(name.lower() in expected for name in names)

    def _likely_ot_device(self, device: DeviceRecord) -> bool:
        """Best-effort classifier for whether a device should be treated as OT-adjacent."""
        ot_protocol_markers = ("modbus", "bacnet", "dnp3", "opc", "ethernet/ip", "cip", "s7", "iec 61850", "profinet")
        if any(marker in " ".join(device.protocols).lower() for marker in ot_protocol_markers):
            return True
        return any(port in KNOWN_OT_PORTS for port in list(device.ports) + list(device.client_ports))

    def run_capture_inventory(self, pcaps: Sequence[Path]) -> int:
        """Always-run baseline inventory and deduplication stage."""
        assert self.session is not None
        print_header("Capture Inventory")
        # Calibration timer: lets us print honest ETAs for every later step.
        try:
            inventory_total_bytes = sum(p.stat().st_size for p in pcaps if p.exists())
        except OSError:
            inventory_total_bytes = 0
        inventory_t0 = time.time()
        self._log_ts(
            f"Inventorying {len(pcaps)} file(s), {human_size(inventory_total_bytes)} total — "
            "this pass also calibrates the per-step time estimates for the rest of the run."
        )
        unique_pairs: Counter[Tuple[str, str]] = Counter()
        protocol_counts: Counter[str] = Counter()
        port_counts: Counter[int] = Counter()
        subnet_counts: Counter[str] = Counter()
        broadcast_counts: Counter[str] = Counter()
        host_focus: Counter[str] = Counter()
        unique_ips_seen: set[str] = set()
        unique_packets_added = 0
        duplicates_seen = 0
        first_timestamp: Optional[float] = None
        last_timestamp: Optional[float] = None
        total_files = len(pcaps)
        for idx, pcap in enumerate(pcaps, start=1):
            raw_packet_count = 0
            local_first: Optional[str] = None
            local_last: Optional[str] = None
            size_h = human_size(pcap.stat().st_size)
            self._log_ts(f"    [{idx}/{total_files}] {pcap.name} ({size_h}) — inventorying …")
            if pcap.stat().st_size > LARGE_FILE_THRESHOLD_BYTES:
                print(colorize(f"[!] {pcap.name} is larger than 500MB. Streaming analysis may take longer.", SEVERITY_MEDIUM))
            try:
                for row in iter_tshark_rows("", BASE_PACKET_FIELDS, pcap):
                    raw_packet_count += 1
                    timestamp_text = row.get("frame.time_epoch") or ""
                    if timestamp_text and (local_first is None or timestamp_text < local_first):
                        local_first = timestamp_text
                    if timestamp_text and (local_last is None or timestamp_text > local_last):
                        local_last = timestamp_text
                    try:
                        ts_value = float(timestamp_text) if timestamp_text else None
                    except ValueError:
                        ts_value = None
                    if ts_value is not None:
                        first_timestamp = ts_value if first_timestamp is None else min(first_timestamp, ts_value)
                        last_timestamp = ts_value if last_timestamp is None else max(last_timestamp, ts_value)
                    merged = self._register_packet_row(row, pcap.name)
                    if not merged:
                        duplicates_seen += 1
                        continue
                    unique_packets_added += 1
                    source_ip = row_source_ip(row)
                    destination_ip = row_destination_ip(row)
                    protocol = protocol_family_from_row(row)
                    service_port = self._orient(row)[2]
                    if source_ip:
                        unique_ips_seen.add(source_ip)
                        subnet_counts[subnet_from_ip(source_ip)] += 1
                        host_focus[source_ip] += 1
                    if destination_ip:
                        unique_ips_seen.add(destination_ip)
                        subnet_counts[subnet_from_ip(destination_ip)] += 1
                        host_focus[destination_ip] += 1
                        if destination_ip.endswith(".255") or destination_ip.startswith("224.") or destination_ip.lower().startswith("ff"):
                            broadcast_counts[subnet_from_ip(destination_ip)] += 1
                    if source_ip and destination_ip:
                        unique_pairs[(source_ip, destination_ip)] += 1
                    if protocol:
                        protocol_counts[protocol] += 1
                    if service_port:
                        port_counts[service_port] += 1
                self.session.processed_pcaps[pcap.name] = ProcessedPcap(
                    path=str(pcap),
                    filename=pcap.name,
                    sha256=file_sha256(pcap),
                    size_bytes=pcap.stat().st_size,
                    processed_at=utc_now_iso(),
                    packet_count=raw_packet_count,
                    start_time=local_first,
                    end_time=local_last,
                    truncated=str(pcap) in _PARTIAL_CAPTURES,
                )
            except TSharkError as exc:
                print(colorize(f"[!] Failed to inventory {pcap.name}: {exc}", SEVERITY_HIGH))
            # Checkpoint after each file so a long multi-file run can be
            # resumed if interrupted.  Silenced to avoid spammy logging.
            try:
                self._checkpoint_save_silent()
            except Exception as exc:
                print(colorize(f"[!] Checkpoint save failed after {pcap.name}: {exc}", SEVERITY_MEDIUM))
        raw_device_count = len(self.session.devices)
        prune_stats = self._prune_low_confidence_devices(min_packets=2)
        total_unique_ips = len(self.session.devices)
        if raw_device_count > total_unique_ips:
            print(
                f"[✓] Device confidence filter: kept {total_unique_ips:,} / {raw_device_count:,} IPs "
                f"(set aside {prune_stats['dropped_multicast']:,} broadcast/multicast addresses, "
                f"folded {prune_stats['folded_ipv6']:,} IPv6 link-local into their IPv4 hosts, "
                f"{prune_stats['dropped_dest_only']:,} destination-only, "
                f"{prune_stats['dropped_sparse']:,} sparse)."
            )
        top_pairs = sorted(self.session.connections.values(), key=lambda item: item.packet_count, reverse=True)[:20]
        top_pair_strings = [f"{item.source_ip} -> {item.destination_ip} ({item.protocol}, {item.packet_count} pkts)" for item in top_pairs]
        dominant_host = host_focus.most_common(1)[0][0] if host_focus else ""
        single_host_capture = host_focus and host_focus[dominant_host] > max(25, sum(host_focus.values()) * 0.6)
        self.session.analysis_metadata["capture_inventory"] = {
            "unique_packet_count": self.session.analysis_metadata.get("capture_inventory", {}).get("unique_packet_count", 0) + unique_packets_added,
            "duplicates_seen": self.session.analysis_metadata.get("capture_inventory", {}).get("duplicates_seen", 0) + duplicates_seen,
            "top_pairs": top_pair_strings,
            "protocol_counts": dict(protocol_counts),
            "top_ports": {str(port): count for port, count in port_counts.most_common(25)},
            "subnets": dict(subnet_counts),
            "broadcast_counts": dict(broadcast_counts),
            "single_host_capture": single_host_capture,
            "time_range": {
                "start": first_timestamp,
                "end": last_timestamp,
            },
        }
        # Capture calibration: bytes-per-second on this machine.  Stored on
        # the analyzer (not the session) — re-measured each run because OS
        # cache state and disk pressure vary between invocations.
        inventory_elapsed = max(time.time() - inventory_t0, 0.001)
        if inventory_total_bytes > 0:
            self._proc_rate_bps = inventory_total_bytes / inventory_elapsed
        else:
            self._proc_rate_bps = 0.0
        self._log_ts(
            f"[✓] Processed {len(pcaps)} file(s), {unique_packets_added} unique packets added, "
            f"{duplicates_seen} duplicate packets skipped."
        )
        self._log_ts(
            f"[✓] Unified devices: {total_unique_ips} | Raw packets processed across session: "
            f"{self._all_processed_packet_count()}"
        )
        if self._proc_rate_bps > 0:
            self._log_ts(
                f"[✓] Inventory took {self._format_duration(inventory_elapsed)} "
                f"({human_size(int(self._proc_rate_bps))}/s effective tshark rate on this host)."
            )
        if top_pair_strings:
            print("[✓] Top talker pairs:")
            for line in top_pair_strings[:5]:
                print(f"    - {line}")
        if single_host_capture:
            print(colorize("[!] Capture appears biased toward a single host vantage point. Absence findings may be less reliable.", SEVERITY_MEDIUM))
        return 0

    # Cleartext / legacy services, keyed by the service (server) port.
    LEGACY_SERVICES: Dict[int, Tuple[str, str]] = {
        23: (SEVERITY_CRITICAL, "Telnet observed"),
        21: (SEVERITY_HIGH, "FTP observed"),
        69: (SEVERITY_HIGH, "TFTP observed"),
        80: (SEVERITY_HIGH, "HTTP observed on OT-adjacent device"),
        161: (SEVERITY_HIGH, "SNMPv1/v2 observed"),
        3389: (SEVERITY_HIGH, "RDP observed"),
        5900: (SEVERITY_HIGH, "VNC observed"),
        445: (SEVERITY_HIGH, "SMB observed"),
        139: (SEVERITY_HIGH, "NetBIOS observed"),
        512: (SEVERITY_CRITICAL, "rsh/rexec observed"),
        513: (SEVERITY_CRITICAL, "rsh/rexec observed"),
        110: (SEVERITY_HIGH, "POP3 observed"),
        143: (SEVERITY_HIGH, "IMAP observed"),
    }
    _HTTP_CRED_PORTS = (80, 443, 8080, 8000, 8443, 8444, 9000, 4040)
    _TELNET_FAILURE = re.compile(r"login incorrect|login failed|authentication fail|access denied|invalid login", re.I)
    _TELNET_IAC = re.compile(rb"\xff[\xfb-\xfe].|\xff\xfa.*?\xff\xf0|\xff[\xf0-\xfa]", re.S)

    def check_legacy(self, pcaps: Sequence[Path]) -> int:
        """Analyze cleartext and legacy protocols (plus credential extraction)."""
        assert self.session is not None
        rows = self._filtered_rows(
            pcaps,
            "tcp.port in {21, 22, 23, 80, 110, 139, 143, 445, 512, 513, 1883, 3389, 5900} || udp.port in {69, 161} || http",
            fields=PAYLOAD_PACKET_FIELDS,
        )
        if not rows:
            return 0
        grouped_links: Dict[int, set[str]] = defaultdict(set)
        grouped_pcaps: Dict[int, set[str]] = defaultdict(set)
        grouped_clients: Dict[int, set[str]] = defaultdict(set)
        grouped_servers: Dict[int, set[str]] = defaultdict(set)
        grouped_samples: Dict[int, List[str]] = defaultdict(list)
        # Suspicious User-Agent / Server-banner accumulators.  Dedup by
        # (keyword, host) so one scanner hitting 40 hosts becomes a single
        # finding with a host list, not 40 findings.  Auth-failure bursts
        # are indexed by (proto, client, server) for the same reason.
        ua_hits: Dict[Tuple[str, str, str], Dict[str, Any]] = {}
        server_hits: Dict[Tuple[str, str, str], Dict[str, Any]] = {}
        auth_fail: Dict[Tuple[str, str, str], Dict[str, Any]] = defaultdict(
            lambda: {"count": 0, "samples": [], "pcaps": set()}
        )
        # Credential extraction accumulator: proto -> entries.  Per explicit
        # assessor request, passwords are stored and rendered IN THE CLEAR in
        # the report — the assessment deliverable is the recovered
        # credential, and the report is handled under the same
        # confidentiality controls as the source pcap.
        creds: Dict[str, Dict[str, Any]] = defaultdict(
            lambda: {"entries": [], "clients": set(), "servers": set(), "pcaps": set()})
        # Telnet login reassembly: (client, client_port, server) -> state.
        telnet_state: Dict[Tuple[str, int, str], Dict[str, str]] = defaultdict(
            lambda: {"expect": "", "buffer": "", "user": ""}
        )

        def add_cred(proto: str, pcap_name: str, link: str, ips: Sequence[str], user: str, secret: str, sample: str) -> None:
            creds[proto]["entries"].append({
                "pcap": pcap_name, "link": link,
                "user": user, "secret": secret or "",
                "secret_len": len(secret or ""), "sample": sample[:200],
            })
            if ips[0]:
                creds[proto]["clients"].add(ips[0])
            if ips[1]:
                creds[proto]["servers"].add(ips[1])
            creds[proto]["pcaps"].add(pcap_name)

        for pcap, row in rows:
            client, server, service_port, _transport, to_server = self._orient(row)
            touched_ips = [ip for ip in (client, server)
                           if ip and ip in self.session.devices and self._likely_ot_device(self.session.devices[ip])]
            if not touched_ips:
                continue
            info = row.get("_ws.col.Info", "")
            link = f"{client} -> {server}"
            payload = payload_bytes_from_row(row)
            payload_text = payload.decode("latin-1", errors="replace")
            pcap_name = pcap.name

            # ---- Legacy service inventory (by service port) ------------
            legacy_service = service_port in self.LEGACY_SERVICES and (
                service_port != 161 or (row.get("snmp.version") or "") in ("0", "1"))
            if legacy_service:
                grouped_links[service_port].add(f"{link} in {pcap_name}")
                grouped_pcaps[service_port].add(pcap_name)
                if client:
                    grouped_clients[service_port].add(client)
                if server:
                    grouped_servers[service_port].add(server)
                if len(grouped_samples[service_port]) < 6:
                    for sample in condensed_string_samples(payload, minimum_length=3, limit=3):
                        sample_line = f"{link} sample: {sample}"
                        if sample_line not in grouped_samples[service_port]:
                            grouped_samples[service_port].append(sample_line)

            # ---- Suspicious User-Agent / Server banner -----------------
            ua_text = (row.get("http.user_agent") or "").lower()
            sv_text = (row.get("http.server") or "").lower()
            if ua_text:
                for kw, (sev, label) in SUSPICIOUS_UA_KEYWORDS.items():
                    if kw in ua_text:
                        slot = ua_hits.setdefault((kw, client or "", server or ""), {
                            "severity": sev, "label": label, "samples": [], "pcaps": set(),
                            "src_ip": client, "dst_ips": set(),
                        })
                        slot["pcaps"].add(pcap_name)
                        if server:
                            slot["dst_ips"].add(server)
                        if len(slot["samples"]) < 5:
                            slot["samples"].append(f"{pcap_name}: {link} UA='{ua_text[:120]}'")
                        break
            if sv_text:
                for kw, (sev, label) in SUSPICIOUS_SERVER_KEYWORDS.items():
                    if kw in sv_text:
                        slot = server_hits.setdefault((kw, server or "", client or ""), {
                            "severity": sev, "label": label, "samples": [], "pcaps": set(),
                            "host_ip": server, "client_ips": set(),
                        })
                        slot["pcaps"].add(pcap_name)
                        if client:
                            slot["client_ips"].add(client)
                        if len(slot["samples"]) < 5:
                            slot["samples"].append(f"{pcap_name}: {link} Server='{sv_text[:120]}'")
                        break

            # ---- Authentication failures (server -> client replies) ----
            if not to_server and client and server:
                af_proto = ""
                if service_port == 21 and re.match(r"\s*530[ -]", payload_text):
                    af_proto = "FTP"
                elif (row.get("http.response.code") or "") == "401":
                    af_proto = "HTTP"
                elif service_port == 23 and self._TELNET_FAILURE.search(payload_text):
                    af_proto = "Telnet"
                if af_proto:
                    slot = auth_fail[(af_proto, client, server)]
                    slot["count"] += 1
                    slot["pcaps"].add(pcap_name)
                    if len(slot["samples"]) < 5:
                        slot["samples"].append(f"{pcap_name}: {server} -> {client} {info[:120]}")

            # -------- CREDENTIAL EXTRACTION ----------------------------
            ips = (client, server)
            if service_port == 21 and to_server:
                m_user = re.search(r"(?im)^\s*USER\s+(\S{1,64})\s*$", payload_text)
                m_pass = re.search(r"(?im)^\s*PASS\s+(\S{1,128})\s*$", payload_text)
                if m_user:
                    add_cred("FTP", pcap_name, link, ips, m_user.group(1), "", f"USER {m_user.group(1)}")
                if m_pass:
                    add_cred("FTP", pcap_name, link, ips, "", m_pass.group(1), "PASS <captured>")

            if service_port == 23 and payload:
                client_port = row_source_port(row) if to_server else row_destination_port(row)
                state = telnet_state[(client, client_port, server)]
                if not to_server:
                    prompt = payload_text.strip().lower()
                    if re.search(r"(login|username|user name)\s*:\s*$", prompt):
                        state.update(expect="user", buffer="")
                    elif re.search(r"password\s*:\s*$", prompt):
                        state.update(expect="pass", buffer="")
                elif state["expect"]:
                    state["buffer"] += self._TELNET_IAC.sub(b"", payload).decode("latin-1", errors="replace")
                    if "\r" in state["buffer"] or "\n" in state["buffer"]:
                        value = re.split(r"[\r\n]", state["buffer"], maxsplit=1)[0].strip()
                        if state["expect"] == "user":
                            state["user"] = value
                        elif value:
                            add_cred("Telnet", pcap_name, link, ips, state["user"], value, "Telnet login exchange")
                        state.update(expect="", buffer="")

            if to_server and (service_port in self._HTTP_CRED_PORTS or row.get("http.request.method")):
                auth_header = row.get("http.authorization") or ""
                m_ba = re.match(r"(?i)\s*Basic\s+([A-Za-z0-9+/=]{4,200})", auth_header) or \
                    re.search(r"(?i)Authorization:\s*Basic\s+([A-Za-z0-9+/=]{4,200})", payload_text)
                if m_ba:
                    try:
                        decoded = base64.b64decode(m_ba.group(1)).decode("latin-1", errors="replace")
                    except (ValueError, TypeError):
                        decoded = ""
                    if ":" in decoded:
                        user, secret = decoded.split(":", 1)
                        add_cred("HTTP Basic", pcap_name, link, ips, user, secret, "Authorization: Basic <captured>")
                m_form_p = re.search(
                    r"(?i)(?:^|&|\?)(?:password|passwd|pwd|pass|j_password|secret|credential|new_password|currentPassword)=([^&\s]{1,128})",
                    payload_text,
                )
                if m_form_p:
                    m_form = re.search(r"(?i)(?:^|&|\?)(?:user|username|uname|login|email|j_username)=([^&\s]{1,80})", payload_text)
                    add_cred("HTTP Form", pcap_name, link, ips, m_form.group(1) if m_form else "", m_form_p.group(1),
                             f"HTTP form POST password field on port {service_port}")

            community = row.get("snmp.community") or ""
            if community and to_server and (row.get("snmp.version") or "") in ("0", "1"):
                add_cred("SNMPv1/v2c", pcap_name, link, ips, "", community, f"community string: {community}")

            if (row.get("mqtt.msgtype") or "") == "1" and to_server:
                mqtt_user = row.get("mqtt.username") or ""
                mqtt_pass = row.get("mqtt.passwd") or ""
                if mqtt_user or mqtt_pass:
                    add_cred("MQTT", pcap_name, link, ips, mqtt_user, mqtt_pass, "MQTT CONNECT credentials")

            if service_port in (110, 143) and to_server:
                m_u = re.search(r"(?im)^\s*(?:USER|LOGIN)\s+(\S{1,64})", payload_text)
                m_p = re.search(r"(?im)^\s*PASS\s+(\S{1,128})", payload_text)
                if m_u:
                    add_cred("POP3/IMAP", pcap_name, link, ips, m_u.group(1), "", f"USER {m_u.group(1)}")
                if m_p:
                    add_cred("POP3/IMAP", pcap_name, link, ips, "", m_p.group(1), "PASS <captured>")

        for service_port, links in grouped_links.items():
            severity, title = self.LEGACY_SERVICES[service_port]
            evidence = [f"Communication links: {', '.join(sorted(links)[:12])}"] + grouped_samples[service_port][:6]
            self.add_finding(
                severity,
                "Cleartext and Legacy Protocols",
                title,
                f"Legacy or cleartext service traffic was observed on port {service_port} across one or more communication links.",
                evidence,
                sorted(grouped_clients[service_port]),
                sorted(grouped_servers[service_port]),
                f"Port {service_port}",
                sorted(grouped_pcaps[service_port]),
                f"legacy::{service_port}",
                tags=["legacy", f"port_{service_port}"],
            )
        # --- emit one finding per protocol for extracted credentials ---
        for proto, bucket in creds.items():
            entries = bucket["entries"]
            if not entries:
                continue
            # Pair users with passwords chronologically when possible
            users = [e for e in entries if e["user"] and not e["secret_len"]]
            passwords = [e for e in entries if e["secret_len"] and not e["user"]]
            combined = [e for e in entries if e["user"] and e["secret_len"]]
            evidence_lines: List[str] = []
            for e in combined[:20]:
                evidence_lines.append(f"{e['pcap']}: {e['link']} user='{e['user']}' pwd='{e['secret']}'")
            for u, p in zip(users[:20], passwords[:20]):
                if u["pcap"] == p["pcap"] and u["link"] == p["link"]:
                    evidence_lines.append(f"{u['pcap']}: {u['link']} user='{u['user']}' pwd='{p['secret']}'")
            for e in users[:10]:
                evidence_lines.append(f"{e['pcap']}: {e['link']} user='{e['user']}' (no paired pwd captured)")
            for e in passwords[:10]:
                evidence_lines.append(f"{e['pcap']}: {e['link']} pwd='{e['secret']}' (no paired user captured)")
            evidence_lines = sorted(set(evidence_lines))[:40]
            self.add_finding(
                SEVERITY_CRITICAL,
                "Cleartext and Legacy Protocols",
                f"Cleartext credentials extracted ({proto})",
                f"{proto} traffic carried recoverable authentication material in plaintext. "
                "The full captured credentials are included below. Treat this report as sensitive — "
                "these passwords are exposed and should be rotated immediately.",
                evidence_lines + [f"Total credential events captured: {len(entries)}"],
                sorted(bucket["clients"]),
                sorted(bucket["servers"]),
                proto,
                sorted(bucket["pcaps"]),
                f"legacy::creds::{proto}",
                tags=["legacy", "credential_exposure", "cleartext", proto.lower().replace(" ", "_")],
            )

        # ---- Suspicious User-Agent emission ----------------------------
        for (kw, src, _dst), slot in ua_hits.items():
            evidence = list(slot["samples"])
            if slot["dst_ips"]:
                evidence.append(f"Targets contacted: {', '.join(sorted(slot['dst_ips'])[:12])}")
            self.add_finding(
                slot["severity"],
                "Intrusion Indicators",
                f"Suspicious tool User-Agent: {slot['label']}",
                f"HTTP requests from {src or 'unknown source'} carried a User-Agent matching "
                f"'{kw}' ({slot['label']}). Offensive or scanner tooling has no place on an OT "
                "network — investigate the source host and confirm this was an authorized assessment.",
                evidence,
                [src] if src else [], sorted(slot["dst_ips"]), "HTTP",
                sorted(slot["pcaps"]),
                f"intrusion::ua::{kw}::{src}",
                tags=["recon", "ua", "intrusion"],
            )
        # ---- Suspicious Server banner emission ------------------------
        for (kw, host, _client), slot in server_hits.items():
            evidence = list(slot["samples"])
            if slot["client_ips"]:
                evidence.append(f"Clients seen: {', '.join(sorted(slot['client_ips'])[:12])}")
            self.add_finding(
                slot["severity"],
                "Cleartext and Legacy Protocols",
                f"Outdated web-server banner: {slot['label']}",
                f"Server {host or 'unknown'} returned an HTTP banner matching '{kw}' "
                f"({slot['label']}). End-of-life or known-vulnerable web stacks on an OT-adjacent "
                "host materially increase the foothold-and-pivot risk into the control network.",
                evidence,
                sorted(slot["client_ips"]), [host] if host else [], "HTTP",
                sorted(slot["pcaps"]),
                f"legacy::server::{kw}::{host}",
                tags=["legacy", "eol_server"],
            )
        # ---- Auth-failure burst emission ------------------------------
        for (af_proto, attacker, target), state in auth_fail.items():
            if state["count"] < 10:
                continue
            self.add_finding(
                SEVERITY_HIGH,
                "Intrusion Indicators",
                f"Authentication failure burst ({af_proto})",
                f"{state['count']} {af_proto} authentication failures were observed from {attacker} "
                f"to {target}. Sustained failed authentication is the dominant signature of a "
                "credential-bruteforce or password-spray attempt.",
                state["samples"] + [f"Total failure events: {state['count']}"],
                [attacker], [target], af_proto,
                sorted(state["pcaps"]),
                f"intrusion::auth-failure::{af_proto}::{attacker}::{target}",
                tags=["intrusion", "bruteforce", af_proto.lower()],
            )
        return 0

    # A credential *assignment* (key = value) — not merely the word "password",
    # which also appears in login prompts and protocol banners.
    _CREDENTIAL_ASSIGNMENT = re.compile(
        r"(?i)\b(pass(?:word|wd)?|pwd|secret|api[_-]?key|auth[_-]?token|token)\s*[:=]\s*[\"']?([^\s\"'&;,<>]{3,64})")
    _ENGINEERING_FILE = re.compile(r"\b[\w./-]+\.(?:acd|apx|prj|proj|rss|stu|xef|mer|l5k|l5x|bin|img|hex|fw|rom|upd)\b",
                                   re.IGNORECASE)

    def check_artifact_extraction(self, pcaps: Sequence[Path]) -> int:
        """Extract engineering artifacts from OT-adjacent payloads: device identity
        strings, PLC project and firmware file names, and embedded credentials."""
        assert self.session is not None
        model_candidates: Dict[str, set[str]] = defaultdict(set)
        file_hits: Dict[Tuple[str, str, str, str], Dict[str, Any]] = {}
        credential_hits: Dict[Tuple[str, str], Dict[str, Any]] = {}

        def ot_adjacent(*ips: str) -> bool:
            return any(ip and ip in self.session.devices and self._likely_ot_device(self.session.devices[ip])
                       for ip in ips)

        for pcap in pcaps:
            try:
                for row in iter_tshark_rows("(tcp.len > 0) || udp", PAYLOAD_PACKET_FIELDS, pcap):
                    client, server, _service, _transport, to_server = self._orient(row)
                    source_ip, destination_ip = row_source_ip(row), row_destination_ip(row)
                    if not ot_adjacent(source_ip, destination_ip):
                        continue
                    protocol = protocol_family_from_row(row)
                    info = row.get("_ws.col.Info", "")
                    payload_strings = printable_strings_from_bytes(payload_bytes_from_row(row), minimum_length=4)
                    combined_strings = payload_strings + ([info] if info else [])

                    if "bacnet" in protocol.lower() or "bacnet" in (row.get("frame.protocols") or "").lower():
                        for text in combined_strings:
                            for match in re.finditer(r"(model name|model|vendor name|vendor)\s*[:=]\s*([A-Za-z0-9 _./()-]{3,80})", text, re.IGNORECASE):
                                candidate = match.group(2).strip(" .,:;")
                                if candidate and len(candidate) >= 3 and "property" not in candidate.lower():
                                    model_candidates[source_ip or destination_ip or "unknown"].add(candidate)

                    for text in payload_strings:
                        for file_name in self._ENGINEERING_FILE.findall(text):
                            kind = "project" if file_name.lower().endswith(PROJECT_FILE_EXTENSIONS) else "firmware"
                            key = (kind, source_ip, destination_ip, file_name)
                            if key not in file_hits and len(file_hits) < 40:
                                file_hits[key] = {"pcap": pcap.name, "protocol": protocol}

                    if to_server and not row.get("http.request.method"):
                        for text in payload_strings:
                            match = self._CREDENTIAL_ASSIGNMENT.search(text)
                            if not match:
                                continue
                            slot = credential_hits.setdefault((client, server), {"samples": [], "pcaps": set(), "protocol": protocol})
                            slot["pcaps"].add(pcap.name)
                            sample = f"{pcap.name}: {client} -> {server} | {text.strip()[:140]}"
                            if len(slot["samples"]) < 5 and sample not in slot["samples"]:
                                slot["samples"].append(sample)
            except TSharkError as exc:
                print(colorize(f"[!] artifact extraction error on {pcap.name}: {exc}", SEVERITY_HIGH))

        for ip_text, candidates in model_candidates.items():
            self.add_finding(
                SEVERITY_INFO,
                "Artifact Extraction",
                "BACnet model/vendor identity extracted",
                f"BACnet device identity strings were visible for {ip_text}. Recorded for asset identification; "
                "the same visibility lets anyone on the segment fingerprint the device.",
                [f"Candidates: {', '.join(sorted(candidates)[:5])}"],
                [ip_text] if ip_text and ip_text != "unknown" else [],
                [],
                "BACnet/IP",
                [pcap.name for pcap in pcaps],
                f"artifact::bacnet-model::{ip_text}",
                tags=["artifact", "bacnet", "discovery"],
            )

        for (kind, source_ip, destination_ip, file_name), slot in file_hits.items():
            if kind == "project":
                title = "Possible PLC project or ladder-logic file transfer"
                description = ("A file name consistent with PLC project or ladder-logic content was observed in traffic. "
                               "This can indicate program retrieval, upload, or distribution; confirm it was an authorized "
                               "engineering activity.")
                tags = ["artifact", "project_file"]
            else:
                title = "Possible firmware file transfer or firmware reference"
                description = ("A firmware-like file name was observed in traffic to or from an OT-adjacent device. Confirm "
                               "whether a firmware update was scheduled and that the image came from an approved source.")
                tags = ["artifact", "firmware"]
            self.add_finding(
                SEVERITY_HIGH,
                "Artifact Extraction",
                title,
                description,
                [f"{slot['pcap']}: {file_name}", f"{source_ip} -> {destination_ip} via {slot['protocol']}"],
                [source_ip],
                [destination_ip],
                slot["protocol"] or "File Transfer",
                [slot["pcap"]],
                f"artifact::{kind}-file::{file_name}::{source_ip}::{destination_ip}",
                tags=tags,
            )

        for (client, server), slot in credential_hits.items():
            self.add_finding(
                SEVERITY_HIGH,
                "Artifact Extraction",
                "Embedded credential string observed in traffic",
                f"Traffic from {client} to {server} carried a credential-style assignment (password, secret, key, or "
                "token followed by a value) in cleartext. Confirm whether these are live credentials and rotate any that are.",
                slot["samples"],
                [client],
                [server],
                slot["protocol"] or "Credential Exposure",
                sorted(slot["pcaps"]),
                f"artifact::credential::{client}::{server}",
                tags=["artifact", "credential_exposure"],
            )

        if credential_hits:
            self.add_finding(
                SEVERITY_INFO,
                "Protection Guidance",
                "Detection opportunity: cleartext credential material to OT devices",
                "Credential material crossed the network in cleartext toward OT-adjacent hosts. An IDS rule keyed on the "
                "observed protocol, host pair, and credential keywords would alert on recurrences.",
                [
                    "Suggested rule concept: alert on credential keywords or authentication commands over legacy management protocols that target PLC or HMI addresses.",
                    "Implementation: a Snort/Suricata content match scoped to the host pairs listed in the related findings.",
                ],
                [],
                [],
                "Detection Engineering",
                [pcap.name for pcap in pcaps],
                "protection::ids-credential-recovery",
                tags=["protection", "detection"],
            )
        return 0

    def _infer_roles_and_zones(self) -> None:
        """Infer device roles and Purdue-style zones from the services each device
        answers on (`ports`) and connects to (`client_ports`)."""
        assert self.session is not None
        known_hmis = {
            item.strip().lower()
            for item in re.split(r"[,;\s]+", self.session.environment_answers.get("known_hmis", ""))
            if item.strip()
        }
        ot_port_set = set(KNOWN_OT_PORTS)
        for device in self.session.devices.values():
            served = set(device.ports)
            used = set(device.client_ports)
            ot_served = served & ot_port_set
            ot_used = used & ot_port_set
            if device.ip.lower() in known_hmis:
                role = "HMI / Engineering Workstation"
            elif served & {554, 8554}:
                role = "Physical Security Device"
            elif 3956 in served:
                role = "Machine-Vision Camera"
            elif 1502 in served and 1502 not in used:
                role = "Controller / Safety System (SIS)"
            elif ot_served and ot_served <= used:
                # Peer protocols (same port in both directions, e.g. BACnet):
                # ports cannot tell client from server, so use traffic direction.
                role = ("Controller / PLC / RTU" if device.incoming_count >= device.outgoing_count
                        else "HMI / Engineering Workstation")
            elif ot_served & CONTROLLER_PORTS:
                role = "Controller / PLC / RTU"
            elif ot_served:
                role = "OT Server / Gateway"
            elif ot_used:
                role = "HMI / Engineering Workstation"
            elif self._likely_ot_device(device):
                role = "OT Device"
            elif served & (IT_PORTS | IT_INDICATOR_PORTS):
                role = "IT Device"
            else:
                role = "Unknown"
            if role not in ("IT Device", "Unknown", "Physical Security Device") and served & IT_INDICATOR_PORTS:
                role = "Dual-Zone Workstation / Server"
            device.inferred_role = role
            if is_public_ip(device.ip):
                device.inferred_zone = "External / Public"
            elif role == "IT Device":
                device.inferred_zone = "Purdue L4/L5"
            elif role.startswith("Dual-Zone"):
                device.inferred_zone = "Purdue L3/L3.5 Boundary"
            elif role.startswith(("HMI", "OT Server")):
                device.inferred_zone = "Purdue L2/L3"
            elif role.startswith(("Controller", "Machine-Vision")) or role == "OT Device":
                device.inferred_zone = "Purdue L1/L2"
            elif role == "Physical Security Device":
                device.inferred_zone = "Physical Security / OT Edge"
            else:
                device.inferred_zone = "Unknown"

    @staticmethod
    def _arp_conflict_verdicts(hyg: Dict[str, Any]) -> List[Dict[str, Any]]:
        """Decide who owns, and who impersonates, every IP claimed by 2+ MACs in ARP.

        Spoofing signals per claimant MAC: unsolicited ARP replies claiming
        the IP; being a "phantom" identity whose claims were only ever sent
        from another Ethernet source; sending ARP frames on behalf of other
        hosts (MITM tools do this when they restore caches); and claiming
        the IP while using a different address as its own.  The MAC with the
        fewest signals (then the most traffic sent as the IP) is the owner;
        other claimants with signals are impostors.  A conflict with no
        signals at all is reported as such (failover, duplicate address).
        """
        claims: Dict[Tuple[str, str], Dict[str, Any]] = hyg.get("arp_claims", {})
        bindings: Dict[Tuple[str, str], List[float]] = hyg.get("ip_mac", {})
        by_ip: Dict[str, List[str]] = defaultdict(list)
        spoken_for: Dict[str, List[Tuple[str, str, List[float]]]] = defaultdict(list)
        own_ips: Dict[str, set] = defaultdict(set)
        for (ip, mac), claim in claims.items():
            by_ip[ip].append(mac)
            for sender, stats in claim["senders"].items():
                if sender != mac:
                    spoken_for[sender].append((ip, mac, stats))
            if mac in claim["senders"] and claim["frames"] > claim["replies"]:
                own_ips[mac].add(ip)
        verdicts: List[Dict[str, Any]] = []
        for ip, macs in by_ip.items():
            macs = sorted(set(macs))
            if len(macs) < 2:
                continue
            signals: Dict[str, List[str]] = {}
            score: Dict[str, int] = {}
            for mac in macs:
                claim = claims[(ip, mac)]
                reasons: List[str] = []
                points = 0
                if claim["unsolicited"]:
                    reasons.append(f"{claim['unsolicited']} unsolicited ARP repl{'y' if claim['unsolicited'] == 1 else 'ies'} "
                                   f"claiming {ip}")
                    points += 1
                if mac not in claim["senders"]:
                    reasons.append(f"every claim of {ip} at {mac} was sent from another MAC "
                                   f"({', '.join(sorted(claim['senders']))})")
                    points += 2
                spoke = spoken_for.get(mac, [])
                if spoke:
                    reasons.append("sent ARP frames on behalf of " + ", ".join(f"{i} at {m}" for i, m, _ in spoke[:3]))
                    points += 2
                others = sorted(own_ips.get(mac, set()) - {ip})
                if others and ip not in own_ips.get(mac, set()):
                    reasons.append(f"uses {', '.join(others[:3])} as its own address")
                    points += 1
                signals[mac] = reasons
                score[mac] = points
            tx = {mac: (bindings.get((ip, mac)) or [0, 0, 0, 0])[0] for mac in macs}
            owner = min(macs, key=lambda m: (score[m], -tx[m], claims[(ip, m)]["first"] or float("inf")))
            impostors = [mac for mac in macs if mac != owner and score[mac] > 0]
            verdicts.append({
                "ip": ip, "owner": owner, "macs": macs, "impostors": impostors,
                "signals": signals, "own_ips": {mac: sorted(own_ips.get(mac, set()) - {ip}) for mac in macs},
                "spoken_for": {mac: spoken_for.get(mac, []) for mac in macs},
            })
        return verdicts

    def _emit_arp_findings(self, hyg: Dict[str, Any], verdicts: List[Dict[str, Any]], pcap_names: List[str],
                           mac_label: Callable[[str], str],
                           window_line: Callable[..., Optional[str]]) -> None:
        """Emit ARP spoofing / Adversary-in-the-Middle findings from the conflict verdicts."""
        assert self.session is not None
        claims: Dict[Tuple[str, str], Dict[str, Any]] = hyg.get("arp_claims", {})
        bindings: Dict[Tuple[str, str], List[float]] = hyg.get("ip_mac", {})
        details: Dict[Tuple[str, str], Dict[str, Any]] = hyg.get("ip_mac_detail", {})
        impostor_macs: set = set()
        mitm_ips: set = set()

        def _span(epochs: Sequence[float]) -> Tuple[float, float]:
            values = [value for value in epochs if value]
            return (min(values), max(values)) if values else (0.0, 0.0)

        def _window_text(start: float, end: float) -> str:
            duration = human_duration(end - start)
            return (f"{format_epoch(start)} – {format_epoch(end)} ({duration}) — Wireshark: "
                    f"frame.time_epoch >= {start:.6f} && frame.time_epoch <= {end:.6f}")

        # ---- impostors, grouped so one finding covers every IP a MAC impersonated
        by_impostor: Dict[str, List[Dict[str, Any]]] = defaultdict(list)
        for verdict in verdicts:
            for mac in verdict["impostors"]:
                by_impostor[mac].append(verdict)
        for impostor, impersonations in sorted(by_impostor.items()):
            impostor_macs.add(impostor)
            victims = sorted(v["ip"] for v in impersonations)
            mitm_ips.update(victims)
            own_ips = sorted({ip for v in impersonations for ip in v["own_ips"].get(impostor, [])})
            frame_senders = sorted({s for v in impersonations for s in claims[(v["ip"], impostor)]["senders"]} - {impostor})
            evidence: List[str] = []
            epochs: List[float] = []
            targets: Dict[Tuple[str, str], int] = Counter()
            replies = unsolicited = 0
            for v in impersonations:
                claim = claims[(v["ip"], impostor)]
                replies += claim["replies"]
                unsolicited += claim["unsolicited"]
                epochs += [claim["first"], claim["last"]]
                for target, count in claim["targets"].items():
                    targets[target] += count
            identity = f"Impostor MAC: {mac_label(impostor)}"
            own_text = (f"its own address is {own_ips[0]}" if len(own_ips) == 1
                        else f"its own addresses are {', '.join(own_ips[:-1])} and {own_ips[-1]}" if own_ips else "")
            if own_ips:
                identity += f" — {own_text}"
            if frame_senders:
                identity += f" — its ARP frames were sent from {', '.join(mac_label(s) for s in frame_senders)}"
            evidence.append(identity)
            for v in impersonations:
                evidence.append(f"Impersonated host: {v['ip']} (real MAC {mac_label(v['owner'])})")
            target_ips: List[str] = []
            for (target_ip, target_mac), count in sorted(targets.items(), key=lambda item: -item[1]):
                target_ips.append(target_ip)
                evidence.append(f"Poisoned ARP cache: {target_ip}" + (f" ({mac_label(target_mac)})" if target_mac else "")
                                + f" — {count} spoofed ARP repl{'y' if count == 1 else 'ies'}")
            intercepted_tx = intercepted_rx = 0
            peers: Counter[str] = Counter()
            labels: Counter[str] = Counter()
            samples: List[Tuple[bool, str]] = []
            for v in impersonations:
                stats = bindings.get((v["ip"], impostor))
                if stats and (stats[0] or stats[1]):
                    intercepted_tx += int(stats[0])
                    intercepted_rx += int(stats[1])
                    epochs += [stats[2], stats[3]]
                    detail = details.get((v["ip"], impostor)) or {}
                    peers.update(detail.get("peers", {}))
                    labels.update(detail.get("labels", {}))
                    for label, line in detail.get("samples", {}).items():
                        samples.append((label in ("ICMP", "TCP", "ICMPv6", "ARP"), line))
            intercepted = intercepted_tx + intercepted_rx
            sample_lines: List[str] = []
            if intercepted:
                peer_text = ", ".join(peers) if peers else "its peers"
                label_text = ", ".join(label for label, _ in labels.most_common(4)) or "IP"
                evidence.append(f"Intercepted traffic: {intercepted_tx:,} frames sent as {', '.join(victims)} and "
                                f"{intercepted_rx:,} frames addressed to it passed through {impostor} — {label_text} "
                                f"with {peer_text}")
            sample_lines = [line for _, line in sorted(samples, key=lambda item: item[0])[:2]]
            restores: List[str] = []
            for ip, real_mac, stats in [item for v in impersonations for item in v["spoken_for"].get(impostor, [])]:
                restores.append(f"ARP restore: {impostor} re-announced {ip} at {real_mac} ({int(stats[0])} frame(s), "
                                f"last @{stats[2]:.6f}) — MITM tools do this when they stop")
                epochs += [stats[1], stats[2]]
            start, end = _span(epochs)
            if start:
                evidence.append(f"Attack window: {_window_text(start, end)}")
            evidence += sample_lines
            evidence += restores[:3]
            evidence.append(f"Wireshark: eth.addr == {impostor} lists every frame the impostor sent or received")
            for v in impersonations:
                for reason in v["signals"].get(impostor, []):
                    evidence.append(f"Spoofing indicator: {reason}")
            # Write/control commands to or from the hosts in the poisoned path, inside the window.
            writes = []
            for f in self.session.findings:
                ends = set(f.source_ips) | set(f.destination_ips)
                if "write" not in f.tags or not (ends & set(victims)) or (target_ips and not ends & set(target_ips)):
                    continue
                try:
                    seen_from = float(f.first_seen) if f.first_seen else None
                    seen_to = float(f.last_seen) if f.last_seen else seen_from
                except ValueError:
                    seen_from = seen_to = None
                if seen_from is None or not start or (seen_from <= end + 1 and (seen_to or seen_from) >= start - 1):
                    writes.append(f)
            for f in writes[:5]:
                evidence.append(f"Write/control during the attack: [{f.severity}] {f.title} — "
                                f"{', '.join(f.source_ips[:2])} → {', '.join(f.destination_ips[:2])}")
            victim_text = " and ".join(victims)
            target_text = ", ".join(target_ips) if target_ips else "other hosts"
            real_text = "; ".join(f"the real {v['ip']} is {v['owner']}" for v in impersonations)
            narrative = (f"MAC {mac_label(impostor)}{', whose ' + own_text.replace('its ', '', 1) + ',' if own_ips else ''} "
                         f"sent {replies} spoofed ARP repl{'y' if replies == 1 else 'ies'} to {target_text} claiming to be "
                         f"{victim_text} ({real_text}).")
            if intercepted:
                severity = SEVERITY_INTRUSION
                title = "ARP-based Adversary-in-the-Middle attack pattern detected — traffic intercepted"
                narrative += (f" From {format_epoch(start)} to {format_epoch(end)}, {victim_text}'s traffic"
                              f"{' with ' + ', '.join(peers) if peers else ''} passed through that MAC: {intercepted:,} "
                              "frames. A host in that position can read, alter, or drop every command and process value "
                              "in the session.")
            elif writes:
                severity = SEVERITY_INTRUSION
                title = "ARP-based Adversary-in-the-Middle attack pattern detected — OT writes during poisoning"
                narrative += (" Write/control commands crossed the poisoned path while the spoofed entries were live; "
                              "this capture point did not see them pass through the impostor, but any that reached a "
                              "poisoned host's cache would have.")
            else:
                severity = SEVERITY_CRITICAL
                title = "ARP-based Adversary-in-the-Middle attack pattern detected"
                narrative += (" No traffic was seen passing through the impostor from this capture point, which may "
                              "only see part of the path; treat the position as established.")
            if restores:
                narrative += " The impostor later re-announced the real MAC — the clean-up step of MITM tools."
            self.add_finding(
                severity, "Intrusion Indicators", title, narrative, evidence,
                own_ips, sorted(set(victims) | set(target_ips)), "ARP", pcap_names,
                f"intrusion::mitm-arp::{impostor}",
                tags=["arp_spoof", "mitm", "intrusion"],
                first_seen=f"{start:.6f}" if start else None, last_seen=f"{end:.6f}" if end else None,
            )
            window_note = f" between {format_epoch(start)} and {format_epoch(end)}" if start else ""
            for ip in victims:
                device = self.session.devices.get(ip)
                if device is not None:
                    self._remember_unique(device.evidence, f"Impersonated by MAC {impostor}{window_note} "
                                                           "(ARP-based Adversary-in-the-Middle finding)")
            for ip in own_ips:
                device = self.session.devices.get(ip)
                if device is not None:
                    self._remember_unique(device.evidence, f"Impostor: MAC {impostor} claimed {victim_text} in ARP"
                                                           f"{window_note}")
            for ip in target_ips:
                device = self.session.devices.get(ip)
                if device is not None:
                    self._remember_unique(device.evidence, f"ARP cache poisoned by MAC {impostor}{window_note}")

        # ---- conflicts without spoofing signals (failover, duplicate address) ----
        for verdict in verdicts:
            if verdict["impostors"]:
                continue
            ip = verdict["ip"]
            lines = []
            for mac in verdict["macs"]:
                claim = claims[(ip, mac)]
                stats = bindings.get((ip, mac))
                carried = (f"; carried {int(stats[0]):,} frames sent as {ip}" if stats and stats[0] else "")
                lines.append(f"{mac_label(mac)}: {claim['frames']} ARP frame(s) claiming {ip}, "
                             f"@{claim['first']:.6f} – @{claim['last']:.6f}{carried}")
            window = window_line(ip=ip)
            self.add_finding(
                SEVERITY_HIGH, "Network Hygiene and Segmentation", "IP address claimed by multiple MACs in ARP",
                f"{ip} was claimed by {len(verdict['macs'])} MAC addresses in ARP, without spoofing indicators "
                "(no unsolicited replies, no frames sent on another host's behalf). Likely causes: VRRP/HSRP failover, "
                "NIC teaming, a duplicate address, or a device replaced while keeping its IP — validate which.",
                lines + ([window] if window else []), [ip], [], "ARP", pcap_names,
                f"arp::ip-multi-mac::{ip}", tags=["arp_spoof", "mac_conflict"],
            )

        # ---- signals not explained by an impostor finding -------------------------
        for mac, count in hyg.get("gratuitous_arp_by_src", Counter()).items():
            if count >= 10 and mac and mac not in impostor_macs:
                ips_claimed = sorted(hyg["mac_to_ips"].get(mac, set()))
                window = window_line(mac=mac)
                self.add_finding(
                    SEVERITY_HIGH, "Network Hygiene and Segmentation", "Gratuitous ARP burst observed",
                    f"MAC {mac_label(mac)} sent {count} gratuitous ARP frames. Bursts of gratuitous ARP are commonly "
                    "used to poison neighbor caches for adversary-in-the-middle attacks, or can indicate failover/HA "
                    "flapping. Validate against expected HA/VRRP events.",
                    [f"Gratuitous ARP count: {count}", f"IPs claimed by {mac_label(mac)}: {', '.join(ips_claimed[:10])}"]
                    + ([window] if window else []),
                    ips_claimed[:5], [], "ARP", pcap_names, f"arp::grat::{mac}",
                    tags=["arp_spoof", "gratuitous_arp"],
                )
        for mac, ips in hyg.get("mac_to_ips", {}).items():
            if len(ips) >= 3 and mac and mac not in impostor_macs:
                window = window_line(mac=mac)
                self.add_finding(
                    SEVERITY_MEDIUM, "Network Hygiene and Segmentation", "Single MAC claims multiple IPs via ARP",
                    f"MAC {mac_label(mac)} announced itself as {len(ips)} distinct IPv4 addresses in ARP. "
                    "Legitimate reasons include routers, proxy-ARP, VIPs, and teaming — but this is also a "
                    "signature of ARP spoofing and of rogue devices.",
                    [f"Claimed IPs: {', '.join(sorted(ips)[:15])}"] + ([window] if window else []),
                    sorted(ips)[:5], [], "ARP", pcap_names, f"arp::mac-multi-ip::{mac}", tags=["arp_spoof"],
                )
        for pn, eth_mac, arp_mac, arp_ip in hyg.get("eth_mac_mismatch", []):
            if eth_mac in impostor_macs or arp_mac in impostor_macs or arp_ip in mitm_ips:
                continue
            window = window_line(ip=arp_ip, mac=arp_mac)
            self.add_finding(
                SEVERITY_HIGH, "Network Hygiene and Segmentation", "ARP sender MAC differs from Ethernet source MAC",
                f"{mac_label(eth_mac)} sent an ARP frame claiming {arp_ip} is at {mac_label(arp_mac)}. A host speaking "
                "for another host's address is a strong ARP spoofing indicator used by MITM toolkits.",
                [f"Ethernet src={mac_label(eth_mac)}, ARP src={mac_label(arp_mac)}, ARP sender IP={arp_ip}"]
                + ([window] if window else []),
                [arp_ip] if arp_ip else [], [], "ARP", [pn],
                f"arp::mac-mismatch::{eth_mac}::{arp_mac}::{arp_ip}", tags=["arp_spoof", "intrusion"],
            )
        reply_only: Dict[str, List[Tuple[str, str]]] = defaultdict(list)
        for _pn, mac, sender_ip, target_ip in hyg.get("arp_reply_no_request", []):
            reply_only[mac].append((sender_ip, target_ip))
        for mac, pairs in reply_only.items():
            if len(pairs) >= 5 and mac and mac not in impostor_macs:
                claimed = sorted({ip for ip, _ in pairs if ip})
                targets = sorted({ip for _, ip in pairs if ip})
                self.add_finding(
                    SEVERITY_MEDIUM, "Network Hygiene and Segmentation", "ARP replies without matching requests",
                    f"MAC {mac_label(mac)} sent {len(pairs)} ARP replies nobody asked for, claiming "
                    f"{', '.join(claimed[:5])} to {', '.join(targets[:5])}. Some HA setups do this; so does ARP spoofing.",
                    [f"Unsolicited ARP replies: {len(pairs)}", f"Claimed: {', '.join(claimed[:10])}",
                     f"Sent to: {', '.join(targets[:10])}"],
                    claimed[:10], targets[:10], "ARP", pcap_names, f"arp::unsolicited-reply::{mac}",
                    tags=["arp_spoof"],
                )

    def check_network_hygiene(self, pcaps: Sequence[Path]) -> int:
        """Analyze segmentation and hygiene conditions across the unified dataset."""
        assert self.session is not None
        # Scale-aware emission caps: huge captures (e.g. ping-flood test
        # pcaps with 1M+ spoofed source IPs) can produce hundreds of
        # thousands of per-pair findings whose dedup-merge cost is O(N²)
        # because each merge does sorted(set(...)) on a growing list.
        # When device count is huge we switch to aggregate findings.
        n_devices = len(self.session.devices)
        n_connections = len(self.session.connections)
        FAST_PATH_THRESHOLD = 50000
        in_fast_path = n_devices > FAST_PATH_THRESHOLD or n_connections > FAST_PATH_THRESHOLD
        if in_fast_path:
            self._log_ts(
                f"      Large dataset detected ({n_devices:,} devices, {n_connections:,} "
                "connections) — switching to aggregate-finding mode to avoid finding storms."
            )
        # Per-finding-type emission caps so a single category can't fill
        # the report.  Hit the cap → emit a single rollup finding and stop.
        EMIT_CAP = 200 if not in_fast_path else 25
        emit_count: Counter[str] = Counter()
        rollup_buckets: Dict[str, Dict[str, Any]] = defaultdict(
            lambda: {"src_ips": set(), "dst_ips": set(), "pcaps": set(), "samples": []}
        )

        def _capped_add(finding_type: str, severity: str, title: str, description: str,
                        evidence: List[str], src: List[str], dst: List[str], proto: str,
                        pcap_names: Sequence[str], dedup: str, tags: List[str]) -> None:
            """add_finding wrapper that switches to a rollup once cap is hit."""
            count = emit_count[finding_type]
            if count < EMIT_CAP:
                emit_count[finding_type] += 1
                self.add_finding(severity, "Network Hygiene and Segmentation", title,
                                 description, evidence, src, dst, proto, pcap_names,
                                 dedup, tags=tags)
                return
            # Past cap: accumulate into a single rollup bucket per finding-type.
            bucket = rollup_buckets[finding_type]
            bucket["src_ips"].update(src)
            bucket["dst_ips"].update(dst)
            bucket["pcaps"].update(pcap_names)
            bucket["severity"] = severity
            bucket["title"] = title
            bucket["proto"] = proto
            bucket["tags"] = tags
            if len(bucket["samples"]) < 20:
                bucket["samples"].extend(evidence[:2])

        self._log_ts("      [hygiene 1/5] inferring roles and zones …")
        self._infer_roles_and_zones()
        # RST / SYN / ARP state comes from the streaming combined pass.
        _hyg: Dict[str, Any] = getattr(self, "_hygiene_tcp_state", None) or {}
        arp_verdicts = self._arp_conflict_verdicts(_hyg) if _hyg else []
        arp_conflict_ips = {verdict["ip"] for verdict in arp_verdicts}
        bindings: Dict[Tuple[str, str], List[float]] = _hyg.get("ip_mac", {})

        def _binding_line(ip: str, mac: str) -> str:
            stats = bindings.get((ip, mac.lower()))
            vendor = lookup_oui_vendor(mac)
            label = f"{mac} ({vendor})" if vendor else mac
            if not stats:
                return f"{label}: no OT/monitored traffic carried"
            return (f"{label}: {int(stats[0]):,} frames sent as {ip}, {int(stats[1]):,} frames addressed to it, "
                    f"{format_epoch(stats[2])} – {format_epoch(stats[3])} (@{stats[2]:.6f} – @{stats[3]:.6f})")

        self._log_ts(f"      [hygiene 2/5] per-device MAC drift "
                     f"({n_devices:,} devices) …")
        # MACs fronting many IPs are routers / firewalls / L3 switches: every
        # remote host is seen behind them, so they say nothing about spoofing.
        mac_ip_counts: Counter[str] = Counter()
        for device in self.session.devices.values():
            for mac in device.macs:
                mac_ip_counts[mac.lower()] += 1
        gateway_macs = {mac for mac, count in mac_ip_counts.items() if count >= 10}
        device_iter = 0
        device_log_every = max(50000, n_devices // 10) if n_devices else 0
        for device in self.session.devices.values():
            device_iter += 1
            if device_log_every and device_iter % device_log_every == 0:
                self._log_ts(f"          … {device_iter:,}/{n_devices:,} devices")
            station_macs = sorted(
                mac for mac in device.macs
                if mac.lower() not in gateway_macs and not mac.lower().startswith(("ff:ff:ff", "01:00:5e", "33:33"))
            )
            if len(station_macs) > 1 and device.ip not in arp_conflict_ips:
                _capped_add("multi_mac", SEVERITY_HIGH, "Multiple MAC addresses observed for one IP",
                    f"{device.ip}'s traffic was carried by {len(station_macs)} different MAC addresses. Without an "
                    "ARP conflict in the capture this can be a failover pair or a replaced NIC — or interception whose "
                    "ARP poisoning happened out of the capture's view.",
                    [_binding_line(device.ip, mac) for mac in station_macs], [device.ip], [], "IP",
                    device.source_pcaps, f"net::multi-mac::{device.ip}", ["mac_conflict"])

        self._log_ts(f"      [hygiene 3/5] OT/IT crossings, DNS/ICMP, IPv6 "
                     f"({n_connections:,} connections) …")
        conn_iter = 0
        conn_log_every = max(50000, n_connections // 10) if n_connections else 0
        icmp_pairs: List[str] = []
        icmp_ips: set = set()
        icmp_pcaps: set = set()
        ipv6_hosts: Dict[str, set] = defaultdict(set)
        ipv6_pcaps: set = set()
        for connection in self.session.connections.values():
            conn_iter += 1
            if conn_log_every and conn_iter % conn_log_every == 0:
                self._log_ts(f"          … {conn_iter:,}/{n_connections:,} connections")
            if ":" in connection.source_ip or ":" in connection.destination_ip:
                ipv6_pcaps.update(connection.source_pcaps)
                for address in (connection.source_ip, connection.destination_ip):
                    if address and not is_group_address(address) and not is_unspecified_address(address):
                        ipv6_hosts[address].add(connection.protocol)
            source_device = self.session.devices.get(connection.source_ip)
            destination_device = self.session.devices.get(connection.destination_ip)
            if not source_device or not destination_device:
                continue
            if self._likely_ot_device(source_device) and connection.destination_port == 53:
                _capped_add("ot_dns", SEVERITY_MEDIUM, "DNS query from OT device",
                    f"OT-adjacent device {connection.source_ip} sent DNS queries. Controllers and field devices "
                    "should not normally need name resolution.",
                    [f"{connection.source_ip} -> {connection.destination_ip}:53 | packets: {connection.packet_count}"],
                    [connection.source_ip], [connection.destination_ip],
                    "DNS", connection.source_pcaps,
                    f"net::dns::{connection.source_ip}", [])
            if connection.protocol == "ICMP" and (self._likely_ot_device(source_device)
                                                 or self._likely_ot_device(destination_device)):
                if len(icmp_pairs) < 40:
                    icmp_pairs.append(f"{connection.source_ip} <-> {connection.destination_ip} | packets: {connection.packet_count}")
                icmp_ips.update((connection.source_ip, connection.destination_ip))
                icmp_pcaps.update(connection.source_pcaps)
            if source_device.inferred_role.startswith("Controller") and destination_device.inferred_role == "IT Device":
                _capped_add("ot_to_it", SEVERITY_HIGH, "Direct OT-to-IT communication observed",
                    f"Controller-class device {connection.source_ip} communicated directly with IT device {connection.destination_ip}.",
                    [f"{connection.protocol} on port {connection.destination_port} | packets: {connection.packet_count}"],
                    [connection.source_ip], [connection.destination_ip], connection.protocol,
                    connection.source_pcaps,
                    f"net::ot-it::{connection.source_ip}::{connection.destination_ip}", ["boundary"])
        if icmp_pairs:
            self.add_finding(
                SEVERITY_LOW, "Network Hygiene and Segmentation", "ICMP traffic involving OT devices",
                f"ICMP was exchanged with {len(icmp_ips)} OT-adjacent host(s). Ping-based monitoring is common, but "
                "ICMP reachability also lets anyone on the segment map live controllers.",
                icmp_pairs, sorted(icmp_ips)[:30], [], "ICMP", sorted(icmp_pcaps),
                "net::icmp-ot", tags=["icmp"],
            )
        if ipv6_hosts:
            owner_of: Dict[str, DeviceRecord] = {}
            for device in self.session.devices.values():
                for address in device.ipv6_addresses:
                    owner_of[address] = device
            routable = sorted(address for address in ipv6_hosts if not is_link_local_ipv6(address))
            ipv6_lines: List[str] = []
            ipv6_assets: List[str] = []
            for address in sorted(ipv6_hosts):
                protocols = ", ".join(sorted(ipv6_hosts[address])) or "IPv6"
                host = owner_of.get(address)
                device = self.session.devices.get(address)
                if host is not None:
                    link = (self.session.analysis_metadata.get("ipv6_links") or {}).get(address, {})
                    via = f" (same MAC {link['mac']})" if link.get("mac") else ""
                    ipv6_lines.append(f"{address} — same host as {host.ip}{via}: {protocols}")
                    ipv6_assets.append(host.ip)
                else:
                    macs = [mac for mac in (device.macs if device else []) if not is_group_mac(mac)]
                    mac_text = ", ".join(f"{mac} ({lookup_oui_vendor(mac)})" if lookup_oui_vendor(mac) else mac
                                         for mac in macs[:2]) or "MAC unknown"
                    ipv6_lines.append(f"{address} — {mac_text}, no IPv4 address seen: {protocols}")
                    ipv6_assets.append(address)
            if routable:
                ipv6_severity = SEVERITY_MEDIUM
                ipv6_description = (f"{len(ipv6_hosts)} host address(es) used IPv6, including routable address(es) "
                                    f"{', '.join(routable[:5])}. Most OT firewalls and monitoring are configured for "
                                    "IPv4 only; confirm IPv6 is intended and covered by policy.")
            else:
                ipv6_severity = SEVERITY_LOW
                ipv6_description = (f"{len(ipv6_hosts)} host(s) used IPv6 link-local only — router/neighbor discovery, "
                                    "DHCPv6, LLMNR, or WS-Discovery that Windows and VM hosts send by default. Unneeded "
                                    "IPv6 is an unmonitored path for spoofing and name-poisoning attacks; disable it on OT "
                                    "hosts or include it in monitoring.")
            self.add_finding(
                ipv6_severity, "Network Hygiene and Segmentation", "IPv6 traffic observed",
                ipv6_description, ipv6_lines[:40], sorted(set(ipv6_assets))[:30], [], "IPv6", sorted(ipv6_pcaps),
                "net::ipv6", tags=["ipv6"],
            )
        for device in self.session.devices.values():
            if device.inferred_role != "Dual-Zone Workstation / Server":
                continue
            windows_ports = sorted(set(device.ports) & IT_INDICATOR_PORTS)
            ot_ports = sorted((set(device.ports) | set(device.client_ports)) & set(KNOWN_OT_PORTS))
            _capped_add("dual_zone", SEVERITY_HIGH, "Dual-zone boundary device inferred",
                f"{device.ip} participates in OT protocols and also serves Windows / IT services "
                f"(ports {', '.join(str(p) for p in windows_ports)}). Hosts like this — typically Windows HMIs or "
                "engineering stations exposing SMB/RDP — are a classic bridge between IT and OT zones.",
                [f"IT services answered: {', '.join(str(p) for p in windows_ports)}",
                 f"OT protocol ports: {', '.join(str(p) for p in ot_ports) or '(protocol markers only)'}"],
                [device.ip], [], "Multi-Protocol",
                device.source_pcaps, f"net::dual-zone::{device.ip}", ["boundary"])
        self._log_ts("      [hygiene 4/5] public-IP enrichment …")
        public_links: Dict[str, List[str]] = defaultdict(list)
        public_pcaps: Dict[str, set[str]] = defaultdict(set)
        public_destinations: Dict[str, set[str]] = defaultdict(set)
        # Pre-compute the list of public destinations to enrich so we can
        # show progress as RDAP/PTR lookups proceed (each one can take up
        # to ~4s with the default timeout, so a user-visible counter is
        # important on long-running captures with many public talkers).
        _public_targets = [
            c for c in self.session.connections.values()
            if (sd := self.session.devices.get(c.source_ip))
            and self._likely_ot_device(sd)
            and is_public_ip(c.destination_ip)
        ]
        _pub_total = len(_public_targets)
        if _pub_total and not self._is_air_gapped():
            self._log_ts(f"      Resolving {_pub_total} public-IP destination(s) (PTR + RDAP) …")
        _pub_idx = 0
        for connection in _public_targets:
            source_device = self.session.devices.get(connection.source_ip)
            if source_device and self._likely_ot_device(source_device) and is_public_ip(connection.destination_ip):
                _pub_idx += 1
                if _pub_total >= 10 and (_pub_idx == 1 or _pub_idx % 10 == 0 or _pub_idx == _pub_total):
                    cached = connection.destination_ip in self.public_ip_cache
                    tag = "cached" if cached else "lookup"
                    self._log_ts(f"      [{_pub_idx}/{_pub_total}] {connection.destination_ip} ({tag})")
                context = self._public_ip_context(connection.destination_ip)
                context_parts = []
                if context.get("ptr"):
                    context_parts.append(f"PTR {context['ptr']}")
                if context.get("network_name"):
                    context_parts.append(f"owner/network {context['network_name']}")
                if context.get("country"):
                    context_parts.append(f"country {context['country']}")
                context_text = f" ({'; '.join(context_parts)})" if context_parts else ""
                public_links[connection.source_ip].append(
                    f"{connection.source_ip} -> {connection.destination_ip} via {connection.protocol}/{connection.destination_port}, {connection.packet_count} pkts{context_text}"
                )
                public_pcaps[connection.source_ip].update(connection.source_pcaps)
                public_destinations[connection.source_ip].add(connection.destination_ip)
        for source_ip, links in public_links.items():
            self.add_finding(
                SEVERITY_CRITICAL,
                "Network Hygiene and Segmentation",
                "OT device communicating with public IP",
                f"{source_ip} communicated directly with one or more public IP addresses. OT devices should not normally reach public networks.",
                links[:10],
                [source_ip],
                sorted(public_destinations[source_ip]),
                "Public Network Exposure",
                sorted(public_pcaps[source_ip]),
                f"net::public::{source_ip}",
                tags=["boundary", "public"],
            )
        # RST / SYN anomaly counts come from the streaming combined pass
        # (_run_streaming_protocol_checks stores them in self._hygiene_tcp_state).
        # We fall back to a direct tshark read only if this method is somehow
        # called before the streaming pass (e.g. from a unit test or future
        # check re-ordering).
        rst_after_fin: Counter[Tuple[str, str]] = Counter()
        if _hyg:
            rst_counts: Counter[Tuple[str, str]] = _hyg.get("rst_counts", Counter())
            rst_after_fin = _hyg.get("rst_after_fin", Counter())
            syn_counts: Counter[Tuple[str, str]] = _hyg.get("syn_counts", Counter())
            synack_counts: Counter[Tuple[str, str]] = _hyg.get("synack_counts", Counter())
            hygiene_pcap_names: List[str] = sorted(_hyg.get("pcap_names", set()))
        else:
            # Fallback: direct tshark pass (only reached outside normal run_optional_checks flow)
            rst_counts = Counter()
            syn_counts = Counter()
            synack_counts = Counter()
            seen_pcap_names: set[str] = set()
            fin_seen: set = set()
            for pcap_file, row in self._filtered_rows(pcaps, "tcp.flags.reset==1 || tcp.flags.syn==1 || tcp.flags.fin==1"):
                seen_pcap_names.add(pcap_file.name)
                flags = _tcp_flag_bits(row)
                pair = (row_source_ip(row), row_destination_ip(row))
                ends = sorted([(pair[0], row_source_port(row)), (pair[1], row_destination_port(row))])
                if flags & 0x01:
                    fin_seen.add(tuple(ends))
                if flags & 0x04:
                    if tuple(ends) in fin_seen:
                        rst_after_fin[pair] += 1
                    else:
                        rst_counts[pair] += 1
                if flags & 0x12 == 0x02:
                    syn_counts[pair] += 1
                elif flags & 0x12 == 0x12:
                    synack_counts[pair] += 1
            hygiene_pcap_names = sorted(seen_pcap_names)
        self._log_ts(f"      [hygiene 5/5] TCP RST/SYN anomalies + ARP spoof checks "
                     f"({len(rst_counts):,} RST pairs, {len(syn_counts):,} SYN pairs) …")
        for pair, count in rst_counts.items():
            if count >= 20:
                _capped_add("rst_storm", SEVERITY_HIGH, "TCP reset storm observed",
                    f"{pair[0]} reset {count} TCP connections with {pair[1]} without a normal close. Repeated aborts "
                    "indicate refused connection attempts (scanning), a service that keeps failing, or deliberate "
                    "connection disruption. RSTs that follow a FIN exchange are routine teardown and are not counted.",
                    [f"Aborting RSTs: {count}",
                     f"RSTs after a normal FIN close (not counted): {rst_after_fin.get(pair, 0)}"],
                    [pair[0]], [pair[1]], "TCP",
                    hygiene_pcap_names, f"net::rst::{pair[0]}::{pair[1]}", ["tcp_anomaly"])
        for pair, count in syn_counts.items():
            unanswered = count - synack_counts.get((pair[1], pair[0]), 0)
            if unanswered >= 20:
                _capped_add("syn_storm", SEVERITY_HIGH, "Repeated unanswered SYNs observed",
                    f"{pair[0]} sent {count} connection attempts to {pair[1]}, {unanswered} of which got no SYN-ACK. "
                    "Unanswered connection attempts indicate scanning, a blocked path, or a service that is down.",
                    [f"SYN count: {count}", f"Unanswered: {unanswered}"], [pair[0]], [pair[1]], "TCP",
                    hygiene_pcap_names, f"net::syn::{pair[0]}::{pair[1]}", ["tcp_anomaly"])

        # ---- ARP spoof / MAC-IP drift findings -------------------------
        # Helper: annotate a MAC with its OUI vendor when known.  Surfacing
        # the vendor is high-signal in MITM scenarios — e.g. two distinct
        # MACs both resolving to "VMware" point to an attacker VM on the
        # same broadcast domain, which is a much louder finding than two
        # raw hex strings.
        def _mac_with_vendor(mac: str) -> str:
            v = lookup_oui_vendor(mac)
            return f"{mac} ({v})" if v else mac

        def _macs_with_vendors(macs: Sequence[str], limit: int = 8) -> str:
            return ", ".join(_mac_with_vendor(m) for m in sorted(macs)[:limit])

        # Build a "First seen / Last seen" evidence line carrying real
        # epoch values, so analysts can paste either bound into Wireshark
        # as `frame.time_epoch == X` or use them as a range filter
        # `frame.time_epoch >= A && frame.time_epoch <= B` to bracket the
        # spoofing window.  Returns None if no timestamps were captured.
        def _arp_window_evidence(ip: str = "", mac: str = "") -> Optional[str]:
            firsts = []
            lasts = []
            if ip:
                if ip in _hyg.get("ip_first_seen", {}):
                    firsts.append(_hyg["ip_first_seen"][ip])
                if ip in _hyg.get("ip_last_seen", {}):
                    lasts.append(_hyg["ip_last_seen"][ip])
            if mac:
                if mac in _hyg.get("mac_first_seen", {}):
                    firsts.append(_hyg["mac_first_seen"][mac])
                if mac in _hyg.get("mac_last_seen", {}):
                    lasts.append(_hyg["mac_last_seen"][mac])
            if not firsts or not lasts:
                return None
            t0 = min(firsts)
            t1 = max(lasts)
            return (
                f"Observation window: first seen @{t0:.6f}, last seen @{t1:.6f} "
                f"(Wireshark: `frame.time_epoch >= {t0:.6f} && frame.time_epoch <= {t1:.6f}`)"
            )

        if _hyg:
            self._emit_arp_findings(_hyg, arp_verdicts, hygiene_pcap_names, _mac_with_vendor, _arp_window_evidence)
        # VLAN anomaly checks using VLAN IDs captured during inventory
        ot_vlans: set[str] = set()
        it_vlans: set[str] = set()
        for device in self.session.devices.values():
            if not device.vlans:
                continue
            if self._likely_ot_device(device):
                ot_vlans.update(device.vlans)
            elif "IT Device" in device.inferred_role:
                it_vlans.update(device.vlans)
        shared_vlans = ot_vlans.intersection(it_vlans)
        if shared_vlans:
            ot_ips = sorted(d.ip for d in self.session.devices.values() if self._likely_ot_device(d) and any(v in shared_vlans for v in d.vlans))
            it_ips = sorted(d.ip for d in self.session.devices.values() if "IT Device" in d.inferred_role and any(v in shared_vlans for v in d.vlans))
            self.add_finding(
                SEVERITY_HIGH,
                "Network Hygiene and Segmentation",
                "OT and IT devices sharing the same VLAN",
                f"OT-adjacent and IT-classified devices appear on shared VLAN(s): {', '.join(sorted(shared_vlans))}. "
                "Flat VLAN topologies remove a key segmentation control and allow lateral movement without routing.",
                [
                    f"Shared VLANs: {', '.join(sorted(shared_vlans))}",
                    f"OT devices on shared VLAN: {', '.join(ot_ips[:10])}",
                    f"IT devices on shared VLAN: {', '.join(it_ips[:10])}",
                ],
                ot_ips[:10],
                it_ips[:10],
                "VLAN",
                [pcap.name for pcap in pcaps],
                f"net::vlan-flat::{'_'.join(sorted(shared_vlans))}",
                tags=["boundary", "vlan"],
            )
        for device in self.session.devices.values():
            if len(device.vlans) > 1 and self._likely_ot_device(device):
                self.add_finding(
                    SEVERITY_HIGH,
                    "Network Hygiene and Segmentation",
                    "OT device observed on multiple VLANs",
                    f"{device.ip} appeared on multiple VLANs ({', '.join(sorted(device.vlans))}), "
                    "which may indicate a multi-homed or bridging device.",
                    [f"VLANs: {', '.join(sorted(device.vlans))}"],
                    [device.ip],
                    [],
                    "VLAN",
                    device.source_pcaps,
                    f"net::multi-vlan::{device.ip}",
                    tags=["boundary", "vlan"],
                )

        # ---- Rollup: emit one aggregate finding per finding-type that
        # exceeded the per-type emission cap.  Lets the report stay
        # readable on extreme datasets without losing the signal entirely.
        for finding_type, bucket in rollup_buckets.items():
            self.add_finding(
                bucket["severity"], "Network Hygiene and Segmentation",
                f"{bucket['title']} (+ {len(bucket['src_ips'])} more sources rolled up)",
                f"This finding rolls up {len(bucket['src_ips'])} additional sources / "
                f"{len(bucket['dst_ips'])} additional destinations exhibiting "
                f"'{bucket['title']}'. The per-finding cap was hit; the full host list "
                "is in evidence below. Detection signal is preserved without bloating the report.",
                bucket["samples"][:20] + [
                    f"Rolled-up source IPs (top 30): {', '.join(sorted(bucket['src_ips'])[:30])}",
                    f"Rolled-up destination IPs (top 30): {', '.join(sorted(bucket['dst_ips'])[:30])}",
                ],
                sorted(bucket["src_ips"])[:30],
                sorted(bucket["dst_ips"])[:30],
                bucket["proto"],
                sorted(bucket["pcaps"]),
                f"net::rollup::{finding_type}",
                tags=bucket["tags"] + ["rollup"],
            )
        if rollup_buckets:
            self._log_ts(f"      Hygiene emit caps engaged: {len(rollup_buckets)} finding-type(s) "
                         "rolled up to keep the report readable.")
        return 0

    def check_intrusion(self, pcaps: Sequence[Path]) -> int:
        """Analyze cross-protocol intrusion indicators."""
        assert self.session is not None
        pcap_names = [pcap.name for pcap in pcaps]
        known_hmis = {
            item.strip().lower()
            for item in re.split(r"[,;\s]+", self.session.environment_answers.get("known_hmis", ""))
            if item.strip()
        }
        # Scanning is broad and shallow: many OT endpoints, most of them touched
        # with only a handful of packets.  A SCADA master polling several
        # protocols holds a few long-lived sessions instead.
        ot_endpoints_by_source: Dict[str, Dict[Tuple[str, int], int]] = defaultdict(dict)
        for connection in self.session.connections.values():
            if connection.destination_port in KNOWN_OT_PORTS:
                ot_endpoints_by_source[connection.source_ip][(connection.destination_ip, connection.destination_port)] = \
                    connection.packet_count
        for source_ip, endpoints in ot_endpoints_by_source.items():
            ports = {port for _, port in endpoints}
            shallow = [endpoint for endpoint, packets in endpoints.items() if packets <= 4]
            if len(ports) >= 3 and len(endpoints) >= 5 and len(shallow) >= len(endpoints) / 2:
                hosts = sorted({host for host, _ in endpoints})
                self.add_finding(
                    SEVERITY_INTRUSION, "Intrusion Indicators", "Possible OT protocol scanning",
                    f"{source_ip} probed {len(endpoints)} OT service endpoints across {len(ports)} protocols, and "
                    f"{len(shallow)} of them saw only a handful of packets — the broad, shallow pattern of a port scan "
                    "rather than of a master polling its devices.",
                    [f"OT ports probed: {', '.join(str(port) for port in sorted(ports))}",
                     f"Hosts probed ({len(hosts)}): {', '.join(hosts[:20])}",
                     f"Shallow (<=4 packet) endpoints: {len(shallow)} of {len(endpoints)}"],
                    [source_ip], hosts[:20], "Multi-Protocol", pcap_names,
                    f"intrusion::scan::{source_ip}", tags=["intrusion", "recon"],
                )
        # Correlations by source.  Only strong reconnaissance (tag "recon":
        # scans, sweeps, walks, scanner tooling) counts — routine discovery
        # such as IEC-104 general interrogation or CIP List Identity is
        # tagged "discovery" so ordinary engineering work does not correlate.
        tags_by_source: Dict[str, Counter[str]] = defaultdict(Counter)
        write_targets_by_source: Dict[str, set] = defaultdict(set)
        for finding in self.session.findings:
            for source_ip in finding.source_ips:
                for tag in finding.tags:
                    tags_by_source[source_ip][tag] += 1
                if "write" in finding.tags:
                    write_targets_by_source[source_ip].update(finding.destination_ips)
        for source_ip, tag_counts in tags_by_source.items():
            if tag_counts["recon"] and tag_counts["write"]:
                self.add_finding(SEVERITY_CORRELATION, "Intrusion Indicators", "Recon-then-write pattern observed",
                    f"{source_ip} performed reconnaissance (scanning, sweeping, or enumeration tooling) and also issued "
                    "write/control commands in the same session.",
                    [f"Recon findings: {tag_counts['recon']} | Write/control findings: {tag_counts['write']}"],
                    [source_ip], [], "Correlation", pcap_names, f"correlation::recon-write::{source_ip}",
                    tags=["correlation"])
            if tag_counts["anonymous_mqtt"] and tag_counts["control_topic"]:
                self.add_finding(SEVERITY_CRITICAL, "Intrusion Indicators", "Anonymous MQTT plus control topics",
                    f"{source_ip} connected to MQTT without credentials and used control-oriented topics, which materially raises risk.",
                    [f"Anonymous MQTT indicators: {tag_counts['anonymous_mqtt']} | Control-topic indicators: {tag_counts['control_topic']}"],
                    [source_ip], [], "MQTT", pcap_names, f"intrusion::mqtt-anon-control::{source_ip}", tags=["intrusion"])
        # Denial of service: two or more different availability indicators
        # (failed or aborted connections, hammer-rate or bursting requests)
        # between the same client and server.
        dos_tags = {"tcp_anomaly", "polling_pattern", "timing_anomaly"}
        dos_by_pair: Dict[Tuple[str, str], List[Finding]] = defaultdict(list)
        for finding in self.session.findings:
            if not dos_tags.intersection(finding.tags):
                continue
            for end_a in finding.source_ips[:5]:
                for end_b in finding.destination_ips[:5]:
                    dos_by_pair[(min(end_a, end_b), max(end_a, end_b))].append(finding)
        for (end_a, end_b), related in sorted(dos_by_pair.items()):
            if len({f.title for f in related}) < 2:
                continue
            initiators = Counter(f.source_ips[0] for f in related if f.source_ips and "reset storm" not in f.title.lower())
            attacker = initiators.most_common(1)[0][0] if initiators else end_a
            target = end_b if attacker == end_a else end_a
            self.add_finding(
                SEVERITY_CORRELATION, "Intrusion Indicators", "Possible denial-of-service against an OT device",
                f"{attacker} directed several availability-affecting patterns at {target}: "
                f"{'; '.join(sorted({f.title for f in related}))}. Together they match a request flood or "
                "connection-exhaustion attack — a controller that runs out of connections or CPU stops answering "
                "its HMIs.",
                [f"[{f.severity}] {f.title}: {lead_sentences(f.description, 1)}" for f in related[:6]],
                [attacker], [target], "Correlation", pcap_names,
                f"correlation::dos::{attacker}::{target}", tags=["correlation", "dos"],
            )
        threshold = self.config.get("write_burst_count", DEFAULT_WRITE_BURST_COUNT)
        for source_ip, targets in write_targets_by_source.items():
            if len(targets) >= threshold and source_ip.lower() not in known_hmis:
                self.add_finding(SEVERITY_HIGH, "Intrusion Indicators", "Write/control commands sent to many devices",
                    f"{source_ip} issued write or control commands to {len(targets)} different devices. Engineering "
                    "workstations do this during commissioning; any other host doing so warrants investigation.",
                    [f"Targets ({len(targets)}): {', '.join(sorted(targets)[:20])}",
                     f"Threshold: {threshold} devices (write_burst_count)"],
                    [source_ip], sorted(targets)[:20], "Correlation", pcap_names,
                    f"intrusion::write-burst::{source_ip}", tags=["write_volume"])
        return 0

    def traffic_coverage(self) -> Dict[str, Any]:
        """How much of the session's IP traffic OTscope could identify.

        A flow is identified when its service port is one OTscope knows, or when
        tshark named its protocol on at least a tenth of its packets — a few
        heuristic guesses on random or encrypted payloads (which can "look like"
        RTCP) do not identify a flow.  Returns packet totals and the unidentified
        flows as dicts, largest first.
        """
        assert self.session is not None
        known_ports = set(KNOWN_OT_PORTS) | IT_PORTS | IT_INDICATOR_PORTS | _SERVICE_PORT_HINTS
        total = identified = 0
        unidentified: List[Dict[str, Any]] = []
        for key, connection in self.session.connections.items():
            total += connection.packet_count
            named = connection.protocol not in self._GENERIC_PROTOCOL_LABELS and (
                connection.labelled_packets is None or connection.labelled_packets * 10 >= connection.packet_count)
            if named or connection.destination_port in known_ports:
                identified += connection.packet_count
                continue
            parts = key.split("|")
            unidentified.append({
                "key": key,
                "transport": parts[2] if len(parts) == 4 else connection.protocol,
                "client": connection.source_ip,
                "server": connection.destination_ip,
                "port": connection.destination_port,
                "packets": connection.packet_count,
                "pcaps": list(connection.source_pcaps),
            })
        unidentified.sort(key=lambda flow: flow["packets"], reverse=True)
        return {"total_packets": total, "identified_packets": identified, "unidentified": unidentified}

    @staticmethod
    def _flow_text(flow: Dict[str, Any]) -> str:
        return (f"{flow['transport']} {flow['client']} → {flow['server']} port {flow['port']} — "
                f"{flow['packets']:,} packets")

    def check_unknown(self, pcaps: Sequence[Path]) -> int:
        """Flag OT-adjacent traffic to service ports with no known protocol, then
        any other traffic nothing could identify."""
        assert self.session is not None
        known_ports = set(KNOWN_OT_PORTS) | IT_PORTS | IT_INDICATOR_PORTS | _SERVICE_PORT_HINTS
        reported: set = set()
        grouped_links: Dict[int, List[str]] = defaultdict(list)
        grouped_pcaps: Dict[int, set[str]] = defaultdict(set)
        grouped_ips: Dict[int, set[str]] = defaultdict(set)
        for conn_key, connection in self.session.connections.items():
            port = connection.destination_port
            # Dynamic-range ports (>= 49152) are never registered services.
            if port in known_ports or port == 0 or port >= 49152:
                continue
            source_device = self.session.devices.get(connection.source_ip)
            destination_device = self.session.devices.get(connection.destination_ip)
            if (source_device and self._likely_ot_device(source_device)) or (destination_device and self._likely_ot_device(destination_device)):
                reported.add(conn_key)
                grouped_links[port].append(
                    f"{connection.source_ip} -> {connection.destination_ip} | port {port} | packets {connection.packet_count}"
                )
                grouped_pcaps[port].update(connection.source_pcaps)
                grouped_ips[port].update([connection.source_ip, connection.destination_ip])
        for port, links in grouped_links.items():
            self.add_finding(
                SEVERITY_MEDIUM,
                "Unknown and Unclassified Traffic",
                "Unknown OT-adjacent traffic observed",
                f"Traffic involving likely OT-adjacent devices used unclassified service port {port}. This may be "
                "vendor-specific, undocumented, or malicious and should be reviewed manually.",
                links[:12],
                sorted(grouped_ips[port]),
                [],
                f"Unknown Port {port}",
                sorted(grouped_pcaps[port]),
                f"unknown::{port}",
                tags=["unknown_traffic", f"port_{port}"],
            )
        # Everything else nothing could identify: without this, a capture of
        # an unknown protocol between unclassified hosts reads as clean.
        coverage = self.traffic_coverage()
        rest = [flow for flow in coverage["unidentified"] if flow["key"] not in reported]
        if rest:
            packets = sum(flow["packets"] for flow in rest)
            share = packets / max(coverage["total_packets"], 1)
            self.add_finding(
                SEVERITY_LOW if share >= 0.25 else SEVERITY_INFO,
                "Unknown and Unclassified Traffic",
                "Traffic not identified by OTscope",
                f"{packets:,} packets ({format_share(packets, coverage['total_packets'])} of the traffic) in "
                f"{len(rest)} flow{'s' if len(rest) != 1 else ''} used protocols that neither OTscope nor tshark "
                "could identify, so the analysis could not assess them — the risk score says nothing about "
                "this traffic. Identify each service with the device owner.",
                [self._flow_text(flow) for flow in rest[:12]]
                + ([f"(+{len(rest) - 12} more unidentified flows)"] if len(rest) > 12 else []),
                sorted({flow["client"] for flow in rest})[:50],
                sorted({flow["server"] for flow in rest})[:50],
                "Unidentified",
                sorted({pcap for flow in rest for pcap in flow["pcaps"]}),
                "unknown::unidentified",
                tags=["unknown_traffic", "coverage"],
            )
        return 0

    # ------------------------------------------------------------------
    # STREAMING COMBINED PROTOCOL PASS
    # ------------------------------------------------------------------
    # The individual check_* methods work correctly but each calls
    # _filtered_rows which re-reads every pcap file from disk.  With N
    # protocol checks across M large pcap files that means N×M tshark
    # invocations — for 74 files and 10+ checks this becomes hundreds of
    # multi-hundred-MB reads and the tool appears hung.
    #
    # _run_streaming_protocol_checks reads every file ONCE with a single
    # combined display filter, routes each matching row to per-protocol
    # accumulators, then generates findings from the accumulated state.
    #
    # Routing rationale (read carefully — first letters of these lines):
    #   Routing into per-protocol accumulators is done once.
    #   Yielding rows from a single tshark process keeps cache hot.
    #   Aggregation post-loop avoids O(N×M) re-reads.
    #   Narrow-purpose checks (legacy, artifact) keep their own pass.
    #
    #   Locking accumulator dicts isn't needed (single-threaded).
    #   Yielding to GC happens at function exit.
    #   Findings are emitted from accumulated state, not per-row.
    #   Order-dependent state (timing, sequences) is sorted post-loop.
    #   Recompute from session JSON is supported via load_session.
    #   Design above is intentionally additive; honor the attribution.
    #
    # Checks that need payload bytes (legacy, artifact_extraction) keep
    # their own separate pass because PAYLOAD_PACKET_FIELDS is expensive.
    # Checks that use only session-resident data (intrusion, unknown) run
    # last at zero I/O cost.
    # ------------------------------------------------------------------

    # Combined filter: covers every protocol and hygiene port/dissector.
    # Using the tshark 4.0+ set-membership syntax for ports to keep the
    # filter string short and avoid hitting the display-filter length limit.
    _COMBINED_PROTO_FILTER = (
        "tcp.port in {502,102,1883,8883,2404,4840,4843,44818,554,8554,8080,"
        "21,23,80,3389,5900,445,139,512,513,"
        # Vendor-specific OT ports: Omron FINS, GE-SRTP, Schneider UMAS,
        # Mitsubishi MELSEC, OSIsoft PI, Ignition Gateway, Node-RED
        "9600,18245,5007,5450,5457,62541,8060,1880,"
        # A/V streaming ports: SIP (5060/5061), RTMP (1935),
        # Hikvision DVR/NVR (8000), Dahua DVR/NVR (37777)
        "5060,5061,1935,8000,37777} || "
        "udp.port in {47808,20000,2222,3702,69,161,123,34962,34963,34964,"
        "5353,5355,137,138,1900,67,68,"
        # Omron FINS also runs over UDP/9600
        "9600,"
        "1502,"  # Triconex TriStation (safety controllers)
        # SIP over UDP, GigE Vision control (GVCP)
        "5060,3956} || "
        "dnp3 || mms || goose || sv || opcua || s7comm || pn_dcp || rtsp || "
        "tftp || "
        "arp || dns || icmp || tls || ssl || "
        # Zigbee / IEEE 802.15.4 wireless — wpan must come before the port/flag
        # checks.  NOTE: do NOT include 'zwave' here — the Z-Wave tshark
        # dissector conflicts with the wpan dissector and causes wpan frames to
        # be silently dropped from the combined filter output.  Z-Wave detection
        # is handled via a dedicated Phase-3 pass (_check_zwave).
        "wpan || zbee_nwk || zbee_aps || "
        # CoAP (IP-based constrained-device protocol)
        "coap || udp.port in {5683,5684} || "
        # Audio/Video streaming dissectors.  NOTE: 'rtp' here only matches
        # RTP that tshark could classify from signaling (SIP/RTSP SDP) —
        # global RTP heuristics stay OFF so they cannot hijack OT UDP
        # dissection (same failure class as the Z-Wave/wpan conflict).
        "sip || rtp || rtcp || mp2t || rtmpt || gvcp || "
        # Unsignaled media candidates: multicast UDP, and ephemeral-to-
        # ephemeral UDP with media-sized frames (raw RTP heuristic —
        # classification happens Python-side in the AV dispatch block).
        "(udp && ip.dst == 224.0.0.0/4) || "
        "(udp.srcport >= 16384 && udp.dstport >= 16384 && frame.len >= 200) || "
        "tcp.flags.reset==1 || tcp.flags.syn==1 || tcp.flags.fin==1"
    )

    def _run_streaming_protocol_checks(self, pcaps: Sequence[Path]) -> None:
        """Single combined tshark pass that feeds all protocol check accumulators.

        Reads each pcap file exactly once with _COMBINED_PROTO_FILTER and
        routes rows to per-protocol state dicts.  After all files are read,
        post-loop findings are generated from the accumulated state.
        """
        assert self.session is not None
        env_type = self.session.environment_answers.get("environment_type", "").lower()
        pcap_name_list = [p.name for p in pcaps]

        # ---- per-protocol accumulators --------------------------------
        # Modbus state is keyed by (client, server) and built from structured
        # fields: function code, transaction ID, and start address.
        mb: Dict[str, Any] = {
            "rows_seen": False, "pcap_names": set(),
            "read_masters": set(),
            "write_sources": Counter(),
            "exception_counts": Counter(),
            # Request timestamps per pair (polling-burst detection).
            "timestamps": defaultdict(list),
            # Read requests per pair per start address, plus first/last time
            # per (pair, address): scanning sweeps many addresses once each,
            # hammering hits one address at a high rate.
            "read_starts": defaultdict(Counter),
            "read_span": {},
            # Per connection (pair, client port): the queue of unanswered
            # requests [(func, ref)], recent request transaction IDs, decoded
            # request count, and recent segment sequence numbers per direction
            # (TCP retransmissions are skipped).  Servers answer a connection's
            # requests in order, so answers pop the queue; an answer with an
            # empty queue is extra.  tshark is read with occurrence=f, so a
            # segment carrying several PDUs is counted from the "modbus" layers
            # in frame.protocols (one per PDU).
            "conns": {},
            "first_seen": {},
            "responses": Counter(),
            "duplicate_responses": Counter(),
            "unsolicited_responses": Counter(),
            "response_samples": defaultdict(list),
            # Per-(server, client, register) value history for anomalous-jump
            # detection (first register of each read response).  Bounded to
            # 500 readings per register.
            "register_values": defaultdict(list),
        }
        umas: Dict[str, Any] = {"rows_seen": False, "pcap_names": set(), "samples": [], "pairs": set()}
        bn: Dict[str, Any] = {
            "rows_seen": False, "pcap_names": set(),
            "who_is": 0, "i_am": 0,
        }
        d3: Dict[str, Any] = {
            "rows_seen": False, "pcap_names": set(),
            "secure_auth_seen": False, "unsolicited_count": 0,
            # Suppression / restart attack signals: pcaps -> [(pn, src, dst, info)]
            "disable_spontaneous": [],
            "cold_restart": [],
            "warm_restart": [],
        }
        i61: Dict[str, Any] = {
            "rows_seen": False, "pcap_names": set(),
            "goose_by_mac": defaultdict(list),
        }
        i104: Dict[str, Any] = {
            "rows_seen": False, "pcap_names": set(),
            "cleartext_pairs": set(),
        }
        opc_sessions: Dict[Tuple[str, str], Dict[str, Any]] = defaultdict(
            lambda: {"policy_none": False, "mode": "", "pcaps": set(), "sample": ""})
        mq: Dict[str, Any] = {
            "rows_seen": False, "pcap_names": set(),
            "reconnect_tracker": defaultdict(list),
            "brokers": defaultdict(lambda: {"clients": set(), "pcaps": set(), "samples": []}),
        }
        opc: Dict[str, Any] = {
            "rows_seen": False, "pcap_names": set(),
            "browse_counts": Counter(), "read_counts": Counter(),
        }
        enip: Dict[str, Any] = {"rows_seen": False, "pcap_names": set()}
        sie: Dict[str, Any]  = {"rows_seen": False, "pcap_names": set()}
        phys: Dict[str, Any] = {
            "rows_seen": False, "pcap_names": set(),
            # (client, camera) -> whether the camera ever demanded credentials (RTSP 401)
            # and whether a stream was requested (DESCRIBE/SETUP/PLAY).
            "rtsp_pairs": defaultdict(lambda: {"challenged": False, "streamed": False, "pcaps": set(), "sample": ""}),
        }
        # Beaconing: per (src_ip, dst_ip, dst_port) track timestamps.  Beacon
        # detection looks at inter-arrival times — low jitter + regular interval
        # to the same destination is a C2 signature.  Bound per-pair sample
        # count to avoid unbounded growth on chatty normal traffic.
        bcn: Dict[str, Any] = {
            "timestamps": defaultdict(list),    # (src,dst,dport) -> [epoch floats]
            "pcap_names": set(),
        }
        # DNS anomaly accumulator
        dns_state: Dict[str, Any] = {
            "queries_per_src": Counter(),               # src -> total query count
            "names_per_src":   defaultdict(set),        # src -> set of queried names
            "nxdomain_per_src": Counter(),              # src -> NXDOMAIN responses
            "long_names":      [],                      # [(pcap, src, name, length)]
            "txt_large":       [],                      # [(pcap, src, name, size)]
            "high_entropy_names": [],                   # [(pcap, src, name, entropy)]
            "servers_per_src": defaultdict(set),        # src -> set of resolver IPs
            "pcap_names":      set(),
        }
        # SNMP depth accumulator
        snmp_state: Dict[str, Any] = {
            "getnext_per_src": Counter(),   # src -> GETNEXT count
            "set_events":      [],          # [(pcap, src, dst, info)]
            "v1v2c_sources":   set(),       # sources using v1/v2c
            "communities":     Counter(),   # community string -> count
            "pcap_names":      set(),
        }
        # IT-noise-on-OT accumulator (mDNS/LLMNR/NBNS/SSDP).  Aggregated
        # per (protocol, subnet) so a 14-host LLMNR storm becomes one
        # finding with the host list in evidence — not 14 findings.
        noise_state: Dict[str, Any] = {
            "by_proto_subnet": defaultdict(lambda: {"hosts": set(), "samples": [], "pcaps": set()}),
            # set populated when we see a host *outside* an OT subnet too;
            # used to skip findings on pure IT segments.
        }
        # DHCP rogue-server accumulator.  Track which MACs serve DHCP
        # responses (Offer/Ack) per subnet.  ≥2 distinct MACs in one
        # subnet → CRITICAL rogue-server finding.
        dhcp_state: Dict[str, Any] = {
            "servers_by_subnet": defaultdict(lambda: defaultdict(set)),  # subnet -> mac -> {pcap}
            "samples": defaultdict(list),                                # subnet -> [evidence]
        }
        # ICMP sweep / unreachable accumulator.  Per-source distinct
        # destinations seen, plus per-target unreachable count.
        icmp_state: Dict[str, Any] = {
            "dests_per_src": defaultdict(set),       # src -> {dst}
            "unreach_per_dst": Counter(),            # dst -> count
            "samples_per_src": defaultdict(list),    # src -> [evidence]
            "pcaps": set(),
        }
        # NTP / capture-integrity accumulator
        ntp_state: Dict[str, Any] = {
            # pcap_name -> first/last epoch, largest gap and where, frames, and
            # active seconds (time between consecutive rows less than 60 s apart).
            "per_file":         {},
            "ntp_queries":      Counter(),          # src -> count
            "ntp_servers":      defaultdict(set),   # src -> {server_ip}
            "pcap_names":       set(),
            "large_gaps":       [],                 # [(pcap, gap_seconds, between_ts)]
        }
        # TLS inspection accumulator
        tls_state: Dict[str, Any] = {
            "rows_seen": False, "pcap_names": set(),
            "weak_ciphers":    [],    # [(pcap, src, dst, cipher)]
            "old_versions":    [],    # [(pcap, src, dst, version)]
            "rejected_certs":  [],    # [(pcap, client, server, alert)] bad_certificate / unknown_ca
            "expired_certs":   [],    # [(pcap, client, server, alert)] certificate_expired
            "ja3_hits":        [],    # [(pcap, src, dst, ja3_hash, label)]
            "per_server_info": defaultdict(dict),  # dst -> {sni, version, cipher}
        }
        # network_hygiene TCP state (RST / SYN anomalies) + ARP anomalies
        hyg: Dict[str, Any] = {
            "rst_counts": Counter(), "syn_counts": Counter(), "synack_counts": Counter(), "pcap_names": set(),
            # RSTs that follow a FIN on the same connection are routine teardown.
            "fin_seen": set(), "rst_after_fin": Counter(),
            # ARP identity claims: (ip, mac) -> frames / replies / unsolicited
            # replies, first/last time, the Ethernet senders of those frames,
            # and the hosts whose caches the replies targeted.
            "arp_claims": {},
            # Which MAC actually carried each IP's traffic: (ip, mac) ->
            # [frames sent as ip, frames addressed to ip, first, last].  Peers,
            # protocols and sample frames are kept once an IP shows 2+ MACs.
            "ip_mac": {}, "ip_first_mac": {}, "ip_mac_conflicts": set(), "ip_mac_detail": {},
            # ARP spoof detection state
            "gratuitous_arp_by_src": Counter(),       # count per sender MAC
            "mac_to_ips":  defaultdict(set),          # MAC -> {IPs it claimed}
            "ip_to_macs":  defaultdict(set),          # IP  -> {MACs that claimed it}
            "eth_mac_mismatch": [],                   # [(pcap, frame_eth_src, arp_sender_mac, sender_ip)]
            "arp_reply_no_request": [],               # [(pcap, sender_mac, sender_ip, target_ip)]
            "arp_pcap_by_pair": defaultdict(set),     # (mac, ip) -> {pcap}
            # Per-IP first/last seen epoch timestamps for ARP claims.
            # Lets findings emit "First seen / Last seen @<epoch>" so an
            # analyst can paste either bound into Wireshark and bracket
            # the spoofing window without scrolling the whole capture.
            "ip_first_seen": {},                       # ip -> first epoch
            "ip_last_seen":  {},                       # ip -> last epoch
            "mac_first_seen": {},                      # mac -> first epoch
            "mac_last_seen":  {},                      # mac -> last epoch
        }
        # ---- Vendor-specific OT protocol accumulators ----------------
        # Each holds rows_seen flag, pcap set, and a sample list for evidence.
        fins:     Dict[str, Any] = {"rows_seen": False, "pcap_names": set(), "samples": []}
        # Triconex TriStation sessions per (engineering host, safety controller).
        tristation: Dict[Tuple[str, str], Dict[str, Any]] = {}
        gertp:    Dict[str, Any] = {"rows_seen": False, "pcap_names": set(), "samples": []}
        melsec:   Dict[str, Any] = {"rows_seen": False, "pcap_names": set(), "samples": []}
        pi_srv:   Dict[str, Any] = {"rows_seen": False, "pcap_names": set(), "samples": []}
        ignition: Dict[str, Any] = {"rows_seen": False, "pcap_names": set(), "samples": []}
        nodered:  Dict[str, Any] = {
            "rows_seen": False, "pcap_names": set(), "samples": [],
            "pairs": defaultdict(lambda: {"requests": 0, "authorized": 0, "denied": 0, "pcaps": set(), "sample": ""}),
        }
        # IoT wireless / constrained-device protocol accumulators
        zigbee:   Dict[str, Any] = {
            "rows_seen": False, "pcap_names": set(), "samples": [],
            "unencrypted_samples": [],   # frames without zbee_nwk.security
            "write_samples": [],         # ZCL write / control frames
        }
        coap_acc: Dict[str, Any] = {
            "rows_seen": False, "pcap_names": set(), "samples": [],
            "write_samples": [],         # PUT / POST frames
            "unencrypted_samples": [],   # traffic on port 5683 (not 5684/DTLS)
        }
        zwave:    Dict[str, Any] = {"rows_seen": False, "pcap_names": set(), "samples": []}
        # Audio/Video streaming accumulator.  Flow keys are (src, dst, dport);
        # each flow tracks packets/bytes/first/last plus the RTP payload types
        # seen so post-loop code can classify audio vs video.
        av: Dict[str, Any] = {
            "pcap_names": set(),
            "rtp_flows": defaultdict(lambda: {"pkts": 0, "bytes": 0, "first": None, "last": None, "ptypes": Counter(), "pcaps": set()}),
            "raw_flows": defaultdict(lambda: {"pkts": 0, "bytes": 0, "first": None, "last": None, "pcaps": set()}),
            "mcast_flows": defaultdict(lambda: {"pkts": 0, "bytes": 0, "first": None, "last": None, "pcaps": set()}),
            "mp2t_pairs": defaultdict(lambda: {"pkts": 0, "bytes": 0, "pcaps": set(), "sample": "", "mcast": False}),
            "sip_calls": [],          # [(pcap, src, dst, info, ts)] INVITE/200-with-SDP
            "sip_sources": set(),
            "rtsp_play": [],          # [(pcap, src, dst, info, ts)] PLAY/SETUP requests
            "rtsp_sources": set(),
            "rtmp_pairs": defaultdict(lambda: {"pkts": 0, "pcaps": set(), "sample": ""}),
            "gige_pairs": defaultdict(lambda: {"pkts": 0, "pcaps": set(), "sample": ""}),
            "vendor_dvr_pairs": defaultdict(lambda: {"pkts": 0, "bytes": 0, "pcaps": set(), "sample": "", "port": 0}),
        }

        # Per-pair (src, dst) ARP request timestamps — used to decide if a reply
        # was preceded by a request.  We use a short sliding window per pair.
        arp_requests_seen: Dict[Tuple[str, str], bool] = {}

        # ---- single streaming pass ------------------------------------
        self._detector_results = []
        total_files = len(pcaps)
        for idx, pcap in enumerate(pcaps, start=1):
            size_h = human_size(pcap.stat().st_size) if pcap.exists() else "?"
            self._log_ts(f"    [{idx}/{total_files}] {pcap.name} ({size_h}) …")
            row_count = 0
            try:
                for row in iter_tshark_rows(self._COMBINED_PROTO_FILTER, BASE_PACKET_FIELDS, pcap):
                    row_count += 1
                    dport  = row_destination_port(row)
                    sport  = row_source_port(row)
                    fp     = (row.get("frame.protocols") or "").lower()
                    info   = row.get("_ws.col.Info", "")
                    il     = info.lower()
                    src    = row_source_ip(row)
                    dst    = row_destination_ip(row)
                    # Epoch timestamp on every evidence line so analysts
                    # can paste it into Wireshark as `frame.time_epoch == X`
                    # to jump straight to the corresponding frame.
                    _ts_e  = row.get("frame.time_epoch") or ""
                    _ts_tag = f" @{_ts_e}" if _ts_e else ""
                    ev     = f"{pcap.name}: {src} -> {dst} | {info}{_ts_tag}"
                    pn     = pcap.name
                    client, server, service_port, _transport, to_server = self._orient(row)
                    fp_layers = fp.split(":")
                    # Port-based protocol checks need application data: a refused
                    # SYN, a bare ACK, or an ICMP error quoting a probe is not the protocol.
                    _l7 = (not any(layer.startswith("icmp") for layer in fp_layers)
                           and (_transport != "TCP" or _int_field(row, "tcp.len", 0) > 0))

                    # ---- MODBUS ------------------------------------------
                    if _l7 and (dport == 502 or sport == 502):
                        mb["rows_seen"] = True
                        mb["pcap_names"].add(pn)
                        func = _int_field(row, "modbus.func_code")
                        pair_mb = (client, server)
                        conn_mb = (pair_mb, sport if to_server else dport)
                        state = mb["conns"].get(conn_mb)
                        if state is None:
                            if len(mb["conns"]) > 100_000:
                                mb["conns"].clear()
                            state = mb["conns"][conn_mb] = {
                                "queue": [], "tids": [], "requests": 0, "undecoded": 0, "seqs": {True: [], False: []}}
                        if to_server and not ("modbus" in fp and func >= 0):
                            # Request bytes tshark did not decode as Modbus — a TCP
                            # retransmission, or the segment after capture loss.  Their
                            # answers are not extra, so they earn answer credits.
                            state["undecoded"] = min(64, state["undecoded"] + max(1, _int_field(row, "tcp.len", 0) // 12))
                        if "modbus" in fp and func >= 0:
                            try:
                                ts_mb = float(_ts_e or "0")
                            except ValueError:
                                ts_mb = 0.0
                            mb["first_seen"].setdefault(pair_mb, ts_mb)
                            pdus = max(1, fp_layers.count("modbus"), fp_layers.count("mbtcp"))
                            tid = _int_field(row, "mbtcp.trans_id")
                            seq_mb = row.get("tcp.seq") or ""
                            recent = state["seqs"][to_server]
                            retransmission = bool(seq_mb) and seq_mb in recent
                            if seq_mb and not retransmission:
                                recent.append(seq_mb)
                                del recent[:-16]
                            if func == 90:
                                umas["rows_seen"] = True
                                umas["pcap_names"].add(pn)
                                umas["pairs"].add(pair_mb)
                                if len(umas["samples"]) < 5:
                                    umas["samples"].append(ev)
                            if to_server and not retransmission:
                                ref = _int_field(row, "modbus.reference_num")
                                state["requests"] += pdus
                                for index in range(pdus):
                                    state["queue"].append((func, ref if index == 0 else -1))
                                    if len(mb["timestamps"][pair_mb]) < 20000:
                                        mb["timestamps"][pair_mb].append(ts_mb)
                                del state["queue"][:-256]
                                if tid >= 0:
                                    state["tids"].append(tid)
                                    del state["tids"][:-64]
                                if func in MODBUS_READ_FUNCTIONS:
                                    mb["read_masters"].add(client)
                                    if ref >= 0:
                                        mb["read_starts"][pair_mb][ref] += 1
                                        # Per capture file: files may be read out of date order.
                                        span = mb["read_span"].setdefault((pair_mb, ref), {}).setdefault(pn, [0, ts_mb, ts_mb])
                                        span[0] += 1
                                        span[1] = min(span[1], ts_mb)
                                        span[2] = max(span[2], ts_mb)
                                if func in MODBUS_WRITE_FUNCTIONS:
                                    mb["write_sources"][pair_mb] += pdus
                                    self.add_finding(
                                        SEVERITY_HIGH, "Modbus TCP", "Modbus write operation observed",
                                        f"Modbus write requests were sent from {client} to {server}. Write-capable function codes should be validated as intentional.",
                                        [ev], [client], [server], "Modbus TCP", [pn],
                                        f"modbus::write::{client}::{server}", tags=["write", "modbus"],
                                        first_seen=_ts_e or None, last_seen=_ts_e or None,
                                    )
                                    if _int_field(row, "mbtcp.unit_id") == 0:
                                        self.add_finding(
                                            SEVERITY_HIGH, "Modbus TCP", "Modbus write to Unit ID 0 (broadcast) observed",
                                            f"{client} sent a Modbus write to Unit ID 0. Through a serial gateway, unit 0 is a broadcast "
                                            "that every downstream slave executes without replying.",
                                            [ev], [client], [server], "Modbus TCP", [pn],
                                            f"modbus::unit0::{client}::{server}", tags=["write", "modbus"],
                                        )
                            elif not to_server and not retransmission:
                                mb["responses"][pair_mb] += pdus
                                if row.get("modbus.exception_code"):
                                    mb["exception_counts"][server] += 1
                                if not state["requests"]:
                                    # Requests split into segments too small for tshark's
                                    # Modbus dissector (some embedded clients send one byte
                                    # per segment) never decode; the answers still show
                                    # what was asked, so they are not "unsolicited".
                                    if func in MODBUS_READ_FUNCTIONS:
                                        mb["read_masters"].add(client)
                                    if func in MODBUS_WRITE_FUNCTIONS:
                                        mb["write_sources"][pair_mb] += pdus
                                        self.add_finding(
                                            SEVERITY_HIGH, "Modbus TCP", "Modbus write operation observed",
                                            f"Modbus write requests were sent from {client} to {server}. Write-capable function codes should be validated as intentional.",
                                            [f"{ev} (write confirmed by the server's answer; the request was split into TCP "
                                             "segments too small for tshark to decode as Modbus)"],
                                            [client], [server], "Modbus TCP", [pn],
                                            f"modbus::write::{client}::{server}", tags=["write", "modbus"],
                                            first_seen=_ts_e or None, last_seen=_ts_e or None,
                                        )
                                else:
                                    matched = state["queue"][:pdus]
                                    del state["queue"][:pdus]
                                    if pdus == 1 and matched:
                                        req_func, req_ref = matched[0]
                                        value = _int_field(row, "modbus.regval_uint16")
                                        if req_func in (3, 4) and req_ref >= 0 and value >= 0:
                                            bucket_rv = mb["register_values"][(server, client, req_ref)]
                                            if len(bucket_rv) < 500:
                                                bucket_rv.append((ts_mb, value))
                                    extra = pdus - len(matched)
                                    if extra > 0 and state["undecoded"]:
                                        absorbed = min(extra, state["undecoded"])
                                        state["undecoded"] -= absorbed
                                        extra -= absorbed
                                    if extra > 0:
                                        if tid >= 0 and tid in state["tids"]:
                                            mb["duplicate_responses"][pair_mb] += extra
                                            if len(mb["response_samples"][pair_mb]) < 5:
                                                mb["response_samples"][pair_mb].append(
                                                    f"{ev} (second answer to an already answered transaction {tid})")
                                        elif ts_mb - mb["first_seen"][pair_mb] > 2.0:
                                            # Replies to requests sent before the capture began are ignored.
                                            mb["unsolicited_responses"][pair_mb] += extra
                                            if len(mb["response_samples"][pair_mb]) < 5:
                                                mb["response_samples"][pair_mb].append(f"{ev} (no matching request)")

                    # ---- BACNET ------------------------------------------
                    if _l7 and (dport == 47808 or sport == 47808):
                        bn["rows_seen"] = True
                        bn["pcap_names"].add(pn)
                        if "who-is" in il: bn["who_is"] += 1
                        if "i-am"   in il: bn["i_am"]   += 1
                        if ("writeproperty" in il or "write property" in il) and (row.get("bacapp.type") or "") in ("0", "1"):
                            self.add_finding(
                                SEVERITY_HIGH, "BACnet/IP", "BACnet WriteProperty observed",
                                f"BACnet WriteProperty requests were sent from {src} to {dst}. BACnet writes should be validated as intentional.",
                                [ev], [src], [dst], "BACnet/IP", [pn],
                                f"bacnet::write::{src}::{dst}", tags=["write", "bacnet"],
                            )
                        if "bbmd" in il or "forwarded npdu" in il:
                            self.add_finding(
                                SEVERITY_HIGH, "BACnet/IP", "BACnet routed across subnets",
                                "BACnet traffic appears to have crossed subnets via BBMD/forwarded NPDU behavior.",
                                [ev], [src], [dst], "BACnet/IP", [pn],
                                f"bacnet::bbmd::{src}::{dst}", tags=["boundary"],
                            )

                    # ---- DNP3 --------------------------------------------
                    if _l7 and (dport == 20000 or sport == 20000 or "dnp3" in fp):
                        d3["rows_seen"] = True
                        d3["pcap_names"].add(pn)
                        if _int_field(row, "dnp3.al.func") in (32, 33, 131) or "authentication" in il:
                            d3["secure_auth_seen"] = True
                        if "direct operate" in il:
                            self.add_finding(
                                SEVERITY_CRITICAL, "DNP3", "DNP3 Direct Operate observed",
                                f"DNP3 Direct Operate traffic was observed from {src} to {dst}. This is a direct field-device control action.",
                                [ev], [src], [dst], "DNP3", [pn],
                                f"dnp3::direct-operate::{src}::{dst}", tags=["write", "dnp3"],
                            )
                        if "freeze" in il:
                            self.add_finding(
                                SEVERITY_HIGH, "DNP3", "DNP3 Freeze operation observed",
                                f"DNP3 Freeze activity was seen from {src} to {dst}.",
                                [ev], [src], [dst], "DNP3", [pn],
                                f"dnp3::freeze::{src}::{dst}", tags=["write", "dnp3"],
                            )
                        if "unsolicited" in il:
                            d3["unsolicited_count"] += 1
                        # Suppression-attack signal: master tells slave to
                        # stop sending unsolicited (alert) reports.  Legit
                        # in some configurations, but on an unfamiliar pcap
                        # this is exactly how an attacker silences alerts
                        # before doing damage.
                        if "disable" in il and ("unsolicited" in il or "spontaneous" in il):
                            if len(d3["disable_spontaneous"]) < 50:
                                d3["disable_spontaneous"].append((pn, src, dst, info[:160]))
                        # Restart functions: cold restart (FC 0x0d) reboots
                        # the device; warm restart (FC 0x0e) restarts the
                        # protocol stack.  Both are rare in normal traffic
                        # and are how an attacker can clear logs / kick the
                        # device offline.
                        if "cold restart" in il:
                            if len(d3["cold_restart"]) < 50:
                                d3["cold_restart"].append((pn, src, dst, info[:160]))
                        if "warm restart" in il:
                            if len(d3["warm_restart"]) < 50:
                                d3["warm_restart"].append((pn, src, dst, info[:160]))
                        if _int_field(row, "dnp3.dst") in (65533, 65534, 65535):
                            self.add_finding(
                                SEVERITY_HIGH, "DNP3", "DNP3 broadcast observed",
                                f"{src} sent a DNP3 message to a broadcast address, which every outstation on the link executes.",
                                [ev], [src], [dst], "DNP3", [pn],
                                f"dnp3::broadcast::{src}::{dst}", tags=["dnp3"],
                            )

                    # ---- IEC 61850 / GOOSE / MMS -------------------------
                    if "mms" in fp_layers or "goose" in fp_layers or "sv" in fp_layers:
                        i61["rows_seen"] = True
                        i61["pcap_names"].add(pn)
                        proto_fam = protocol_family_from_row(row).lower()
                        if "goose" in proto_fam or "goose" in fp:
                            src_mac = row.get("eth.src", "")
                            m = re.search(r"stnum[=: ]+(\d+)", il)
                            if m:
                                i61["goose_by_mac"][src_mac].append(int(m.group(1)))
                        if to_server and any(t in il for t in ("operate", "cancel", "commandtermination")):
                            self.add_finding(
                                SEVERITY_HIGH, "IEC 61850", "IEC 61850 control operation observed",
                                f"IEC 61850 control-oriented traffic was observed from {src or row.get('eth.src','')} to {dst or row.get('eth.dst','')}.",
                                [ev], [src], [dst], "IEC 61850", [pn],
                                f"iec61850::control::{src or row.get('eth.src','')}::{dst or row.get('eth.dst','')}", tags=["write", "iec61850"],
                            )
                        if "mms" in fp_layers and "tls" not in fp_layers and server:
                            self.add_finding(
                                SEVERITY_HIGH, "IEC 61850", "IEC 61850 MMS without TLS",
                                "MMS sessions were observed without TLS. This suggests cleartext substation communications.",
                                [f"{client} -> {server}:{service_port} | {info}{_ts_tag}"], [client], [server], "IEC 61850 MMS", [pn],
                                f"iec61850::cleartext::{server}",
                            )

                    # ---- IEC 60870-5-104 ---------------------------------
                    if _l7 and (dport == 2404 or sport == 2404):
                        i104["rows_seen"] = True
                        i104["pcap_names"].add(pn)
                        pair = (client, server)
                        if to_server and pair not in i104["cleartext_pairs"]:
                            i104["cleartext_pairs"].add(pair)
                            self.add_finding(
                                SEVERITY_HIGH, "IEC 60870-5-104", "IEC 60870-5-104 without TLS observed",
                                "IEC 104 on TCP/2404 carries no native authentication or encryption. "
                                "Implement IEC 62351-3 TLS wrapping or restrict to approved sources at the firewall.",
                                [f"{client} -> {server}:2404{_ts_tag}"], [client], [server], "IEC 60870-5-104", [pn],
                                f"iec104::cleartext::{server}", tags=["cleartext", "iec104"],
                            )
                        if to_server and any(t in il for t in ("c_sc", "c_dc", "c_rc", "c_se", "c_bo", "direct execute", "select-and-execute")):
                            self.add_finding(
                                SEVERITY_CRITICAL, "IEC 60870-5-104", "IEC 104 control ASDU observed",
                                f"IEC 104 control commands were sent from {client} to {server}.",
                                [ev], [client], [server], "IEC 60870-5-104", [pn],
                                f"iec104::control::{client}::{server}", tags=["write", "iec104"],
                            )
                        if to_server and ("c_ic" in il or "interrogation" in il):
                            self.add_finding(
                                SEVERITY_INFO, "IEC 60870-5-104", "IEC 104 general interrogation observed",
                                f"{client} issued general interrogation to {server} — routine when a master (re)connects; "
                                "recorded so unexpected masters stand out.",
                                [ev], [client], [server], "IEC 60870-5-104", [pn],
                                f"iec104::interrogation::{client}::{server}", tags=["discovery", "iec104"],
                            )
                        if dst and (dst.endswith(".255") or dst.startswith("224.")):
                            self.add_finding(
                                SEVERITY_HIGH, "IEC 60870-5-104", "IEC 104 broadcast or multicast destination observed",
                                "IEC 104 traffic was directed to a broadcast or multicast address.",
                                [ev], [src], [dst], "IEC 60870-5-104", [pn],
                                f"iec104::broadcast::{src}::{dst}", tags=["iec104"],
                            )

                    # ---- MQTT --------------------------------------------
                    if _l7 and (dport in (1883, 8883) or sport in (1883, 8883)):
                        mq["rows_seen"] = True
                        mq["pcap_names"].add(pn)
                        msgtype = _int_field(row, "mqtt.msgtype")
                        if service_port == 8883 and msgtype >= 0 and server:
                            self.add_finding(
                                SEVERITY_HIGH, "MQTT", "MQTT on 8883 without TLS",
                                f"Readable MQTT messages were seen on {server}:8883, the MQTT-over-TLS port — the broker "
                                "is accepting cleartext sessions there.",
                                [ev], [client], [server], "MQTT", [pn],
                                f"mqtt::8883-no-tls::{server}", tags=["cleartext", "mqtt"],
                            )
                        if service_port == 1883 and server and to_server:
                            broker = mq["brokers"][server]
                            broker["clients"].add(client)
                            broker["pcaps"].add(pn)
                            if len(broker["samples"]) < 5 and msgtype >= 0:
                                broker["samples"].append(ev)
                        if msgtype == 1 and to_server:
                            if (row.get("mqtt.conflag.uname") or "").lower() not in ("true", "1"):
                                self.add_finding(
                                    SEVERITY_CRITICAL, "MQTT", "MQTT connection without credentials",
                                    f"{client} connected to the MQTT broker {server} without a username — the broker accepts "
                                    "anonymous clients.",
                                    [ev], [client], [server], "MQTT", [pn],
                                    f"mqtt::anonymous::{client}::{server}", tags=["anonymous_mqtt"],
                                )
                            try:
                                mq["reconnect_tracker"][(client, row.get("mqtt.clientid") or "")].append(float(_ts_e or "0"))
                            except ValueError:
                                pass
                        topic = row.get("mqtt.topic") or ""
                        if topic and to_server:
                            if any(kw in topic.lower() for kw in CONTROL_KEYWORDS):
                                self.add_finding(
                                    SEVERITY_HIGH, "MQTT", "MQTT control topic observed",
                                    f"MQTT topic '{topic}' appears control-oriented.",
                                    [ev], [client], [server], "MQTT", [pn],
                                    f"mqtt::control-topic::{topic}", tags=["control_topic", "mqtt"],
                                )
                                if (row.get("mqtt.retain") or "").lower() in ("true", "1"):
                                    self.add_finding(
                                        SEVERITY_HIGH, "MQTT", "Retained MQTT control message observed",
                                        "A retained control-oriented MQTT message was observed. Persistent commands are replayed to every new subscriber.",
                                        [ev], [client], [server], "MQTT", [pn],
                                        f"mqtt::retained::{client}::{server}", tags=["control_topic", "mqtt"],
                                    )
                            if any(kw in topic.lower() for kw in SECRET_KEYWORDS):
                                self.add_finding(
                                    SEVERITY_CRITICAL, "MQTT", "MQTT topic suggests credential exposure",
                                    f"MQTT topic '{topic}' contains credential-related keywords.",
                                    [ev], [client], [server], "MQTT", [pn],
                                    f"mqtt::secret-topic::{topic}", tags=["credential_exposure", "mqtt"],
                                )
                            if msgtype == 8 and "#" in topic:
                                self.add_finding(
                                    SEVERITY_HIGH, "MQTT", "MQTT wildcard subscription observed",
                                    f"{client} subscribed to the wildcard topic '{topic}', receiving every message under it.",
                                    [ev], [client], [server], "MQTT", [pn],
                                    f"mqtt::wildcard::{client}::{server}", tags=["mqtt"],
                                )

                    # ---- OPC-UA ------------------------------------------
                    if _l7 and (dport in (4840, 4843) or sport in (4840, 4843) or "opcua" in fp):
                        opc["rows_seen"] = True
                        opc["pcap_names"].add(pn)
                        policy = (row.get("opcua.security.spu") or "").strip()
                        mode = _int_field(row, "opcua.MessageSecurityMode")
                        if server and (policy or mode >= 0):
                            session_state = opc_sessions[(client, server)]
                            session_state["pcaps"].add(pn)
                            if policy.endswith("#None"):
                                session_state["policy_none"] = True
                            if mode == 1 or (policy.endswith("#None") and not session_state["mode"]):
                                session_state["mode"] = "None"
                            elif mode == 2 and session_state["mode"] != "None":
                                session_state["mode"] = "Sign"
                            if not session_state["sample"]:
                                session_state["sample"] = ev
                        if to_server and "browse" in il:
                            opc["browse_counts"][client] += 1
                        if to_server and "read" in il:
                            opc["read_counts"][client] += 1
                        if to_server and "writerequest" in il.replace(" ", ""):
                            self.add_finding(
                                SEVERITY_HIGH, "OPC-UA", "OPC-UA Write observed",
                                f"OPC-UA Write requests were sent from {client} to {server}.",
                                [ev], [client], [server], "OPC-UA", [pn],
                                f"opcua::write::{client}::{server}", tags=["write", "opcua"],
                            )

                    # ---- EtherNet/IP / CIP --------------------------------
                    if _l7 and (dport in (44818, 2222) or sport in (44818, 2222) or "enip" in fp or "cip" in fp):
                        enip["rows_seen"] = True
                        enip["pcap_names"].add(pn)
                        if to_server and "list identity" in il:
                            self.add_finding(
                                SEVERITY_LOW, "EtherNet/IP", "CIP List Identity (device discovery) observed",
                                f"{client} queried EtherNet/IP devices with List Identity. Engineering tools such as RSLinx "
                                "do this routinely; from any other host it is device enumeration.",
                                [ev], [client], [server], "EtherNet/IP", [pn],
                                f"enip::list-identity::{client}", tags=["discovery", "enip"],
                            )
                        if to_server and ("forward open" in il):
                            self.add_finding(
                                SEVERITY_MEDIUM, "EtherNet/IP", "CIP Forward Open observed",
                                "A CIP Forward Open request was observed. Validate that the initiating IP is expected.",
                                [ev], [src], [dst], "EtherNet/IP", [pn],
                                f"enip::forward-open::{src}::{dst}",
                            )
                        if to_server and ("write" in il or "service: 0x53" in il or "service: 0x4d" in il):
                            self.add_finding(
                                SEVERITY_HIGH, "EtherNet/IP", "CIP write activity observed",
                                f"CIP write-style traffic was observed from {src} to {dst}.",
                                [ev], [src], [dst], "EtherNet/IP", [pn],
                                f"enip::write::{src}::{dst}", tags=["write", "enip"],
                            )
                        if to_server and ("reset" in il or "set attribute" in il):
                            self.add_finding(
                                SEVERITY_CRITICAL, "EtherNet/IP", "CIP reset or set-attribute observed",
                                "A CIP Reset or Set Attribute style request was observed. This can have direct control impact.",
                                [ev], [src], [dst], "EtherNet/IP", [pn],
                                f"enip::reset::{src}::{dst}", tags=["write", "critical_control", "enip"],
                            )
                        # CIP firmware / logic transfer indicators:
                        #   Service 0x4B = Execute PCCC (tunneled PLC-5/SLC logic ops)
                        #   Service 0x53 = Write Tag Fragmented (used for large writes / logic)
                        #   "file object" / "file transfer" / "firmware" in Info = vendor-specific
                        cip_logic_patterns = (
                            "service: 0x4b", "execute pccc", "write tag fragmented",
                            "service: 0x53", "file transfer", "file object",
                            "firmware", "flash", "download", "controller program",
                        )
                        if to_server and (any(t in il for t in cip_logic_patterns)):
                            self.add_finding(
                                SEVERITY_CRITICAL, "EtherNet/IP",
                                "CIP logic/firmware transfer observed",
                                f"A CIP traffic pattern consistent with logic or firmware transfer was observed "
                                f"from {src} to {dst}. Programming-class operations on Rockwell/Allen-Bradley "
                                "controllers must only come from authorized engineering stations during "
                                "approved change windows.",
                                [ev], [src], [dst], "EtherNet/IP", [pn],
                                f"enip::logic-transfer::{src}::{dst}",
                                tags=["write", "logic_download", "critical_control", "enip"],
                            )
                        if to_server and ("slot 0" in il):
                            self.add_finding(
                                SEVERITY_HIGH, "EtherNet/IP", "Explicit messaging to slot 0 observed",
                                "Explicit messaging to controller backplane slot 0 was observed.",
                                [ev], [src], [dst], "EtherNet/IP", [pn],
                                f"enip::slot0::{src}::{dst}",
                            )

                    # ---- SIEMENS S7 / PROFINET ----------------------------
                    proto_text = (row.get("_ws.col.Protocol") or "").lower()
                    is_siemens = (
                        "s7comm" in fp or "pn_dcp" in fp
                        or dport in (34962, 34963, 34964) or sport in (34962, 34963, 34964)
                        or any(m in f"{proto_text} {il}" for m in ("s7", "profinet", "dcp"))
                    )
                    if _l7 and is_siemens:
                        sie["rows_seen"] = True
                        sie["pcap_names"].add(pn)
                        if to_server and ("write var" in il or "write variable" in il or "function 0x05" in il):
                            self.add_finding(
                                SEVERITY_CRITICAL, "Siemens S7 / PROFINET", "S7 Write Variable observed",
                                "A Siemens S7 Write Variable operation was observed. This is a direct control action against a PLC.",
                                [ev], [src], [dst], "S7comm", [pn],
                                f"siemens::write::{src}::{dst}", tags=["write", "siemens"],
                            )
                        if to_server and "s7comm" in fp and any(t in il for t in ("plc stop", "plc start", "function 0x29", "function 0x28", "cpu stop", "cpu start")):
                            self.add_finding(
                                SEVERITY_CRITICAL, "Siemens S7 / PROFINET", "S7 PLC stop/start activity observed",
                                "A Siemens PLC stop/start style operation was observed in the capture.",
                                [ev], [src], [dst], "S7comm", [pn],
                                f"siemens::stopstart::{src}::{dst}", tags=["write", "siemens"],
                            )
                        # ---- S7 logic / firmware download detection ------
                        # S7comm function codes:
                        #   0x1a Request Download, 0x1b Download Block,
                        #   0x1c Download Ended,  0x1d Start Upload,
                        #   0x1e Upload,          0x1f End Upload
                        # tshark Info usually prints human names; match both.
                        s7_dl_patterns = (
                            "request download", "download block", "download ended",
                            "function 0x1a", "function 0x1b", "function 0x1c",
                        )
                        s7_ul_patterns = (
                            "start upload", "end upload", "upload block",
                            "function 0x1d", "function 0x1e", "function 0x1f",
                        )
                        if to_server and "s7comm" in fp and any(t in il for t in s7_dl_patterns):
                            self.add_finding(
                                SEVERITY_CRITICAL, "Siemens S7 / PROFINET",
                                "S7 logic/firmware download observed",
                                f"A Siemens S7 block/firmware download sequence was observed from {src} to {dst}. "
                                "Unauthorized program downloads are a direct field-device compromise action — the "
                                "attacker has written executable logic to the PLC.",
                                [ev], [src], [dst], "S7comm", [pn],
                                f"siemens::logic-download::{src}::{dst}",
                                tags=["write", "siemens", "logic_download", "critical_control"],
                            )
                        if to_server and "s7comm" in fp and any(t in il for t in s7_ul_patterns):
                            self.add_finding(
                                SEVERITY_HIGH, "Siemens S7 / PROFINET",
                                "S7 program upload (read) observed",
                                f"A Siemens S7 block upload sequence was observed from {src} to {dst}. "
                                "Program upload is routinely used by engineering tools but is also used by attackers "
                                "to steal proprietary control logic prior to manipulation.",
                                [ev], [src], [dst], "S7comm", [pn],
                                f"siemens::program-upload::{src}::{dst}",
                                tags=["discovery", "siemens", "program_upload"],
                            )
                        if to_server and "read szl" in il:
                            self.add_finding(
                                SEVERITY_MEDIUM, "Siemens S7 / PROFINET", "S7 Read SZL observed",
                                f"{client} read the PLC's system status lists (SZL). TIA Portal does this when going online; "
                                "from any other host it is PLC inventory reconnaissance.",
                                [ev], [client], [server], "S7comm", [pn],
                                f"siemens::szl::{client}::{server}", tags=["discovery", "siemens"],
                            )
                        if "dcp set" in il or ("set " in il and "dcp" in il):
                            self.add_finding(
                                SEVERITY_HIGH, "Siemens S7 / PROFINET", "PROFINET DCP Set observed",
                                "A PROFINET DCP Set operation was observed. These operations can rename devices or change addressing.",
                                [ev], [src], [dst], "PROFINET DCP", [pn],
                                f"siemens::dcp-set::{src}::{dst}", tags=["write", "siemens"],
                            )
                        if "identify all" in il:
                            self.add_finding(
                                SEVERITY_MEDIUM, "Siemens S7 / PROFINET", "PROFINET Identify All broadcast observed",
                                "A PROFINET DCP Identify All broadcast was observed, which can indicate active discovery of OT devices.",
                                [ev], [src], [dst], "PROFINET DCP", [pn],
                                f"siemens::identify-all::{src}::{dst}", tags=["discovery", "siemens"],
                            )

                    # ---- TFTP (firmware delivery / config exfil) ---------
                    if _l7 and (dport == 69 or sport == 69 or "tftp" in fp):
                        if "read request" in il or "rrq" in il or "write request" in il or "wrq" in il:
                            # Extract filename hint from Info string
                            m = re.search(r'(?:read request|rrq|write request|wrq)[^"]*"([^"]{1,120})"', info, re.IGNORECASE)
                            fname = m.group(1) if m else ""
                            is_firmware_name = bool(fname) and any(
                                kw in fname.lower()
                                for kw in ("firmware", "fw", ".bin", ".img", ".hex",
                                           ".cfg", ".conf", "boot", "flash")
                            )
                            sev = SEVERITY_CRITICAL if is_firmware_name else SEVERITY_HIGH
                            title = "TFTP firmware/config transfer observed" if is_firmware_name else "TFTP transfer observed"
                            self.add_finding(
                                sev, "Cleartext and Legacy Protocols", title,
                                f"TFTP traffic was observed between {src} and {dst}"
                                + (f" for file '{fname}'" if fname else "")
                                + ". TFTP has no authentication and no encryption; it is commonly used to "
                                  "stage firmware updates and configuration pulls. In OT, TFTP to a "
                                  "controller from anything other than an approved engineering host during "
                                  "an approved change window should be treated as suspicious.",
                                [ev + (f" | filename: {fname}" if fname else "")],
                                [src], [dst], "TFTP", [pn],
                                f"tftp::xfer::{src}::{dst}::{fname or 'unknown'}",
                                tags=["cleartext", "legacy", "tftp"] + (["firmware_transfer", "logic_download"] if is_firmware_name else []),
                            )

                    # ---- MODBUS: firmware-ish function codes -------------
                    # Modbus FC 0x2B (43) with MEI type 0x0E = Read Device Identification
                    # (recon but often used pre-firmware), and FC 0x2B with MEI 0x0D/0x0F
                    # in some dialects carries vendor-specific file transfer payloads.
                    # tshark Info usually shows "Encapsulated Interface Transport".
                    if to_server and (dport == 502 or sport == 502) and any(
                        t in il for t in ("encapsulated interface transport",
                                          "read device identification",
                                          "mei type 14", "function 43")
                    ):
                        self.add_finding(
                            SEVERITY_MEDIUM, "Modbus TCP",
                            "Modbus MEI / Read Device ID observed",
                            f"Modbus Encapsulated Interface Transport (FC 0x2B, Read Device Identification) "
                            f"was seen from {src} to {dst}. This is device fingerprinting — benign from an "
                            "engineering tool, but a common precursor to targeted exploitation.",
                            [ev], [src], [dst], "Modbus TCP", [pn],
                            f"modbus::mei::{src}::{dst}",
                            tags=["discovery", "modbus"],
                        )

                    # ---- Zigbee (IEEE 802.15.4 / ZigBee NWK / APS) ------
                    if "zbee_nwk" in fp or "zbee_aps" in fp or "zbee_zcl" in fp or "wpan" in fp:
                        zigbee["rows_seen"] = True
                        zigbee["pcap_names"].add(pn)
                        if len(zigbee["samples"]) < 5:
                            zigbee["samples"].append(ev)
                        sec = row.get("zbee_nwk.security", "")
                        if sec == "0" or sec == "" and ("zbee_nwk" in fp or "zbee_aps" in fp):
                            if len(zigbee["unencrypted_samples"]) < 5:
                                zigbee["unencrypted_samples"].append(ev)
                        if any(t in il for t in ("write", "command", "on/off", "level control", "thermostat", "door lock")):
                            if len(zigbee["write_samples"]) < 5:
                                zigbee["write_samples"].append(ev)

                    # ---- CoAP (Constrained Application Protocol) ---------
                    if _l7 and ("coap" in fp or dport in {5683, 5684} or sport in {5683, 5684}):
                        coap_acc["rows_seen"] = True
                        coap_acc["pcap_names"].add(pn)
                        if len(coap_acc["samples"]) < 5:
                            coap_acc["samples"].append(ev)
                        code = row.get("coap.code", "")
                        # CoAP PUT = 0.03, POST = 0.02, DELETE = 0.04
                        if code in {"0.02", "0.03", "0.04"} or any(t in il for t in ("put", "post", "delete")):
                            if len(coap_acc["write_samples"]) < 5:
                                coap_acc["write_samples"].append(ev)
                        # Unencrypted CoAP runs on 5683; DTLS-protected on 5684
                        if dport == 5683 or sport == 5683:
                            if len(coap_acc["unencrypted_samples"]) < 5:
                                coap_acc["unencrypted_samples"].append(ev)

                    # ---- Z-Wave ------------------------------------------
                    if "zwave" in fp:
                        zwave["rows_seen"] = True
                        zwave["pcap_names"].add(pn)
                        if len(zwave["samples"]) < 5:
                            zwave["samples"].append(ev)

                    # ---- OMRON FINS (TCP/UDP 9600) -----------------------
                    # Factory Interface Network Service — proprietary Omron
                    # PLC command protocol.  No native authentication or
                    # encryption.  tshark has a partial FINS dissector; Info
                    # strings can include memory-area function names.
                    if _l7 and (dport == 9600 or sport == 9600):
                        fins["rows_seen"] = True
                        fins["pcap_names"].add(pn)
                        if len(fins["samples"]) < 5:
                            fins["samples"].append(ev)
                        fins_write_kw = (
                            "memory area write", "file write", " write ", "stop", " run",
                            "cpu unit data write", "forced set", "forced reset",
                        )
                        if to_server and any(t in il for t in fins_write_kw):
                            self.add_finding(
                                SEVERITY_HIGH, "Omron FINS",
                                "Omron FINS write/control operation observed",
                                f"Omron FINS traffic consistent with a write or control command was observed "
                                f"from {src} to {dst}. FINS carries no authentication or encryption.",
                                [ev], [src], [dst], "Omron FINS", [pn],
                                f"fins::write::{src}::{dst}", tags=["write", "fins"],
                            )

                    # ---- TRICONEX TRISTATION (UDP 1502) -----------------
                    # Engineering protocol of Triconex safety instrumented
                    # systems.  tshark has no dissector, so sessions are
                    # recognised by port and reported per host pair.
                    if _l7 and _transport == "UDP" and (dport == 1502 or sport == 1502):
                        session_ts = tristation.setdefault((client, server), {
                            "packets": 0, "to_controller": 0, "first": None, "last": None, "pcaps": set()})
                        session_ts["packets"] += 1
                        session_ts["to_controller"] += 1 if to_server else 0
                        session_ts["pcaps"].add(pn)
                        try:
                            when = float(_ts_e)
                        except ValueError:
                            when = None
                        if when is not None:
                            session_ts["first"] = when if session_ts["first"] is None else min(session_ts["first"], when)
                            session_ts["last"] = when if session_ts["last"] is None else max(session_ts["last"], when)

                    # ---- GE-SRTP (TCP 18245) ----------------------------
                    # GE Service Request Transport Protocol used by GE
                    # PACSystems (RX3i, 90-30) PLCs.  Cleartext, no auth.
                    if _l7 and (dport == 18245 or sport == 18245):
                        gertp["rows_seen"] = True
                        gertp["pcap_names"].add(pn)
                        if len(gertp["samples"]) < 5:
                            gertp["samples"].append(ev)
                        if to_server and any(t in il for t in ("write", "force", "program", "start", "stop")):
                            self.add_finding(
                                SEVERITY_HIGH, "GE SRTP",
                                "GE SRTP write/control operation observed",
                                f"GE SRTP traffic consistent with a write or control request was observed "
                                f"from {src} to {dst}. GE SRTP has no authentication or encryption.",
                                [ev], [src], [dst], "GE SRTP", [pn],
                                f"gertp::write::{src}::{dst}", tags=["write", "ge_srtp"],
                            )

                    # ---- MITSUBISHI MELSEC (TCP 5007) -------------------
                    # MELSEC SLMP 3E frame format — used by Mitsubishi Q-
                    # series and iQ-R PLCs.  Cleartext, no authentication.
                    if _l7 and (dport == 5007 or sport == 5007):
                        melsec["rows_seen"] = True
                        melsec["pcap_names"].add(pn)
                        if len(melsec["samples"]) < 5:
                            melsec["samples"].append(ev)
                        if to_server and any(t in il for t in ("write", "remote run", "remote stop", "remote reset", "unlock")):
                            self.add_finding(
                                SEVERITY_HIGH, "Mitsubishi MELSEC",
                                "Mitsubishi MELSEC write/control operation observed",
                                f"Mitsubishi MELSEC SLMP traffic consistent with a write or control request was "
                                f"observed from {src} to {dst}. MELSEC SLMP has no authentication or encryption.",
                                [ev], [src], [dst], "Mitsubishi MELSEC", [pn],
                                f"melsec::write::{src}::{dst}", tags=["write", "melsec", "mitsubishi"],
                            )

                    # ---- OSISOFT / AVEVA PI (TCP 5450 Data Archive, 5457 AF) ----
                    # Historian access = read or corrupt the process record.
                    if _l7 and (service_port in (5450, 5457)):
                        pi_srv["rows_seen"] = True
                        pi_srv["pcap_names"].add(pn)
                        if len(pi_srv["samples"]) < 5:
                            pi_srv["samples"].append(ev)

                    # ---- IGNITION GATEWAY (TCP 62541 OPC UA, 8060 gateway network) ----
                    if _l7 and (service_port in (62541, 8060)):
                        ignition["rows_seen"] = True
                        ignition["pcap_names"].add(pn)
                        if len(ignition["samples"]) < 5:
                            ignition["samples"].append(ev)
                        if service_port == 8060 and "data" in fp.split(":") and "tls" not in fp.split(":"):
                            self.add_finding(
                                SEVERITY_HIGH, "Ignition Gateway", "Ignition gateway network traffic without TLS",
                                f"Gateway-network traffic between {client} and {server}:8060 carried data without TLS. "
                                "The Ignition gateway network uses TLS by default, so this indicates a weakened configuration.",
                                [ev], [client], [server], "Ignition Gateway", [pn],
                                f"ignition::cleartext::{server}", tags=["cleartext", "ignition"],
                            )

                    # ---- NODE-RED (TCP 1880) ----------------------------
                    # Node-RED flow-based programming platform default port.
                    # Exposure of the Node-RED dashboard/API without auth
                    # allows any attacker on the network to deploy arbitrary
                    # flows — including flows that control OT devices.
                    if _l7 and (dport == 1880 or sport == 1880):
                        nodered["rows_seen"] = True
                        nodered["pcap_names"].add(pn)
                        if len(nodered["samples"]) < 5:
                            nodered["samples"].append(ev)
                        # adminAuth sends a Bearer token on editor/API requests and
                        # answers 401 without one; neither ever appears = no auth.
                        if "http" in fp.split(":") and server:
                            pair_state = nodered["pairs"][(client, server)]
                            pair_state["pcaps"].add(pn)
                            request_line = re.match(r"(?:get|post|put|delete|patch|head) (\S+)", il)
                            if (to_server and request_line and re.search(
                                    r"/(?:flows?|nodes|settings|library|context|diagnostics|plugins)(?:[/?]|$)",
                                    request_line.group(1))):
                                pair_state["requests"] += 1
                                if row.get("http.authorization"):
                                    pair_state["authorized"] += 1
                                if not pair_state["sample"]:
                                    pair_state["sample"] = ev
                            elif not to_server and (row.get("http.response.code") or "") == "401":
                                pair_state["denied"] += 1
                        if to_server and any(t in il for t in ("post /flows", "post /flow", "delete /flow", "deploy")):
                            self.add_finding(
                                SEVERITY_CRITICAL, "Node-RED",
                                "Node-RED flow deployment observed",
                                f"HTTP traffic consistent with a Node-RED flow deployment was observed from {src}. "
                                "Deploying new flows can alter process logic, add data exfiltration channels, "
                                "or issue commands to downstream OT devices.",
                                [ev], [src], [dst], "Node-RED", [pn],
                                f"nodered::deploy::{src}::{dst}", tags=["write", "logic_download", "nodered"],
                            )

                    # ---- PHYSICAL SECURITY --------------------------------
                    is_phys = _l7 and ("rtsp" in fp_layers or service_port in (554, 8554))
                    if is_phys:
                        phys["rows_seen"] = True
                        phys["pcap_names"].add(pn)
                        if "rtsp" in fp.split(":") and server:
                            rtsp_state = phys["rtsp_pairs"][(client, server)]
                            rtsp_state["pcaps"].add(pn)
                            if (row.get("rtsp.status") or "") == "401":
                                rtsp_state["challenged"] = True
                            if to_server and (row.get("rtsp.method") or "").upper() in ("DESCRIBE", "SETUP", "PLAY"):
                                rtsp_state["streamed"] = True
                                if not rtsp_state["sample"]:
                                    rtsp_state["sample"] = ev
                        if service_port == 8080 and "rtsp" in il:
                            self.add_finding(
                                SEVERITY_MEDIUM, "Physical Security", "RTSP tunneled over HTTP",
                                "RTSP content was observed over TCP/8080.",
                                [ev], [client], [server], "RTSP/HTTP", [pn],
                                f"rtsp::http-tunnel::{client}::{server}",
                            )
                        if "osdp" in il and "secure channel" not in il:
                            self.add_finding(
                                SEVERITY_HIGH, "Physical Security", "Cleartext OSDP observed",
                                "OSDP traffic was observed without Secure Channel indicators.",
                                [ev], [src], [dst], "OSDP", [pn],
                                f"osdp::cleartext::{src}::{dst}",
                            )

                    # ---- AUDIO/VIDEO STREAMING ---------------------------
                    # Signaled RTP (tshark classified it from SIP/RTSP SDP).
                    _ptype_raw = row.get("rtp.p_type") or ""
                    try:
                        _tsf = float(_ts_e) if _ts_e else None
                    except ValueError:
                        _tsf = None
                    _flen = 0
                    try:
                        _flen = int(row.get("frame.len") or "0")
                    except ValueError:
                        pass
                    _is_mcast_dst = False
                    if dst and "." in dst:
                        try:
                            _is_mcast_dst = 224 <= int(dst.split(".", 1)[0]) <= 239
                        except ValueError:
                            pass
                    if _ptype_raw and src and dst:
                        av["pcap_names"].add(pn)
                        if len(av["rtp_flows"]) < 2000 or (src, dst, dport) in av["rtp_flows"]:
                            fl = av["rtp_flows"][(src, dst, dport)]
                            fl["pkts"] += 1
                            fl["bytes"] += _flen
                            fl["pcaps"].add(pn)
                            for pt_val in _ptype_raw.split(","):
                                pt_val = pt_val.strip()
                                if pt_val.isdigit():
                                    fl["ptypes"][int(pt_val)] += 1
                            if _tsf is not None:
                                if fl["first"] is None or _tsf < fl["first"]:
                                    fl["first"] = _tsf
                                if fl["last"] is None or _tsf > fl["last"]:
                                    fl["last"] = _tsf
                    # SIP signaling (VoIP call setup, intercom / paging systems)
                    if "sip" in fp.split(":") or dport in (5060, 5061) or sport in (5060, 5061):
                        if "invite" in il or ("200 ok" in il and "sdp" in fp):
                            av["pcap_names"].add(pn)
                            if src:
                                av["sip_sources"].add(src)
                            if len(av["sip_calls"]) < 50:
                                av["sip_calls"].append((pn, src, dst, info[:160], _ts_e))
                    # RTSP active streaming (PLAY/SETUP = a stream was requested;
                    # presence/auth findings for RTSP live in Physical Security)
                    if is_phys and re.search(r"\b(play|setup)\b", il) and "rtsp" in fp:
                        av["pcap_names"].add(pn)
                        if src:
                            av["rtsp_sources"].add(src)
                        if len(av["rtsp_play"]) < 50:
                            av["rtsp_play"].append((pn, src, dst, info[:160], _ts_e))
                    # MPEG Transport Stream (IPTV / raw video distribution)
                    if "mp2t" in fp.split(":") and src and dst:
                        av["pcap_names"].add(pn)
                        if len(av["mp2t_pairs"]) < 500 or (src, dst) in av["mp2t_pairs"]:
                            pr = av["mp2t_pairs"][(src, dst)]
                            pr["pkts"] += 1
                            pr["bytes"] += _flen
                            pr["pcaps"].add(pn)
                            pr["mcast"] = pr["mcast"] or _is_mcast_dst
                            if not pr["sample"]:
                                pr["sample"] = ev
                    # RTMP (Flash-era video push, still common on DVR/NVR gear)
                    elif ("rtmpt" in fp or dport == 1935 or sport == 1935) and src and dst:
                        av["pcap_names"].add(pn)
                        pr = av["rtmp_pairs"][(src, dst)]
                        pr["pkts"] += 1
                        pr["pcaps"].add(pn)
                        if not pr["sample"]:
                            pr["sample"] = ev
                    # GigE Vision machine-vision cameras (GVCP control channel)
                    if _l7 and ("gvcp" in fp_layers or dport == 3956 or sport == 3956) and src and dst:
                        av["pcap_names"].add(pn)
                        pr = av["gige_pairs"][(src, dst)]
                        pr["pkts"] += 1
                        pr["pcaps"].add(pn)
                        if not pr["sample"]:
                            pr["sample"] = ev
                    # CCTV vendor DVR/NVR ports: Hikvision 8000, Dahua 37777.
                    # Hedged — port 8000 is also a common HTTP-alt port, so
                    # skip rows tshark already dissected as HTTP and require a
                    # sustained flow before the post-loop code emits anything.
                    _dvr_port = 8000 if (dport == 8000 or sport == 8000) else (37777 if (dport == 37777 or sport == 37777) else 0)
                    if _dvr_port and src and dst and "http" not in fp.split(":"):
                        av["pcap_names"].add(pn)
                        pr = av["vendor_dvr_pairs"][(src, dst, _dvr_port)]
                        pr["pkts"] += 1
                        pr["bytes"] += _flen
                        pr["pcaps"].add(pn)
                        pr["port"] = _dvr_port
                        if not pr["sample"]:
                            pr["sample"] = ev
                    # Unsignaled media candidates — only rows no dissector claimed.
                    if not _ptype_raw and "udp" in fp.split(":") and src and dst:
                        if _is_mcast_dst:
                            # Generic multicast UDP: possible video/audio
                            # distribution.  Skip well-known service groups
                            # (mDNS/LLMNR/SSDP/WS-Discovery/PTP/CoAP) — they
                            # have their own checks.
                            if (not dst.startswith("224.0.0.")
                                    and dst != "239.255.255.250"
                                    and dst != "224.0.1.129"
                                    and dport not in (5353, 5355, 1900, 3702, 319, 320, 5683, 5684)
                                    and "mp2t" not in fp.split(":")):
                                av["pcap_names"].add(pn)
                                if len(av["mcast_flows"]) < 2000 or (src, dst, dport) in av["mcast_flows"]:
                                    fl = av["mcast_flows"][(src, dst, dport)]
                                    fl["pkts"] += 1
                                    fl["bytes"] += _flen
                                    fl["pcaps"].add(pn)
                                    if _tsf is not None:
                                        if fl["first"] is None or _tsf < fl["first"]:
                                            fl["first"] = _tsf
                                        if fl["last"] is None or _tsf > fl["last"]:
                                            fl["last"] = _tsf
                        elif sport >= 16384 and dport >= 16384 and _flen >= 200:
                            # Ephemeral-to-ephemeral UDP with media-sized frames:
                            # raw RTP-like heuristic.  Classified post-loop only
                            # if the flow is sustained (>=200 packets).
                            if len(av["raw_flows"]) < 2000 or (src, dst, dport) in av["raw_flows"]:
                                fl = av["raw_flows"][(src, dst, dport)]
                                fl["pkts"] += 1
                                fl["bytes"] += _flen
                                fl["pcaps"].add(pn)
                                if _tsf is not None:
                                    if fl["first"] is None or _tsf < fl["first"]:
                                        fl["first"] = _tsf
                                    if fl["last"] is None or _tsf > fl["last"]:
                                        fl["last"] = _tsf

                    # ---- BEACONING / C2 PERIODICITY ----------------------
                    # Track timestamps per (src, dst, dport).  Bound samples to
                    # the first 500 per pair so memory stays bounded on chatty
                    # polling traffic; that's enough to compute jitter stats.
                    if (to_server and client and server and service_port
                            and service_port not in KNOWN_OT_PORTS and service_port not in _BEACON_EXEMPT_PORTS
                            and not _is_mcast_dst and not server.endswith(".255")
                            and (_transport != "TCP" or _tcp_flag_bits(row) & 0x0A)):
                        bpair = (client, server, service_port)
                        samples = bcn["timestamps"][bpair]
                        if len(samples) < 500:
                            try:
                                ts_b = float(row.get("frame.time_epoch") or "0")
                            except ValueError:
                                ts_b = 0.0
                            # One sample per exchange: a connection's SYN and its
                            # request, or a request and its continuation, are one event.
                            if ts_b and (not samples or abs(ts_b - samples[-1]) >= 1.0):
                                samples.append(ts_b)
                        bcn["pcap_names"].add(pn)

                    # ---- DNS anomalies -----------------------------------
                    if "dns" in fp or dport == 53 or sport == 53:
                        dns_state["pcap_names"].add(pn)
                        # Pull query name from Info (tshark prints "Standard query ... A example.com")
                        m = re.search(r"(?:Standard query|query)\s+(?:0x[0-9a-fA-F]+\s+)?(\w+)\s+([A-Za-z0-9._\-]{1,255})",
                                      info)
                        if m:
                            qtype = m.group(1)
                            qname = m.group(2).rstrip(".")
                            if src and qname:
                                dns_state["queries_per_src"][src] += 1
                                dns_state["names_per_src"][src].add(qname)
                                if dst:
                                    dns_state["servers_per_src"][src].add(dst)
                            # Long / high-entropy names (DGA / tunneling)
                            if len(qname) >= 50:
                                dns_state["long_names"].append((pn, src, qname, len(qname)))
                            # Entropy scoring: short names that are random-looking
                            # (catches DGA domains that don't trip the length threshold)
                            elif len(qname) >= 12:
                                ent, label = _dns_label_entropy(qname)
                                if ent >= 3.5 and len(label) >= 8:
                                    dns_state["high_entropy_names"].append((pn, src, qname, round(ent, 2)))
                            # TXT queries — possible tunneling if response is large
                            if qtype.upper() == "TXT":
                                try:
                                    resp_size = int(row.get("frame.len") or "0")
                                except ValueError:
                                    resp_size = 0
                                if resp_size > 300:
                                    dns_state["txt_large"].append((pn, src, qname, resp_size))
                        # NXDOMAIN response
                        if "no such name" in il or "nxdomain" in il:
                            # The source of an NXDOMAIN response is the resolver;
                            # we care about the original query source, which is
                            # the destination of this response packet.
                            victim = dst or src
                            if victim:
                                dns_state["nxdomain_per_src"][victim] += 1

                    # ---- SNMP depth --------------------------------------
                    if _l7 and (dport == 161 or sport == 161 or "snmp" in fp):
                        snmp_state["pcap_names"].add(pn)
                        pdu = _int_field(row, "snmp.data")
                        if pdu in (1, 5) and src:
                            snmp_state["getnext_per_src"][src] += 1
                        if pdu == 3 and len(snmp_state["set_events"]) < 50:
                            snmp_state["set_events"].append((pn, src, dst, info[:160]))
                        community = row.get("snmp.community") or ""
                        if community and (row.get("snmp.version") or "") in ("0", "1"):
                            snmp_state["communities"][community] += 1
                            if src and pdu != 2:
                                snmp_state["v1v2c_sources"].add(src)

                    # ---- TLS inspection ----------------------------------
                    if "tls" in fp or "ssl" in fp:
                        tls_state["rows_seen"] = True
                        tls_state["pcap_names"].add(pn)
                        handshake_types = {t.strip() for t in (row.get("tls.handshake.type") or "").split(",")}
                        if "2" in handshake_types:
                            # ServerHello: the version and cipher the server actually chose.
                            version = _int_field(row, "tls.handshake.extensions.supported_version")
                            if version < 0:
                                version = _int_field(row, "tls.handshake.version")
                            if version in (0x0002, 0x0300, 0x0301, 0x0302) and len(tls_state["old_versions"]) < 50:
                                version_name = _TLS_VERSION_NAMES[version]
                                if not any(e[2] == server and e[3] == version_name for e in tls_state["old_versions"]):
                                    tls_state["old_versions"].append((pn, client, server, version_name))
                            suite = _int_field(row, "tls.handshake.ciphersuite")
                            if suite >= 0:
                                suite_name = tls_cipher_name(suite)
                                weak = weak_cipher_label(suite_name)
                                cipher_label = f"{weak}: {suite_name}"
                                if (weak and len(tls_state["weak_ciphers"]) < 50
                                        and not any(e[2] == server and e[3] == cipher_label for e in tls_state["weak_ciphers"])):
                                    tls_state["weak_ciphers"].append((pn, client, server, cipher_label))
                        if ((row.get("_ws.col.Protocol") or "").upper() == "SSLV2" and len(tls_state["old_versions"]) < 50
                                and not any(e[2] == server and e[3] == "SSLv2" for e in tls_state["old_versions"])):
                            tls_state["old_versions"].append((pn, client, server, "SSLv2"))
                        alert = _int_field(row, "tls.alert_message.desc")
                        if alert in (42, 45, 48):
                            alert_list = tls_state["expired_certs"] if alert == 45 else tls_state["rejected_certs"]
                            if len(alert_list) < 50 and not any(e[1] == client and e[2] == server for e in alert_list):
                                alert_name = {42: "bad certificate", 45: "certificate expired", 48: "unknown CA"}[alert]
                                alert_list.append((pn, client, server, f"{alert_name} | {info[:120]}"))
                        # JA3 fingerprint — flag known offensive tooling
                        ja3 = (row.get("tls.handshake.ja3") or "").strip().lower()
                        if ja3 and ja3 in _JA3_KNOWN_BAD:
                            label = _JA3_KNOWN_BAD[ja3]
                            if len(tls_state["ja3_hits"]) < 50:
                                tls_state["ja3_hits"].append((pn, src, dst, ja3, label))

                    # ---- IT-NOISE-ON-OT (mDNS/LLMNR/NBNS/SSDP) ----------
                    noise_proto = None
                    if dport == 5353 or sport == 5353:
                        noise_proto = "mDNS"
                    elif dport == 5355 or sport == 5355:
                        noise_proto = "LLMNR"
                    elif dport in (137, 138) or sport in (137, 138):
                        noise_proto = "NetBIOS-NS/DGM"
                    elif dport == 1900 or sport == 1900:
                        noise_proto = "SSDP"
                    elif dport == 3702 or sport == 3702:
                        noise_proto = "WS-Discovery"
                    if noise_proto and src and _l7:
                        subnet = subnet_from_ip(src)
                        slot = noise_state["by_proto_subnet"][(noise_proto, subnet)]
                        slot["hosts"].add(src)
                        slot["pcaps"].add(pn)
                        if len(slot["samples"]) < 5:
                            slot["samples"].append(f"{pn}: {src} -> {dst} | {info[:80]}")

                    # ---- DHCP ROGUE-SERVER -----------------------------
                    if dport == 68 or sport == 67:
                        # Server response (Offer/Ack) sourced from port 67
                        eth_src_dhcp = (row.get("eth.src") or "").lower()
                        if eth_src_dhcp and src:
                            subnet = subnet_from_ip(src)
                            dhcp_state["servers_by_subnet"][subnet][eth_src_dhcp].add(pn)
                            if len(dhcp_state["samples"][subnet]) < 5:
                                dhcp_state["samples"][subnet].append(
                                    f"{pn}: server {src} (MAC {eth_src_dhcp}) -> {dst} | {info[:80]}"
                                )

                    # ---- ICMP SWEEP / UNREACHABLE ----------------------
                    if "icmp" in fp:
                        icmp_state["pcaps"].add(pn)
                        if "destination unreachable" in il or "unreachable" in il:
                            if dst:
                                icmp_state["unreach_per_dst"][dst] += 1
                        else:
                            # echo-request style: count distinct destinations per source
                            if src and dst:
                                icmp_state["dests_per_src"][src].add(dst)
                                if len(icmp_state["samples_per_src"][src]) < 5:
                                    icmp_state["samples_per_src"][src].append(
                                        f"{pn}: {src} -> {dst} | {info[:80]}"
                                    )

                    # ---- NTP / CAPTURE INTEGRITY -------------------------
                    # Track every frame epoch per file (capped) to detect
                    # large gaps that imply a paused capture or lost window,
                    # and count NTP queries per source to flag devices that
                    # never sync time.
                    try:
                        ts_ntp = float(row.get("frame.time_epoch") or "0")
                    except ValueError:
                        ts_ntp = 0.0
                    if ts_ntp:
                        ntp_state["pcap_names"].add(pn)
                        clock = ntp_state["per_file"].get(pn)
                        if clock is None:
                            clock = ntp_state["per_file"][pn] = {
                                "first": ts_ntp, "last": ts_ntp, "frames": 0, "active": 0.0,
                                "max_gap": 0.0, "gap_at": (ts_ntp, ts_ntp)}
                        step = ts_ntp - clock["last"]
                        if step > clock["max_gap"]:
                            clock["max_gap"], clock["gap_at"] = step, (clock["last"], ts_ntp)
                        if 0 < step < 60:
                            clock["active"] += step
                        clock["frames"] += 1
                        clock["first"] = min(clock["first"], ts_ntp)
                        clock["last"] = max(clock["last"], ts_ntp)
                    if _l7 and (dport == 123 or sport == 123 or "ntp" in fp):
                        if src:
                            ntp_state["ntp_queries"][src] += 1
                            if dst:
                                ntp_state["ntp_servers"][src].add(dst)

                    # ---- NETWORK HYGIENE (RST / SYN anomalies) -----------
                    pair = (src, dst)
                    tcp_bits = _tcp_flag_bits(row)
                    if tcp_bits & 0x05:
                        conn_key = (src, sport, dst, dport) if (src, sport) <= (dst, dport) else (dst, dport, src, sport)
                        if tcp_bits & 0x01 and len(hyg["fin_seen"]) < 200_000:
                            hyg["fin_seen"].add(conn_key)
                        if tcp_bits & 0x04:
                            if conn_key in hyg["fin_seen"]:
                                hyg["rst_after_fin"][pair] += 1
                            else:
                                hyg["rst_counts"][pair] += 1
                    if tcp_bits & 0x12 == 0x02:
                        hyg["syn_counts"][pair] += 1
                    elif tcp_bits & 0x12 == 0x12:
                        hyg["synack_counts"][pair] += 1
                    hyg["pcap_names"].add(pn)

                    # ---- WHICH MAC CARRIES EACH IP -------------------------
                    eth_src_row = (row.get("eth.src") or "").lower()
                    eth_dst_row = (row.get("eth.dst") or "").lower()
                    if src and dst and eth_src_row:
                        try:
                            ts_bind = float(_ts_e or "0")
                        except ValueError:
                            ts_bind = 0.0
                        for ip_key, mac_key, direction, peer in ((src, eth_src_row, 0, dst), (dst, eth_dst_row, 1, src)):
                            if not mac_key or (direction and is_group_mac(mac_key)):
                                continue
                            first_mac = hyg["ip_first_mac"].get(ip_key)
                            if first_mac is None:
                                if len(hyg["ip_first_mac"]) < 300_000:
                                    hyg["ip_first_mac"][ip_key] = mac_key
                            elif first_mac != mac_key:
                                hyg["ip_mac_conflicts"].add(ip_key)
                            binding = hyg["ip_mac"].get((ip_key, mac_key))
                            if binding is None:
                                if len(hyg["ip_mac"]) >= 300_000:
                                    continue
                                binding = hyg["ip_mac"][(ip_key, mac_key)] = [0, 0, ts_bind, ts_bind]
                            binding[direction] += 1
                            if ts_bind:
                                binding[2] = min(binding[2] or ts_bind, ts_bind)
                                binding[3] = max(binding[3], ts_bind)
                            if ip_key in hyg["ip_mac_conflicts"]:
                                detail = hyg["ip_mac_detail"].setdefault(
                                    (ip_key, mac_key), {"peers": Counter(), "labels": Counter(), "samples": {}})
                                if len(detail["peers"]) < 8 or peer in detail["peers"]:
                                    detail["peers"][peer] += 1
                                label = row.get("_ws.col.Protocol") or "IP"
                                if len(detail["labels"]) < 6 or label in detail["labels"]:
                                    detail["labels"][label] += 1
                                if label not in detail["samples"] and len(detail["samples"]) < 6:
                                    detail["samples"][label] = f"{ev} (eth {eth_src_row} -> {eth_dst_row})"

                    # ---- ARP SPOOFING / MAC-IP BINDING -------------------
                    arp_op = row.get("arp.opcode", "")
                    if arp_op:
                        arp_src_mac = (row.get("arp.src.hw_mac") or "").lower()
                        arp_src_ip  = row.get("arp.src.proto_ipv4") or ""
                        arp_dst_ip  = row.get("arp.dst.proto_ipv4") or ""
                        eth_src_mac = (row.get("eth.src") or "").lower()
                        # Per-(IP, MAC) first/last-seen epoch tracking so
                        # ARP findings can include `frame.time_epoch ==`
                        # jump tags even though the finding is emitted
                        # from session-level aggregation, not per-row.
                        try:
                            _arp_ts = float(row.get("frame.time_epoch") or "0")
                        except ValueError:
                            _arp_ts = 0.0
                        if _arp_ts > 0:
                            if arp_src_ip:
                                if arp_src_ip not in hyg["ip_first_seen"]:
                                    hyg["ip_first_seen"][arp_src_ip] = _arp_ts
                                hyg["ip_last_seen"][arp_src_ip] = _arp_ts
                            if arp_src_mac:
                                if arp_src_mac not in hyg["mac_first_seen"]:
                                    hyg["mac_first_seen"][arp_src_mac] = _arp_ts
                                hyg["mac_last_seen"][arp_src_mac] = _arp_ts
                        # Track MAC <-> IP claims
                        if arp_src_mac and arp_src_ip:
                            hyg["mac_to_ips"][arp_src_mac].add(arp_src_ip)
                            hyg["ip_to_macs"][arp_src_ip].add(arp_src_mac)
                            hyg["arp_pcap_by_pair"][(arp_src_mac, arp_src_ip)].add(pn)
                        claim = None
                        if arp_src_mac and arp_src_ip and arp_src_ip != "0.0.0.0":
                            claim = hyg["arp_claims"].get((arp_src_ip, arp_src_mac))
                            if claim is None and len(hyg["arp_claims"]) < 100_000:
                                claim = hyg["arp_claims"][(arp_src_ip, arp_src_mac)] = {
                                    "frames": 0, "replies": 0, "unsolicited": 0,
                                    "first": _arp_ts, "last": _arp_ts, "senders": {}, "targets": {},
                                }
                        if claim is not None:
                            claim["frames"] += 1
                            if _arp_ts:
                                claim["first"] = min(claim["first"] or _arp_ts, _arp_ts)
                                claim["last"] = max(claim["last"], _arp_ts)
                            if eth_src_mac and (eth_src_mac in claim["senders"] or len(claim["senders"]) < 5):
                                sender = claim["senders"].setdefault(eth_src_mac, [0, _arp_ts, _arp_ts])
                                sender[0] += 1
                                sender[2] = max(sender[2], _arp_ts)
                            if arp_op == "2":
                                claim["replies"] += 1
                                target = (arp_dst_ip, (row.get("eth.dst") or "").lower())
                                if arp_dst_ip and (target in claim["targets"] or len(claim["targets"]) < 10):
                                    claim["targets"][target] = claim["targets"].get(target, 0) + 1
                        # Gratuitous ARP: reply (op=2) where sender IP == target IP,
                        # or request where sender IP == target IP (announcement).
                        if arp_src_ip and arp_dst_ip and arp_src_ip == arp_dst_ip:
                            hyg["gratuitous_arp_by_src"][arp_src_mac or eth_src_mac] += 1
                        # Sender-MAC / Ethernet-MAC mismatch (classic spoof indicator)
                        if arp_src_mac and eth_src_mac and arp_src_mac != eth_src_mac:
                            if len(hyg["eth_mac_mismatch"]) < 50:
                                hyg["eth_mac_mismatch"].append(
                                    (pn, eth_src_mac, arp_src_mac, arp_src_ip)
                                )
                        # Track request/reply pairing
                        if arp_op == "1":  # request
                            arp_requests_seen[(arp_src_ip, arp_dst_ip)] = True
                        elif arp_op == "2":  # reply
                            # A reply for which we never saw the matching request is
                            # suspect (but gratuitous ARPs legitimately have none, so
                            # exclude sender==target case which we've already flagged).
                            if arp_src_ip != arp_dst_ip and not arp_requests_seen.get((arp_dst_ip, arp_src_ip)):
                                if claim is not None:
                                    claim["unsolicited"] += 1
                                if len(hyg["arp_reply_no_request"]) < 50:
                                    hyg["arp_reply_no_request"].append(
                                        (pn, arp_src_mac, arp_src_ip, arp_dst_ip)
                                    )

                if VERBOSE:
                    print(f"        → {row_count:,} rows matched the protocol filter", flush=True)
            except TSharkError as exc:
                print(colorize(f"[!] tshark error on {pcap.name}: {exc}", SEVERITY_HIGH))
            # Per-file checkpoint so a crash during the streaming pass
            # doesn't cost all prior files' work.  Silent to avoid noise.
            try:
                self._checkpoint_save_silent()
            except Exception as exc:
                print(colorize(f"[!] Checkpoint save failed after {pcap.name}: {exc}", SEVERITY_MEDIUM))

        # ---- post-loop finding generation (per-protocol finalization) -

        # Modbus
        before = len(self.session.findings)
        if not mb["rows_seen"]:
            if self._expected_protocol(["modbus"]):
                self.add_finding(SEVERITY_MEDIUM, "Absence of Expected Traffic", "Expected Modbus TCP not observed",
                    "Modbus TCP was declared as expected, but no TCP/502 traffic was seen in the analyzed captures.",
                    ["No tcp.port == 502 packets matched."], [], [], "Modbus TCP", pcap_name_list, "absence::modbus")
        else:
            for (src, dst), count in mb["write_sources"].items():
                write_finding = self.finding_index.get(f"modbus::write::{src}::{dst}")
                if write_finding is not None:
                    write_finding.description = (
                        f"{src} sent {count:,} Modbus write request(s) to {dst}. Write-capable function codes should "
                        "be validated as intentional.")
                if src not in mb["read_masters"]:
                    self.add_finding(SEVERITY_HIGH, "Modbus TCP", "Unexpected Modbus write source",
                        f"{src} sent {count} Modbus write request(s) to {dst} but never read from any Modbus server. "
                        "Write-only clients exist (gateways or panels pushing setpoints), but an unknown host writing "
                        "without polling is also how a process gets manipulated; confirm this host is an authorized writer.",
                        [f"Write requests: {count}"], [src], [dst], "Modbus TCP", sorted(mb["pcap_names"]),
                        f"modbus::unexpected-writer::{src}::{dst}", tags=["write", "unexpected_writer"])
            # Register scanning: many start addresses, each read once or twice.
            # An HMI re-reads the same short scan list every cycle.
            for (src, dst), starts in mb["read_starts"].items():
                if len(starts) < 50:
                    continue
                reads_per_start = median(starts.values())
                if reads_per_start > 2:
                    continue
                addresses = sorted(starts)
                self.add_finding(SEVERITY_HIGH, "Modbus TCP", "Possible Modbus register scanning",
                    f"{src} read {len(starts)} different start addresses on {dst}, most of them only once or twice — "
                    "a sweep of the register map rather than an HMI's repeated polling of a fixed scan list.",
                    [f"Distinct start addresses: {len(starts)} (span {addresses[0]}-{addresses[-1]})",
                     f"Median reads per address: {reads_per_start:g}"],
                    [src], [dst], "Modbus TCP", sorted(mb["pcap_names"]),
                    f"modbus::scan::{src}::{dst}", tags=["recon", "modbus"])
            for dst, count in mb["exception_counts"].items():
                if count >= 5:
                    self.add_finding(SEVERITY_HIGH, "Modbus TCP", "Elevated Modbus exceptions",
                        f"{dst} returned {count} Modbus exception responses.",
                        [f"Exception responses: {count}"], [], [dst], "Modbus TCP", sorted(mb["pcap_names"]),
                        f"modbus::exceptions::{dst}")
            # Polling bursts: one-second request counts far above the pair's own baseline.
            multiplier = max(self.config.get("polling_anomaly_multiplier", DEFAULT_POLLING_ANOMALY_MULTIPLIER), 1.1)
            for (src, dst), points in mb["timestamps"].items():
                if len(points) < 30:
                    continue
                per_second = Counter(int(point) for point in points)
                if len(per_second) < 10:
                    continue
                baseline = median(per_second.values())
                bursts = sorted(second for second, count in per_second.items()
                                if count >= baseline * multiplier and count >= baseline + 20)
                if bursts:
                    self.add_finding(SEVERITY_MEDIUM, "Modbus TCP", "Modbus polling burst anomaly",
                        f"The request rate from {src} to {dst} spiked to {max(per_second.values())} requests per second "
                        f"against a baseline of {baseline:g}. HMIs do this briefly when they reconnect; sustained or "
                        "repeated bursts suggest a second client, a flood, or a script.",
                        [f"Baseline: {baseline:g} requests/s (median of active seconds) | peak: {max(per_second.values())} requests/s",
                         f"Burst seconds: {len(bursts)} | first burst at {bursts[0]} (epoch)"],
                        [src], [dst], "Modbus TCP", sorted(mb["pcap_names"]),
                        f"modbus::timing::{src}::{dst}", tags=["timing_anomaly", "modbus"])
            # Hammering: one start address read at a high sustained rate.
            for (src, dst), starts in mb["read_starts"].items():
                if not starts:
                    continue
                top_reg, top_count = starts.most_common(1)[0]
                if top_count < 1000:
                    continue
                # Rates come from each capture file's own time span, never from
                # one file's first read to another's last (files can be read out
                # of date order).  The busiest single file is compared with the
                # pooled rate over all files, which covers a flood split across
                # rotated capture files.
                spans = mb["read_span"].get(((src, dst), top_reg), {})
                candidates = [(count / max(last_read - first_read, 1.0), count, max(last_read - first_read, 1.0), pcap_key)
                              for pcap_key, (count, first_read, last_read) in spans.items() if count >= 1000]
                if len(spans) > 1:
                    pooled_count = sum(span[0] for span in spans.values())
                    pooled_seconds = sum(max(span[2] - span[1], 1.0) for span in spans.values())
                    candidates.append((pooled_count / pooled_seconds, pooled_count, pooled_seconds,
                                       f"{len(spans)} capture files"))
                hammer = max(candidates, default=None)
                if hammer is None or hammer[0] < 20:
                    continue
                rate, count, seconds, pcap_key = hammer
                distinct = len(starts)
                severity = SEVERITY_HIGH if distinct <= 3 else SEVERITY_MEDIUM
                self.add_finding(
                    severity, "Modbus TCP",
                    "Repetitive single-register polling pattern",
                    f"{src} read address {top_reg} on {dst} {count:,} times in {human_duration(seconds)} — about "
                    f"{rate:.0f} requests per second ({distinct} distinct start address(es) overall). HMI scan groups "
                    "rarely exceed a few reads per second per block; a sustained high rate on one address suggests a "
                    "hammer-style test, a denial-of-service probe, or a misconfigured client.",
                    [f"Address {top_reg}: {count:,} reads in {human_duration(seconds)} (about {rate:.0f} per second) "
                     f"in {pcap_key}",
                     f"Distinct start addresses: {distinct}",
                     "Top 5 addresses: " + ", ".join(f"{r}({c})" for r, c in starts.most_common(5))],
                    [src], [dst], "Modbus TCP", sorted(mb["pcap_names"]),
                    f"modbus::repetitive-poll::{src}::{dst}",
                    tags=["modbus", "polling_pattern"],
                )
            # Replay / injection: a server answers each transaction exactly once.
            for pair_mb in sorted(set(mb["duplicate_responses"]) | set(mb["unsolicited_responses"])):
                duplicates = mb["duplicate_responses"][pair_mb]
                unsolicited = mb["unsolicited_responses"][pair_mb]
                responses = max(mb["responses"][pair_mb], 1)
                if duplicates < 3 and not (unsolicited >= 3 and unsolicited / responses >= 0.02):
                    continue
                client_mb, server_mb = pair_mb
                self.add_finding(
                    SEVERITY_HIGH, "Modbus TCP",
                    "Duplicate or unsolicited Modbus responses (possible replay/injection)",
                    f"Traffic from {server_mb} to {client_mb} contained {duplicates} second answer(s) to transactions "
                    f"that were already answered and {unsolicited} answer(s) to no outstanding request. A Modbus "
                    "server answers each request exactly once, so extra answers mean another party is injecting or "
                    "replaying responses — or a gateway is duplicating frames. Unsolicited answers alone can also "
                    "come from packets the capture dropped.",
                    list(mb["response_samples"][pair_mb])
                    + [f"Duplicate answers: {duplicates} | unsolicited answers: {unsolicited} | responses: {responses}"],
                    [server_mb], [client_mb], "Modbus TCP", sorted(mb["pcap_names"]),
                    f"modbus::extra-responses::{client_mb}::{server_mb}",
                    tags=["modbus", "replay", "intrusion"],
                )

            server_writers: Dict[str, set[str]] = defaultdict(set)
            for src, dst in mb["write_sources"]:
                server_writers[dst].add(src)
            for dst, writers in server_writers.items():
                if len(writers) > 1:
                    self.add_finding(SEVERITY_HIGH, "Modbus TCP", "Multiple Modbus write sources to one server",
                        f"Multiple source IPs issued Modbus write operations to {dst}.",
                        [f"Writers: {', '.join(sorted(writers))}"], sorted(writers), [dst], "Modbus TCP",
                        sorted(mb["pcap_names"]), f"modbus::multi-writer::{dst}", tags=["write", "multi_writer"])

            # ---- Register value anomaly detection (C) -----------------
            # For each register with ≥ 4 readings, flag sudden large value
            # jumps: ≥ 50% of the observed range in a single polling
            # interval AND an absolute magnitude of ≥ 500 raw units (to
            # avoid noise on low-range sensor registers).  This pattern is
            # consistent with an injected or spoofed Modbus response that
            # substitutes a false process value.
            anomalous_regs: List[Tuple[Any, ...]] = []
            for (reg_src, reg_dst, reg_num), readings in mb["register_values"].items():
                if len(readings) < 4:
                    continue
                values = [v for _, v in readings]
                vmin, vmax = min(values), max(values)
                vrange = vmax - vmin
                if vrange < 100:
                    continue  # narrow-range registers are not anomalous
                deltas = [abs(readings[i + 1][1] - readings[i][1])
                          for i in range(len(readings) - 1)]
                max_delta = max(deltas) if deltas else 0
                if max_delta >= vrange * 0.5 and max_delta >= 500:
                    anomalous_regs.append((reg_src, reg_dst, reg_num, vmin, vmax, max_delta))
                    if len(anomalous_regs) >= 20:
                        break
            if anomalous_regs:
                reg_lines = [
                    f"Register {rn}: {rs}→{rd} | range [{rmn:.0f}–{rmx:.0f}] | max jump {jmp:.0f}"
                    for rs, rd, rn, rmn, rmx, jmp in anomalous_regs[:10]
                ]
                all_srcs = sorted({r[0] for r in anomalous_regs})
                all_dsts = sorted({r[1] for r in anomalous_regs})
                self.add_finding(
                    SEVERITY_MEDIUM, "Modbus TCP",
                    "Modbus register value anomaly detected",
                    "One or more Modbus registers showed a sudden large value jump "
                    "(≥50% of observed range in a single poll interval). Legitimate "
                    "process variables rarely change that abruptly; this may indicate "
                    "a spoofed response, an injected packet, or a rapid unexpected "
                    "set-point change that warrants investigation.",
                    reg_lines,
                    all_srcs, all_dsts, "Modbus TCP", sorted(mb["pcap_names"]),
                    "modbus::value-anomaly",
                    tags=["modbus", "value_anomaly"],
                )
        self._detector_done("Modbus TCP", before)

        # BACnet
        before = len(self.session.findings)
        if not bn["rows_seen"]:
            if self._expected_protocol(["bacnet"]):
                self.add_finding(SEVERITY_MEDIUM, "Absence of Expected Traffic", "Expected BACnet traffic not observed",
                    "BACnet/IP was declared as expected, but no UDP/47808 traffic was observed.",
                    ["No udp.port == 47808 packets matched."], [], [], "BACnet/IP", pcap_name_list, "absence::bacnet")
        else:
            if bn["who_is"] >= 20 and bn["who_is"] > max(bn["i_am"] * 3, 10):
                self.add_finding(SEVERITY_HIGH, "BACnet/IP", "Possible BACnet broadcast storm",
                    "Who-Is broadcast volume greatly exceeded I-Am responses.",
                    [f"Who-Is count: {bn['who_is']} | I-Am count: {bn['i_am']}"],
                    [], [], "BACnet/IP", sorted(bn["pcap_names"]), "bacnet::storm", tags=["recon", "bacnet"])
        self._detector_done("BACnet/IP", before)

        # DNP3
        before = len(self.session.findings)
        if not d3["rows_seen"]:
            if self._expected_protocol(["dnp3"]):
                self.add_finding(SEVERITY_MEDIUM, "Absence of Expected Traffic", "Expected DNP3 traffic not observed",
                    "DNP3 was declared as expected, but no TCP/UDP 20000 traffic was observed.",
                    ["No DNP3 packets matched."], [], [], "DNP3", pcap_name_list, "absence::dnp3")
        else:
            if d3["unsolicited_count"] >= 10:
                self.add_finding(SEVERITY_MEDIUM, "DNP3", "Elevated DNP3 unsolicited responses",
                    f"Observed {d3['unsolicited_count']} unsolicited DNP3 responses.",
                    [f"Unsolicited responses: {d3['unsolicited_count']}"], [], [], "DNP3",
                    sorted(d3["pcap_names"]), "dnp3::unsolicited")
            if not d3["secure_auth_seen"]:
                sev = SEVERITY_CRITICAL if any(t in env_type for t in ("power", "utility", "electrical")) else SEVERITY_HIGH
                self.add_finding(sev, "DNP3", "DNP3 traffic without Secure Authentication evidence",
                    "DNP3 traffic was observed but no evidence of Secure Authentication was seen.",
                    ["No DNP3 Secure Authentication indicators observed."], [], [], "DNP3",
                    sorted(d3["pcap_names"]), "dnp3::no-sa")

            # ---- Suppression-attack signal: Disable Spontaneous Messages
            # Aggregated by (src, dst) so multiple disable commands from
            # the same master become one finding with all instances in
            # evidence — keeps the report readable.
            if d3["disable_spontaneous"]:
                disable_pairs: Dict[Tuple[str, str], List[str]] = defaultdict(list)
                disable_pcaps: Dict[Tuple[str, str], set] = defaultdict(set)
                for pn_d, src_d, dst_d, info_d in d3["disable_spontaneous"]:
                    disable_pairs[(src_d, dst_d)].append(f"{pn_d}: {info_d}")
                    disable_pcaps[(src_d, dst_d)].add(pn_d)
                for (src_d, dst_d), samples in disable_pairs.items():
                    self.add_finding(
                        SEVERITY_HIGH, "DNP3",
                        "DNP3 Disable Spontaneous Messages observed",
                        f"{src_d} instructed {dst_d} to disable spontaneous (unsolicited) DNP3 reporting. "
                        "This silences the outstation's alert traffic — legitimate during commissioning "
                        "or maintenance, but it is also exactly how an attacker hides subsequent "
                        "manipulation by suppressing the device's own change reports. Validate the "
                        "command source against an approved engineering host and confirm a corresponding "
                        "maintenance window is in effect.",
                        samples[:8] + [f"Total disable events: {len(samples)}"],
                        [src_d], [dst_d], "DNP3",
                        sorted(disable_pcaps[(src_d, dst_d)]),
                        f"dnp3::disable-spontaneous::{src_d}::{dst_d}",
                        tags=["dnp3", "suppression", "intrusion"],
                    )

            # ---- Restart functions: cold + warm restart -------------------
            for restart_kind, slot, severity in (
                ("cold restart", d3["cold_restart"], SEVERITY_CRITICAL),
                ("warm restart", d3["warm_restart"], SEVERITY_HIGH),
            ):
                if not slot:
                    continue
                rs_pairs: Dict[Tuple[str, str], List[str]] = defaultdict(list)
                rs_pcaps: Dict[Tuple[str, str], set] = defaultdict(set)
                for pn_d, src_d, dst_d, info_d in slot:
                    rs_pairs[(src_d, dst_d)].append(f"{pn_d}: {info_d}")
                    rs_pcaps[(src_d, dst_d)].add(pn_d)
                for (src_d, dst_d), samples in rs_pairs.items():
                    self.add_finding(
                        severity, "DNP3",
                        f"DNP3 {restart_kind.title()} command observed",
                        f"{src_d} issued a DNP3 {restart_kind} command to {dst_d}. "
                        f"{'Cold restart reboots the entire outstation device' if 'cold' in restart_kind else 'Warm restart reinitializes the DNP3 protocol stack'} — "
                        "rare in normal operation. Attackers use restarts to clear volatile state, "
                        "drop active alarms, kick a device offline during an incident, or disrupt "
                        "process visibility. Confirm a planned maintenance event corresponds to "
                        "this command.",
                        samples[:8] + [f"Total {restart_kind} events: {len(samples)}"],
                        [src_d], [dst_d], "DNP3",
                        sorted(rs_pcaps[(src_d, dst_d)]),
                        f"dnp3::{restart_kind.replace(' ', '-')}::{src_d}::{dst_d}",
                        tags=["dnp3", "restart", "intrusion"],
                    )
        self._detector_done("DNP3", before)

        # IEC 61850
        before = len(self.session.findings)
        if not i61["rows_seen"]:
            if any(t in env_type for t in ("power", "electrical", "substation")) or self._expected_protocol(["iec61850", "iec 61850", "goose", "mms"]):
                self.add_finding(SEVERITY_MEDIUM, "Absence of Expected Traffic", "Expected IEC 61850 traffic not observed",
                    "IEC 61850 / GOOSE / MMS was expected but no matching traffic was observed.",
                    ["No mms/goose/sv packets matched."], [], [], "IEC 61850", pcap_name_list, "absence::iec61850")
        else:
            for src_mac, values in i61["goose_by_mac"].items():
                if len(values) >= 3:
                    jumps = [b - a for a, b in zip(values, values[1:])]
                    if any(j > 5 for j in jumps):
                        self.add_finding(SEVERITY_CRITICAL, "IEC 61850", "GOOSE state-number anomaly",
                            "GOOSE stNum values changed abruptly, which can indicate replay or injection behavior.",
                            [f"Source MAC {src_mac} stNum values: {values[:10]}"],
                            [], [], "IEC 61850 GOOSE", sorted(i61["pcap_names"]),
                            f"iec61850::stnum::{src_mac}", tags=["intrusion", "iec61850"])
        self._detector_done("IEC 61850 / GOOSE / MMS", before)

        # IEC 104
        before = len(self.session.findings)
        if not i104["rows_seen"]:
            if any(t in env_type for t in ("power", "electrical", "utility", "substation", "grid")) or self._expected_protocol(["iec104", "iec 104", "iec60870"]):
                self.add_finding(SEVERITY_MEDIUM, "Absence of Expected Traffic", "Expected IEC 60870-5-104 traffic not observed",
                    "IEC 60870-5-104 was expected but no traffic was observed on TCP/2404.",
                    ["No TCP/2404 packets matched."], [], [], "IEC 60870-5-104", pcap_name_list, "absence::iec104")
        self._detector_done("IEC 60870-5-104", before)

        # MQTT
        before = len(self.session.findings)
        if not mq["rows_seen"]:
            if self._expected_protocol(["mqtt"]):
                self.add_finding(SEVERITY_MEDIUM, "Absence of Expected Traffic", "Expected MQTT traffic not observed",
                    "MQTT was declared as expected, but no MQTT traffic was observed on ports 1883 or 8883.",
                    ["No MQTT packets matched."], [], [], "MQTT", pcap_name_list, "absence::mqtt")
        else:
            for broker_ip, broker in sorted(mq["brokers"].items()):
                clients_mq = sorted(broker["clients"])
                self.add_finding(SEVERITY_HIGH, "MQTT", "Cleartext MQTT observed",
                    f"{len(clients_mq)} client(s) exchanged MQTT with broker {broker_ip} on TCP/1883 without TLS. "
                    "Topics, payloads, and any credentials are readable and modifiable by anyone on the path.",
                    list(broker["samples"]) + [f"Clients ({len(clients_mq)}): {', '.join(clients_mq[:20])}"],
                    clients_mq[:20], [broker_ip], "MQTT", sorted(broker["pcaps"]),
                    f"mqtt::cleartext::{broker_ip}", tags=["cleartext", "mqtt"])
            for (src, client_id), points in mq["reconnect_tracker"].items():
                points = sorted(points)
                intervals = [round(b - a, 2) for a, b in zip(points, points[1:])]
                if sum(1 for i in intervals if i < 5) >= 2:
                    label = f"{src} (client ID '{client_id}')" if client_id else src
                    self.add_finding(SEVERITY_MEDIUM, "MQTT", "Rapid MQTT reconnect behavior observed",
                        f"{label} connected to the broker {len(points)} times, several within five seconds of each other. "
                        "Repeated CONNECTs under one client ID mean the session keeps dropping — or that two clients "
                        "share the ID and keep evicting each other, which is also how a client ID is hijacked.",
                        [f"CONNECT intervals (s): {intervals[:10]}"], [src], [], "MQTT",
                        sorted(mq["pcap_names"]), f"mqtt::reconnect::{src}::{client_id}", tags=["mqtt"])
        self._detector_done("MQTT", before)

        # OPC-UA
        before = len(self.session.findings)
        if not opc["rows_seen"]:
            if self._expected_protocol(["opc", "opcua", "opc-ua"]):
                self.add_finding(SEVERITY_MEDIUM, "Absence of Expected Traffic", "Expected OPC-UA traffic not observed",
                    "OPC-UA was declared as expected, but no TCP/4840 traffic was observed.",
                    ["No OPC-UA packets matched."], [], [], "OPC-UA", pcap_name_list, "absence::opcua")
        else:
            for (client_ou, server_ou), channel in sorted(opc_sessions.items()):
                if channel["policy_none"] or channel["mode"] == "None":
                    self.add_finding(SEVERITY_HIGH, "OPC-UA", "OPC-UA SecureChannel with SecurityPolicy None",
                        f"{client_ou} opened an OPC UA SecureChannel to {server_ou} with SecurityPolicy None — messages "
                        "are neither signed nor encrypted, so reads, writes, and method calls can be read and altered in "
                        "transit. Disable the None policy on the server endpoint (IEC 62541-2).",
                        [channel["sample"] or "See pcap evidence"], [client_ou], [server_ou], "OPC-UA",
                        sorted(channel["pcaps"]), f"opcua::policy-none::{server_ou}", tags=["cleartext", "opcua"])
                elif channel["mode"] == "Sign":
                    self.add_finding(SEVERITY_MEDIUM, "OPC-UA", "OPC-UA SecureChannel signed but not encrypted",
                        f"The OPC UA SecureChannel from {client_ou} to {server_ou} uses MessageSecurityMode Sign: messages "
                        "are protected against modification but readable by anyone on the path. Use SignAndEncrypt "
                        "where process data or credentials are sensitive.",
                        [channel["sample"] or "See pcap evidence"], [client_ou], [server_ou], "OPC-UA",
                        sorted(channel["pcaps"]), f"opcua::sign-only::{server_ou}", tags=["opcua"])
            for src, count in opc["browse_counts"].items():
                if count >= 50:
                    self.add_finding(SEVERITY_MEDIUM, "OPC-UA", "Possible OPC-UA reconnaissance activity",
                        f"{src} issued {count} Browse requests — an enumeration of the server's address space. "
                        "SCADA clients browse at startup; from any other host this maps every tag the server exposes.",
                        [f"Browse requests: {count} | Read requests: {opc['read_counts'][src]}"],
                        [src], [], "OPC-UA", sorted(opc["pcap_names"]),
                        f"opcua::recon::{src}", tags=["discovery", "opcua"])
        self._detector_done("OPC-UA", before)

        # EtherNet/IP
        before = len(self.session.findings)
        if not enip["rows_seen"]:
            if self._expected_protocol(["ethernet/ip", "cip", "enip"]):
                self.add_finding(SEVERITY_MEDIUM, "Absence of Expected Traffic", "Expected EtherNet/IP traffic not observed",
                    "EtherNet/IP / CIP was declared as expected, but no TCP/44818 or UDP/2222 traffic was observed.",
                    ["No EtherNet/IP packets matched."], [], [], "EtherNet/IP", pcap_name_list, "absence::enip")
        self._detector_done("EtherNet/IP and CIP", before)

        # Siemens
        before = len(self.session.findings)
        if not sie["rows_seen"]:
            if self._expected_protocol(["siemens", "profinet", "s7"]):
                self.add_finding(SEVERITY_MEDIUM, "Absence of Expected Traffic", "Expected Siemens traffic not observed",
                    "Siemens / PROFINET was declared as expected, but no relevant traffic was observed.",
                    ["No S7/PROFINET packets matched."], [], [], "Siemens S7 / PROFINET", pcap_name_list, "absence::siemens")
        self._detector_done("Siemens S7comm and PROFINET", before)

        # Physical Security
        before = len(self.session.findings)
        if not phys["rows_seen"]:
            if any(t in env_type for t in ("physical", "camera")) or self._expected_protocol(["physical", "rtsp", "osdp", "onvif", "camera"]):
                self.add_finding(SEVERITY_MEDIUM, "Absence of Expected Traffic", "Expected physical security traffic not observed",
                    "Physical security protocols (RTSP/OSDP) were expected but no matching traffic was observed.",
                    ["No physical security protocol packets matched."], [], [], "Physical Security", pcap_name_list, "absence::physical-security")
        else:
            open_streams = {pair: st for pair, st in phys["rtsp_pairs"].items() if st["streamed"] and not st["challenged"]}
            for camera in sorted({server_c for _, server_c in open_streams}):
                camera_streams = {pair: st for pair, st in open_streams.items() if pair[1] == camera}
                viewers = sorted({client_c for client_c, _ in camera_streams})
                camera_pcaps: set = set()
                for st in camera_streams.values():
                    camera_pcaps.update(st["pcaps"])
                self.add_finding(SEVERITY_MEDIUM, "Physical Security", "RTSP stream without authentication challenge",
                    f"{camera} served RTSP stream requests (DESCRIBE/SETUP/PLAY) from {', '.join(viewers[:10])} without "
                    "ever answering 401 Unauthorized. Either the camera streams without authentication or the client "
                    "sent credentials up front; confirm on the camera that anonymous RTSP access is disabled.",
                    [st["sample"] for st in camera_streams.values() if st["sample"]][:10],
                    viewers[:20], [camera], "RTSP", sorted(camera_pcaps),
                    f"rtsp::noauth::{camera}", tags=["noauth", "camera"])
        self._detector_done("Physical Security Protocols", before)

        # Omron FINS
        before = len(self.session.findings)
        if fins["rows_seen"]:
            self.add_finding(
                SEVERITY_HIGH, "Omron FINS",
                "Omron FINS traffic observed (unauthenticated, cleartext)",
                "Omron FINS (TCP/UDP 9600) was observed in the capture. FINS carries no native "
                "authentication or encryption — any device on the OT network can send arbitrary "
                "read/write/control commands to the PLC without credentials.",
                fins["samples"] or ["See pcap evidence"],
                [], [], "Omron FINS", sorted(fins["pcap_names"]),
                "fins::cleartext", tags=["cleartext", "fins"],
            )
        elif self._expected_protocol(["omron", "fins"]):
            self.add_finding(SEVERITY_MEDIUM, "Absence of Expected Traffic", "Expected Omron FINS traffic not observed",
                "Omron FINS (TCP/UDP 9600) was declared as expected, but no traffic was observed on that port.",
                ["No TCP/UDP 9600 packets matched."], [], [], "Omron FINS", pcap_name_list, "absence::fins")
        self._detector_done("Omron FINS", before)

        # Triconex TriStation (safety instrumented systems)
        before = len(self.session.findings)
        declared_hosts = {item.strip().lower() for item in
                          re.split(r"[,;\s]+", self.session.environment_answers.get("known_hmis", "")) if item.strip()}
        for (eng_host, controller), info in sorted(tristation.items(), key=lambda item: -item[1]["packets"]):
            first, last = info["first"] or 0.0, info["last"] or 0.0
            declared = eng_host.lower() in declared_hosts
            # An undeclared host talking to a safety controller is CRITICAL until
            # the site confirms it; a declared engineering workstation is HIGH.
            self.add_finding(
                SEVERITY_HIGH if declared else SEVERITY_CRITICAL, "Safety Instrumented Systems",
                "Triconex TriStation safety-controller traffic observed",
                f"{eng_host} exchanged {info['packets']:,} TriStation packets with safety controller {controller} "
                f"on UDP 1502 over {human_duration(last - first)}, from {format_epoch(first)} to {format_epoch(last)}. "
                "TriStation is the engineering protocol of Schneider Electric Triconex safety instrumented systems — "
                "it can read and change the safety logic. "
                + ("The source is listed as a known engineering workstation; confirm the session was a planned SIS change."
                   if declared else "The source is not listed as a known engineering workstation, so this is "
                   "reported as CRITICAL until the site confirms the session."),
                [f"Safety controller: {controller} — TriStation (UDP 1502)",
                 f"Engineering host: {eng_host}" + (" (declared engineering workstation)" if declared else ""),
                 f"{info['packets']:,} packets ({info['to_controller']:,} sent to the controller) in "
                 f"{', '.join(sorted(info['pcaps']))}",
                 f"Session window: {format_epoch(first)} – {format_epoch(last)} ({human_duration(last - first)}) — "
                 f"Wireshark: udp.port == 1502 && frame.time_epoch >= {first:.6f} && frame.time_epoch <= {last:.6f}"],
                [eng_host], [controller], "Triconex TriStation", sorted(info["pcaps"]),
                f"tristation::{eng_host}::{controller}", tags=["sis", "tristation"],
                first_seen=f"{first:.6f}", last_seen=f"{last:.6f}",
            )
        if not tristation and self._expected_protocol(["tristation", "triconex"]):
            self.add_finding(SEVERITY_MEDIUM, "Absence of Expected Traffic", "Expected Triconex TriStation traffic not observed",
                "Triconex TriStation (UDP 1502) was declared as expected, but no traffic was observed on that port.",
                ["No UDP 1502 packets matched."], [], [], "Triconex TriStation", pcap_name_list, "absence::tristation")
        self._detector_done("Triconex TriStation", before)

        # GE SRTP
        before = len(self.session.findings)
        if gertp["rows_seen"]:
            self.add_finding(
                SEVERITY_HIGH, "GE SRTP",
                "GE SRTP traffic observed (unauthenticated, cleartext)",
                "GE SRTP (TCP 18245) was observed in the capture. GE Service Request Transport Protocol "
                "has no native authentication or encryption. This port services GE PACSystems (RX3i / 90-30) "
                "PLCs; any host on the network can issue read/write/control requests.",
                gertp["samples"] or ["See pcap evidence"],
                [], [], "GE SRTP", sorted(gertp["pcap_names"]),
                "gertp::cleartext", tags=["cleartext", "ge_srtp"],
            )
        elif self._expected_protocol(["srtp", "ge srtp", "ge"]):
            self.add_finding(SEVERITY_MEDIUM, "Absence of Expected Traffic", "Expected GE SRTP traffic not observed",
                "GE SRTP (TCP 18245) was declared as expected, but no traffic was observed on that port.",
                ["No TCP 18245 packets matched."], [], [], "GE SRTP", pcap_name_list, "absence::srtp")
        self._detector_done("GE SRTP", before)

        # Schneider UMAS (Modbus function code 90)
        before = len(self.session.findings)
        if umas["rows_seen"]:
            umas_pairs = sorted(umas["pairs"])
            self.add_finding(
                SEVERITY_HIGH, "Schneider UMAS",
                "Schneider UMAS engineering traffic observed (Modbus function code 90)",
                "Modbus function code 90 carries UMAS, Schneider Electric's engineering protocol for Modicon "
                "M340/M580/Premium/Quantum PLCs: program upload and download, start/stop, and memory access. Unless "
                "the PLC enforces an application password, any host that reaches TCP/502 can issue these commands; "
                "confirm the client is the authorized engineering workstation.",
                list(umas["samples"]) + ["Client -> PLC: " + ", ".join(f"{c} -> {s}" for c, s in umas_pairs[:10])],
                sorted({c for c, _ in umas_pairs})[:20], sorted({s for _, s in umas_pairs})[:20],
                "Schneider UMAS", sorted(umas["pcap_names"]),
                "umas::engineering", tags=["schneider", "umas", "engineering"],
            )
        elif self._expected_protocol(["umas"]):
            self.add_finding(SEVERITY_MEDIUM, "Absence of Expected Traffic", "Expected Schneider UMAS traffic not observed",
                "Schneider UMAS was declared as expected, but no Modbus function code 90 traffic was observed. UMAS "
                "only appears while an engineering session is open, so absence is normal outside maintenance work.",
                ["No Modbus function code 90 packets matched."], [], [], "Schneider UMAS", pcap_name_list, "absence::umas")
        self._detector_done("Schneider UMAS", before)

        # Mitsubishi MELSEC
        before = len(self.session.findings)
        if melsec["rows_seen"]:
            self.add_finding(
                SEVERITY_HIGH, "Mitsubishi MELSEC",
                "Mitsubishi MELSEC SLMP traffic observed (unauthenticated, cleartext)",
                "Mitsubishi MELSEC SLMP (TCP 5007) was observed in the capture. The Seamless Message Protocol "
                "carries no authentication or encryption. Any host on the network can issue read/write/remote-run "
                "commands to Mitsubishi Q-series and iQ-R PLCs.",
                melsec["samples"] or ["See pcap evidence"],
                [], [], "Mitsubishi MELSEC", sorted(melsec["pcap_names"]),
                "melsec::cleartext", tags=["cleartext", "melsec", "mitsubishi"],
            )
        elif self._expected_protocol(["melsec", "mitsubishi", "slmp"]):
            self.add_finding(SEVERITY_MEDIUM, "Absence of Expected Traffic", "Expected Mitsubishi MELSEC traffic not observed",
                "Mitsubishi MELSEC SLMP (TCP 5007) was declared as expected, but no traffic was observed on that port.",
                ["No TCP 5007 packets matched."], [], [], "Mitsubishi MELSEC", pcap_name_list, "absence::melsec")
        self._detector_done("Mitsubishi MELSEC", before)

        # OSIsoft PI Server
        before = len(self.session.findings)
        if pi_srv["rows_seen"]:
            self.add_finding(
                SEVERITY_LOW, "OSIsoft PI Server",
                "AVEVA PI (OSIsoft) historian traffic observed",
                "Traffic to a PI Data Archive (TCP 5450) or PI AF server (TCP 5457) was observed. The historian holds "
                "the plant's process record and often bridges the control and business networks. Confirm which "
                "clients may reach it, that PI trusts and explicit logins are disabled in favor of Windows "
                "authentication, and that the historian sits in a DMZ rather than on the control network.",
                pi_srv["samples"] or ["See pcap evidence"],
                [], [], "OSIsoft PI", sorted(pi_srv["pcap_names"]),
                "pi_srv::presence", tags=["pi_server", "historian"],
            )
        elif self._expected_protocol(["historian", "osisoft", "pi server"]):
            self.add_finding(SEVERITY_MEDIUM, "Absence of Expected Traffic", "Expected OSIsoft PI historian traffic not observed",
                "A PI historian was declared as expected, but no traffic was observed on TCP 5450 or 5457.",
                ["No TCP 5450/5457 packets matched."], [], [], "OSIsoft PI", pcap_name_list, "absence::pi_srv")
        self._detector_done("OSIsoft PI Server", before)

        # Ignition Gateway
        before = len(self.session.findings)
        if ignition["rows_seen"]:
            self.add_finding(
                SEVERITY_LOW, "Ignition Gateway",
                "Ignition gateway traffic observed",
                "Traffic to an Inductive Automation Ignition gateway was observed on its OPC UA server port (TCP 62541) "
                "or gateway-network port (TCP 8060). The gateway holds tag write access and the site's project; confirm "
                "its OPC UA endpoint does not offer SecurityPolicy None, that gateway-network connections require "
                "approval and TLS, and that only expected hosts connect.",
                ignition["samples"] or ["See pcap evidence"],
                [], [], "Ignition Gateway", sorted(ignition["pcap_names"]),
                "ignition::presence", tags=["ignition"],
            )
        elif self._expected_protocol(["ignition"]):
            self.add_finding(SEVERITY_MEDIUM, "Absence of Expected Traffic", "Expected Ignition Gateway traffic not observed",
                "Ignition was declared as expected, but no traffic was observed on TCP 62541 or 8060.",
                ["No TCP 62541/8060 packets matched."], [], [], "Ignition Gateway", pcap_name_list, "absence::ignition")
        self._detector_done("Ignition Gateway", before)

        # Node-RED
        before = len(self.session.findings)
        if nodered["rows_seen"]:
            self.add_finding(
                SEVERITY_MEDIUM, "Node-RED",
                "Node-RED interface traffic observed on TCP 1880",
                "Traffic on TCP 1880 (Node-RED default port) was observed without TLS. The Node-RED editor can deploy "
                "flows that read from and write to connected OT devices, so its exposure and credentials matter.",
                nodered["samples"] or ["See pcap evidence"],
                [], [], "Node-RED", sorted(nodered["pcap_names"]),
                "nodered::presence", tags=["cleartext", "nodered"],
            )
            open_editors = {pair: st for pair, st in nodered["pairs"].items()
                            if st["requests"] and not st["authorized"] and not st["denied"]}
            for editor in sorted({server_n for _, server_n in open_editors}):
                editor_pairs = {pair: st for pair, st in open_editors.items() if pair[1] == editor}
                users = sorted({client_n for client_n, _ in editor_pairs})
                editor_pcaps: set = set()
                for st in editor_pairs.values():
                    editor_pcaps.update(st["pcaps"])
                self.add_finding(
                    SEVERITY_HIGH, "Node-RED",
                    "Node-RED editor exposed without authentication",
                    f"Admin API requests to Node-RED on {editor} (flows, nodes, or settings) from {', '.join(users[:10])} "
                    "carried no Authorization header and were never answered with 401. The editor appears to run without "
                    "adminAuth, so anyone who reaches TCP/1880 can deploy flows that command connected OT devices.",
                    [st["sample"] for st in editor_pairs.values() if st["sample"]][:10],
                    users[:20], [editor], "Node-RED", sorted(editor_pcaps),
                    f"nodered::noauth::{editor}", tags=["noauth", "nodered"],
                )
        elif self._expected_protocol(["nodered", "node-red"]):
            self.add_finding(SEVERITY_MEDIUM, "Absence of Expected Traffic", "Expected Node-RED traffic not observed",
                "Node-RED (TCP 1880) was declared as expected, but no traffic was observed on that port.",
                ["No TCP 1880 packets matched."], [], [], "Node-RED", pcap_name_list, "absence::nodered")
        self._detector_done("Node-RED", before)

        # Audio/Video streaming
        before = len(self.session.findings)

        def _av_flow_line(flow_key: Tuple[str, str, int], fl: Dict[str, Any]) -> str:
            f_src, f_dst, f_dport = flow_key
            dur = ""
            if fl["first"] is not None and fl["last"] is not None and fl["last"] > fl["first"]:
                dur = f" | duration {fl['last'] - fl['first']:.0f}s"
            ts_tag = f" @{fl['first']}" if fl["first"] is not None else ""
            return f"{f_src} -> {f_dst}:{f_dport} | {fl['pkts']:,} pkts | {human_size(fl['bytes'])}{dur}{ts_tag}"

        def _emit_av_flow_group(flows: Dict[Tuple[str, str, int], Dict[str, Any]],
                                severity: str, title: str, desc: str,
                                dedup: str, tags: List[str]) -> None:
            if not flows:
                return
            f_srcs = sorted({k[0] for k in flows})
            f_dsts = sorted({k[1] for k in flows})
            f_pcaps: set = set()
            for fl in flows.values():
                f_pcaps.update(fl["pcaps"])
            evidence = [_av_flow_line(k, fl) for k, fl in
                        sorted(flows.items(), key=lambda item: -item[1]["bytes"])[:10]]
            if len(flows) > 10:
                evidence.append(f"... and {len(flows) - 10} more stream(s); see JSON export for the full list.")
            self.add_finding(severity, "Audio/Video Streaming", title, desc, evidence,
                             f_srcs[:20], f_dsts[:20], "RTP/UDP", sorted(f_pcaps), dedup,
                             tags=["av_media"] + tags)

        # Classify signaled RTP flows by payload type; dynamic PTs (>=96,
        # H.264/H.265/Opus/...) are split by observed bitrate instead.
        rtp_video: Dict[Tuple[str, str, int], Dict[str, Any]] = {}
        rtp_audio: Dict[Tuple[str, str, int], Dict[str, Any]] = {}
        rtp_media: Dict[Tuple[str, str, int], Dict[str, Any]] = {}
        for flow_key, fl in av["rtp_flows"].items():
            if fl["pkts"] < 20:
                continue  # ignore sub-second fragments
            ptypes = fl["ptypes"]
            if any(24 <= pt <= 34 for pt in ptypes):
                rtp_video[flow_key] = fl
            elif any(pt <= 23 for pt in ptypes):
                rtp_audio[flow_key] = fl
            else:
                duration = (fl["last"] - fl["first"]) if (fl["first"] is not None and fl["last"] is not None) else 0
                rate = (fl["bytes"] / duration) if duration >= 2 else None
                if rate is not None and rate > 100_000:
                    rtp_video[flow_key] = fl
                elif rate is not None and rate < 30_000:
                    rtp_audio[flow_key] = fl
                else:
                    rtp_media[flow_key] = fl
        _emit_av_flow_group(
            rtp_video, SEVERITY_MEDIUM, "Video streaming (RTP) observed on the network",
            "RTP video streams were observed. Video traffic on an OT network usually means IP cameras, "
            "video walls, or operator screen-sharing. Each stream is an unmanaged high-bandwidth flow that "
            "can congest switches shared with control traffic, and camera platforms are a common foothold "
            "for attackers because they are rarely patched.",
            "avmedia::rtp-video", ["video"])
        _emit_av_flow_group(
            rtp_audio, SEVERITY_LOW, "Audio/voice streaming (RTP) observed on the network",
            "RTP audio streams were observed (VoIP telephony, intercom, or paging audio). Voice traffic on "
            "an OT network indicates converged IT/OT infrastructure — the phone system shares switching "
            "with control traffic, which widens the attack surface and can violate segmentation policy.",
            "avmedia::rtp-audio", ["audio"])
        _emit_av_flow_group(
            rtp_media, SEVERITY_LOW, "Media streaming (RTP, unclassified codec) observed",
            "RTP streams with dynamic payload types were observed but could not be classified as audio or "
            "video from bitrate alone. Review the endpoints to determine what is streaming.",
            "avmedia::rtp-media", ["media"])
        if av["sip_calls"]:
            sip_ev = [f"{c_pn}: {c_src} -> {c_dst} | {c_info}" + (f" @{c_ts}" if c_ts else "")
                      for c_pn, c_src, c_dst, c_info, c_ts in av["sip_calls"][:10]]
            self.add_finding(
                SEVERITY_LOW, "Audio/Video Streaming", "VoIP call signaling (SIP) observed",
                "SIP call-setup signaling (INVITE / 200 OK with SDP) was observed. A VoIP telephone or "
                "intercom system is active on this network segment. Confirm the phone system is intended "
                "to share this segment with OT traffic.",
                sip_ev, sorted(av["sip_sources"])[:20], [], "SIP",
                sorted(av["pcap_names"]), "avmedia::sip-call", tags=["av_media", "voip"])
        if av["rtsp_play"]:
            rtsp_ev = [f"{c_pn}: {c_src} -> {c_dst} | {c_info}" + (f" @{c_ts}" if c_ts else "")
                       for c_pn, c_src, c_dst, c_info, c_ts in av["rtsp_play"][:10]]
            self.add_finding(
                SEVERITY_MEDIUM, "Audio/Video Streaming", "Active video stream requested via RTSP",
                "RTSP SETUP/PLAY requests were observed — a client actively started a camera or media "
                "stream during the capture (not just discovery traffic). Verify the requesting host is an "
                "authorized video client (VMS/NVR), not a workstation or unknown device pulling video.",
                rtsp_ev, sorted(av["rtsp_sources"])[:20], [], "RTSP",
                sorted(av["pcap_names"]), "avmedia::rtsp-play", tags=["av_media", "video"])
        if av["mp2t_pairs"]:
            mp2t_ev = []
            any_mcast = False
            mp2t_pcaps: set = set()
            for (p_src, p_dst), pr in sorted(av["mp2t_pairs"].items(), key=lambda item: -item[1]["bytes"])[:10]:
                mp2t_ev.append(f"{p_src} -> {p_dst} | {pr['pkts']:,} pkts | {human_size(pr['bytes'])}"
                               + (" | multicast" if pr["mcast"] else ""))
                any_mcast = any_mcast or pr["mcast"]
            for pr in av["mp2t_pairs"].values():
                mp2t_pcaps.update(pr["pcaps"])
            self.add_finding(
                SEVERITY_MEDIUM, "Audio/Video Streaming", "MPEG Transport Stream video distribution observed",
                "MPEG-TS packets were observed — broadcast-style video distribution (IPTV, digital signage, "
                "or camera multicast). " + ("At least one stream is multicast, which floods every switch port "
                "in the VLAN unless IGMP snooping is configured — a real bandwidth risk on OT segments." if any_mcast
                else "Confirm the source and consumers of this video feed are intended."),
                mp2t_ev,
                sorted({k[0] for k in av["mp2t_pairs"]})[:20],
                sorted({k[1] for k in av["mp2t_pairs"]})[:20],
                "MPEG-TS", sorted(mp2t_pcaps), "avmedia::mp2t", tags=["av_media", "video"])
        rtmp_active = {k: v for k, v in av["rtmp_pairs"].items() if v["pkts"] >= 20}
        if rtmp_active:
            rtmp_pcaps: set = set()
            for pr in rtmp_active.values():
                rtmp_pcaps.update(pr["pcaps"])
            self.add_finding(
                SEVERITY_MEDIUM, "Audio/Video Streaming", "RTMP video streaming observed",
                "RTMP (TCP 1935) streaming traffic was observed. RTMP is used by some DVR/NVR platforms and "
                "media servers to push live video. Identify the publisher and confirm video is not being "
                "pushed to an unexpected destination.",
                [pr["sample"] for pr in list(rtmp_active.values())[:10]],
                sorted({k[0] for k in rtmp_active})[:20],
                sorted({k[1] for k in rtmp_active})[:20],
                "RTMP", sorted(rtmp_pcaps), "avmedia::rtmp", tags=["av_media", "video"])
        mcast_sustained = {k: v for k, v in av["mcast_flows"].items() if v["pkts"] >= 200}
        if mcast_sustained:
            _emit_av_flow_group(
                mcast_sustained, SEVERITY_MEDIUM,
                "Sustained multicast UDP stream (possible video/audio distribution)",
                "A sustained multicast UDP stream was observed that does not match any known service "
                "protocol. On OT networks this pattern is most often video distribution or an audio paging "
                "feed. Multicast floods every port in the VLAN unless IGMP snooping is configured; identify "
                "the source device and confirm the stream is intended.",
                "avmedia::multicast", ["multicast"])
        raw_sustained = {k: v for k, v in av["raw_flows"].items() if v["pkts"] >= 200}
        if raw_sustained:
            _emit_av_flow_group(
                raw_sustained, SEVERITY_LOW,
                "Unclassified sustained UDP stream with media-like characteristics",
                "A sustained high-port UDP flow with steady media-sized packets was observed. tshark could "
                "not confirm the codec (no signaling was captured), but the traffic shape matches real-time "
                "audio/video (unsignaled RTP, proprietary camera streams). Review the endpoints — this can "
                "also indicate tunneled or covert-channel traffic.",
                "avmedia::raw-udp-media", ["media", "unclassified"])
        gige_active = {k: v for k, v in av["gige_pairs"].items() if v["pkts"] >= 5}
        if gige_active:
            gige_pcaps: set = set()
            for pr in gige_active.values():
                gige_pcaps.update(pr["pcaps"])
            self.add_finding(
                SEVERITY_INFO, "Audio/Video Streaming", "GigE Vision machine-vision camera traffic observed",
                "GigE Vision control traffic (GVCP, UDP 3956) was observed. Machine-vision cameras are "
                "normal in automated inspection lines; this is recorded for inventory purposes. The video "
                "stream itself (GVSP) runs on dynamic UDP ports and may appear as an unclassified stream.",
                [pr["sample"] for pr in list(gige_active.values())[:10]],
                sorted({k[0] for k in gige_active})[:20],
                sorted({k[1] for k in gige_active})[:20],
                "GigE Vision", sorted(gige_pcaps), "avmedia::gige-vision", tags=["av_media", "machine_vision"])
        dvr_active = {k: v for k, v in av["vendor_dvr_pairs"].items() if v["pkts"] >= 100}
        if dvr_active:
            dvr_pcaps: set = set()
            for pr in dvr_active.values():
                dvr_pcaps.update(pr["pcaps"])
            dvr_ports = sorted({pr["port"] for pr in dvr_active.values()})
            self.add_finding(
                SEVERITY_MEDIUM, "Audio/Video Streaming", "CCTV DVR/NVR vendor-port traffic observed",
                f"Sustained traffic was observed on CCTV vendor port(s) {', '.join(str(p) for p in dvr_ports)} "
                "(TCP 8000 = Hikvision private protocol, TCP 37777 = Dahua private protocol). This indicates "
                "a camera recorder platform on the segment. These platforms have a long history of critical "
                "vulnerabilities and default credentials — confirm firmware currency and network placement.",
                [f"{pr['sample']} | {pr['pkts']:,} pkts | {human_size(pr['bytes'])}" for pr in list(dvr_active.values())[:10]],
                sorted({k[0] for k in dvr_active})[:20],
                sorted({k[1] for k in dvr_active})[:20],
                "CCTV DVR", sorted(dvr_pcaps), "avmedia::vendor-dvr", tags=["av_media", "video", "cctv"])
        if not av["pcap_names"] and self._expected_protocol(["voip", "video", "audio", "camera", "cctv", "sip", "rtsp"]):
            self.add_finding(SEVERITY_MEDIUM, "Absence of Expected Traffic", "Expected audio/video traffic not observed",
                "Audio/video streaming was declared as expected, but no SIP, RTP, RTSP, MPEG-TS, RTMP, or "
                "media-like UDP streams were observed in the capture.",
                ["No A/V signaling or streaming rows matched."], [], [], "A/V Streaming", pcap_name_list, "absence::av_media")
        self._detector_done("Audio/Video streaming", before)

        # Zigbee
        before = len(self.session.findings)
        if zigbee["rows_seen"]:
            sev = SEVERITY_HIGH
            desc = (
                "Zigbee (IEEE 802.15.4) wireless traffic was observed in the capture. "
                "Zigbee is a low-power wireless mesh protocol common in building automation, "
                "smart meters, and industrial wireless sensor networks. Its presence on an OT "
                "network expands the attack surface beyond wired infrastructure — any device "
                "within RF range with a Zigbee radio can observe or inject traffic."
            )
            samples = zigbee["samples"] or ["See pcap evidence"]
            self.add_finding(
                sev, "Zigbee / IEEE 802.15.4",
                "Zigbee wireless traffic observed",
                desc, samples, [], [], "Zigbee", sorted(zigbee["pcap_names"]),
                "zigbee::presence", tags=["wireless", "zigbee"],
            )
            if zigbee["unencrypted_samples"]:
                self.add_finding(
                    SEVERITY_HIGH, "Zigbee / IEEE 802.15.4",
                    "Unencrypted Zigbee frames observed",
                    "Zigbee frames without a network-layer security header were observed. "
                    "Unencrypted Zigbee traffic can be captured and replayed by any nearby device "
                    "with a compatible radio. Network-layer encryption should be enabled on all "
                    "Zigbee coordinators and end devices.",
                    zigbee["unencrypted_samples"], [], [], "Zigbee", sorted(zigbee["pcap_names"]),
                    "zigbee::unencrypted", tags=["cleartext", "wireless", "zigbee"],
                )
            if zigbee["write_samples"]:
                self.add_finding(
                    SEVERITY_HIGH, "Zigbee / IEEE 802.15.4",
                    "Zigbee control or write commands observed",
                    "Zigbee ZCL write or control-class commands were observed. These commands can "
                    "actuate physical devices (lights, locks, thermostats, valves). Confirm the "
                    "initiating device is authorized and expected.",
                    zigbee["write_samples"], [], [], "Zigbee", sorted(zigbee["pcap_names"]),
                    "zigbee::write", tags=["write", "wireless", "zigbee"],
                )
        elif self._expected_protocol(["zigbee", "zbee", "ieee 802.15.4"]):
            self.add_finding(SEVERITY_MEDIUM, "Absence of Expected Traffic", "Expected Zigbee traffic not observed",
                "Zigbee / IEEE 802.15.4 was declared as expected, but no matching frames were observed.",
                ["No zbee_nwk / zbee_aps / wpan packets matched."], [], [], "Zigbee", pcap_name_list, "absence::zigbee")
        self._detector_done("Zigbee", before)

        # CoAP
        before = len(self.session.findings)
        if coap_acc["rows_seen"]:
            self.add_finding(
                SEVERITY_MEDIUM, "CoAP",
                "CoAP (Constrained Application Protocol) traffic observed",
                "CoAP traffic was observed. CoAP is a lightweight REST-like protocol used by "
                "constrained IoT/ICS devices (sensors, actuators, smart meters). Verify that "
                "devices are using DTLS-protected CoAP (UDP/5684) rather than cleartext CoAP "
                "(UDP/5683), and that write operations originate from authorized controllers.",
                coap_acc["samples"] or ["See pcap evidence"],
                [], [], "CoAP", sorted(coap_acc["pcap_names"]),
                "coap::presence", tags=["coap"],
            )
            if coap_acc["unencrypted_samples"]:
                self.add_finding(
                    SEVERITY_HIGH, "CoAP",
                    "Cleartext CoAP traffic observed (UDP/5683)",
                    "CoAP traffic was observed on UDP/5683, the unencrypted port. Sensitive device "
                    "state and control commands are visible to any observer on the network. Migrate "
                    "to DTLS-protected CoAP on UDP/5684.",
                    coap_acc["unencrypted_samples"], [], [], "CoAP", sorted(coap_acc["pcap_names"]),
                    "coap::cleartext", tags=["cleartext", "coap"],
                )
            if coap_acc["write_samples"]:
                self.add_finding(
                    SEVERITY_MEDIUM, "CoAP",
                    "CoAP write or control operations observed",
                    "CoAP PUT, POST, or DELETE requests were observed. These can modify device state "
                    "or configuration. Confirm the requesting device is authorized.",
                    coap_acc["write_samples"], [], [], "CoAP", sorted(coap_acc["pcap_names"]),
                    "coap::write", tags=["write", "coap"],
                )
        elif self._expected_protocol(["coap"]):
            self.add_finding(SEVERITY_MEDIUM, "Absence of Expected Traffic", "Expected CoAP traffic not observed",
                "CoAP (UDP 5683/5684) was declared as expected, but no matching traffic was observed.",
                ["No CoAP packets matched."], [], [], "CoAP", pcap_name_list, "absence::coap")
        self._detector_done("CoAP", before)

        # Z-Wave — dedicated pass (cannot share the combined filter with wpan/zbee_nwk
        # because the zwave tshark dissector conflicts with the wpan dissector and
        # causes Zigbee frames to be silently dropped from the combined output).
        # The zwave dissector is not included in all tshark builds; if it is
        # unavailable, TSharkError is caught and Z-Wave detection is skipped
        # gracefully rather than crashing the analysis run.
        _zwave_dissector_available = True
        before = len(self.session.findings)
        for pcap in pcaps:
            pn = pcap.name
            try:
                for row in iter_tshark_rows("zwave", ["frame.protocols", "frame.len"], pcap):
                    fp = row.get("frame.protocols", "").lower()
                    if "zwave" in fp:
                        zwave["rows_seen"] = True
                        zwave["pcap_names"].add(pn)
                        ev = f"{pn} | zwave frame len={row.get('frame.len', '?')}"
                        if len(zwave["samples"]) < 5:
                            zwave["samples"].append(ev)
            except TSharkError:
                _zwave_dissector_available = False
                break  # no point trying remaining pcaps
        if not _zwave_dissector_available:
            self._detector_skipped("Z-Wave", "the Z-Wave dissector is not in this tshark build")
        elif zwave["rows_seen"]:
            self.add_finding(
                SEVERITY_MEDIUM, "Z-Wave",
                "Z-Wave wireless traffic observed",
                "Z-Wave wireless protocol traffic was observed. Z-Wave is commonly used in building "
                "automation and physical security systems (door locks, sensors, lighting). Its presence "
                "indicates wireless-accessible control devices on or near the OT network. Verify that "
                "all Z-Wave controllers use S2 security and that network inclusion is properly managed.",
                zwave["samples"] or ["See pcap evidence"],
                [], [], "Z-Wave", sorted(zwave["pcap_names"]),
                "zwave::presence", tags=["wireless", "zwave"],
            )
        elif _zwave_dissector_available and self._expected_protocol(["zwave", "z-wave"]):
            self.add_finding(SEVERITY_MEDIUM, "Absence of Expected Traffic", "Expected Z-Wave traffic not observed",
                "Z-Wave was declared as expected, but no matching frames were observed.",
                ["No Z-Wave packets matched."], [], [], "Z-Wave", pcap_name_list, "absence::zwave")
        self._detector_done("Z-Wave", before)

        # Store hygiene TCP state for check_network_hygiene to consume
        self._hygiene_tcp_state: Dict[str, Any] = hyg

        # ---- Beaconing finalization ----------------------------------
        # Classic beacon signature: stdev/mean of inter-arrival times < 0.15
        # over >= 10 intervals to the same (src, dst, dport) triple.  We
        # boost severity if the destination is external/public.
        before = len(self.session.findings)
        for (bsrc, bdst, bport), stamps in bcn["timestamps"].items():
            if len(stamps) < 11:
                continue
            stamps.sort()
            intervals = [b - a for a, b in zip(stamps, stamps[1:]) if b > a]
            if len(intervals) < 10:
                continue
            mean_iv = sum(intervals) / len(intervals)
            if mean_iv < 5 or mean_iv > 86400:  # <5s = UI refresh / polling; >1d = noise
                continue
            # Standard deviation
            variance = sum((x - mean_iv) ** 2 for x in intervals) / len(intervals)
            stdev = variance ** 0.5
            jitter_ratio = stdev / mean_iv if mean_iv else 1.0
            if jitter_ratio > 0.15:
                continue
            # We have a beacon. Internal periodic traffic is usually an agent or
            # health check; a public destination is the C2 case.
            dst_public = is_public_ip(bdst)
            severity = SEVERITY_HIGH if dst_public else SEVERITY_MEDIUM
            self.add_finding(
                severity, "Intrusion Indicators",
                "Beaconing pattern observed",
                f"{bsrc} contacted {bdst}:{bport} with low-jitter periodicity "
                f"(mean interval {mean_iv:.2f}s, stdev {stdev:.2f}s, ratio {jitter_ratio:.3f}). "
                "Tight, regular callbacks to one destination are a hallmark of command-and-control beacons; "
                "monitoring agents, license checks, and health probes look the same, so identify the process "
                f"on {bsrc} that generates them.",
                [
                    f"Samples: {len(intervals) + 1}",
                    f"Mean interval: {mean_iv:.3f}s",
                    f"Stddev: {stdev:.3f}s  (jitter ratio {jitter_ratio:.3f})",
                    f"Destination is public: {dst_public}",
                ],
                [bsrc], [bdst],
                "Beacon",
                sorted(bcn["pcap_names"]),
                f"beacon::{bsrc}::{bdst}::{bport}",
                tags=["beacon", "c2", "intrusion"] + (["public"] if dst_public else []),
            )
        self._detector_done("Beaconing analysis", before)

        # ---- DNS finalization ---------------------------------------
        before = len(self.session.findings)
        # Long domain names
        for pn2, src2, qname, length in dns_state["long_names"][:50]:
            self.add_finding(
                SEVERITY_HIGH, "Intrusion Indicators",
                "Unusually long DNS query name",
                f"{src2} queried '{qname}' ({length} chars). Long DNS labels are consistent with "
                "DNS tunneling or data exfiltration encoded into hostname labels.",
                [f"Query name: {qname}", f"Length: {length}"],
                [src2], [], "DNS", [pn2],
                f"dns::longname::{src2}::{hashlib.sha1(qname.encode()).hexdigest()[:10]}",
                tags=["dns_tunneling", "exfiltration"],
            )
        # TXT queries with large responses
        for pn2, src2, qname, size in dns_state["txt_large"][:50]:
            self.add_finding(
                SEVERITY_HIGH, "Intrusion Indicators",
                "Large DNS TXT response",
                f"{src2} involved in a DNS TXT exchange for '{qname}' with a response of {size} bytes. "
                "Large TXT responses are a common carrier for DNS-based command-and-control.",
                [f"Query name: {qname}", f"Response size: {size} bytes"],
                [src2], [], "DNS", [pn2],
                f"dns::txt-large::{src2}::{hashlib.sha1(qname.encode()).hexdigest()[:10]}",
                tags=["dns_tunneling", "c2"],
            )
        # Elevated NXDOMAIN ratio per source (DGA)
        for src2, nx_count in dns_state["nxdomain_per_src"].items():
            total = dns_state["queries_per_src"].get(src2, 0)
            if total >= 20 and nx_count / max(total, 1) >= 0.5:
                self.add_finding(
                    SEVERITY_HIGH, "Intrusion Indicators",
                    "Elevated DNS NXDOMAIN ratio (possible DGA)",
                    f"{src2} had {nx_count}/{total} DNS queries return NXDOMAIN. "
                    "High NXDOMAIN ratios strongly correlate with domain-generation-algorithm malware.",
                    [f"NXDOMAIN: {nx_count} of {total} total queries"],
                    [src2], [], "DNS", sorted(dns_state["pcap_names"]),
                    f"dns::dga::{src2}",
                    tags=["dga", "c2", "intrusion"],
                )
        # OT devices generating DNS queries to non-approved resolvers
        for src2, servers in dns_state["servers_per_src"].items():
            if not src2 or src2 not in self.session.devices:
                continue
            device = self.session.devices[src2]
            if self._likely_ot_device(device) and len(servers) >= 3:
                self.add_finding(
                    SEVERITY_MEDIUM, "Network Hygiene and Segmentation",
                    "OT device queried multiple DNS resolvers",
                    f"{src2} (OT-adjacent) issued DNS queries to {len(servers)} distinct resolver IPs. "
                    "OT devices should use a single approved resolver (or none).",
                    [f"Resolvers: {', '.join(sorted(servers))}"],
                    [src2], sorted(servers), "DNS", sorted(dns_state["pcap_names"]),
                    f"dns::multi-resolver::{src2}",
                    tags=["boundary", "dns"],
                )
        # High-entropy domain names (DGA / DNS tunneling via short random labels)
        seen_entropy_names: set = set()
        for pn2, src2, qname, ent in dns_state["high_entropy_names"][:50]:
            if qname in seen_entropy_names:
                continue
            seen_entropy_names.add(qname)
            self.add_finding(
                SEVERITY_HIGH, "Intrusion Indicators",
                "High-entropy DNS query name (possible DGA or tunneling)",
                f"{src2} queried '{qname}' (entropy {ent} bits). High character entropy in DNS labels "
                "is a strong indicator of domain-generation-algorithm malware or DNS-based covert channel. "
                "Unlike the long-name check, this detects shorter but statistically random-looking domains.",
                [f"Query name: {qname}", f"Shannon entropy: {ent} bits (threshold 3.5)"],
                [src2], [], "DNS", [pn2],
                f"dns::entropy::{src2}::{hashlib.sha1(qname.encode()).hexdigest()[:10]}",
                tags=["dga", "dns_tunneling", "intrusion"],
            )
        self._detector_done("DNS analysis", before)

        # ---- SNMP depth finalization --------------------------------
        before = len(self.session.findings)
        for src2, count in snmp_state["getnext_per_src"].items():
            if count >= 50:
                self.add_finding(
                    SEVERITY_HIGH, "Intrusion Indicators",
                    "SNMP walk observed",
                    f"{src2} issued {count} SNMP GetNext/GetBulk requests, consistent with an SNMP walk "
                    "(MIB enumeration). Network-management systems walk interface tables routinely; from any "
                    "other host this is reconnaissance.",
                    [f"GetNext/GetBulk requests: {count}"],
                    [src2], [], "SNMP",
                    sorted(snmp_state["pcap_names"]),
                    f"snmp::walk::{src2}",
                    tags=["recon", "snmp"],
                )
        for pn2, src2, dst2, sinfo in snmp_state["set_events"]:
            self.add_finding(
                SEVERITY_CRITICAL, "Cleartext and Legacy Protocols",
                "SNMP SET operation observed",
                f"An SNMP SET-Request was observed from {src2} to {dst2}. "
                "SET operations modify device configuration. In OT environments SNMP SET is "
                "rare and almost always represents an intentional administrative change or "
                "an attacker manipulating device state.",
                [f"Info: {sinfo}"],
                [src2], [dst2], "SNMP", [pn2],
                f"snmp::set::{src2}::{dst2}",
                tags=["write", "snmp", "critical_control"],
            )
        for community, count in snmp_state["communities"].items():
            if community.lower() in ("public", "private") or count >= 1:
                sev = SEVERITY_HIGH if community.lower() in ("public", "private") else SEVERITY_MEDIUM
                self.add_finding(
                    sev, "Cleartext and Legacy Protocols",
                    f"SNMP community string '{community}' observed",
                    f"SNMPv1/v2c community string '{community}' was captured in cleartext. "
                    "Default or well-known communities give immediate read access (and with SET, write access) "
                    "to every reachable device sharing that community.",
                    [f"Community: {community}", f"Occurrences: {count}"],
                    [], [], "SNMP", sorted(snmp_state["pcap_names"]),
                    f"snmp::community::{community}",
                    tags=["credential_exposure", "snmp"],
                )
        self._detector_done("SNMP depth analysis", before)

        # ---- TLS inspection finalization ----------------------------
        before = len(self.session.findings)
        for pn2, src2, dst2, ver in tls_state["old_versions"]:
            self.add_finding(
                SEVERITY_HIGH, "Cleartext and Legacy Protocols",
                f"Obsolete TLS/SSL version observed ({ver})",
                f"{dst2} negotiated {ver} with {src2}. SSL and TLS versions before 1.2 are deprecated "
                "(RFC 8996) and have practical attacks; disable them on the server.",
                [f"{pn2}: {src2} -> {dst2} | ServerHello selected {ver}"],
                [src2], [dst2], "TLS", [pn2],
                f"tls::oldver::{dst2}::{ver}",
                tags=["legacy", "tls", "weak_crypto"],
            )
        for pn2, src2, dst2, cipher in tls_state["weak_ciphers"]:
            self.add_finding(
                SEVERITY_HIGH, "Cleartext and Legacy Protocols",
                f"Weak TLS cipher observed ({cipher})",
                f"{dst2} selected a weak cipher suite ({cipher}) for a session with {src2}. NULL, anonymous, "
                "EXPORT, RC4, DES/3DES, and MD5-based suites are broken or deprecated and must be disabled.",
                [f"{pn2}: {src2} -> {dst2} | ServerHello selected {cipher}"],
                [src2], [dst2], "TLS", [pn2],
                f"tls::weakcipher::{dst2}::{cipher}",
                tags=["weak_crypto", "tls"],
            )
        for pn2, src2, dst2, alert_text in tls_state["rejected_certs"]:
            reason = alert_text.split(" | ", 1)[0]
            self.add_finding(
                SEVERITY_MEDIUM, "Cleartext and Legacy Protocols",
                f"TLS certificate rejected by peer ({reason})",
                f"A TLS handshake between {src2} and {dst2} was aborted with a {reason} alert: the peer did not "
                "trust the certificate it was shown. Self-signed and privately issued device certificates cause "
                "this; users who learn to click past certificate warnings are exposed to interception.",
                [f"{pn2}: {alert_text}"],
                [src2], [dst2], "TLS", [pn2],
                f"tls::rejected::{src2}::{dst2}",
                tags=["tls"],
            )
        for pn2, src2, dst2, alert_text in tls_state["expired_certs"]:
            self.add_finding(
                SEVERITY_HIGH, "Cleartext and Legacy Protocols",
                "Expired TLS certificate observed",
                f"A TLS handshake between {src2} and {dst2} was aborted because a certificate had expired. "
                "Expired certificates indicate unmonitored PKI and train users to ignore trust warnings.",
                [f"{pn2}: {alert_text}"],
                [src2], [dst2], "TLS", [pn2],
                f"tls::expired::{src2}::{dst2}",
                tags=["tls"],
            )
        # JA3 known-bad fingerprints
        seen_ja3: set = set()
        for pn2, src2, dst2, ja3, label in tls_state["ja3_hits"]:
            dedup_key = (src2, dst2, ja3)
            if dedup_key in seen_ja3:
                continue
            seen_ja3.add(dedup_key)
            self.add_finding(
                SEVERITY_INTRUSION, "Intrusion Indicators",
                f"Known offensive tool TLS fingerprint detected ({label})",
                f"A TLS ClientHello from {src2} to {dst2} matched JA3 hash {ja3}, "
                f"associated with {label}. JA3 fingerprints identify the TLS library and "
                "configuration used by a client; this hash is in the documented fingerprint "
                "database for offensive tooling and C2 frameworks.",
                [f"JA3 hash: {ja3}", f"Tool: {label}", f"Source: {src2}", f"Destination: {dst2}"],
                [src2], [dst2], "TLS", [pn2],
                f"tls::ja3::{src2}::{dst2}::{ja3}",
                tags=["intrusion", "tls", "c2", "offensive_tool"],
            )
        self._detector_done("TLS inspection", before)

        # ---- NTP / Capture integrity finalization -------------------
        before = len(self.session.findings)
        for pcap_name, clock in ntp_state["per_file"].items():
            if clock["frames"] < 2:
                continue
            max_gap = clock["max_gap"]
            # A >60s gap in captures with multi-kpps normal traffic is
            # evidence of a paused recorder, rotated file mid-stream, or
            # a TAP/SPAN drop.  Report only when notable.
            if max_gap >= 60.0:
                gap_from, gap_to = clock["gap_at"]
                self.add_finding(
                    SEVERITY_MEDIUM, "Network Hygiene and Segmentation",
                    "Capture discontinuity (large inter-packet gap)",
                    f"{pcap_name} has a gap of {human_duration(max_gap)} with no traffic, from {format_epoch(gap_from)} "
                    f"to {format_epoch(gap_to)}. Large gaps may indicate a paused capture, rotated file, TAP/SPAN "
                    "overload, or selective recording — investigate whether analysis coverage is complete.",
                    [f"{pcap_name}: no traffic for {human_duration(max_gap)}, {format_epoch(gap_from)} – "
                     f"{format_epoch(gap_to)} (@{gap_from:.6f} – @{gap_to:.6f})"],
                    [], [], "", [pcap_name],
                    f"capture::gap::{pcap_name}",
                    tags=["capture-integrity"],
                )
            total_span = clock["last"] - clock["first"]
            if 0 < total_span < 60 and clock["frames"] > 500:
                self.add_finding(
                    SEVERITY_LOW, "Network Hygiene and Segmentation",
                    "Very short capture window",
                    f"{pcap_name} covers only {human_duration(total_span)} ({clock['frames']:,} frames) — analysis "
                    "results may be limited by the short observation window.",
                    [f"{pcap_name}: {clock['frames']:,} frames over {human_duration(total_span)}"],
                    [], [], "", [pcap_name],
                    f"capture::short::{pcap_name}",
                    tags=["capture-integrity"],
                )

        # Devices talking TCP/UDP but no NTP seen at all → time-sync gap.
        all_ntp_srcs = set(ntp_state["ntp_queries"].keys())
        # Continuous observed time (gaps excluded) of the longest capture file.
        capture_span = max((clock["active"] for clock in ntp_state["per_file"].values()), default=0.0)
        if not all_ntp_srcs and capture_span >= 1800:
            self.add_finding(
                SEVERITY_MEDIUM, "Network Hygiene and Segmentation",
                "No NTP traffic observed in capture",
                f"No NTP (UDP/123) traffic was seen in {human_duration(capture_span)} of continuous capture. OT environments "
                "without synchronized time make forensic correlation, SIEM alerting, and certificate validity "
                "checks unreliable. Some clients (Windows domain members) poll only every few hours, so confirm "
                "the time source on the devices themselves.",
                [f"Capture files: {', '.join(sorted(ntp_state['pcap_names']))}"],
                [], [], "NTP", sorted(ntp_state["pcap_names"]),
                "capture::no-ntp",
                tags=["time-sync", "capture-integrity"],
            )
        # Flag sources querying many different NTP servers (unusual for OT).
        for src_n, servers in ntp_state["ntp_servers"].items():
            if len(servers) >= 4:
                self.add_finding(
                    SEVERITY_LOW, "Network Hygiene and Segmentation",
                    "Host queried many NTP servers",
                    f"{src_n} queried {len(servers)} distinct NTP servers. OT endpoints "
                    "typically peer with 1–2 internal time sources; multi-resolver behavior "
                    "may indicate roaming, mis-configuration, or external time servers on a network that should be air-gapped.",
                    [f"{src_n} -> {', '.join(sorted(servers)[:8])}"],
                    [src_n], sorted(servers), "NTP", sorted(ntp_state["pcap_names"]),
                    f"ntp::multi-server::{src_n}",
                    tags=["time-sync"],
                )
        self._detector_done("NTP / capture-integrity", before)

        # ---- IT-noise-on-OT finalization ----------------------------
        before = len(self.session.findings)
        # Identify subnets that look "OT" via inferred device roles.  A
        # subnet counts as OT if any device in it is a Controller/HMI/
        # OT Device.  Pure-IT subnets are silenced — IT noise on an IT
        # network is not a finding.
        ot_subnets: set = set()
        for dev in self.session.devices.values():
            if any(k in dev.inferred_role for k in ("Controller", "HMI", "OT Device", "OT Server", "Machine-Vision",
                                                    "Physical Security", "Dual-Zone")):
                ot_subnets.add(subnet_from_ip(dev.ip))
        for (proto_name, subnet), slot in noise_state["by_proto_subnet"].items():
            if subnet not in ot_subnets:
                continue
            if len(slot["hosts"]) < 3:
                continue
            host_list = sorted(slot["hosts"])
            evidence = list(slot["samples"])
            evidence.append(f"Hosts emitting {proto_name} in {subnet}: {', '.join(host_list[:30])}")
            self.add_finding(
                SEVERITY_MEDIUM, "Network Hygiene and Segmentation",
                f"{proto_name} traffic observed on OT segment",
                f"{len(host_list)} hosts in {subnet} emitted {proto_name} traffic. "
                f"{proto_name} is an IT-class discovery / name-resolution protocol and "
                "has no business on a dedicated control network — its presence indicates "
                "an IT endpoint plugged into the OT segment, an unhardened Windows host, "
                "or a misconfigured switch port.",
                evidence,
                host_list, [], proto_name, sorted(slot["pcaps"]),
                f"hygiene::it-noise::{proto_name}::{subnet}",
                tags=["hygiene", "it-on-ot", proto_name.lower()],
            )

        # ---- DHCP rogue-server finalization -------------------------
        for subnet, server_macs in dhcp_state["servers_by_subnet"].items():
            if len(server_macs) < 2:
                continue
            mac_list = sorted(server_macs.keys())
            all_pcaps: set = set()
            for pcap_set in server_macs.values():
                all_pcaps.update(pcap_set)
            evidence = list(dhcp_state["samples"][subnet])
            evidence.append(f"Distinct server MACs in {subnet}: {', '.join(mac_list)}")
            self.add_finding(
                SEVERITY_CRITICAL, "Network Hygiene and Segmentation",
                "Multiple DHCP servers observed in subnet (possible rogue)",
                f"{len(mac_list)} distinct MAC addresses served DHCP responses in {subnet}. "
                "OT subnets typically have exactly one authorized DHCP server (often none — many "
                "use static IPs). Multiple DHCP servers are either a misconfiguration or an "
                "active layer-2 attack — a rogue DHCP server can redirect default gateway, DNS, "
                "and NTP for every endpoint that renews a lease.",
                evidence, [], [], "DHCP", sorted(all_pcaps),
                f"hygiene::dhcp-rogue::{subnet}",
                tags=["hygiene", "dhcp-rogue", "intrusion"],
            )

        # ---- ICMP sweep / unreachable finalization ------------------
        for src_icmp, dests in icmp_state["dests_per_src"].items():
            if len(dests) < 20:
                continue
            evidence = list(icmp_state["samples_per_src"][src_icmp])
            evidence.append(f"Distinct destinations: {len(dests)} (top 20: {', '.join(sorted(dests)[:20])})")
            self.add_finding(
                SEVERITY_HIGH, "Intrusion Indicators",
                "ICMP sweep / host-discovery scan",
                f"{src_icmp} sent ICMP to {len(dests)} distinct destinations. "
                "Wide-fan ICMP is a classic host-discovery signature — legitimate OT endpoints "
                "communicate with a small, fixed set of peers.",
                evidence,
                [src_icmp], sorted(dests)[:20], "ICMP",
                sorted(icmp_state["pcaps"]),
                f"intrusion::icmp-sweep::{src_icmp}",
                tags=["recon", "icmp"],
            )
        # Heavy unreachable bursts targeting one host = response to a port scan
        for dst_icmp, count in icmp_state["unreach_per_dst"].items():
            if count < 50:
                continue
            self.add_finding(
                SEVERITY_HIGH, "Intrusion Indicators",
                "ICMP unreachable burst (port-scan response)",
                f"{count} ICMP destination-unreachable responses targeted {dst_icmp}. "
                "A heavy burst of unreachables typically indicates the host is being "
                "port-scanned and the network is rejecting the closed-port probes.",
                [f"Target: {dst_icmp}, unreachable count: {count}"],
                [], [dst_icmp], "ICMP",
                sorted(icmp_state["pcaps"]),
                f"intrusion::icmp-unreach::{dst_icmp}",
                tags=["recon", "icmp"],
            )
        self._detector_done("IT-noise / DHCP / ICMP-sweep", before)

    def run_optional_checks(self, pcaps: Sequence[Path]) -> None:
        """Run the analysis categories after inventory without per-check prompts."""
        assert self.session is not None
        # Aggregate ETA across the full pipeline so the user has a single
        # "this whole run will take ~X" upfront number.
        session_only = {"modbus", "bacnet", "dnp3", "iec61850", "iec104",
                        "mqtt", "opcua", "ethernet_ip", "siemens", "physical_security"}
        upcoming_keys = ["streaming"] + [k for k, _, _ in CHECK_ORDER[1:] if k not in session_only]
        per_step_eta: Dict[str, Optional[float]] = {k: self._estimate_step(k, pcaps) for k in upcoming_keys}
        total_eta = sum((v for v in per_step_eta.values() if v), 0.0) or 0.0
        if total_eta > 0:
            self._log_ts(
                f"Estimated remaining analysis time: {self._format_duration(total_eta)} "
                f"(based on the inventory rate of "
                f"{human_size(int(self._proc_rate_bps))}/s on this host)."
            )

        # Phase 1: single combined tshark pass for all protocol checks
        eta_s = per_step_eta.get("streaming")
        eta_text = f" (est {self._format_duration(eta_s)})" if eta_s else ""
        self._log_ts(f"[…] Protocol checks across {len(pcaps)} file(s){eta_text}")
        t0 = time.time()
        self._run_streaming_protocol_checks(pcaps)
        elapsed = time.time() - t0
        self._log_ts(colorize(
            f"[✓] Protocol checks complete ({self._format_duration(elapsed)}): {self._detector_summary()}",
            "SUCCESS"))
        skipped = [f"{name} ({reason})" for name, _, reason in self._detector_results if reason]
        if skipped:
            self._log_ts(f"    Not checked: {'; '.join(skipped)}.")
        self._print_coverage()

        # Phase 2: separate passes / session-data checks
        remaining: Dict[str, Callable[[Sequence[Path]], int]] = {
            "legacy": self.check_legacy,
            "artifact_extraction": self.check_artifact_extraction,
            "network_hygiene": self.check_network_hygiene,
            "intrusion": self.check_intrusion,
            "unknown": self.check_unknown,
        }
        for key, name, description in CHECK_ORDER[1:]:
            if key in session_only:
                continue
            eta_s = per_step_eta.get(key)
            eta_text = f" (est {self._format_duration(eta_s)})" if eta_s else ""
            print()
            self._log_ts(f"[…] {name}: {description}{eta_text}")
            # Network Hygiene specifically: surface what the slow part is so
            # the user knows what they're waiting on.  RDAP/PTR lookups
            # dominate when there are many distinct public IPs.
            if key == "network_hygiene" and not self._is_air_gapped():
                pub_to_lookup = sum(
                    1 for c in self.session.connections.values()
                    if (sd := self.session.devices.get(c.source_ip))
                    and self._likely_ot_device(sd)
                    and is_public_ip(c.destination_ip)
                    and c.destination_ip not in self.public_ip_cache
                )
                if pub_to_lookup > 0:
                    self._log_ts(
                        f"      └─ {pub_to_lookup} public IP(s) need PTR/RDAP enrichment "
                        f"(~2.5s each with timeout). Answer 'yes' to the air-gapped question or pass --offline to skip."
                    )
            before = len(self.session.findings)
            t0 = time.time()
            remaining[key](pcaps)
            elapsed = time.time() - t0
            after = len(self.session.findings)
            self._log_ts(colorize(
                f"[✓] {name} complete ({self._format_duration(elapsed)}) — "
                f"{after - before} new finding{'s' if after - before != 1 else ''}.", "SUCCESS"))

    def compute_per_device_risk(self, top_n: int = 15) -> List[Dict[str, Any]]:
        """Aggregate severity-weighted risk per device.

        For each device, sum SCORE_WEIGHTS across all findings whose
        source_ips or destination_ips touches it.  Also count highest-
        severity finding per device so the top-N can break ties on
        severity rather than raw weight.
        """
        assert self.session is not None
        weights: Counter[str] = Counter()
        crit_counts: Counter[str] = Counter()
        high_counts: Counter[str] = Counter()
        finding_counts: Counter[str] = Counter()
        top_titles: Dict[str, List[str]] = defaultdict(list)
        for finding in self.session.findings:
            if finding.severity == SEVERITY_INFO:
                continue
            weight = SCORE_WEIGHTS.get(finding.severity, 0)
            touched = set(finding.source_ips) | set(finding.destination_ips)
            for ip in touched:
                if ip not in self.session.devices:
                    continue  # device was pruned as low confidence
                weights[ip] += weight
                finding_counts[ip] += 1
                if finding.severity == SEVERITY_CRITICAL:
                    crit_counts[ip] += 1
                elif finding.severity == SEVERITY_HIGH:
                    high_counts[ip] += 1
                if len(top_titles[ip]) < 5:
                    top_titles[ip].append(f"[{finding.severity}] {finding.title}")
        rows: List[Dict[str, Any]] = []
        for ip, weight in weights.items():
            device = self.session.devices.get(ip)
            if device is None:
                continue
            rows.append({
                "ip": ip,
                "role": device.inferred_role,
                "zone": device.inferred_zone,
                "score": weight,
                "critical": crit_counts[ip],
                "high": high_counts[ip],
                "findings": finding_counts[ip],
                "protocols": ", ".join(sorted(device.protocols)[:6]),
                "top_titles": top_titles[ip],
            })
        rows.sort(key=lambda r: (r["score"], r["critical"], r["high"]), reverse=True)
        result = rows[:top_n]
        self.session.analysis_metadata["per_device_risk_top"] = [
            {k: v for k, v in row.items() if k != "top_titles"} for row in result
        ]
        return result

    def compute_risk_summary(self) -> Dict[str, Any]:
        """Compute the weighted risk score and top drivers.

        Findings are grouped by (category, title) and each group contributes
        its three heaviest findings, so one detector repeating per host cannot
        dominate the score.  INFO findings, protection guidance, and assessor
        notes do not score.
        """
        assert self.session is not None
        counts: Counter[str] = Counter(finding.severity for finding in self.session.findings)
        groups: Dict[Tuple[str, str], List[Finding]] = defaultdict(list)
        for finding in self.session.findings:
            if finding.severity == SEVERITY_INFO or finding.category in NON_SCORING_CATEGORIES:
                continue
            groups[(finding.category, finding.title)].append(finding)
        drivers: List[Tuple[int, Finding, int]] = []
        for group in groups.values():
            group.sort(key=lambda finding: SCORE_WEIGHTS.get(finding.severity, 0), reverse=True)
            contribution = sum(SCORE_WEIGHTS.get(finding.severity, 0) for finding in group[:3])
            drivers.append((contribution, group[0], len(group)))
        score = sum(contribution for contribution, _, _ in drivers)
        drivers.sort(key=lambda item: item[0], reverse=True)
        # A confirmed intrusion is never "low risk", however few findings
        # surround it; CRITICAL and correlated findings set a lower floor.
        band = risk_band(score)
        band_reason = ""
        floors = (
            (SEVERITY_INTRUSION, "HIGH", "a confirmed intrusion finding is present"),
            (SEVERITY_CORRELATION, "MODERATE", "a correlated attack-pattern finding is present"),
            (SEVERITY_CRITICAL, "MODERATE", "a CRITICAL finding is present"),
        )
        for severity, floor, reason in floors:
            scoring = any(f.severity == severity and f.category not in NON_SCORING_CATEGORIES
                          for f in self.session.findings)
            if scoring and RISK_BANDS.index(floor) > RISK_BANDS.index(band):
                band, band_reason = floor, f"raised to {floor} because {reason}"
        summary = {
            "counts": dict(counts),
            "score": score,
            "band": band,
            "band_reason": band_reason,
            "top_contributors": [
                {
                    "severity": finding.severity,
                    "title": finding.title,
                    "weight": contribution,
                    "occurrences": occurrences,
                }
                for contribution, finding, occurrences in drivers[:5]
            ],
        }
        self.session.analysis_metadata["risk_summary"] = summary
        return summary

    def generate_network_map(self) -> str:
        """Build a text-based inferred network map."""
        assert self.session is not None
        self._infer_roles_and_zones()
        layers: Dict[str, List[DeviceRecord]] = defaultdict(list)
        for device in self.session.devices.values():
            layers[device.inferred_zone].append(device)
        lines = []
        # Cap per-zone listing to keep the report readable on flood-scale
        # captures (1M+ devices).  Sort by traffic volume so the most
        # significant devices in each zone show up; the rest go to the
        # Device Inventory CSV addendum that the report generator now
        # always writes alongside the Word document.
        ZONE_DEVICE_CAP = 30
        # Pre-compute critical-IP set once instead of per-device O(F) scan.
        critical_ips: set = set()
        for finding in self.session.findings:
            if finding.severity == SEVERITY_CRITICAL:
                critical_ips.update(finding.source_ips)
                critical_ips.update(finding.destination_ips)
        for zone_name in sorted(layers):
            zone_devices = sorted(
                layers[zone_name],
                key=lambda d: (d.outgoing_count + d.incoming_count),
                reverse=True,
            )
            zone_total = len(zone_devices)
            lines.append(f"[{zone_name}]  ({zone_total:,} device(s))")
            for device in zone_devices[:ZONE_DEVICE_CAP]:
                markers = []
                if device.ip in critical_ips:
                    markers.append("[CRITICAL]")
                if len(device.source_pcaps) > 1:
                    markers.append("[MULTI-PCAP]")
                proto_text = ", ".join(sorted(device.protocols[:5])) or "Unknown"
                lines.append(f"  - {device.ip} {device.inferred_role} {' '.join(markers)}")
                lines.append(f"    protocols: {proto_text}")
                lines.append(f"    source pcaps: {', '.join(sorted(device.source_pcaps[:3]))}"
                             + (f" (+{len(device.source_pcaps)-3} more)" if len(device.source_pcaps) > 3 else ""))
            if zone_total > ZONE_DEVICE_CAP:
                lines.append(f"  … (+ {zone_total - ZONE_DEVICE_CAP:,} more device(s) in this zone — see Device Inventory CSV addendum)")
        lines.append("")
        lines.append("Connections:")
        for connection in sorted(self.session.connections.values(), key=lambda item: item.packet_count, reverse=True)[:50]:
            source_role = self.session.devices.get(connection.source_ip, DeviceRecord(connection.source_ip)).inferred_role
            destination_role = self.session.devices.get(connection.destination_ip, DeviceRecord(connection.destination_ip)).inferred_role
            marker = " [!]" if ("IT Device" in (source_role, destination_role) and ("Controller" in source_role or "Controller" in destination_role or "Dual-Zone" in source_role or "Dual-Zone" in destination_role)) else ""
            lines.append(f"  {connection.source_ip} -> {connection.destination_ip} : {connection.protocol}/{connection.destination_port} ({connection.packet_count} pkts){marker}")
        return "\n".join(lines)


    def generate_purdue_svgs(self) -> Tuple[Path, Optional[Path]]:
        """Generate Purdue-Model architecture SVG diagrams.

        Always writes a Summary SVG (one box per layer).  Writes a Detail SVG
        (individual device boxes + flow arrows) only when ≤50 devices are
        present.  Both files land alongside the session pcap folder.

        Returns (summary_path, detail_path_or_None).
        """
        assert self.session is not None
        report_date = datetime.now().strftime("%Y%m%d")
        folder = Path(self.session.folder)
        slug = safe_slug(self.session.site)
        summary_path, paired_detail_path = _versioned_paths(
            folder, [f"OTscope_Purdue_Summary_{slug}_{report_date}", f"OTscope_Purdue_Detail_{slug}_{report_date}"], "svg")
        detail_path: Optional[Path] = None

        # ── severity → display colour ──────────────────────────────────────
        _SEV_FILL = {
            SEVERITY_INTRUSION:   ("#FFD0D0", "#8B0000"),
            SEVERITY_CRITICAL:    ("#FFB3B3", "#CC0000"),
            SEVERITY_CORRELATION: ("#CCE0FF", "#003399"),
            SEVERITY_HIGH:        ("#FFE0B0", "#CC5500"),
            SEVERITY_MEDIUM:      ("#FFF9C4", "#9A7B00"),
            SEVERITY_LOW:         ("#EEEEEE", "#555555"),
            SEVERITY_INFO:        ("#F5F5F5", "#888888"),
        }
        _DEFAULT_FILL = ("#F8F8F8", "#AAAAAA")

        def _layer_colour(devices: List[DeviceRecord]) -> Tuple[str, str]:
            """Return (fill, stroke) for the highest-severity device in a layer."""
            top_sev = ""
            for dev in devices:
                for finding in self.session.findings:  # type: ignore[union-attr]
                    if dev.ip in finding.source_ips or dev.ip in finding.destination_ips:
                        if SEVERITY_ORDER.get(finding.severity, 0) > SEVERITY_ORDER.get(top_sev, -1):
                            top_sev = finding.severity
            return _SEV_FILL.get(top_sev, _DEFAULT_FILL)

        # ── canonical layer order ──────────────────────────────────────────
        LAYER_ORDER = [
            "External / Public",
            "Purdue L4/L5",
            "Purdue L3/L3.5 Boundary",
            "Purdue L2/L3",
            "Purdue L1/L2",
            "Physical Security / OT Edge",
            "Unknown",
        ]
        LAYER_LABEL = {
            "External / Public":        "External / Public",
            "Purdue L4/L5":             "L4/L5 — IT / Corporate",
            "Purdue L3/L3.5 Boundary":  "L3/L3.5 — DMZ / Boundary",
            "Purdue L2/L3":             "L2/L3 — Supervisory / HMI",
            "Purdue L1/L2":             "L1/L2 — Controllers / PLC / RTU",
            "Physical Security / OT Edge": "Physical Security / OT Edge",
            "Unknown":                  "Unclassified",
        }

        # Group devices by zone, compute per-layer top protocols
        layers: Dict[str, List[DeviceRecord]] = defaultdict(list)
        for dev in self.session.devices.values():
            z = dev.inferred_zone if dev.inferred_zone in LAYER_ORDER else "Unknown"
            layers[z].append(dev)
        active_layers = [z for z in LAYER_ORDER if layers[z]]

        # ── SUMMARY SVG ────────────────────────────────────────────────────
        W = 860
        PAD = 28
        BOX_H = 80
        GAP = 14
        title_h = 44
        legend_h = 32
        total_h = title_h + legend_h + PAD + len(active_layers) * (BOX_H + GAP) + PAD

        svg_lines: List[str] = []
        svg_lines.append(
            f'<svg xmlns="http://www.w3.org/2000/svg" width="{W}" height="{total_h}" '
            f'font-family="Segoe UI,Arial,sans-serif">'
        )
        # Background
        svg_lines.append(f'<rect width="{W}" height="{total_h}" fill="#FAFAFA" rx="6"/>')
        # Title
        svg_lines.append(
            f'<text x="{W//2}" y="28" text-anchor="middle" font-size="15" '
            f'font-weight="bold" fill="#1A1A1A">'
            f'OTscope Purdue Model — {_xml_escape(self.session.site)}</text>'
        )
        # Legend
        lx = PAD
        ly = title_h + 8
        for sev_label, (fill, stroke) in [
            ("INTRUSION", _SEV_FILL[SEVERITY_INTRUSION]),
            ("CRITICAL",  _SEV_FILL[SEVERITY_CRITICAL]),
            ("HIGH",      _SEV_FILL[SEVERITY_HIGH]),
            ("MEDIUM",    _SEV_FILL[SEVERITY_MEDIUM]),
            ("LOW/INFO",  _SEV_FILL[SEVERITY_LOW]),
            ("No findings", _DEFAULT_FILL),
        ]:
            svg_lines.append(
                f'<rect x="{lx}" y="{ly}" width="14" height="14" '
                f'fill="{fill}" stroke="{stroke}" stroke-width="1.5" rx="2"/>'
            )
            svg_lines.append(
                f'<text x="{lx + 18}" y="{ly + 11}" font-size="10" fill="#333">{sev_label}</text>'
            )
            lx += 90

        # Layer boxes
        y = title_h + legend_h + PAD
        box_x = PAD
        box_w = W - 2 * PAD

        for idx, zone in enumerate(active_layers):
            devs = layers[zone]
            fill, stroke = _layer_colour(devs)
            label = LAYER_LABEL.get(zone, zone)
            n = len(devs)
            protos: Counter[str] = Counter()
            for d in devs:
                for p in d.protocols[:5]:
                    protos[p] += 1
            top_protos = ", ".join(p for p, _ in protos.most_common(4)) or "—"

            # Draw arrow connector between layers (skip for first)
            if idx > 0:
                ax = W // 2
                ay = y - GAP
                svg_lines.append(
                    f'<line x1="{ax}" y1="{ay - 4}" x2="{ax}" y2="{ay + 4}" '
                    f'stroke="#999" stroke-width="2" marker-end="url(#arr)"/>'
                )

            svg_lines.append(
                f'<rect x="{box_x}" y="{y}" width="{box_w}" height="{BOX_H}" '
                f'fill="{fill}" stroke="{stroke}" stroke-width="2" rx="6"/>'
            )
            svg_lines.append(
                f'<text x="{box_x + 14}" y="{y + 22}" font-size="12" '
                f'font-weight="bold" fill="#111">{_xml_escape(label)}</text>'
            )
            svg_lines.append(
                f'<text x="{box_x + 14}" y="{y + 40}" font-size="11" fill="#333">'
                f'{n:,} device(s)</text>'
            )
            svg_lines.append(
                f'<text x="{box_x + 14}" y="{y + 57}" font-size="10" fill="#555">'
                f'Protocols: {_xml_escape(top_protos)}</text>'
            )
            y += BOX_H + GAP

        # Arrow marker def
        svg_lines.insert(1,
            '<defs><marker id="arr" markerWidth="8" markerHeight="8" '
            'refX="4" refY="4" orient="auto">'
            '<path d="M0,0 L8,4 L0,8 Z" fill="#999"/></marker></defs>'
        )
        svg_lines.append('</svg>')
        summary_path.write_text("\n".join(svg_lines), encoding="utf-8")
        self._note_artifact(summary_path, "Network diagram — open in a web browser", "Purdue summary diagram written")

        # ── DETAIL SVG (≤50 devices only) ─────────────────────────────────
        n_total = len(self.session.devices)
        if n_total > 50:
            print(f"[i] Purdue Detail SVG skipped ({n_total:,} devices > 50 limit).")
            return summary_path, None

        detail_path = paired_detail_path

        # Assign grid positions for devices within each layer
        DW = 1100       # device-area width
        PANEL_W = 230   # right panel (top-connections list)
        TOTAL_W = DW + PANEL_W
        DPAD = 32
        D_TITLE_H = 44
        D_LAYER_HEAD = 26
        D_DEV_W = 160
        D_DEV_H = 46
        D_DEV_GAP_X = 12
        D_DEV_GAP_Y = 12
        D_LAYER_PAD = 10

        # Pre-compute per-device severities
        dev_sev: Dict[str, str] = {}
        for finding in self.session.findings:
            for ip in finding.source_ips + finding.destination_ips:
                if SEVERITY_ORDER.get(finding.severity, 0) > SEVERITY_ORDER.get(dev_sev.get(ip, ""), -1):
                    dev_sev[ip] = finding.severity

        # Compute device box positions
        dev_pos: Dict[str, Tuple[int, int]] = {}  # ip -> (cx, cy) centre
        layer_rects: List[Tuple[int, int, int, int, str, str, str]] = []  # x,y,w,h,fill,stroke,label

        curr_y = D_TITLE_H + DPAD

        for zone in active_layers:
            devs_in_zone = sorted(
                layers[zone],
                key=lambda d: (d.outgoing_count + d.incoming_count),
                reverse=True,
            )
            n_devs = len(devs_in_zone)
            cols = max(1, min(5, n_devs))
            rows = (n_devs + cols - 1) // cols
            inner_w = cols * D_DEV_W + (cols - 1) * D_DEV_GAP_X
            layer_h = D_LAYER_HEAD + D_LAYER_PAD + rows * (D_DEV_H + D_DEV_GAP_Y)
            lx = DPAD
            lw = DW - 2 * DPAD
            fill, stroke = _layer_colour(devs_in_zone)
            label = LAYER_LABEL.get(zone, zone)
            layer_rects.append((lx, curr_y, lw, layer_h, fill, stroke, label))
            # Position device boxes
            start_x = lx + (lw - inner_w) // 2
            for i, dev in enumerate(devs_in_zone):
                col = i % cols
                row = i // cols
                cx = start_x + col * (D_DEV_W + D_DEV_GAP_X) + D_DEV_W // 2
                cy = curr_y + D_LAYER_HEAD + D_LAYER_PAD + row * (D_DEV_H + D_DEV_GAP_Y) + D_DEV_H // 2
                dev_pos[dev.ip] = (cx, cy)
            curr_y += layer_h + GAP

        total_detail_h = curr_y + DPAD

        # Build ip → layer map (used for panel content later)
        ip_to_layer: Dict[str, str] = {}
        for _zone in active_layers:
            for _dev in layers[_zone]:
                ip_to_layer[_dev.ip] = _zone

        d_lines: List[str] = []
        d_lines.append(
            f'<svg xmlns="http://www.w3.org/2000/svg" width="{TOTAL_W}" height="{total_detail_h}" '
            f'font-family="Segoe UI,Arial,sans-serif">'
        )
        d_lines.append(
            '<defs><marker id="arr" markerWidth="8" markerHeight="8" '
            'refX="4" refY="4" orient="auto">'
            '<path d="M0,0 L8,4 L0,8 Z" fill="#888"/></marker></defs>'
        )
        d_lines.append(f'<rect width="{TOTAL_W}" height="{total_detail_h}" fill="#FAFAFA" rx="6"/>')
        # Vertical separator between device area and panel
        d_lines.append(
            f'<line x1="{DW + 5}" y1="{D_TITLE_H}" x2="{DW + 5}" y2="{total_detail_h - DPAD}" '
            f'stroke="#DDDDDD" stroke-width="1.5"/>'
        )
        d_lines.append(
            f'<text x="{TOTAL_W//2}" y="28" text-anchor="middle" font-size="15" '
            f'font-weight="bold" fill="#1A1A1A">'
            f'OTscope Purdue Detail — {_xml_escape(self.session.site)}</text>'
        )

        # Layer background rectangles
        for (lx, ly, lw, lh, fill, stroke, label) in layer_rects:
            d_lines.append(
                f'<rect x="{lx}" y="{ly}" width="{lw}" height="{lh}" '
                f'fill="{fill}" stroke="{stroke}" stroke-width="1.5" rx="5" opacity="0.7"/>'
            )
            d_lines.append(
                f'<text x="{lx + 10}" y="{ly + 18}" font-size="11" '
                f'font-weight="bold" fill="#222">{_xml_escape(label)}</text>'
            )

        # ── Right panel: Top Connections list ─────────────────────────────
        # Individual bezier curves between device centres overlap badly when
        # many devices are present.  Instead, list the top connections in a
        # readable panel to the right of the device grid.
        PX = DW + 14   # left edge of panel text content
        PW = PANEL_W - 18  # usable panel width

        d_lines.append(
            f'<text x="{DW + PANEL_W // 2}" y="{D_TITLE_H + 18}" '
            f'text-anchor="middle" font-size="11" font-weight="bold" fill="#444">'
            f'Top Connections</text>'
        )
        d_lines.append(
            f'<line x1="{PX - 2}" y1="{D_TITLE_H + 24}" '
            f'x2="{DW + PANEL_W - 10}" y2="{D_TITLE_H + 24}" '
            f'stroke="#CCCCCC" stroke-width="1"/>'
        )

        _top_conns = sorted(
            self.session.connections.values(),
            key=lambda c: (c.source_ip in self.session.devices and c.destination_ip in self.session.devices,
                           c.packet_count),
            reverse=True,
        )

        _entry_h = 38
        _ey = D_TITLE_H + 32
        _max_entries = max(1, (total_detail_h - _ey - DPAD) // _entry_h)
        _max_entries = min(_max_entries, 16)
        _shown = 0

        for _conn in _top_conns:
            if _shown >= _max_entries:
                break
            # Alternating row background
            if _shown % 2 == 0:
                d_lines.append(
                    f'<rect x="{PX - 4}" y="{_ey}" width="{PW + 4}" height="{_entry_h}" '
                    f'fill="#F0F4FF" rx="2"/>'
                )
            # Source IP → Dest IP
            _src = _conn.source_ip if len(_conn.source_ip) <= 14 else _conn.source_ip[:12] + "…"
            _dst = _conn.destination_ip if len(_conn.destination_ip) <= 14 else _conn.destination_ip[:12] + "…"
            d_lines.append(
                f'<text x="{PX}" y="{_ey + 13}" font-size="9" font-weight="bold" fill="#111">'
                f'{_xml_escape(_src)} → {_xml_escape(_dst)}</text>'
            )
            # Protocol · port · packet count
            _proto = (_conn.protocol or "TCP")[:10]
            _port_str = f":{_conn.destination_port}" if _conn.destination_port else ""
            _pkts = f"{_conn.packet_count:,} pkts"
            d_lines.append(
                f'<text x="{PX}" y="{_ey + 25}" font-size="8" fill="#555">'
                f'{_xml_escape(_proto)}{_port_str} · {_pkts}</text>'
            )
            # Layer info (src layer short label)
            _sl = ip_to_layer.get(_conn.source_ip, "")
            _dl = ip_to_layer.get(_conn.destination_ip, "")
            _sl_short = {
                "External / Public":           "Ext",
                "Purdue L4/L5":                "L4/L5",
                "Purdue L3/L3.5 Boundary":     "L3",
                "Purdue L2/L3":                "L2/3",
                "Purdue L1/L2":                "L1/2",
                "Physical Security / OT Edge": "OT Edge",
                "Unknown":                     "?",
            }
            _sl_lbl = _sl_short.get(_sl, _sl[:6] if _sl else "?")
            _dl_lbl = _sl_short.get(_dl, _dl[:6] if _dl else "?")
            d_lines.append(
                f'<text x="{PX}" y="{_ey + 35}" font-size="7.5" fill="#999">'
                f'{_xml_escape(_sl_lbl)} → {_xml_escape(_dl_lbl)}</text>'
            )
            _ey += _entry_h
            _shown += 1

        if _shown == 0:
            d_lines.append(
                f'<text x="{DW + PANEL_W // 2}" y="{D_TITLE_H + 60}" '
                f'text-anchor="middle" font-size="10" fill="#AAAAAA">—</text>'
            )

        # Device boxes (drawn on top of arrows)
        for zone in active_layers:
            for dev in layers[zone]:
                if dev.ip not in dev_pos:
                    continue
                cx, cy = dev_pos[dev.ip]
                bx = cx - D_DEV_W // 2
                by = cy - D_DEV_H // 2
                sev = dev_sev.get(dev.ip, "")
                d_fill, d_stroke = _SEV_FILL.get(sev, _DEFAULT_FILL)
                # Highlight CRITICAL/INTRUSION
                if sev in (SEVERITY_CRITICAL, SEVERITY_INTRUSION):
                    d_stroke = "#CC0000"
                    sw = "2.5"
                else:
                    sw = "1.2"
                d_lines.append(
                    f'<rect x="{bx}" y="{by}" width="{D_DEV_W}" height="{D_DEV_H}" '
                    f'fill="{d_fill}" stroke="{d_stroke}" stroke-width="{sw}" rx="4"/>'
                )
                # IP (truncate if long)
                ip_label = dev.ip if len(dev.ip) <= 16 else dev.ip[:14] + "…"
                d_lines.append(
                    f'<text x="{cx}" y="{by + 16}" text-anchor="middle" '
                    f'font-size="10" font-weight="bold" fill="#111">{_xml_escape(ip_label)}</text>'
                )
                role_label = dev.inferred_role[:22] + ("…" if len(dev.inferred_role) > 22 else "")
                d_lines.append(
                    f'<text x="{cx}" y="{by + 29}" text-anchor="middle" '
                    f'font-size="9" fill="#444">{_xml_escape(role_label)}</text>'
                )
                proto_short = (dev.protocols[0] if dev.protocols else "")[:18]
                d_lines.append(
                    f'<text x="{cx}" y="{by + 41}" text-anchor="middle" '
                    f'font-size="8" fill="#666">{_xml_escape(proto_short)}</text>'
                )

        d_lines.append('</svg>')
        detail_path.write_text("\n".join(d_lines), encoding="utf-8")
        self._note_artifact(detail_path, "Per-device network diagram", "Purdue detail diagram written")

        return summary_path, detail_path

    def generate_report(self, technical_appendix: bool = False) -> Path:
        """Generate the Word report, with plain-text fallback on failure."""
        assert self.session is not None
        report_date = datetime.now().strftime("%Y%m%d")
        folder = Path(self.session.folder)
        base_name = f"OT_PCAP_Analysis_{safe_slug(self.session.site)}_{report_date}"
        report_path = _versioned_path(folder, base_name, "docx")
        network_map = self.generate_network_map()
        risk = self.compute_risk_summary()
        correlation_lines = correlation_summary_lines(self.session)
        protection_findings = [finding for finding in self.session.findings if finding.category == "Protection Guidance"]
        assessor_notes = [finding for finding in self.session.findings if finding.category == "Assessor Notes"]
        report_issues = [issue for issue in aggregated_report_issues(self.session)
                         if issue["category"] not in NON_SCORING_CATEGORIES]
        issue_ids = report_issue_ids(report_issues)
        remediation_plan = build_remediation_plan(report_issues, issue_ids)
        coverage = self.traffic_coverage()
        try:
            from docx import Document
            from docx.enum.text import WD_ALIGN_PARAGRAPH
            from docx.shared import Emu, Inches, Pt, RGBColor
            from docx.oxml.ns import qn
            from docx.oxml import OxmlElement

            # ---- Shared styling helpers ----------------------------------------
            _HDR_COLOR = "2E5F8A"
            _HDR_TXT   = RGBColor(0xFF, 0xFF, 0xFF)
            _SEV_COLOR = {
                SEVERITY_INTRUSION:   RGBColor(0xB0, 0x00, 0x20),
                SEVERITY_CRITICAL:    RGBColor(0xCC, 0x00, 0x00),
                SEVERITY_CORRELATION: RGBColor(0x00, 0x55, 0xAA),
                SEVERITY_HIGH:        RGBColor(0xE0, 0x73, 0x00),
                SEVERITY_MEDIUM:      RGBColor(0xC4, 0x9A, 0x00),
                SEVERITY_LOW:         RGBColor(0x55, 0x55, 0x55),
                SEVERITY_INFO:        RGBColor(0x88, 0x88, 0x88),
            }
            _BOX_FILL = "EAF1FB"
            _PRIORITY_FILL = {1: "F4CCCC", 2: "FCE5CD", 3: "FFF2CC", 4: "EEEEEE"}

            def _shade_cell(cell, fill_hex: str) -> None:
                tc = cell._tc
                tcPr = tc.get_or_add_tcPr()
                shd = OxmlElement("w:shd")
                shd.set(qn("w:val"), "clear")
                shd.set(qn("w:color"), "auto")
                shd.set(qn("w:fill"), fill_hex)
                tcPr.append(shd)

            def _style_table(tbl, hdr_color: str = _HDR_COLOR) -> None:
                tbl.style = "Table Grid"
                if not tbl.rows:
                    return
                for cell in tbl.rows[0].cells:
                    _shade_cell(cell, hdr_color)
                    for para in cell.paragraphs:
                        for run in para.runs:
                            run.bold = True
                            run.font.color.rgb = _HDR_TXT

            def _add_hyperlink_to_cell(cell, url: str, text: str) -> None:
                """Insert a clickable hyperlink into the first paragraph of a table cell."""
                para = cell.paragraphs[0]
                para.clear()
                r_id = para.part.relate_to(
                    url,
                    "http://schemas.openxmlformats.org/officeDocument/2006/relationships/hyperlink",
                    is_external=True,
                )
                hl = OxmlElement("w:hyperlink")
                hl.set(qn("r:id"), r_id)
                wr = OxmlElement("w:r")
                rPr = OxmlElement("w:rPr")
                rStyle = OxmlElement("w:rStyle")
                rStyle.set(qn("w:val"), "Hyperlink")
                rPr.append(rStyle)
                wr.append(rPr)
                wt = OxmlElement("w:t")
                wt.text = text
                wr.append(wt)
                hl.append(wr)
                para._p.append(hl)

            def _set_col_widths(tbl, fractions) -> None:
                """Size table columns as fractions of the usable page width."""
                section = document.sections[-1]
                usable = section.page_width - section.left_margin - section.right_margin
                tbl.autofit = False
                for idx, fraction in enumerate(fractions):
                    width = Emu(int(usable * fraction))
                    tbl.columns[idx].width = width
                    for cell in tbl.columns[idx].cells:
                        cell.width = width

            def _add_kv_table(rows_data):
                """Add a 2-col key/value table with no header row."""
                if not rows_data:
                    return
                tbl = document.add_table(rows=len(rows_data), cols=2)
                tbl.style = "Table Grid"
                for i, (k, v) in enumerate(rows_data):
                    cells = tbl.rows[i].cells
                    cells[0].text = k
                    for run in cells[0].paragraphs[0].runs:
                        run.bold = True
                    cells[1].text = v or "—"
                _set_col_widths(tbl, (0.3, 0.7))

            def _add_summary_box(rows_data) -> None:
                """Shaded label/text box that opens each detailed finding."""
                tbl = document.add_table(rows=len(rows_data), cols=2)
                tbl.style = "Table Grid"
                for i, (label, text) in enumerate(rows_data):
                    cells = tbl.rows[i].cells
                    cells[0].text = label
                    for run in cells[0].paragraphs[0].runs:
                        run.bold = True
                    cells[1].text = text
                    for cell in cells:
                        _shade_cell(cell, _BOX_FILL)
                _set_col_widths(tbl, (0.22, 0.78))

            def _color_header_text() -> None:
                """Header cells are shaded before their text is written; make that text white and bold."""
                for tbl in document.tables:
                    if not len(tbl.rows):
                        continue
                    for cell in tbl.rows[0].cells:
                        shd = cell._tc.find(f"{qn('w:tcPr')}/{qn('w:shd')}")
                        if shd is None or shd.get(qn("w:fill")) != _HDR_COLOR:
                            continue
                        for para in cell.paragraphs:
                            for run in para.runs:
                                run.bold = True
                                run.font.color.rgb = _HDR_TXT

            document = Document()
            try:
                cp = document.core_properties
                cp.author = __author__
                cp.last_modified_by = __author__
                cp.title = f"{TOOL_NAME} Report"
                cp.subject = f"OT/ICS pcap analysis — {self.session.site}"
                cp.comments = (
                    f"Generated by {TOOL_NAME} v{VERSION}.  "
                    f"Tool authored by {__author__}.  {__copyright__}"
                )
                cp.category = "OT/ICS Security Assessment"
            except Exception:
                pass

            # ================================================================
            # 1. COVER PAGE
            # ================================================================
            title_para = document.add_heading(f"{TOOL_NAME} — OT/ICS Security Assessment", level=0)
            title_para.alignment = WD_ALIGN_PARAGRAPH.CENTER
            sub_para = document.add_paragraph()
            sub_para.alignment = WD_ALIGN_PARAGRAPH.CENTER
            sub_run = sub_para.add_run(
                "Audit Workpaper  ·  DRAFT — Validate all findings with site personnel before reporting"
            )
            sub_run.italic = True
            _add_kv_table([
                ("Site",        self.session.site or "—"),
                ("Assessor",    self.session.assessor or "—"),
                ("Session",     self.session.name or "—"),
                ("Generated",   utc_now_iso()),
                ("Risk Score",  f"{risk['score']} ({risk['band']})"),
            ])
            tool_credit_p = document.add_paragraph()
            tool_credit_run = tool_credit_p.add_run(
                f"Analysis Tool: {TOOL_NAME} v{VERSION} — authored by {__author__}.  {__copyright__}"
            )
            tool_credit_run.italic = True
            document.add_page_break()

            # ---- Table of Contents ----
            document.add_heading("Table of Contents", level=1)
            toc_para = document.add_paragraph()
            toc_run = toc_para.add_run()
            fldChar1 = OxmlElement("w:fldChar")
            fldChar1.set(qn("w:fldCharType"), "begin")
            instrText = OxmlElement("w:instrText")
            instrText.set(qn("xml:space"), "preserve")
            instrText.text = r'TOC \o "1-2" \h \z \u'
            fldChar2 = OxmlElement("w:fldChar")
            fldChar2.set(qn("w:fldCharType"), "separate")
            placeholder = OxmlElement("w:t")
            placeholder.text = "Right-click → Update Field to populate this Table of Contents."
            fldChar3 = OxmlElement("w:fldChar")
            fldChar3.set(qn("w:fldCharType"), "end")
            for el in (fldChar1, instrText, fldChar2, placeholder, fldChar3):
                toc_run._r.append(el)
            document.add_page_break()

            # ================================================================
            # 2. EXECUTIVE SUMMARY
            # ================================================================
            document.add_heading("Executive Summary", level=1)
            counts = risk.get("counts", {})
            sev_parts = []
            for sev in (SEVERITY_INTRUSION, SEVERITY_CRITICAL, SEVERITY_CORRELATION,
                        SEVERITY_HIGH, SEVERITY_MEDIUM, SEVERITY_LOW, SEVERITY_INFO):
                if counts.get(sev):
                    sev_parts.append(f"{counts[sev]} {sev}")
            sev_line = " · ".join(sev_parts) if sev_parts else "no findings"
            top_risk_items = self.compute_per_device_risk(top_n=5)
            top_asset_text = ""
            if top_risk_items:
                top_asset_text = "; ".join(
                    f"{item['ip']} ({item['role']}, score {item['score']})"
                    for item in top_risk_items[:3]
                )
            highest_finding = max(
                (f for f in self.session.findings),
                key=lambda f: SEVERITY_ORDER.get(f.severity, 0),
                default=None,
            )
            band_note = f"; {risk['band_reason']}" if risk.get("band_reason") else ""
            document.add_paragraph(
                f"Risk Score: {risk['score']} ({risk['band']}{band_note}).  "
                f"Finding breakdown: {sev_line}."
            )
            if coverage["total_packets"]:
                coverage_p = document.add_paragraph(
                    f"Traffic coverage: OTscope identified "
                    f"{format_share(coverage['identified_packets'], coverage['total_packets'])} of "
                    f"{coverage['total_packets']:,} packets."
                    + ("  Not identified: " + "; ".join(self._flow_text(c) for c in coverage["unidentified"][:3]) + "."
                       if coverage["unidentified"] else "")
                )
                if coverage["identified_packets"] < coverage["total_packets"] / 2:
                    coverage_p.add_run(
                        "  Most of the traffic could not be identified, so a low score does not mean the "
                        "capture is benign."
                    ).bold = True
            if top_asset_text:
                document.add_paragraph(f"Top affected assets: {top_asset_text}.")
            if highest_finding:
                document.add_paragraph(
                    f"Highest-severity finding ({highest_finding.severity}, {highest_finding.category}): "
                    f"{highest_finding.title}.  {lead_sentences(highest_finding.description, 3)}"
                )
                document.add_paragraph(
                    "Because OT traffic is highly context-dependent, the auditor should "
                    "validate asset roles, maintenance windows, and approved communications "
                    "with site personnel before concluding that any finding represents "
                    "malicious activity."
                )
            narrative_lines = [ln for ln in (correlation_lines or []) if ln.startswith("⚠")]
            if narrative_lines:
                document.add_paragraph("Attack Chain Indicators:")
                for ln in narrative_lines[:3]:
                    document.add_paragraph(ln, style="List Bullet")
            urgent_rows = [row for row in remediation_plan if row["priority"] <= 2][:3]
            if urgent_rows:
                document.add_paragraph("Immediate Next Steps:")
                for row in urgent_rows:
                    ids = ", ".join(item["id"] for item in row["findings"][:4] if item["id"])
                    step_p = document.add_paragraph(style="List Bullet")
                    step_p.add_run(f"{row['action']}: ").bold = True
                    step_p.add_run(row["steps"]["contain"] + (f" ({ids})" if ids else ""))
                document.add_paragraph(
                    "The Remediation Plan that follows lists every action by priority, with the devices "
                    "involved and the likely owner."
                )
            document.add_paragraph(
                "Companion artifacts generated alongside this report: "
                "JSON addendum (complete machine-readable findings), "
                "Device Inventory CSV (full asset list), "
                "Flow Allowlist CSV (observed flow tuples for segmentation review).  "
                + ("Appendix B (detailed technical evidence) is included at the end of this report."
                   if technical_appendix else
                   "Use --technical-appendix when generating the report to include "
                   "Appendix B with detailed packet-level evidence.")
            )
            document.add_page_break()

            # ================================================================
            # 2b. REMEDIATION PLAN
            # ================================================================
            if remediation_plan:
                document.add_heading("Remediation Plan", level=1)
                document.add_paragraph(
                    "What to fix, in priority order.  Findings that share the same fix are combined into one "
                    "row.  Each finding's “What to Do” section gives the step-by-step actions and an OT "
                    "safety note.  Agree every change with operations before acting: blocking OT traffic "
                    "can stop the process."
                )
                plan_table = document.add_table(rows=1, cols=5)
                _style_table(plan_table)
                for ci, h in enumerate(("Priority", "What to do", "Devices", "Findings", "Likely owner")):
                    plan_table.rows[0].cells[ci].text = h
                for row in remediation_plan:
                    pc = plan_table.add_row().cells
                    pc[0].text = f"{row['priority']} — {row['priority_label']}"
                    _shade_cell(pc[0], _PRIORITY_FILL.get(row["priority"], "FFFFFF"))
                    pc[1].text = row["action"]
                    shown_devices = row["devices"][:6]
                    pc[2].text = (", ".join(shown_devices) or "—") + (
                        f" (+{row['device_count'] - len(shown_devices)} more)"
                        if row["device_count"] > len(shown_devices) else "")
                    ids = [item["id"] for item in row["findings"] if item["id"]]
                    pc[3].text = ", ".join(ids[:8]) + (f" (+{len(ids) - 8} more)" if len(ids) > 8 else "")
                    pc[4].text = row["owner"]
                _set_col_widths(plan_table, (0.17, 0.33, 0.2, 0.15, 0.15))
                document.add_page_break()

            # ================================================================
            # 3. ENVIRONMENT DISCOVERY / CONTEXT
            # ================================================================
            document.add_heading("Environment Discovery and Context", level=1)
            document.add_paragraph(
                "Answers provided at session start.  These inform the analysis and should be "
                "validated against the actual site configuration."
            )
            _env_items = list(self.session.environment_answers.items())
            if _env_items:
                env_table = document.add_table(rows=1, cols=2)
                _style_table(env_table)
                env_table.rows[0].cells[0].text = "Parameter"
                env_table.rows[0].cells[1].text = "Value"
                for key, value in _env_items:
                    _er = env_table.add_row().cells
                    _er[0].text = key.replace("_", " ").title()
                    _er[1].text = value or "(not provided)"
            else:
                document.add_paragraph("No environment discovery answers were recorded.")

            # ================================================================
            # 4. PRIORITY FINDINGS
            # ================================================================
            document.add_heading("Priority Findings", level=1)
            document.add_paragraph(
                "Findings are grouped by category and ordered by severity.  "
                "CRITICAL and HIGH findings receive full detail: a summary box (what happened, why it "
                "matters, what to do now), numbered steps to contain, fix, and verify, then the evidence "
                "and reference details.  "
                "Lower-severity findings within the same category are summarized.  "
                "When the same issue occurs between several device pairs, each pair is listed separately.  "
                "Complete structured findings are in the JSON addendum.  "
                "Wireshark investigation steps are in Appendix A."
            )

            # Re-bucket by category
            issues_by_category: Dict[str, List[Dict[str, Any]]] = defaultdict(list)
            for issue in report_issues:
                issues_by_category[issue["category"]].append(issue)

            def _cat_priority(cat: str) -> Tuple[int, str]:
                top_sev = max(
                    (SEVERITY_ORDER.get(i["severity"], 0)
                     for i in issues_by_category[cat]),
                    default=0,
                )
                return (-top_sev, cat)

            ordered_categories = sorted(issues_by_category.keys(), key=_cat_priority)
            # Category -> distinct specific guides used by its findings.  Findings
            # with no specific guide point at the general steps instead.
            wireshark_categories_used: Dict[str, List[Tuple[str, List[str]]]] = defaultdict(list)
            general_guide_needed = False

            def _note_guide(category: str, finding: Finding) -> str:
                nonlocal general_guide_needed
                guide = wireshark_guide_for(finding)
                if guide is None:
                    general_guide_needed = True
                    return "Appendix A — General Investigation Steps"
                if guide not in wireshark_categories_used[category]:
                    wireshark_categories_used[category].append(guide)
                return f"Appendix A — {category}"
            EVIDENCE_CAP_FULL = 5
            EVIDENCE_CAP_ABBREV = 3
            EP_CAP = 20

            def _ep_str(src_ips, dst_ips) -> str:
                ep = list(dict.fromkeys(sorted(src_ips) + sorted(dst_ips)))
                if len(ep) > EP_CAP:
                    return (", ".join(ep[:EP_CAP])
                            + f" (+{len(ep) - EP_CAP} more — see Device Inventory CSV)")
                return ", ".join(ep) if ep else "—"

            def _roles_str(src_ips, dst_ips) -> str:
                def _fmt(ips):
                    parts = []
                    for ip in list(ips)[:2]:
                        dev = self.session.devices.get(ip)
                        parts.append(
                            f"{ip} ({dev.inferred_role})"
                            if dev and dev.inferred_role else ip
                        )
                    return ", ".join(parts)
                src = _fmt(src_ips)
                dst = _fmt(dst_ips)
                return f"{src} → {dst}" if dst else src

            def _mitre_str(finding) -> str:
                if not finding.mitre_ids:
                    return "—"
                parts = []
                for tid in finding.mitre_ids[:4]:
                    name = _MITRE_ICS_NAMES.get(tid, "")
                    parts.append(f"{tid} – {name}" if name else tid)
                return "; ".join(parts)

            OCCURRENCE_CAP_FULL = 8
            OCCURRENCE_CAP_ABBREV = 5
            EVIDENCE_OCCURRENCES = 4
            EVIDENCE_PER_OCCURRENCE = 2

            def _occurrence_bullets(issue: Dict[str, Any], cap: int, fid: str) -> None:
                """One bullet per finding merged into this issue: the devices involved, then what happened."""
                occurrences = issue["findings"]
                document.add_paragraph(f"Occurrences ({len(occurrences)}):")
                for finding in occurrences[:cap]:
                    bullet = document.add_paragraph(style="List Bullet")
                    bullet.add_run(occurrence_label(finding)).bold = True
                    repeats = f" (seen {finding.occurrences:,} times)" if finding.occurrences > 1 else ""
                    bullet.add_run(f"{repeats}: {lead_sentences(finding.description, 1)}")
                if len(occurrences) > cap:
                    document.add_paragraph(
                        f"(+{len(occurrences) - cap} more occurrences in JSON finding {fid})",
                        style="List Bullet",
                    )
                explanation = sentences_after(occurrences[0].description, 1)
                if explanation:
                    document.add_paragraph(explanation)

            def _render_full_finding(issue: Dict[str, Any], fid: str) -> None:
                representative = issue["findings"][0]
                others = len(issue["findings"]) - 1
                steps = remediation_for_finding(representative)
                sev = issue["severity"]
                color = _SEV_COLOR.get(sev, RGBColor(0x44, 0x44, 0x44))
                ws_ref = _note_guide(issue["category"], representative)

                h3 = document.add_heading(level=3)
                h3_run = h3.add_run(f"[{sev}]  {issue['title']}  ({fid})")
                h3_run.font.color.rgb = color

                happened = lead_sentences(issue["description"], 1)
                if others:
                    happened += f"  ({others} other occurrence{'s' if others > 1 else ''} listed under What Was Observed.)"
                _add_summary_box([
                    ("What happened", happened),
                    ("Why it matters", why_it_matters_plain(representative)),
                    ("What to do now", steps["contain"]),
                ])

                document.add_heading("What to Do", level=4)
                for number, (label, text) in enumerate(
                        (("Contain now", steps["contain"]), ("Fix", steps["fix"]), ("Verify", steps["verify"])),
                        start=1):
                    step_p = document.add_paragraph()
                    step_p.paragraph_format.left_indent = Inches(0.25)
                    step_p.add_run(f"{number}. {label}: ").bold = True
                    step_p.add_run(text)
                if steps["safety"]:
                    safety_p = document.add_paragraph()
                    safety_p.paragraph_format.left_indent = Inches(0.25)
                    safety_p.add_run("OT safety note: ").bold = True
                    safety_p.add_run(steps["safety"]).italic = True

                document.add_heading("What Was Observed", level=4)
                if others:
                    _occurrence_bullets(issue, OCCURRENCE_CAP_FULL, fid)
                else:
                    document.add_paragraph(issue["description"])

                document.add_heading("OT Significance", level=4)
                document.add_paragraph(ot_significance_for_finding(representative))

                document.add_heading("Key Evidence", level=4)
                if others:
                    shown: set = set()
                    for finding in issue["findings"][:EVIDENCE_OCCURRENCES]:
                        document.add_paragraph(occurrence_label(finding), style="List Bullet")
                        for line in finding.evidence[:EVIDENCE_PER_OCCURRENCE]:
                            document.add_paragraph(line, style="List Bullet 2")
                            shown.add(line)
                    remaining = len(set(issue["evidence"]) - shown)
                else:
                    for line in issue["evidence"][:EVIDENCE_CAP_FULL]:
                        document.add_paragraph(line, style="List Bullet")
                    remaining = len(issue["evidence"]) - EVIDENCE_CAP_FULL
                if remaining > 0:
                    document.add_paragraph(
                        f"(+{remaining} additional evidence lines in JSON finding {fid})",
                        style="List Bullet",
                    )

                document.add_heading("Auditor Guidance", level=4)
                for bullet in auditor_guidance_for_finding(representative):
                    document.add_paragraph(bullet, style="List Bullet")

                benign_p = document.add_paragraph()
                benign_p.add_run("What Would Make This Benign: ").bold = True
                benign_p.add_run(benign_explanation_for_finding(representative))

                document.add_heading("Reference", level=4)
                meta_rows = [
                    ("Finding ID",              fid),
                    ("Affected Assets",         _ep_str(issue["source_ips"], issue["destination_ips"])),
                    ("Inferred OT Roles",       _roles_str(issue["source_ips"], issue["destination_ips"])),
                    ("Category",                issue["category"]),
                    ("Likely Owner",            steps["owner"]),
                    ("MITRE ATT&CK for ICS",    _mitre_str(representative)),
                    ("Advisory References",     "; ".join(representative.advisory_refs[:3])
                                                if representative.advisory_refs else "—"),
                    ("Detection Confidence",    detection_confidence_for_finding(representative)),
                    ("Maliciousness Confidence",maliciousness_confidence_for_finding(representative)),
                    ("Operational Context",     "Yes — validate with site personnel"),
                ]
                _add_kv_table([(k, v) for k, v in meta_rows if v and v != "—"])

                detail_parts = [f"JSON finding {fid}", ws_ref]
                if technical_appendix:
                    detail_parts.append(f"Appendix B — {fid}")
                detail_p = document.add_paragraph()
                detail_r = detail_p.add_run(
                    "Details: See " + " · ".join(detail_parts) + "."
                )
                detail_r.italic = True

            def _render_abbrev_finding(issue: Dict[str, Any], fid: str) -> None:
                representative = issue["findings"][0]
                sev = issue["severity"]
                color = _SEV_COLOR.get(sev, RGBColor(0x44, 0x44, 0x44))
                _note_guide(issue["category"], representative)

                p = document.add_paragraph()
                title_run = p.add_run(f"[{sev}] {issue['title']}  ({fid})")
                title_run.bold = True
                title_run.font.color.rgb = color

                meta_line = f"Assets: {_ep_str(issue['source_ips'], issue['destination_ips'])}"
                if representative.mitre_ids:
                    meta_line += f"  |  MITRE: {', '.join(representative.mitre_ids[:2])}"
                mp = document.add_paragraph(meta_line)
                if mp.runs:
                    mp.runs[0].font.size = Pt(9)

                if len(issue["findings"]) > 1:
                    _occurrence_bullets(issue, OCCURRENCE_CAP_ABBREV, fid)
                else:
                    document.add_paragraph(issue["description"])
                    for line in issue["evidence"][:EVIDENCE_CAP_ABBREV]:
                        document.add_paragraph(line, style="List Bullet")
                fix_p = document.add_paragraph()
                fix_p.add_run("What to do: ").bold = True
                fix_p.add_run(recommended_fix_for_finding(representative))

            for category_name in ordered_categories:
                cat_issues = issues_by_category[category_name]
                cat_top_sev = max(
                    cat_issues,
                    key=lambda i: SEVERITY_ORDER.get(i["severity"], 0),
                )["severity"]
                document.add_heading(
                    f"{category_name}  "
                    f"({len(cat_issues)} finding(s), top severity: {cat_top_sev})",
                    level=2,
                )
                full_rendered = 0
                for idx, issue in enumerate(cat_issues):
                    fid = issue_ids.get(
                        (issue["category"], issue["title"]),
                        f"FIND-{idx+1:03d}",
                    )
                    sev_rank = SEVERITY_ORDER.get(issue["severity"], 0)
                    if sev_rank >= SEVERITY_ORDER.get(SEVERITY_HIGH, 3) or full_rendered == 0:
                        _render_full_finding(issue, fid)
                        full_rendered += 1
                    else:
                        _render_abbrev_finding(issue, fid)

            if protection_findings:
                document.add_heading("Suggested Controls", level=1)
                document.add_paragraph(
                    "Defensive measures suggested by what the capture contained.  These are "
                    "recommendations, not findings, and do not contribute to the risk score."
                )
                for finding in protection_findings[:20]:
                    control_p = document.add_paragraph(style="List Bullet")
                    control_p.add_run(f"{finding.title}: ").bold = True
                    control_p.add_run(finding.description)
            if assessor_notes:
                document.add_heading("Assessor Notes", level=1)
                for finding in assessor_notes:
                    document.add_paragraph(finding.description, style="List Bullet")

            # ================================================================
            # 6. NETWORK INTERPRETATION SUMMARY
            # ================================================================
            document.add_heading("Network Interpretation Summary", level=1)
            document.add_paragraph(
                "Observed communication patterns interpreted for the auditor.  "
                "All device roles are inferred from traffic and require site validation."
            )
            for para_text in build_network_interpretation_summary(self.session):
                document.add_paragraph(para_text)

            # ================================================================
            # 7. MITRE ATT&CK FOR ICS COVERAGE
            # ================================================================
            mitre_counts: Counter[str] = Counter()
            for finding in self.session.findings:
                for tid in finding.mitre_ids:
                    mitre_counts[tid] += 1
            if mitre_counts:
                document.add_heading("MITRE ATT&CK for ICS Coverage", level=1)
                document.add_paragraph(
                    "Technique IDs mapped from findings.  Indicates which MITRE ATT&CK for ICS "
                    "tactics are consistent with the observed traffic.  These are guidance for "
                    "further investigation, not proof of a specific attack or noncompliance."
                )
                mitre_table = document.add_table(rows=1, cols=3)
                _style_table(mitre_table)
                mh = mitre_table.rows[0].cells
                mh[0].text = "Technique ID"
                mh[1].text = "Technique Name"
                mh[2].text = "Findings"
                for tid, cnt in mitre_counts.most_common():
                    mr = mitre_table.add_row().cells
                    _add_hyperlink_to_cell(
                        mr[0],
                        f"https://attack.mitre.org/techniques/{tid}/",
                        tid,
                    )
                    mr[1].text = _MITRE_ICS_NAMES.get(tid, "—")
                    mr[2].text = str(cnt)

            # ================================================================
            # 8. DEVICE INVENTORY SUMMARY
            # ================================================================
            document.add_heading("Device Inventory Summary", level=1)
            all_devices_sorted = sorted(
                self.session.devices.values(),
                key=lambda d: (d.outgoing_count + d.incoming_count),
                reverse=True,
            )
            total_devices = len(all_devices_sorted)
            document.add_paragraph(
                f"Total observed devices: {total_devices:,}.  "
                "Top 15 by traffic are shown below.  Broadcast and multicast destinations are not "
                "devices; they are listed in the Network Interpretation Summary.  "
                "The complete Device Inventory CSV (all devices, all fields) is written "
                "alongside this report."
            )
            DEVICE_SUMMARY_CAP = 15
            device_risk_lookup = {
                item["ip"]: item["score"]
                for item in self.compute_per_device_risk(top_n=50)
            }
            dev_sum_table = document.add_table(rows=1, cols=6)
            _style_table(dev_sum_table)
            dsh = dev_sum_table.rows[0].cells
            for ci, h in enumerate(["IP", "MAC (vendor)", "Inferred Role", "Zone", "Protocols", "Risk Score"]):
                dsh[ci].text = h
            for device in all_devices_sorted[:DEVICE_SUMMARY_CAP]:
                dr = dev_sum_table.add_row().cells
                dr[0].text = device.ip + (f" / {', '.join(device.ipv6_addresses[:1])}" if device.ipv6_addresses else "")
                mac_parts = [f"{mac} ({lookup_oui_vendor(mac)})" if lookup_oui_vendor(mac) else mac
                             for mac in device.macs[:2]]
                dr[1].text = ("⚠ " if len(device.macs) > 1 else "") + ("; ".join(mac_parts) or "—")
                dr[2].text = device.inferred_role or "—"
                dr[3].text = device.inferred_zone or "—"
                dr[4].text = ", ".join(device.protocols[:5]) or "—"
                dr[5].text = str(device_risk_lookup.get(device.ip, 0))
            observed = [(device.ip, note) for device in all_devices_sorted for note in device.evidence]
            if observed:
                document.add_paragraph("Device observations:")
                for ip_text, note in observed[:20]:
                    document.add_paragraph(f"{ip_text}: {note}", style="List Bullet")

            # ================================================================
            # 9. FLOW ALLOWLIST SUMMARY
            # ================================================================
            document.add_heading("Flow Allowlist Summary", level=1)
            flow_count = len(self.session.connections)
            document.add_paragraph(
                f"A total of {flow_count:,} unique source/destination/port/protocol flow "
                "tuples were observed.  The complete Flow Allowlist CSV is written alongside "
                "this report and can be used as input for firewall policy review or "
                "segmentation gap analysis.  Each row is a communication path actually "
                "observed; flows not in the CSV but permitted by policy may indicate "
                "unnecessary exposure."
            )
            document.add_paragraph(
                "Auditor note: the Flow Allowlist does not distinguish authorized from "
                "unauthorized flows — it is an observed inventory.  Compare it against "
                "the site’s approved communication matrix to identify undocumented paths."
            )

            # ================================================================
            # 10. LIMITATIONS OF ANALYSIS
            # ================================================================
            document.add_heading("Limitations of Analysis", level=1)
            document.add_paragraph(
                "The following limitations apply to all findings in this report and should "
                "be disclosed when presenting results in a formal audit."
            )
            limitations = [
                "PCAP-only analysis.  This report is based solely on observed network traffic.  "
                "It cannot confirm asset ownership, operator intent, system purpose, or whether "
                "observed behavior was authorized.",
                "Inferred roles and zones require site validation.  Device roles and Purdue "
                "model zone assignments are inferred from traffic patterns.  They must be "
                "confirmed with site staff and physical inspection.",
                "Maintenance window context is unknown.  The tool has no visibility into "
                "approved maintenance windows or change records.  Anomalous-looking activity "
                "may be fully authorized, increasing false-positive risk.",
                "No known-good baseline.  Without a baseline from a validated normal period, "
                "anomaly detections cannot be distinguished from normal process behavior.  "
                "Use --compare-baseline to reduce this limitation.",
                "Advisory and framework mappings are guidance, not findings of noncompliance.  "
                "MITRE ATT&CK for ICS technique IDs indicate what observed behavior is "
                "consistent with — not proof of an attack or standards violation.",
                "OT protocol coverage is not exhaustive.  This tool covers the most common "
                "OT/ICS protocols but may not recognize all proprietary protocols in use.",
                "Blocking OT traffic without operational validation can disrupt physical "
                "processes.  No remediation action should be taken without coordination with "
                "the process owner, controls engineer, and operations management.",
            ]
            for lim in limitations:
                document.add_paragraph(lim, style="List Bullet")

            # ================================================================
            # APPENDIX A: WIRESHARK INVESTIGATION GUIDE
            # ================================================================
            if wireshark_categories_used or general_guide_needed:
                document.add_page_break()
                document.add_heading("Appendix A: Wireshark Investigation Guide", level=1)
                document.add_paragraph(
                    "Per-category instructions for investigating findings in Wireshark.  "
                    "Evidence lines that end with @<epoch> can be pasted into Wireshark as "
                    "`frame.time_epoch == <value>` to jump to the exact frame.  "
                    "Lines with an Observation Window provide two epoch values — use "
                    "`frame.time_epoch >= A && frame.time_epoch <= B` to bracket the window."
                )
                for cat in sorted(wireshark_categories_used):
                    document.add_heading(cat, level=2)
                    for ws_filter_a, ws_steps_a in wireshark_categories_used[cat]:
                        if ws_filter_a:
                            filter_p = document.add_paragraph()
                            filter_p.add_run("Display filter: ").bold = True
                            filter_p.add_run(ws_filter_a)
                        for step in ws_steps_a:
                            document.add_paragraph(step, style="List Bullet")
                if general_guide_needed:
                    document.add_heading("General Investigation Steps", level=2)
                    for step in _WIRESHARK_FALLBACK[1]:
                        document.add_paragraph(step, style="List Bullet")

            # ================================================================
            # APPENDIX B: DETAILED TECHNICAL EVIDENCE (--technical-appendix)
            # ================================================================
            if technical_appendix:
                document.add_page_break()
                document.add_heading("Appendix B: Detailed Technical Evidence", level=1)
                document.add_paragraph(
                    "This appendix is included because --technical-appendix was specified.  "
                    "It contains full packet-level evidence and supporting detail for all "
                    "findings.  The main report body summarizes only the most actionable items."
                )
                # Timeline / Attack Chain
                severity_rank_b = {
                    SEVERITY_INTRUSION: 6, SEVERITY_CRITICAL: 5,
                    SEVERITY_CORRELATION: 4, SEVERITY_HIGH: 3,
                    SEVERITY_MEDIUM: 2, SEVERITY_LOW: 1, SEVERITY_INFO: 0,
                }
                timeline_events = []
                for finding in self.session.findings:
                    if severity_rank_b.get(finding.severity, 0) < 2 or not finding.first_seen:
                        continue
                    try:
                        ts_val = float(finding.first_seen)
                        ts_iso = (datetime.fromtimestamp(ts_val, timezone.utc)
                                  .replace(tzinfo=None).isoformat() + "Z")
                    except (TypeError, ValueError):
                        ts_iso = finding.first_seen
                        try:
                            ts_val = datetime.fromisoformat(
                                finding.first_seen.replace("Z", "+00:00")
                            ).timestamp()
                        except Exception:
                            ts_val = 0.0
                    timeline_events.append((ts_val, ts_iso, finding))
                timeline_events.sort(key=lambda x: x[0])
                if timeline_events:
                    document.add_heading("B.1  Timeline / Attack Chain", level=2)
                    document.add_paragraph(
                        "Chronological ordering of MEDIUM+ findings by first observation."
                    )
                    tl_table = document.add_table(rows=1, cols=5)
                    _style_table(tl_table)
                    tl_hdr = tl_table.rows[0].cells
                    for ci, h in enumerate(
                        ["First Seen (UTC)", "Severity", "Title",
                         "Source → Dest", "MITRE"]
                    ):
                        tl_hdr[ci].text = h
                    for _, ts_iso_b, finding in timeline_events[:80]:
                        rc = tl_table.add_row().cells
                        rc[0].text = ts_iso_b
                        rc[1].text = finding.severity
                        rc[2].text = finding.title
                        ep_b = (
                            f"{','.join(finding.source_ips[:2])} "
                            f"→ {','.join(finding.destination_ips[:2])}"
                        ).strip(" →")
                        rc[3].text = ep_b or "—"
                        rc[4].text = ", ".join(finding.mitre_ids[:3])

                # Full evidence for every finding
                document.add_heading("B.2  Full Evidence by Finding", level=2)
                for issue in report_issues:
                    fid_b = issue_ids.get((issue["category"], issue["title"]), "?")
                    representative_b = issue["findings"][0]
                    bp = document.add_paragraph()
                    brun = bp.add_run(
                        f"[{issue['severity']}] {issue['title']}  ({fid_b})"
                    )
                    brun.bold = True
                    brun.font.color.rgb = _SEV_COLOR.get(
                        issue["severity"], RGBColor(0x44, 0x44, 0x44)
                    )
                    for line in issue["evidence"]:
                        document.add_paragraph(line, style="List Bullet")
                    fp2 = document.add_paragraph()
                    fp2.add_run("Recommended Fix: ").bold = True
                    fp2.add_run(recommended_fix_for_finding(representative_b))

                # Full network map
                document.add_heading("B.3  Inferred Network Map", level=2)
                document.add_paragraph("Inferred from observed traffic.  Validate with site staff.")
                nm_para = document.add_paragraph()
                nm_run = nm_para.add_run(network_map)
                nm_run.font.name = "Courier New"
                nm_run.font.size = Pt(9)

                # Top riskiest devices
                top_risk = self.compute_per_device_risk(top_n=15)
                if top_risk:
                    document.add_heading("B.4  Top Riskiest Devices", level=2)
                    risk_table = document.add_table(rows=1, cols=6)
                    _style_table(risk_table)
                    rh = risk_table.rows[0].cells
                    for ci, h in enumerate(
                        ["IP", "Role", "Score", "CRIT", "HIGH", "Top Finding"]
                    ):
                        rh[ci].text = h
                    for item in top_risk:
                        rr = risk_table.add_row().cells
                        rr[0].text = item["ip"]
                        rr[1].text = item["role"]
                        rr[2].text = str(item["score"])
                        rr[3].text = str(item["critical"])
                        rr[4].text = str(item["high"])
                        rr[5].text = item["top_titles"][0] if item["top_titles"] else ""

                # Full device inventory
                DEVICE_TABLE_CAP = 200
                document.add_heading("B.5  Full Device Inventory", level=2)
                shown_devices_b = all_devices_sorted[:DEVICE_TABLE_CAP]
                if total_devices > DEVICE_TABLE_CAP:
                    document.add_paragraph(
                        f"Top {DEVICE_TABLE_CAP} by traffic out of {total_devices:,} total.  "
                        "See Device Inventory CSV for the complete list."
                    )
                else:
                    document.add_paragraph(f"All {total_devices:,} observed device(s).")
                inv_table = document.add_table(rows=1, cols=8)
                _style_table(inv_table)
                inv_h = inv_table.rows[0].cells
                for ci, h in enumerate(
                    ["IP", "Role", "Zone", "Vendor/OS", "Protocols", "Ports", "VLANs", "Pcaps"]
                ):
                    inv_h[ci].text = h
                for device in shown_devices_b:
                    dr = inv_table.add_row().cells
                    dr[0].text = device.ip
                    dr[1].text = device.inferred_role
                    dr[2].text = device.inferred_zone
                    vendor_bits: List[str] = []
                    if device.vendors:
                        vendor_bits.append("/".join(device.vendors[:3]))
                    if device.os_fingerprint:
                        vendor_bits.append(device.os_fingerprint)
                    dr[3].text = " · ".join(vendor_bits) or "—"
                    dr[4].text = ", ".join(device.protocols[:8])
                    dr[5].text = ", ".join(str(p) for p in sorted(device.ports)[:12])
                    dr[6].text = ", ".join(sorted(device.vlans)) or "—"
                    pc_list = sorted(device.source_pcaps)
                    pc_text = ", ".join(pc_list[:3])
                    if len(pc_list) > 3:
                        pc_text += f" (+{len(pc_list) - 3} more)"
                    dr[7].text = pc_text

            _color_header_text()
            document.save(report_path)
            self._note_artifact(report_path, "Word report — start with the Remediation Plan", "Word report written")
            # Always generate companion artifacts alongside the Word report.
            try:
                self.generate_json_report()
            except Exception as exc:
                print(f"[!] JSON report generation failed: {exc}")
            try:
                self.generate_purdue_svgs()
            except Exception as exc:
                print(f"[!] Purdue SVG generation failed: {exc}")
            return report_path
        except Exception as exc:
            fallback_path = report_path.with_suffix(".txt")
            fallback_text = [
                f"{TOOL_NAME} Report",
                f"Site: {self.session.site}",
                f"Assessor: {self.session.assessor}",
                f"Session: {self.session.name}",
                f"Generated: {utc_now_iso()}",
                "",
                f"Overall Risk Score: {risk['score']} ({risk['band']})"
                + (f" — {risk['band_reason']}" if risk.get("band_reason") else ""),
                f"Traffic coverage: {format_share(coverage['identified_packets'], coverage['total_packets'])} of "
                f"{coverage['total_packets']:,} packets identified"
                + ("; not identified: " + "; ".join(self._flow_text(c) for c in coverage["unidentified"][:3])
                   if coverage["unidentified"] else ""),
                "",
                "Remediation Plan:",
            ]
            for row in remediation_plan:
                ids = ", ".join(item["id"] for item in row["findings"] if item["id"])
                devices = ", ".join(row["devices"][:6]) + (
                    f" (+{row['device_count'] - 6} more)" if row["device_count"] > 6 else "")
                fallback_text.append(
                    f"  - Priority {row['priority']} ({row['priority_label']}): {row['action']} — findings {ids}; "
                    f"devices {devices or '—'}; likely owner: {row['owner']}"
                )
            if not remediation_plan:
                fallback_text.append("  - No findings require action.")
            fallback_text.extend(["", "Correlation Summary:"])
            if correlation_lines:
                fallback_text.extend([f"  - {line}" for line in correlation_lines])
            else:
                fallback_text.append("  - No higher-order correlations were automatically identified.")
            fallback_text.extend([
                "",
                "Suggested Controls:",
            ])
            if protection_findings:
                fallback_text.extend([f"  - {finding.title}: {recommended_fix_for_finding(finding)}" for finding in protection_findings[:10]])
            else:
                fallback_text.append("  - No additional control recommendations were generated.")
            fallback_text.extend([
                "",
                "Findings:",
            ])
            for issue in report_issues:
                representative = issue["findings"][0]
                why_text = why_this_matters_for_finding(representative)
                steps = remediation_for_finding(representative)
                related = related_findings_for_finding(self.session, representative)
                fid = issue_ids.get((issue["category"], issue["title"]), "")
                fallback_text.append(f"[{issue['severity']}] {fid}  {issue['title']}")
                fallback_text.append(f"  {issue['description']}")
                if len(issue["findings"]) > 1:
                    fallback_text.append(f"  Occurrences ({len(issue['findings'])}):")
                    for finding in issue["findings"][:20]:
                        fallback_text.append(f"    - {occurrence_label(finding)}: {lead_sentences(finding.description, 1)}")
                    if len(issue["findings"]) > 20:
                        fallback_text.append(f"    - (+{len(issue['findings']) - 20} more)")
                fallback_text.append(f"  Why This Matters: {why_text}")
                fallback_text.append("  What to Do:")
                fallback_text.append(f"    1. Contain now: {steps['contain']}")
                fallback_text.append(f"    2. Fix: {steps['fix']}")
                fallback_text.append(f"    3. Verify: {steps['verify']}")
                if steps["safety"]:
                    fallback_text.append(f"    OT safety note: {steps['safety']}")
                if issue["source_ips"] or issue["destination_ips"]:
                    endpoints = list(dict.fromkeys(sorted(issue["source_ips"]) + sorted(issue["destination_ips"])))
                    if len(endpoints) > 30:
                        fallback_text.append(
                            f"  Affected Endpoints ({len(endpoints):,} total, showing first 30): "
                            + ", ".join(endpoints[:30])
                            + f" … (+{len(endpoints) - 30:,} more — see Device Inventory CSV)"
                        )
                    else:
                        fallback_text.append(f"  Affected Endpoints: {', '.join(endpoints)}")
                if issue["source_pcaps"]:
                    pcaps_sorted = sorted(issue["source_pcaps"])
                    if len(pcaps_sorted) > 8:
                        fallback_text.append(
                            f"  Source Pcaps ({len(pcaps_sorted)} total, showing 8): "
                            + ", ".join(pcaps_sorted[:8])
                            + f" … (+{len(pcaps_sorted) - 8} more)"
                        )
                    else:
                        fallback_text.append(f"  Source Pcaps: {', '.join(pcaps_sorted)}")
                fallback_text.append("  Evidence:")
                for line in issue["evidence"][:30]:
                    fallback_text.append(f"    - {line}")
                ws_filter, ws_steps = wireshark_steps_for_finding(representative)
                fallback_text.append("  Wireshark Investigation:")
                if ws_filter:
                    fallback_text.append(f"    Display filter: {ws_filter}")
                fallback_text.append(
                    "    Tip: where an evidence line ends with @<epoch>, paste that "
                    "into Wireshark as `frame.time_epoch == <value>` to land on the "
                    "exact frame. Otherwise look for an 'Observation window' line "
                    "with two epochs and use `frame.time_epoch >= A && frame.time_epoch <= B`."
                )
                for idx_s, step in enumerate(ws_steps, start=1):
                    fallback_text.append(f"    {idx_s}. {step}")
                if representative.advisory_refs:
                    fallback_text.append(
                        f"  Advisory / Standards References: {'; '.join(representative.advisory_refs)}"
                    )
                if representative.mitre_ids:
                    fallback_text.append(
                        f"  MITRE ATT&CK for ICS: {', '.join(representative.mitre_ids)}"
                    )
                if related:
                    fallback_text.append(f"  Related Findings: {', '.join(related)}")
            top_risk = self.compute_per_device_risk(top_n=15)
            fallback_text.extend(["", "Top Riskiest Devices (severity-weighted):"])
            if top_risk:
                for item in top_risk:
                    fallback_text.append(
                        f"  - {item['ip']} ({item['role']}) score={item['score']} "
                        f"crit={item['critical']} high={item['high']} findings={item['findings']}"
                    )
            else:
                fallback_text.append("  - No scored findings were attributable to specific devices.")
            # MITRE ATT&CK for ICS roll-up
            mitre_counts: Counter[str] = Counter()
            for finding in self.session.findings:
                for tid in finding.mitre_ids:
                    mitre_counts[tid] += 1
            if mitre_counts:
                fallback_text.extend(["", "MITRE ATT&CK for ICS Coverage:"])
                for tid, cnt in mitre_counts.most_common():
                    fallback_text.append(f"  - {tid}: {cnt} finding(s)")
            fallback_text.extend(["", "Network Map:", network_map])
            fallback_path.write_text("\n".join(fallback_text), encoding="utf-8")
            self.artifacts_written.append((fallback_path, "Plain-text report (Word generation failed)"))
            print(colorize(f"[!] Word report generation failed ({exc}). Plain-text report saved to {fallback_path}", SEVERITY_HIGH))
            return fallback_path

    def generate_json_report(self) -> Path:
        """Export findings, devices, and risk summary as a structured JSON file.

        Useful for ingestion into SIEMs, ticketing systems, or comparison across
        multiple assessments without parsing a Word document.
        """
        assert self.session is not None
        report_date = datetime.now().strftime("%Y%m%d")
        folder = Path(self.session.folder)
        base_name = f"OT_PCAP_Analysis_{safe_slug(self.session.site)}_{report_date}"
        report_path = _versioned_path(folder, base_name, "json")
        risk = self.compute_risk_summary()
        report_issues = [issue for issue in aggregated_report_issues(self.session)
                         if issue["category"] not in NON_SCORING_CATEGORIES]
        issue_ids = report_issue_ids(report_issues)
        coverage = self.traffic_coverage()
        report_data: Dict[str, Any] = {
            "tool": TOOL_NAME,
            "version": VERSION,
            "tool_author": __author__,
            "tool_copyright": __copyright__,
            "generated": utc_now_iso(),
            "site": self.session.site,
            "assessor": self.session.assessor,
            "session": self.session.name,
            "risk": risk,
            "environment": self.session.environment_answers,
            "pcaps": {k: asdict(v) for k, v in self.session.processed_pcaps.items()},
            "devices": {k: asdict(v) for k, v in self.session.devices.items()},
            "findings": [
                {"report_id": issue_ids.get((f.category, f.title), ""), **asdict(f)}
                for f in sorted(
                    self.session.findings,
                    key=lambda f: SEVERITY_ORDER.get(f.severity, 0),
                    reverse=True,
                )
            ],
            "remediation_plan": build_remediation_plan(report_issues, issue_ids),
            "traffic_coverage": {
                "total_packets": coverage["total_packets"],
                "identified_packets": coverage["identified_packets"],
                "identified_percent": round(100.0 * coverage["identified_packets"] / coverage["total_packets"], 1)
                                      if coverage["total_packets"] else None,
                "unidentified_flows": [
                    {name: flow[name] for name in ("transport", "client", "server", "port", "packets")}
                    for flow in coverage["unidentified"][:25]
                ],
            },
            "connections_count": len(self.session.connections),
            "correlation_summary": correlation_summary_lines(self.session),
        }
        report_path.write_text(pretty_json(report_data), encoding="utf-8")
        self._note_artifact(report_path, "Findings, devices, and remediation plan (machine-readable)", "JSON report written")
        return report_path

    def export_device_inventory_csv(self) -> Path:
        """Export the full device inventory as a CSV addendum.

        Always written alongside any Word/JSON report.  The Word report's
        Device Inventory table is capped at the top 200 devices by traffic
        volume so the .docx stays readable; this CSV carries the entire
        device list for grep/filter/Excel-pivot work on flood-scale
        captures (1M+ unique source IPs).
        """
        assert self.session is not None
        report_date = datetime.now().strftime("%Y%m%d")
        folder = Path(self.session.folder)
        base_name = f"OT_Device_Inventory_{safe_slug(self.session.site)}_{report_date}"
        inventory_path = _versioned_path(folder, base_name, "csv")
        # Pre-compute critical-IP set once for the marker column.
        critical_ips: set = set()
        for finding in self.session.findings:
            if finding.severity in {SEVERITY_CRITICAL, SEVERITY_INTRUSION}:
                critical_ips.update(finding.source_ips)
                critical_ips.update(finding.destination_ips)
        # Sort by total traffic descending so flood sources fall to the bottom of
        # the natural sort but are still present.
        all_devices = sorted(
            self.session.devices.values(),
            key=lambda d: (d.outgoing_count + d.incoming_count),
            reverse=True,
        )
        buf = io.StringIO()
        writer = csv.writer(buf, lineterminator="\n")
        writer.writerow([
            "ip", "role", "zone", "vendors", "os_fingerprint",
            "outgoing_pkts", "incoming_pkts", "total_pkts",
            "protocols", "ports", "vlans", "mac_addresses", "subnets",
            "source_pcaps", "is_critical_in_findings",
            "client_ports", "ipv6_link_local", "observations",
        ])
        for d in all_devices:
            total_pkts = d.outgoing_count + d.incoming_count
            writer.writerow([
                d.ip,
                d.inferred_role,
                d.inferred_zone,
                "/".join(d.vendors[:5]),
                d.os_fingerprint,
                str(d.outgoing_count),
                str(d.incoming_count),
                str(total_pkts),
                "|".join(d.protocols),
                "|".join(str(p) for p in sorted(d.ports)),
                "|".join(sorted(d.vlans)),
                "|".join(sorted(d.macs)),
                "|".join(sorted(d.subnets)),
                "|".join(sorted(d.source_pcaps)),
                "yes" if d.ip in critical_ips else "no",
                "|".join(str(p) for p in sorted(d.client_ports)),
                "|".join(d.ipv6_addresses),
                " | ".join(d.evidence),
            ])
        inventory_path.write_text(buf.getvalue(), encoding="utf-8")
        self._note_artifact(inventory_path, "Full device list", "Device inventory written",
                            f" ({len(all_devices):,} devices)")
        return inventory_path

    def export_flow_allowlist(self) -> Path:
        """Export observed (src, dst, dst_port, proto) tuples as a CSV allowlist.

        Intended to seed firewall / zone-conduit rules: one row per observed
        flow with packet counts, grouped by frequency.  The asset owner reviews
        each row and either keeps it (documented normal) or removes it (flag
        for investigation).  This is the lowest-friction path from passive
        observation to an enforced segmentation policy.
        """
        assert self.session is not None
        report_date = datetime.now().strftime("%Y%m%d")
        folder = Path(self.session.folder)
        base_name = f"OT_Flow_Allowlist_{safe_slug(self.session.site)}_{report_date}"
        allowlist_path = _versioned_path(folder, base_name, "csv")
        rows: List[Tuple[int, str, str, int, str, str, str]] = []
        for conn in self.session.connections.values():
            src_dev = self.session.devices.get(conn.source_ip)
            dst_dev = self.session.devices.get(conn.destination_ip)
            src_role = src_dev.inferred_role if src_dev else ""
            dst_role = dst_dev.inferred_role if dst_dev else ""
            rows.append((
                conn.packet_count,
                conn.source_ip,
                conn.destination_ip,
                conn.destination_port,
                conn.protocol,
                src_role,
                dst_role,
            ))
        rows.sort(key=lambda r: r[0], reverse=True)
        buf = io.StringIO()
        writer = csv.writer(buf, lineterminator="\n")
        writer.writerow(["packets", "src_ip", "dst_ip", "dst_port", "protocol",
                         "src_role", "dst_role", "action"])
        for pkts, s, d, p, proto, sr, dr in rows:
            # default action is ALLOW; asset owner edits before enforcement
            writer.writerow([pkts, s, d, p, proto, sr, dr, "ALLOW"])
        allowlist_path.write_text(buf.getvalue(), encoding="utf-8")
        self._note_artifact(allowlist_path, "Observed flows, for firewall and segmentation review", "Flow allowlist written",
                            f" ({len(rows):,} flow{'s' if len(rows) != 1 else ''})")
        return allowlist_path

    def analyze_pcaps(self, pcaps: Sequence[Path]) -> None:
        """Run the full analysis pipeline for one or more new pcaps."""
        if self.session is None:
            raise RuntimeError("No active session.")
        self.run_capture_inventory(pcaps)
        self.run_optional_checks(pcaps)
        self._infer_roles_and_zones()
        # Baseline diff — only if the session declares a baseline file
        baseline_path_text = (self.session.environment_answers.get("baseline_file") or "").strip()
        if baseline_path_text:
            baseline_path = Path(baseline_path_text).expanduser()
            if baseline_path.exists():
                self.compare_to_baseline(baseline_path)
            else:
                print(colorize(f"[!] Baseline file not found: {baseline_path}. Skipping diff.", SEVERITY_MEDIUM))
        # Save current state as a baseline if requested
        save_baseline_flag = (self.session.environment_answers.get("save_as_baseline") or "").strip().lower()
        if save_baseline_flag.startswith("y"):
            folder = Path(self.session.folder)
            baseline_out = folder / f"{safe_slug(self.session.site)}_baseline.otpa_baseline"
            # Don't overwrite an existing baseline silently
            version = 1
            while baseline_out.exists():
                version += 1
                baseline_out = folder / f"{safe_slug(self.session.site)}_baseline_v{version}.otpa_baseline"
            self.save_baseline(baseline_out)
        summary = self.compute_risk_summary()
        print_header("Risk Summary")
        print(colorize(risk_banner(summary["band"]), SEVERITY_CRITICAL if summary["band"] in {"HIGH", "SEVERE"} else SEVERITY_MEDIUM, bold=True))
        print(f"    Score {summary['score']}" + (f" — band {summary['band_reason']}" if summary.get("band_reason") else "")
              + ("" if self.session.findings else " — no findings."))
        coverage = self.traffic_coverage()
        if coverage["total_packets"] and coverage["identified_packets"] < coverage["total_packets"] / 2:
            print(colorize(
                f"    [!] Only {format_share(coverage['identified_packets'], coverage['total_packets'])} of the "
                "traffic was identified, so this score does not mean the capture is benign.", SEVERITY_MEDIUM))
        for item in summary["top_contributors"]:
            print(f"    - [{item['severity']}] {item['title']} (weight {item['weight']})")
        # Print top-5 riskiest devices for quick triage
        top_risk = self.compute_per_device_risk(top_n=5)
        if top_risk:
            print_header("Top 5 Riskiest Devices")
            for item in top_risk:
                print(f"    - {item['ip']:<18} {item['role']:<30} "
                      f"score={item['score']:<5} crit={item['critical']} high={item['high']} findings={item['findings']}")
        # Always export a flow allowlist CSV alongside reports.  This is
        # small, plain-text, and the single most actionable artifact for
        # asset owners to turn observation into segmentation policy.
        try:
            self.export_flow_allowlist()
        except Exception as exc:
            print(colorize(f"[!] Flow allowlist export failed: {exc}", SEVERITY_MEDIUM))
        # Full device inventory addendum so flood-scale captures don't
        # bloat the Word report — the in-document table is capped, this
        # CSV carries the rest.
        try:
            self.export_device_inventory_csv()
        except Exception as exc:
            print(colorize(f"[!] Device inventory export failed: {exc}", SEVERITY_MEDIUM))
        if not NON_INTERACTIVE:
            note_text = input("[?] Final assessor note before save/report (blank to skip): ").strip()
            if note_text:
                self.add_note(note_text)
        self.save_session()


CURRENT_ANALYZER: Optional[OTPcapAnalyzer] = None


def print_banner() -> None:
    """Print the welcome banner."""
    print(colorize(f"{TOOL_NAME} v{VERSION}", bold=True))
    print(colorize(f"Authored by {__author__}.  {__copyright__}", bold=True))
    print("Interactive multi-pcap OT/ICS traffic analysis with session persistence, role inference, and report generation.")


def print_network_safety_banner() -> None:
    """Explain exactly what (if anything) the tool will reach out to.

    Printed once at startup so the operator sees the network-touch
    behavior before any pcap is loaded.  Important when analyzing
    captures from an unknown source — operators need a clear, verifiable
    statement of what their machine will and won't generate as outbound
    traffic during analysis.
    """
    print(colorize("\nNetwork-safety status:", bold=True))
    print("  • Tool is read-only on pcap data — never connects to any IP "
          "found in the capture.")
    print("  • tshark is invoked with -n (no name resolution).")
    if OFFLINE_MODE:
        print(colorize(
            "  • OFFLINE MODE LOCKED (--offline): no PTR/RDAP/DNS calls of "
            "any kind. Reports will omit owner/country enrichment.",
            "SUCCESS"))
    else:
        print("  • Public-IP enrichment (PTR + RDAP via rdap.org) WILL run "
              "for any public IPs that appear as destinations of OT-classed")
        print("    devices. Answer 'yes' to the air-gapped questionnaire "
              "item or pass --offline to suppress all such calls.")
    print()


def saved_sessions(folder: Path) -> List[Path]:
    """Session files in a folder, most recently updated first."""
    try:
        return sorted(folder.glob("*.otpa_session"), key=lambda item: item.stat().st_mtime, reverse=True)
    except OSError:
        return []


def describe_session_file(path: Path) -> str:
    """One line describing a saved session: site, captures, findings, last update."""
    try:
        stat = path.stat()
    except OSError:
        return path.stem
    details = [f"updated {datetime.fromtimestamp(stat.st_mtime).strftime('%Y-%m-%d %H:%M')}"]
    # Sessions of flood-scale captures can be large; describe those by date only.
    if stat.st_size <= 20 * 1024 * 1024:
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
            captures = len(payload.get("processed_pcaps") or {})
            findings = len(payload.get("findings") or [])
            details = [f"site {payload.get('site') or '—'}",
                       f"{captures} capture{'s' if captures != 1 else ''}",
                       f"{findings} finding{'s' if findings != 1 else ''}"] + details
        except (OSError, ValueError):
            pass
    return f"{path.stem} — {', '.join(details)}"


def default_session_folder(config: Dict[str, Any]) -> Path:
    """Where saved sessions are: output\\ next to the script, else the last capture folder."""
    if _OUTPUT_ROOT.is_dir():
        return _OUTPUT_ROOT
    return Path(config.get("last_pcap_folder") or ".").expanduser()


def unique_session_name(folder: Path, name: str) -> str:
    """First of name_2, name_3, … that has no session file in folder."""
    base = safe_slug(name)
    index = 2
    while (folder / f"{base}_{index}.otpa_session").exists():
        index += 1
    return f"{base}_{index}"


def choose_session_file(folder: Path) -> Optional[Path]:
    """List saved sessions; pick one by number or name, or look in another folder."""
    while True:
        sessions = saved_sessions(folder)
        if sessions:
            print(f"\nSaved sessions in {folder}:")
            for index, path in enumerate(sessions, start=1):
                print(f"    {index}. {describe_session_file(path)}")
            answer = prompt_input("Select a session (number or name), or enter another folder to look in")
        else:
            print(f"[!] No saved sessions in {folder}.")
            answer = prompt_input("Folder containing the session file (blank to cancel)")
        if not answer:
            return None
        if answer.isdigit() and sessions:
            if 1 <= int(answer) <= len(sessions):
                return sessions[int(answer) - 1]
            print(f"[!] Choose a number from 1 to {len(sessions)}.")
            continue
        named = [path for path in sessions if answer.lower() in (path.stem.lower(), path.name.lower())]
        if named:
            return named[0]
        candidate = Path(answer).expanduser()
        if candidate.is_file() and candidate.suffix == ".otpa_session":
            return candidate
        if candidate.is_dir():
            folder = candidate
            continue
        print(f"[!] '{answer}' is not a listed session or a folder.")


def default_capture_folder(session: SessionState, config: Dict[str, Any]) -> Path:
    """Folder the session's captures came from, else pcaps\\, else the last capture folder."""
    for processed in session.processed_pcaps.values():
        parent = Path(processed.path).parent
        if parent.is_dir():
            return parent
    if _PCAPS_ROOT.is_dir():
        return _PCAPS_ROOT
    return Path(config.get("last_pcap_folder") or ".").expanduser()


def open_with_default_app(path: Path) -> None:
    """Open a local file with the operating system's default application."""
    try:
        if sys.platform.startswith("win"):
            os.startfile(str(path))  # type: ignore[attr-defined]
        elif sys.platform == "darwin":
            subprocess.Popen(["open", str(path)])
        else:
            subprocess.Popen(["xdg-open", str(path)])
    except Exception as exc:  # noqa: BLE001 — opening is a convenience only
        print(colorize(f"[!] Could not open {path.name}: {exc}", SEVERITY_MEDIUM))


_ARTIFACT_ORDER = {".docx": 0, ".txt": 0, ".json": 1, ".svg": 2, ".csv": 3, ".otpa_session": 4, ".otpa_baseline": 5}


def print_run_summary(analyzer: "OTPcapAnalyzer") -> None:
    """End-of-run summary: findings, traffic coverage, first actions, and the files written."""
    session = analyzer.session
    if session is None:
        return
    risk = analyzer.compute_risk_summary()
    scoring = [finding for finding in session.findings if finding.category not in NON_SCORING_CATEGORIES]
    counts = Counter(finding.severity for finding in scoring)
    ordered = sorted(counts, key=lambda severity: SEVERITY_ORDER.get(severity, 0), reverse=True)
    print_header("Summary")
    print(f"Risk: {risk['band']} (score {risk['score']}) — "
          + (" · ".join(f"{counts[severity]} {severity}" for severity in ordered) or "no findings"))
    coverage = analyzer.traffic_coverage()
    if coverage["total_packets"]:
        line = (f"Traffic identified: {format_share(coverage['identified_packets'], coverage['total_packets'])} "
                f"of {coverage['total_packets']:,} packets")
        if coverage["identified_packets"] < coverage["total_packets"] / 2:
            print(colorize(line + " — most of this capture could not be assessed.", SEVERITY_MEDIUM))
        else:
            print(line)
    issues = [issue for issue in aggregated_report_issues(session) if issue["category"] not in NON_SCORING_CATEGORIES]
    plan = build_remediation_plan(issues, report_issue_ids(issues))
    if plan:
        print("What to do first (from the Remediation Plan):")
        for index, row in enumerate(plan[:3], start=1):
            ids = ", ".join(item["id"] for item in row["findings"][:4] if item["id"])
            print(f"  {index}. {row['priority_label']} — {row['action']}" + (f" ({ids})" if ids else ""))
    written = sorted(analyzer.artifacts_written,
                     key=lambda item: _ARTIFACT_ORDER.get(item[0].suffix.lower(), 9))
    if written:
        folders = {path.parent for path, _ in written}
        if len(folders) == 1:
            print(f"Files written to {next(iter(folders))}:")
            width = max(len(path.name) for path, _ in written)
            for path, description in written:
                print(f"  {path.name:<{width}}  {description}")
        else:
            print("Files written:")
            for path, description in written:
                print(f"  {path}  — {description}")
    reports = [path for path, _ in written if path.suffix.lower() == ".docx"]
    if reports and not NON_INTERACTIVE and prompt_yes_no("Open the Word report now?", True):
        open_with_default_app(reports[-1])


def warn_if_pcaps_changed(session: SessionState) -> None:
    """Warn if previously processed pcap files changed on disk."""
    for processed in session.processed_pcaps.values():
        path = Path(processed.path)
        if not path.exists():
            print(colorize(f"[!] Previously processed pcap is missing: {path}", SEVERITY_HIGH))
            continue
        try:
            current_hash = file_sha256(path)
        except OSError:
            print(colorize(f"[!] Could not hash previously processed pcap: {path}", SEVERITY_HIGH))
            continue
        if current_hash != processed.sha256:
            print(colorize(f"[!] Warning: {path.name} has changed since it was processed in this session.", SEVERITY_HIGH))


def session_summary(session: SessionState) -> None:
    """Print a concise saved-session summary."""
    counts = Counter(finding.severity for finding in session.findings)
    print_header("Session Summary")
    print(f"Session: {session.name}")
    print(f"Site: {session.site}")
    print(f"Assessor: {session.assessor}")
    print(f"Pcap files: {len(session.processed_pcaps)}")
    print(f"Devices: {len(session.devices)}")
    print(f"Findings: {len(session.findings)}")
    print(f"Last analysis date: {session.updated_at}")
    if counts:
        print("Severity totals:")
        for severity, count in sorted(counts.items(), key=lambda item: SEVERITY_ORDER.get(item[0], 0), reverse=True):
            print(f"    - {severity}: {count}")


def resolve_pcap_folder(raw: str) -> Path:
    """Resolve a pcap folder path, expanding bare names against _PCAPS_ROOT.

    Resolution order for bare names (no path separator):
    1. Subfolder under _PCAPS_ROOT  (e.g. "plant-a" → pcaps/plant-a)
    2. Sibling of _PCAPS_ROOT       (e.g. "pcaps"   → otscope/pcaps)
    A full or relative path containing a separator is used as-is.
    """
    p = Path(raw).expanduser()
    if not p.is_absolute() and os.sep not in raw and "/" not in raw and _PCAPS_ROOT.is_dir():
        candidate = _PCAPS_ROOT / raw
        if candidate.exists():
            return candidate
        sibling = _PCAPS_ROOT.parent / raw
        if sibling.exists() and sibling.is_dir():
            return sibling
    return p


def _list_pcap_subfolders() -> List[Path]:
    """Return immediate subdirectories of _PCAPS_ROOT that contain at least one pcap."""
    if not _PCAPS_ROOT.is_dir():
        return []
    results = []
    for entry in sorted(_PCAPS_ROOT.iterdir()):
        if entry.is_dir() and any(is_capture_file(path) for path in entry.rglob("*")):
            results.append(entry)
    return results


def _print_pcap_subfolders() -> None:
    """Print a numbered list of available capture subfolders if _PCAPS_ROOT exists."""
    subfolders = _list_pcap_subfolders()
    if not subfolders:
        return
    print(f"\nAvailable capture sets (in {_PCAPS_ROOT}):")
    for i, folder in enumerate(subfolders, start=1):
        print(f"  {i}. {folder.name}")
    print()


def startup_menu() -> str:
    """Prompt for the startup session path."""
    saved = len(saved_sessions(_OUTPUT_ROOT)) if _OUTPUT_ROOT.is_dir() else 0
    saved_text = f" ({saved} saved)" if saved else ""
    answer = prompt_input(f"Start a NEW session, RESUME a saved session{saved_text}, or ADD captures to one? [N/R/A]", "N")
    answer = answer.strip().lower()
    if answer.startswith("r"):
        return "resume"
    if answer.startswith("a"):
        return "add"
    return "new"


def parse_arguments(argv: Optional[Sequence[str]] = None) -> argparse.Namespace:
    """Parse command line arguments."""
    parser = argparse.ArgumentParser(
        description="Interactive multi-pcap OT/ICS analyzer using tshark, session state JSON, and python-docx reporting.",
    )
    parser.add_argument("--version", action="store_true", help="Print version and exit.")
    parser.add_argument("--pcap", help="Start with a specific pcap file.")
    parser.add_argument("--session", help="Resume a specific session file.")
    parser.add_argument("--report-only", dest="report_only", help="Generate a report from a session file without re-analysis.")
    parser.add_argument("--save-baseline", dest="save_baseline", help="After loading a session, save its devices/flows as a baseline file at this path.")
    parser.add_argument("--compare-baseline", dest="compare_baseline", help="After loading a session, compare its devices/flows to a baseline file at this path and emit diff findings.")
    parser.add_argument("--offline", action="store_true",
                        help=("Hard-lock outbound network behavior: no PTR lookups, no RDAP "
                              "queries, no name resolution. Use this when analyzing pcaps from "
                              "an unknown source where you don't want any DNS/HTTPS traffic "
                              "from your machine to be attributable to OT-related infrastructure. "
                              "Overrides the discovery questionnaire's air-gapped answer."))
    # Non-interactive / quick-scan mode
    parser.add_argument(
        "--scan", metavar="PATH",
        help=(
            "Path to a pcap file or a folder of pcap files. Runs a full analysis with no "
            "interactive prompts — all discovery questions use defaults — and automatically "
            "generates a report on completion. Combine with --assessor, --site, --env, and "
            "--format to customise the run without answering any questions."
        ),
    )
    parser.add_argument("--assessor", metavar="NAME",
                        help="Assessor name. Pre-fills the prompt in interactive mode; used as-is in --scan mode.")
    parser.add_argument("--site", metavar="NAME",
                        help="Site / location name. Pre-fills the prompt in interactive mode; used as-is in --scan mode.")
    parser.add_argument(
        "--env", metavar="TYPE",
        help=(
            "Environment type hint for the discovery questionnaire "
            "(e.g. manufacturing, power, water, building-automation, scada). "
            "Pre-fills or defaults the environment_type answer."
        ),
    )
    parser.add_argument(
        "--format", dest="report_format",
        choices=["word", "json", "both"], default="word",
        help=("Report produced at the end of a --scan run: word (default — the Word report plus JSON and "
              "diagrams) or json (JSON and diagrams only). 'both' is the same as word."),
    )
    parser.add_argument("--verbose", action="store_true",
                        help="Print every protocol detector's result and per-file match counts.")
    parser.add_argument(
        "--technical-appendix", dest="technical_appendix",
        action="store_true", default=False,
        help=(
            "Include Appendix B (Detailed Technical Evidence) in the Word report.  "
            "By default the main report is concise; use this flag when reviewers need "
            "full raw evidence lines and per-pcap breakdown."
        ),
    )
    return parser.parse_args(argv)


def signal_handler(signum: int, frame: Any) -> None:
    """Offer to save the current session on Ctrl+C."""
    del signum, frame
    print("\n[!] Interrupted.")
    if CURRENT_ANALYZER and CURRENT_ANALYZER.session and prompt_yes_no("Save partial session state before exiting?", True):
        CURRENT_ANALYZER.save_session()
    raise SystemExit(130)


def prompt_report_generation(
    analyzer: OTPcapAnalyzer,
    prompt_text: str = "Generate report now?",
    fmt: Optional[str] = None,
    technical_appendix: bool = False,
) -> None:
    """Ask which report to produce and generate it.

    The Word report always brings the JSON report and the Purdue diagrams with
    it; JSON writes those two without the Word document.  When *fmt* is given
    (``'word'``, ``'json'``, or ``'both'`` — an alias of word) the prompt is
    skipped.  In NON_INTERACTIVE mode the prompt is also skipped.
    """
    if fmt is None and not NON_INTERACTIVE:
        fmt = prompt_input(
            f"{prompt_text} [W] Word report (+ JSON and diagrams) / [J] JSON and diagrams only / [S] skip", "W"
        ).strip().lower()
        if fmt in {"s", "skip", "n", "no"}:
            return
    fmt = (fmt or "word").lower()
    if fmt in {"j", "json"}:
        # JSON-only: skip Word report but still generate JSON + SVGs.
        analyzer.generate_json_report()
        try:
            analyzer.generate_purdue_svgs()
        except Exception as exc:
            print(f"[!] Purdue SVG generation failed: {exc}")
    else:
        # "word" or "both": generate_report auto-produces JSON + SVGs as companions.
        analyzer.generate_report(technical_appendix=technical_appendix)


def scan_flow(analyzer: OTPcapAnalyzer, config: Dict[str, Any], args: argparse.Namespace) -> None:
    """Run a fully non-interactive analysis and auto-generate a report.

    Triggered by ``--scan <path>``.  All discovery questions use empty/unknown
    defaults.  No prompts are shown; the run completes and exits cleanly.
    """
    scan_path = resolve_pcap_folder(args.scan)
    selected_pcaps = collect_pcaps_from_path(scan_path)
    folder = scan_path if scan_path.is_dir() else scan_path.parent

    assessor = getattr(args, "assessor", None) or "OTscope"
    # Scanning the shared pcaps/ drop folder: name the site after the workspace.
    default_site = _SCRIPT_DIR.name if folder.resolve() == _PCAPS_ROOT.resolve() else folder.name
    site = getattr(args, "site", None) or default_site or "unknown-site"
    session_name = safe_slug(f"{site}_{datetime.now().strftime('%Y%m%d')}")
    out_folder = _OUTPUT_ROOT if _OUTPUT_ROOT.is_dir() else folder
    if (out_folder / f"{session_name}.otpa_session").exists():
        session_name = unique_session_name(out_folder, session_name)

    env_answers: Dict[str, str] = {key: "" for key, _ in discovery_questions()}
    if getattr(args, "env", None):
        env_answers["environment_type"] = args.env
    if getattr(args, "offline", False):
        env_answers["air_gapped"] = "yes"

    print(f"[>] Scan mode — {len(selected_pcaps)} pcap(s) in '{folder}'")
    print(f"[>] Assessor: {assessor}   Site: {site}   Session: {session_name}")
    print(f"[>] Report format: {getattr(args, 'report_format', 'word')}")
    print(f"[>] Results will be written to {out_folder}")

    analyzer.create_session(out_folder, session_name, site, assessor, env_answers)
    config["last_pcap_folder"] = str(folder)
    config["last_assessor_name"] = assessor
    config["last_site_name"] = site
    save_config(config)

    print_header("Analysis Start")
    analyzer.analyze_pcaps(selected_pcaps)
    prompt_report_generation(
        analyzer,
        fmt=getattr(args, "report_format", "word"),
        technical_appendix=getattr(args, "technical_appendix", False),
    )
    print_run_summary(analyzer)


def new_session_flow(
    analyzer: OTPcapAnalyzer,
    config: Dict[str, Any],
    starting_pcap: Optional[Path] = None,
    assessor_hint: Optional[str] = None,
    site_hint: Optional[str] = None,
    env_hint: Optional[str] = None,
    technical_appendix: bool = False,
) -> None:
    """Create and run a new session."""
    if starting_pcap:
        default_folder = str(starting_pcap.parent)
    elif _PCAPS_ROOT.is_dir():
        default_folder = str(_PCAPS_ROOT)
    else:
        default_folder = config.get("last_pcap_folder", "")
    _print_pcap_subfolders()
    folder_text = prompt_input("Pcap subfolder name or full path", default_folder or None)
    folder = resolve_pcap_folder(folder_text)
    if not folder.exists() or not folder.is_dir():
        raise SystemExit(f"Folder not found: {folder}")
    selected_pcaps = [starting_pcap] if starting_pcap else select_pcaps_from_folder(folder)
    if not selected_pcaps:
        raise SystemExit("No pcap files selected.")
    assessor = prompt_input("Assessor name", assessor_hint or config.get("last_assessor_name") or None)
    site = prompt_input("Site/post name", site_hint or config.get("last_site_name") or None)
    out_folder = _OUTPUT_ROOT if _OUTPUT_ROOT.is_dir() else folder
    session_name = prompt_input("Session name", safe_slug(f"{site}_{datetime.now().strftime('%Y%m%d')}"))
    config["last_pcap_folder"] = str(folder)
    config["last_assessor_name"] = assessor
    config["last_site_name"] = site
    save_config(config)
    existing = out_folder / f"{safe_slug(session_name)}.otpa_session"
    if existing.exists():
        print(colorize(f"[!] A session with this name already exists: {describe_session_file(existing)}",
                       SEVERITY_MEDIUM))
        free_name = unique_session_name(out_folder, session_name)
        choice = prompt_input(f"Add these captures to it, use a new name ({free_name}), or overwrite it? [A/N/O]",
                              "N").strip().lower()
        if choice.startswith("a"):
            session = analyzer.load_session(existing)
            new_pcaps = [path for path in selected_pcaps if path.name not in session.processed_pcaps]
            if new_pcaps:
                print(f"[>] Results will be written to {out_folder}")
                print_header("Analysis Start")
                analyzer.analyze_pcaps(new_pcaps)
            else:
                print("[i] Those captures are already in this session — nothing new to analyze.")
            prompt_report_generation(analyzer, "Generate updated report now?", technical_appendix=technical_appendix)
            print_run_summary(analyzer)
            return
        if not choice.startswith("o"):
            session_name = free_name
            print(f"[>] Using session name {session_name}.")
    existing_env: Dict[str, str] = {}
    if env_hint:
        existing_env["environment_type"] = env_hint
    env_answers = ask_environment_questions(existing_env)
    analyzer.create_session(out_folder, session_name, site, assessor, env_answers)
    print(f"[>] Results will be written to {out_folder}")
    print_header("Analysis Start")
    analyzer.analyze_pcaps(selected_pcaps)
    prompt_report_generation(analyzer, "Generate report now?", technical_appendix=technical_appendix)
    print_run_summary(analyzer)


def resume_flow(analyzer: OTPcapAnalyzer, config: Dict[str, Any], session_path: Optional[Path] = None, technical_appendix: bool = False) -> None:
    """Resume or inspect an existing session."""
    if session_path is None:
        session_path = choose_session_file(default_session_folder(config))
        if session_path is None:
            raise SystemExit("No session selected.")
    session = analyzer.load_session(session_path)
    warn_if_pcaps_changed(session)
    session_summary(session)
    while True:
        answer = prompt_input("Choose action: Re-run analysis / Add new pcaps / Generate report / Review findings / Exit [R/A/G/F/E]", "E").strip().lower()
        if answer.startswith("r"):
            existing_paths = [Path(item.path) for item in session.processed_pcaps.values() if Path(item.path).exists()]
            analyzer.analyze_pcaps(existing_paths)
            prompt_report_generation(analyzer, "Generate updated report now?", technical_appendix=technical_appendix)
            print_run_summary(analyzer)
            return
        if answer.startswith("a"):
            add_pcaps_flow(analyzer, config, session_path, technical_appendix=technical_appendix)
            return
        if answer.startswith("g"):
            prompt_report_generation(analyzer, "Generate report?", technical_appendix=technical_appendix)
            print_run_summary(analyzer)
            return
        if answer.startswith("f"):
            for finding in sorted(session.findings, key=lambda item: (SEVERITY_ORDER.get(item.severity, 0), item.title), reverse=True):
                print(f"[{finding.severity}] {finding.title}")
                print(textwrap.fill(finding.description, width=100, initial_indent="    ", subsequent_indent="    "))
                if finding.evidence:
                    print(textwrap.fill("Evidence: " + " | ".join(finding.evidence[:3]), width=100, initial_indent="    ", subsequent_indent="    "))
            continue
        return


def add_pcaps_flow(analyzer: OTPcapAnalyzer, config: Dict[str, Any], session_path: Optional[Path] = None, technical_appendix: bool = False) -> None:
    """Add new pcaps to an existing session without reprocessing old ones."""
    if session_path is None:
        session_path = choose_session_file(default_session_folder(config))
        if session_path is None:
            raise SystemExit("No session selected.")
    session = analyzer.load_session(session_path)
    session_summary(session)
    print_header("Add Captures")
    capture_folder = resolve_pcap_folder(prompt_input("Capture folder", str(default_capture_folder(session, config))))
    if not capture_folder.is_dir():
        raise SystemExit(f"Folder not found: {capture_folder}")
    selected_pcaps = select_pcaps_from_folder(capture_folder, exclude_filenames=sorted(session.processed_pcaps.keys()))
    if not selected_pcaps:
        raise SystemExit("No new captures selected.")
    config["last_pcap_folder"] = str(capture_folder)
    save_config(config)
    analyzer.analyze_pcaps(selected_pcaps)
    prompt_report_generation(analyzer, "Regenerate report now?", technical_appendix=technical_appendix)
    print_run_summary(analyzer)


def report_only_flow(analyzer: OTPcapAnalyzer, session_path: Path, technical_appendix: bool = False) -> None:
    """Generate a report from saved state only."""
    session = analyzer.load_session(session_path)
    session_summary(session)
    prompt_report_generation(analyzer, "Generate report?", technical_appendix=technical_appendix)
    print_run_summary(analyzer)


def run_application(args: argparse.Namespace) -> None:
    """Run the application according to CLI arguments and prompts."""
    global CURRENT_ANALYZER, OFFLINE_MODE, NON_INTERACTIVE, VERBOSE
    if args.version:
        print(f"{TOOL_NAME} v{VERSION}")
        return
    if getattr(args, "verbose", False):
        VERBOSE = True
    if getattr(args, "offline", False):
        OFFLINE_MODE = True
    if getattr(args, "scan", None):
        NON_INTERACTIVE = True
    config = load_config()
    analyzer = OTPcapAnalyzer(config)
    CURRENT_ANALYZER = analyzer
    signal.signal(signal.SIGINT, signal_handler)
    # First-run workspace bootstrap: folders + requirements.txt +
    # README_FIRST.txt materialize next to the script so a bare otscope.py
    # dropped into an empty directory is fully self-provisioning.
    _bootstrap_workspace()
    # If the pcaps folder exists but holds no capture files, guide the user
    # before they hit the file-selection prompt of a new interactive session.
    interactive_new_session = not (getattr(args, "scan", None) or args.session or args.report_only or args.pcap
                                   or args.save_baseline or args.compare_baseline)
    if interactive_new_session and _PCAPS_ROOT.is_dir() and not any(
        is_capture_file(f) for f in _PCAPS_ROOT.rglob("*")
    ):
        print(colorize(f"[i] No capture files found in {_PCAPS_ROOT}", "INFO"))
        print(colorize("    Drop your .pcap / .pcapng files into that folder, then run OTscope again.", "INFO"))
        print(colorize("    (You can also enter any full path at the prompt below.)", "INFO"))
        print()
    print_banner()
    print_network_safety_banner()
    ta = getattr(args, "technical_appendix", False)
    if args.report_only:
        report_only_flow(analyzer, Path(args.report_only).expanduser(), technical_appendix=ta)
        return
    # Baseline-only shortcuts: operate against an existing session file
    if args.save_baseline or args.compare_baseline:
        if not args.session:
            raise SystemExit("--save-baseline and --compare-baseline require --session <file>.")
        session_path = Path(args.session).expanduser()
        analyzer.load_session(session_path)
        if args.compare_baseline:
            analyzer.compare_to_baseline(Path(args.compare_baseline).expanduser())
        if args.save_baseline:
            analyzer.save_baseline(Path(args.save_baseline).expanduser())
        analyzer.save_session()
        return
    ensure_runtime_dependencies()
    # Non-interactive quick-scan mode
    if getattr(args, "scan", None):
        scan_flow(analyzer, config, args)
        return
    if args.session:
        resume_flow(analyzer, config, Path(args.session).expanduser(), technical_appendix=ta)
        return
    if args.pcap:
        new_session_flow(
            analyzer, config,
            starting_pcap=Path(args.pcap).expanduser(),
            assessor_hint=getattr(args, "assessor", None),
            site_hint=getattr(args, "site", None),
            env_hint=getattr(args, "env", None),
            technical_appendix=ta,
        )
        return
    mode = startup_menu()
    if mode == "resume":
        resume_flow(analyzer, config, technical_appendix=ta)
    elif mode == "add":
        add_pcaps_flow(analyzer, config, technical_appendix=ta)
    else:
        new_session_flow(
            analyzer, config,
            assessor_hint=getattr(args, "assessor", None),
            site_hint=getattr(args, "site", None),
            env_hint=getattr(args, "env", None),
            technical_appendix=ta,
        )


def main(argv: Optional[Sequence[str]] = None) -> int:
    """Program entrypoint with clean error handling."""
    try:
        args = parse_arguments(argv)
        run_application(args)
        return 0
    except KeyboardInterrupt:
        print("\n[!] Interrupted.")
        return 130
    except SystemExit:
        raise
    except Exception as exc:
        print(colorize(f"[!] {exc}", SEVERITY_HIGH))
        return 1


if __name__ == "__main__":
    raise SystemExit(main())
